def resolve_germany_overtime_premium_category(
    db: Session, category_code: str, as_of: Optional[date] = None,
    jurisdiction_pack_id: Optional[int] = None,
) -> Optional[GermanyOvertimePremiumCategory]:
    """Return the PUBLISHED premium-category record applicable on `as_of`
    (defaults to today). Returns None (never raises) if no published
    record covers that date — fail closed, never a hardcoded percentage.

    Phase 8DJ: `jurisdiction_pack_id`, when given, narrows to rows linked
    to that Germany Compliance Pack version, falling back to the
    unfiltered result if no pack-linked row matches — identical pattern
    to resolve_germany_health_fund (Phase 8DI); omitted, behavior is
    unchanged."""
    as_of = as_of or date.today()
    query = db.query(GermanyOvertimePremiumCategory).filter(
        GermanyOvertimePremiumCategory.category_code == category_code,
        GermanyOvertimePremiumCategory.status == "PUBLISHED",
        GermanyOvertimePremiumCategory.effective_from <= as_of,
        (GermanyOvertimePremiumCategory.effective_to.is_(None)) | (GermanyOvertimePremiumCategory.effective_to >= as_of),
    )
    if jurisdiction_pack_id is not None:
        pack_scoped = query.filter(GermanyOvertimePremiumCategory.jurisdiction_pack_id == jurisdiction_pack_id).order_by(GermanyOvertimePremiumCategory.effective_from.desc()).first()
        if pack_scoped is not None:
            return pack_scoped
    return query.order_by(GermanyOvertimePremiumCategory.effective_from.desc()).first()


_GERMANY_OVERTIME_GRUNDLOHN_DIMENSIONS = ("WAGE_TAX", "SOCIAL_INSURANCE")
_OVERTIME_GRUNDLOHN_CAP_EDITABLE_STATUSES = ("DRAFT", "VERIFIED", "APPROVED")
_OVERTIME_GRUNDLOHN_CAP_VALID_STATUSES = ("DRAFT", "VERIFIED", "APPROVED", "PUBLISHED", "SUPERSEDED")
_OVERTIME_GRUNDLOHN_CAP_ALLOWED_TRANSITIONS = {
    "DRAFT": {"VERIFIED"},
    "VERIFIED": {"APPROVED", "DRAFT"},
    "APPROVED": {"PUBLISHED", "VERIFIED"},
    "PUBLISHED": {"SUPERSEDED"},
    "SUPERSEDED": set(),
}


def _require_editable_overtime_grundlohn_cap(row: GermanyOvertimeGrundlohnCap) -> None:
    if row.status not in _OVERTIME_GRUNDLOHN_CAP_EDITABLE_STATUSES:
        raise BadRequestException(
            f"Overtime Grundlohn cap record for {row.dimension} ({row.effective_from}) is {row.status} — "
            "no longer editable. Record a new effective-dated version instead."
        )


def _validate_overtime_grundlohn_cap_no_overlap(
    db: Session, dimension: str, effective_from: date, effective_to: Optional[date],
    exclude_id: Optional[int] = None,
) -> None:
    query = db.query(GermanyOvertimeGrundlohnCap).filter(GermanyOvertimeGrundlohnCap.dimension == dimension)
    if exclude_id is not None:
        query = query.filter(GermanyOvertimeGrundlohnCap.id != exclude_id)
    new_end = effective_to or date.max
    for existing in query.all():
        existing_end = existing.effective_to or date.max
        if effective_from <= existing_end and existing.effective_from <= new_end:
            raise BadRequestException(
                f"Period {effective_from} to {effective_to or 'open-ended'} overlaps existing overtime "
                f"Grundlohn cap record #{existing.id} for {dimension} ({existing.effective_from} to "
                f"{existing.effective_to or 'open-ended'}). Close or adjust that record first."
            )


def list_overtime_grundlohn_caps(db: Session, dimension: Optional[str] = None) -> List[GermanyOvertimeGrundlohnCap]:
    query = db.query(GermanyOvertimeGrundlohnCap)
    if dimension:
        query = query.filter(GermanyOvertimeGrundlohnCap.dimension == dimension)
    return query.order_by(GermanyOvertimeGrundlohnCap.dimension, GermanyOvertimeGrundlohnCap.effective_from.desc()).all()


def get_overtime_grundlohn_cap_by_id(db: Session, record_id: int) -> GermanyOvertimeGrundlohnCap:
    row = db.query(GermanyOvertimeGrundlohnCap).filter(GermanyOvertimeGrundlohnCap.id == record_id).first()
    if not row:
        raise NotFoundException("GermanyOvertimeGrundlohnCap", record_id)
    return row


def create_overtime_grundlohn_cap_record(
    db: Session, data: "GermanyOvertimeGrundlohnCapCreate", actor_id: Optional[int] = None,
    auto_close_previous: bool = True,
) -> GermanyOvertimeGrundlohnCap:
    if data.dimension not in _GERMANY_OVERTIME_GRUNDLOHN_DIMENSIONS:
        raise BadRequestException(
            f"dimension must be one of {_GERMANY_OVERTIME_GRUNDLOHN_DIMENSIONS}, got {data.dimension!r}."
        )
    if data.hourly_cap_amount is None or data.hourly_cap_amount <= 0:
        raise BadRequestException("hourly_cap_amount must be a positive value.")
    if data.effective_to is not None and data.effective_to < data.effective_from:
        raise BadRequestException("effectiveTo must not be before effectiveFrom.")

    previous_open = (
        db.query(GermanyOvertimeGrundlohnCap)
        .filter(
            GermanyOvertimeGrundlohnCap.dimension == data.dimension,
            GermanyOvertimeGrundlohnCap.effective_to.is_(None),
        )
        .first()
    )
    closing_previous = bool(auto_close_previous and previous_open and previous_open.effective_from < data.effective_from)
    if closing_previous:
        previous_open.effective_to = data.effective_from - timedelta(days=1)

    _validate_overtime_grundlohn_cap_no_overlap(
        db, data.dimension, data.effective_from, data.effective_to,
        exclude_id=previous_open.id if closing_previous else None,
    )

    row = GermanyOvertimeGrundlohnCap(
        dimension=data.dimension, hourly_cap_amount=data.hourly_cap_amount,
        effective_from=data.effective_from, effective_to=data.effective_to,
        authority_source_id=data.authority_source_id, jurisdiction_pack_id=data.jurisdiction_pack_id, status="DRAFT",
        created_by_id=actor_id, updated_by_id=actor_id,
    )
    db.add(row)
    db.commit()
    db.refresh(row)

    record_tax_audit(
        db, actor_id=actor_id, action="create", entity_type="germany_overtime_grundlohn_cap", entity_id=row.id,
        old_value=None,
        new_value={
            "dimension": data.dimension, "hourly_cap_amount": str(data.hourly_cap_amount),
            "effective_from": str(data.effective_from),
            "effective_to": str(data.effective_to) if data.effective_to else None,
        },
    )
    return row


def set_overtime_grundlohn_cap_status(
    db: Session, record_id: int, status: str, actor_id: Optional[int] = None,
) -> GermanyOvertimeGrundlohnCap:
    row = get_overtime_grundlohn_cap_by_id(db, record_id)
    if status not in _OVERTIME_GRUNDLOHN_CAP_VALID_STATUSES:
        raise BadRequestException(f"Unknown overtime Grundlohn cap status: {status!r}.")
    if status not in _OVERTIME_GRUNDLOHN_CAP_ALLOWED_TRANSITIONS.get(row.status, set()):
        raise BadRequestException(f"Cannot move an overtime Grundlohn cap record from {row.status} to {status}.")

    if status == "PUBLISHED":
        if not row.approved_by_id or row.approved_by_id == row.updated_by_id:
            raise BadRequestException(
                "This overtime Grundlohn cap record needs a distinct approver before it can be published — "
                "use the approve action with a different Super Admin than whoever last edited it."
            )
        if not row.authority_source_id:
            raise BadRequestException(
                "An overtime Grundlohn cap record cannot be published without a linked source evidence "
                "artifact (authoritySourceId) — record one via /compliance/source-artifacts first."
            )

    old_status = row.status
    row.status = status
    row.updated_by_id = actor_id
    db.commit()
    db.refresh(row)
    record_tax_audit(
        db, actor_id=actor_id, action="status_change", entity_type="germany_overtime_grundlohn_cap", entity_id=row.id,
        old_value={"status": old_status}, new_value={"status": status},
    )
    return row


def set_overtime_grundlohn_cap_approver(db: Session, record_id: int, actor_id: Optional[int] = None) -> GermanyOvertimeGrundlohnCap:
    row = get_overtime_grundlohn_cap_by_id(db, record_id)
    _require_editable_overtime_grundlohn_cap(row)
    old_approver = row.approved_by_id
    old_status = row.status
    row.approved_by_id = actor_id
    if row.status == "VERIFIED":
        row.status = "APPROVED"
    db.commit()
    db.refresh(row)
    record_tax_audit(
        db, actor_id=actor_id, action="update", entity_type="germany_overtime_grundlohn_cap", entity_id=row.id,
        old_value={"approved_by_id": old_approver, "status": old_status},
        new_value={"approved_by_id": actor_id, "status": row.status},
        reason="Approver set",
    )
    return row


def resolve_germany_overtime_grundlohn_cap(
    db: Session, dimension: str, as_of: Optional[date] = None,
    jurisdiction_pack_id: Optional[int] = None,
) -> Optional[GermanyOvertimeGrundlohnCap]:
    """Return the PUBLISHED Grundlohn cap applicable on `as_of` (defaults
    to today) for one dimension ("WAGE_TAX" or "SOCIAL_INSURANCE"). Returns
    None (never raises) if no published record covers that date — fail
    closed, never a hardcoded €50/€25 fallback.

    Phase 8DJ: `jurisdiction_pack_id`, when given, narrows to rows linked
    to that Germany Compliance Pack version, falling back to the
    unfiltered result if no pack-linked row matches; omitted, behavior is
    unchanged — same pattern as every other Germany resolver (Phase 8DI)."""
    as_of = as_of or date.today()
    query = db.query(GermanyOvertimeGrundlohnCap).filter(
        GermanyOvertimeGrundlohnCap.dimension == dimension,
        GermanyOvertimeGrundlohnCap.status == "PUBLISHED",
        GermanyOvertimeGrundlohnCap.effective_from <= as_of,
        (GermanyOvertimeGrundlohnCap.effective_to.is_(None)) | (GermanyOvertimeGrundlohnCap.effective_to >= as_of),
    )
    if jurisdiction_pack_id is not None:
        pack_scoped = query.filter(GermanyOvertimeGrundlohnCap.jurisdiction_pack_id == jurisdiction_pack_id).order_by(GermanyOvertimeGrundlohnCap.effective_from.desc()).first()
        if pack_scoped is not None:
            return pack_scoped
    return query.order_by(GermanyOvertimeGrundlohnCap.effective_from.desc()).first()


# ── Germany: per-employee calculation-input resolver (Phase 7) ─────────
# Phase 8BF — disclosed onboarding gap closure. A Germany employee could
# previously be created (and payroll attempted) with zero visibility into
# whether the GLOBAL statutory registries (health funds, both contribution
# -ceiling branches, PV configuration) had ever been published at all —
# the first sign of an incomplete configuration was a fail-closed
# GermanyCalculationBlockedException at actual payroll-run time. This is
# organization-independent (these four registries are global, not
# per-org — confirmed by this project's own prior forensic audit) and
# deliberately does NOT check per-employee state (statutory profile,
# health-fund code, PAP asset) — that is what preview_germany_calculation
# already covers once an employee exists. This function answers a
# narrower, earlier question: "is Germany payroll configuration even
# possible today, for ANY employee?" Read-only; never creates, seeds, or
# infers a registry row — an incomplete answer here is reported, never
# silently completed.
def get_germany_statutory_configuration_readiness(db: Session, as_of=None) -> dict:
    as_of = as_of or date.today()

    def _has_published(rows, effective_check=True):
        for row in rows:
            if row.status != "PUBLISHED":
                continue
            if not effective_check:
                return True
            effective_to = getattr(row, "effective_to", None)
            if row.effective_from <= as_of and (effective_to is None or as_of <= effective_to):
                return True
        return False

    health_fund_ready = _has_published(list_health_funds(db))
    ceiling_rv_alv_ready = _has_published(list_contribution_ceilings(db, branch="RV_ALV"))
    ceiling_gkv_pv_ready = _has_published(list_contribution_ceilings(db, branch="GKV_PV"))
    pv_configuration_ready = _has_published(list_pv_configurations(db))

    missing = []
    if not health_fund_ready:
        missing.append("No PUBLISHED health fund (Krankenkasse) record is effective as of this date.")
    if not ceiling_rv_alv_ready:
        missing.append("No PUBLISHED RV/ALV contribution ceiling is effective as of this date.")
    if not ceiling_gkv_pv_ready:
        missing.append("No PUBLISHED GKV/PV contribution ceiling is effective as of this date.")
    if not pv_configuration_ready:
        missing.append("No PUBLISHED PV (long-term care) configuration is effective as of this date.")

    return {
        "asOf": str(as_of),
        "ready": not missing,
        "healthFundReady": health_fund_ready,
        "ceilingRvAlvReady": ceiling_rv_alv_ready,
        "ceilingGkvPvReady": ceiling_gkv_pv_ready,
        "pvConfigurationReady": pv_configuration_ready,
        "missing": missing,
    }


# Resolves every Germany registry a calculation might need for ONE
# employee on ONE payroll date, in a single place, so _compute_payslip_values
# and preview_payroll_run can never disagree about which rows applied.
# Deliberately NOT cached across employees (unlike rate_map/slabs in
# _resolve_employee_calc_inputs) — profile/health-fund/PV category are
# genuinely per-employee, so caching by jurisdiction alone would silently
# apply one employee's resolved rows to another's.
#
# Returns a plain dict of ORM rows (or None) — never raises. Whether a
# missing row is fatal is a decision for engine/countries/germany.py
# (the actual calculation), not this resolver — mirrors
# resolve_germany_pap_asset's own "absence is not an error" contract.
def resolve_applicable_germany_pack(db: Session, as_of: Optional[date] = None) -> Optional[JurisdictionPack]:
    """Phase 8DI — the Germany Compliance Pack analogue of
    engine/tax_resolver.py's `_find_active_tax_pack`, deliberately NOT
    reusing that function: Germany packs are never organization-scoped
    (no Germany registry table has an `organization_id` column — the
    statutory rates are national, not per-employer-customizable, unlike
    USA/UK/India's ContributionRate/TaxSlab), so the org-scoped-with-
    canonical-fallback query shape that function implements does not
    apply here. This is a simpler, country-global lookup: the single
    Active, pack_type="tax", jurisdiction_country="DE" pack whose
    effective period covers `as_of` (defaults to today).

    Returns None (never raises) when no such pack exists — callers must
    treat that as "no governed pack applies; existing Germany registry
    resolution (effective-dated, PUBLISHED-status, no pack involved)
    still governs exactly as it has since before this phase," never as
    license to block calculation outright. This is a deliberate, minimal
    design choice, not an oversight: it keeps changing/activating a
    pack version something registries can OPT INTO (via their own
    `jurisdiction_pack_id`), instead of retroactively requiring a pack to
    exist before Germany can calculate at all — a much larger behavior
    change than this phase's brief asked for, and one that would silently
    break both this codebase's ~576 existing Germany tests and today's
    real production shape (registries can be legitimately configured
    before any pack version formally wraps them)."""
    as_of = as_of or date.today()
    return (
        db.query(JurisdictionPack)
        .filter(
            JurisdictionPack.jurisdiction_country == "DE",
            JurisdictionPack.pack_type == "tax",
            JurisdictionPack.status == "Active",
            JurisdictionPack.effective_from.isnot(None),
            JurisdictionPack.effective_from <= as_of,
            (JurisdictionPack.effective_to.is_(None)) | (JurisdictionPack.effective_to >= as_of),
        )
        .order_by(JurisdictionPack.effective_from.desc())
        .first()
    )


_GERMANY_PACK_COMPLETENESS_COMPONENTS = [
    # (result key, human label, model, extra filter fn(query) -> query | None)
    ("contribution_ceilings", "Contribution ceilings (GKV_PV, RV_ALV)", GermanyContributionCeiling, None),
    ("pv_configurations", "PV (long-term care insurance) configuration", GermanyPvConfiguration, None),
    ("health_funds", "Health funds (GKV)", GermanyHealthFund, None),
    ("u1_tariffs", "U1 tariffs (sickness reimbursement)", GermanyHealthFundU1Tariff, None),
    ("earning_taxability_rules", "Earning/deduction taxability rules", GermanyEarningTaxabilityRule, None),
    ("overtime_premium_categories", "Overtime premium categories", GermanyOvertimePremiumCategory, None),
    ("overtime_grundlohn_caps", "Overtime Grundlohn caps", GermanyOvertimeGrundlohnCap, None),
    ("church_tax_exceptions", "Church tax exceptions", GermanyChurchTaxException, None),
    ("minijob_midijob_parameters", "Minijob/Midijob parameters", GermanyMinijobMidijobParameter, None),
]


def assess_germany_pack_completeness(db: Session, jurisdiction_pack_id: int, as_of: Optional[date] = None) -> dict:
    """Phase 8DI, Phase 14 requirement — a Germany Compliance Pack
    completeness validator. For the given pack id, reports, per component,
    how many PUBLISHED rows are linked to it (via `jurisdiction_pack_id`)
    and effective as of `as_of` (defaults to today), and an overall
    verdict of COMPLETE / PARTIAL / INVALID.

    Deliberately NOT included as a required component: income tax
    (Lohnsteuer/Soli). Germany's tax calculation is NOT registry/pack-
    based at all — it is computed by a dedicated internal calculator
    (engine/jurisdictions/germany/tax.py's hardcoded, effective-dated 2026
    tariff constants, and the PAP interpreter for the certified path,
    which remains FAIL-CLOSED/UNAVAILABLE by design). Requiring a tax
    registry component here would misrepresent how this codebase actually
    computes German income tax — see docs/GERMANY_2026_8DI_..._REPORT.md
    §"Germany current architecture" for the full trace.

    Also NOT included: PAP certification, ELStAM, ELSTER, DEÜV — none of
    these are in scope for this pack's completeness (per this phase's own
    explicit instruction not to require unsupported government
    integrations).

    Returns a dict: {"pack_id": ..., "as_of": ..., "components": {key:
    {"label": ..., "published_row_count": int}}, "verdict": "COMPLETE" |
    "PARTIAL" | "INVALID", "missing_components": [...]}."""
    as_of = as_of or date.today()
    pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == jurisdiction_pack_id).first()
    if pack is None:
        return {
            "pack_id": jurisdiction_pack_id, "as_of": as_of, "components": {},
            "verdict": "INVALID", "missing_components": [],
            "reason": f"No JurisdictionPack row exists with id={jurisdiction_pack_id}.",
        }

    components = {}
    missing = []
    for key, label, model, extra_filter in _GERMANY_PACK_COMPLETENESS_COMPONENTS:
        query = db.query(model).filter(
            model.jurisdiction_pack_id == jurisdiction_pack_id,
            model.status == "PUBLISHED",
            model.effective_from <= as_of,
            (model.effective_to.is_(None)) | (model.effective_to >= as_of),
        )
        if extra_filter is not None:
            query = extra_filter(query)
        count = query.count()
        components[key] = {"label": label, "published_row_count": count}
        if count == 0:
            missing.append(key)

    if pack.status != "Active":
        verdict = "INVALID"
        reason = f"Pack status is {pack.status!r}, not Active — a non-Active pack cannot be considered complete for production payroll regardless of registry linkage."
    elif not missing:
        verdict = "COMPLETE"
        reason = "Every tracked Germany registry component has at least one PUBLISHED row linked to this pack, effective as of the given date."
    elif len(missing) == len(_GERMANY_PACK_COMPLETENESS_COMPONENTS):
        verdict = "INVALID"
        reason = "No tracked Germany registry component has any PUBLISHED row linked to this pack."
    else:
        verdict = "PARTIAL"
        reason = f"{len(missing)} of {len(_GERMANY_PACK_COMPLETENESS_COMPONENTS)} tracked components have no PUBLISHED row linked to this pack: {missing}."

    return {
        "pack_id": jurisdiction_pack_id, "pack_version": pack.version, "pack_status": pack.status,
        "as_of": as_of, "components": components, "verdict": verdict,
        "missing_components": missing, "reason": reason,
        "tax_calculation_note": (
            "Income tax (Lohnsteuer/Soli) is NOT a registry component of this pack — "
            "computed by the dedicated internal Germany tax calculator, independent of "
            "any JurisdictionPack. PAP remains FAIL-CLOSED/UNAVAILABLE by design; this is "
            "not a completeness gap."
        ),
    }


# ── France: engine input resolution (ZP-FR-ENG-001 Phase 5 wiring) ────
# engine/countries/france.py is a pure function of PayrollContext's
# france_* fields; this is the ONE place those fields are resolved from the
# France authority tables, for every calculation entry point (preview,
# batch generation, manual payslip). Nothing here guesses: anything
# unresolvable is passed through empty, and the engine blocks with the
# precise reason (FR-027) — surfaced as FranceCalculationBlockedException.

def _load_fr_ytd(db: Session, employee_id: int, payroll_date, exclude_run_id: Optional[int] = None) -> dict:
    """The RGDU/CSG accumulator state after the employee's latest earlier
    France payslip in the same calendar year (read from its frozen
    fr_calculation_snapshot["ytd_after"]) — empty for the first period."""
    if payroll_date is None:
        return {}
    query = (db.query(PayslipItem)
             .join(PayrollRun, PayrollRun.id == PayslipItem.payroll_run_id)
             .filter(PayslipItem.employee_id == employee_id,
                     PayslipItem.fr_calculation_snapshot.isnot(None),
                     PayslipItem.status != PayslipStatus.FAILED,
                     PayrollRun.pay_date < payroll_date,
                     PayrollRun.pay_date >= date(payroll_date.year, 1, 1)))
    if exclude_run_id is not None:
        query = query.filter(PayrollRun.id != exclude_run_id)
    previous = query.order_by(PayrollRun.pay_date.desc(), PayslipItem.id.desc()).first()
    if previous is None:
        return {}
    return dict((previous.fr_calculation_snapshot or {}).get("ytd_after") or {})


def _resolve_france_calc_inputs(db: Session, organization_id: int, employee, payroll_date,
                                exclude_run_id: Optional[int] = None) -> dict:
    """Build build_context_from_employee(france_inputs=...) for one France
    employee on payroll_date: the SIRET rate pack in force (the employee's
    compliance_fields["siret"], or the org's only establishment), the PAS
    rate governing that date, prior-period YTD, and contract facts."""
    compliance = getattr(employee, "compliance_fields", None) or {}
    siret = (compliance.get("siret") or "").strip() or None

    packs = [p for p in list_france_establishment_rate_packs(db, organization_id)
             if p.effective_from <= payroll_date and (p.effective_to is None or p.effective_to >= payroll_date)]
    if siret:
        packs = [p for p in packs if p.siret == siret]
    elif len({p.siret for p in packs}) > 1:
        packs = []   # several establishments and no SIRET on the employee → engine blocks, never guesses
    pack = packs[0] if packs else None

    establishment = {}
    if pack is not None:
        profile = db.query(EmployerFranceProfile).filter(
            EmployerFranceProfile.organization_id == organization_id).first()
        effectif = pack.effectif
        if effectif is None and profile is not None and profile.effectif_state:
            years = [int(k) for k in profile.effectif_state if str(k).isdigit() and int(k) < payroll_date.year]
            if years:
                effectif = (profile.effectif_state.get(str(max(years))) or {}).get("value")
        establishment = {
            "siret": pack.siret,
            "commune_insee": pack.commune_insee,
            "at_mp_rate_pct": pack.at_mp_rate_pct,
            "vm_rate_pct": pack.vm_rate_pct,
            "vm_threshold_applies": pack.vm_threshold_applies,
            "fnal_class": pack.fnal_class,
            "cfp_class": pack.cfp_class,
            "effectif": effectif,
        }

    pas_row = get_active_france_pas_rate(db, organization_id, employee.id, as_of=payroll_date)
    pas = {}
    if pas_row is not None:
        pas = {
            "rate_type": pas_row.rate_type,
            "rate_pct": pas_row.rate_pct,
            "rate_id": pas_row.dgfip_rate_id,
            "short_contract": bool(compliance.get("short_contract")),
            "apprentice": bool(compliance.get("apprentice")),
        }

    idcc_minimum = compliance.get("idcc_minimum")
    return {
        "france_payroll_date": payroll_date,
        "france_pas": pas,
        "france_establishment": establishment,
        "france_ytd": _load_fr_ytd(db, employee.id, payroll_date, exclude_run_id=exclude_run_id),
        "france_cadre": str(compliance.get("cadre", "")).lower() in ("1", "true", "yes", "cadre"),
        "france_idcc_minimum": Decimal(str(idcc_minimum)) if idcc_minimum not in (None, "") else None,
        "france_social_coverage": compliance.get("social_coverage") or "GENERAL",
        "france_employee_id": employee.id,
        "france_organization_id": organization_id,
    }


def _jsonable_decimal(value):
    if isinstance(value, Decimal):
        return str(value)
    if isinstance(value, dict):
        return {k: _jsonable_decimal(v) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [_jsonable_decimal(v) for v in value]
    if isinstance(value, date):
        return value.isoformat()
    return value


def _fr_payslip_snapshot(result) -> Optional[dict]:
    """PayslipItem.fr_calculation_snapshot for a France result (None for
    every other country) — the three nets, PAS provenance, trace, RGDU and
    ytd_after, JSON-safe."""
    if getattr(result, "fr_net_social", None) is None:
        return None
    return _jsonable_decimal({
        "net_social": result.fr_net_social,
        "net_imposable": result.fr_net_imposable,
        "net_a_payer": (result.fr_bases or {}).get("net_a_payer"),
        "employee_total": result.fr_employee_total,
        "employer_total": result.fr_employer_total,
        "pas": {"withheld": result.fr_pas_withheld, "rate_type": result.fr_pas_rate_type,
                "rate_pct": result.fr_pas_rate_pct, "rate_id": result.fr_pas_rate_id},
        "bases": result.fr_bases,
        "contributions": result.fr_contributions,
        "calculation": result.fr_calculation_snapshot,
        "ytd_after": result.fr_ytd_after,
    })


def _se_payslip_snapshot(result) -> "dict | None":
    """PayslipItem.se_calculation_snapshot for a Sweden result (None for
    every other country) — the withholding strategy + table/column actually
    applied, the employer-contribution cohort and component breakdown, SLP,
    plan premiums and se_calculation_trace verbatim, JSON-safe. Gated on
    se_employee_total, the one key the Sweden engine always sets. A snapshot,
    never a re-derivation: spec §29 requires historical payroll to replay the
    rule pack of the ORIGINAL payment date, and this is that evidence."""
    if getattr(result, "se_employee_total", None) is None:
        return None
    return _jsonable_decimal({
        "withholding": {
            "amount": result.se_preliminary_tax,
            "strategy": result.se_tax_strategy,
            "unrounded": result.se_withholding_unrounded,
            "table": result.se_tax_table,
            "column": result.se_tax_column,
            "tax_status": result.se_tax_status,
            "income_role": result.se_income_role,
        },
        "employer": {
            "amount": result.se_employer_contribution,
            "rate": result.se_employer_contribution_rate,
            "cohort": result.se_employer_contribution_cohort,
            "base": result.se_employer_contribution_base,
            "components": result.se_employer_contribution_components,
            "youth_applied": result.se_youth_applied,
            "month_compensation": result.se_month_compensation,
        },
        "slp": result.se_slp,
        "pension": {
            "plan": result.se_pension_plan,
            "employee": result.se_occupational_pension_employee,
            "employer": result.se_occupational_pension_employer,
        },
        "employee_total": result.se_employee_total,
        "employer_total": result.se_employer_total,
        "trace": result.se_calculation_trace,
    })


def _france_blocked(exc) -> "FranceCalculationBlockedException":
    return FranceCalculationBlockedException(exc.code, exc.message, trace={"code": exc.code, "message": exc.message})


def _ie_payslip_snapshot(result) -> "dict | None":
    """PayslipItem.ie_calculation_snapshot for an Ireland result (None for
    every other country) — the applied RPN, each tax head's own figure, the
    MyFutureFund state, the LPT instruction, and ie_calculation_trace
    verbatim, JSON-safe.

    Gated on ie_employee_total (not ie_paye) because that is the one key
    the Ireland engine always sets alongside the others: it is the total of
    employee deductions, so its presence means an Irish calculation really
    ran, rather than merely that a field happened to be non-None.

    Deliberately a snapshot, never a re-derivation (IE-045): ie_rpn_hash and
    the RPN's own values are what make a finalized payslip reproducible after
    Revenue later reissues or supersedes that RPN.
    """
    if getattr(result, "ie_employee_total", None) is None:
        return None
    return _jsonable_decimal({
        # The Revenue instruction actually applied. ie_paye_basis is the
        # important one: it is the only way to tell a real RPN-derived PAYE
        # from the Emergency treatment (or the blocked state) after the fact.
        "rpn": {
            "rpn_number": result.ie_rpn_number,
            "snapshot_id": result.ie_rpn_snapshot_id,
            "raw_hash": result.ie_rpn_hash,
            "issued_at": result.ie_rpn_issued_at,
        },
        "paye": {
            "basis": result.ie_paye_basis,
            "amount": result.ie_paye,
            "unrounded": result.ie_paye_unrounded,
            "standard_rate_pay": result.ie_standard_rate_pay,
            "higher_rate_pay": result.ie_higher_rate_pay,
            "tax_credit_applied": result.ie_tax_credit_applied,
        },
        "usc": {
            "amount": result.ie_usc,
            "unrounded": result.ie_usc_unrounded,
        },
        "prsi": {
            "subclass": result.ie_prsi_class,
            "declared_subclass": result.ie_prsi_declaration,
            "employee": result.ie_employee_prsi,
            "employer": result.ie_employer_prsi,
            "ax_credit": result.ie_prsi_ax_credit,
            "contribution_weeks": result.ie_prsi_contribution_weeks,
            "weekly_reckonable": result.ie_prsi_weekly_reckonable,
        },
        "myfuturefund": {
            "employee": result.ie_mff_employee,
            "employer": result.ie_mff_employer,
            # Informational only — the State top-up is administered by
            # NAERSA and is never deducted from pay (IE-018).
            "state_topup": result.ie_mff_state_topup,
            "status": result.ie_mff_status,
            "contributory": result.ie_mff_contributory,
            "ceased_reason": result.ie_mff_ceased_reason,
        },
        "lpt": {
            "amount": result.ie_lpt,
            "instructed": result.ie_lpt_instructed,
            "rate_pct": result.ie_lpt_rate_pct,
        },
        "pension": {
            "employee_prsc": result.ie_employee_pension,
            "employer_prsc": result.ie_employer_pension,
        },
        "labour": {
            # The NMW band and the effective hourly rate the block was
            # evaluated on — the evidence an inspector asks for (IE-035).
            "nmw_rate": result.ie_nmw_rate,
            "nmw_band": result.ie_nmw_band,
            "effective_hourly": result.ie_effective_hourly,
        },
        "employee_total": result.ie_employee_total,
        "tax_year": result.ie_tax_year,
        # ie_calculation_trace already carries inputs/bases/rates/band
        # selection/rounding for every head; ytd_after is the accumulator
        # state the NEXT period reads back (IE-023/IE-024/IE-025).
        "calculation": result.ie_calculation_trace,
        "ytd_after": result.ie_ytd_after,
    })


def _resolve_germany_calc_inputs(db: Session, organization_id: int, employee, payroll_date) -> dict:
    from app.modules.payroll.engine.jurisdictions.germany.pap.core import (
        GermanyCalculationError, resolve_pv_child_category,
    )

    # Phase 8DI — resolve the applicable Germany Compliance Pack version
    # ONCE per calculation, and thread its id through every registry
    # resolver below as an ADDITIVE filter (see resolve_applicable_germany_
    # pack's own docstring for why "no pack found" falls back to plain
    # effective-dated resolution rather than failing closed). This is the
    # one and only place this wiring happens — every resolver function
    # itself defaults jurisdiction_pack_id to None and is unchanged for
    # every other caller (tests, super_admin endpoints, etc.).
    applicable_pack = resolve_applicable_germany_pack(db, as_of=payroll_date)
    pack_id = applicable_pack.id if applicable_pack is not None else None

    profile = resolve_employee_statutory_profile(db, employee.id, organization_id, as_of=payroll_date)
    pap_asset = resolve_germany_pap_asset(db, payroll_date)
    ceiling_gkv_pv = resolve_germany_contribution_ceiling(db, "GKV_PV", as_of=payroll_date, jurisdiction_pack_id=pack_id)
    ceiling_rv_alv = resolve_germany_contribution_ceiling(db, "RV_ALV", as_of=payroll_date, jurisdiction_pack_id=pack_id)

    health_fund = None
    u1_tariff = None
    pv_configuration = None
    church_tax_exception = None
    if profile is not None:
        health_fund_code = getattr(profile, "de_health_fund_code", None)
        if health_fund_code:
            health_fund = resolve_germany_health_fund(db, health_fund_code, as_of=payroll_date, jurisdiction_pack_id=pack_id)
            # Phase 8W: resolve the employer's selected U1 tariff at this fund
            u1_tariff_id = getattr(profile, "de_u1_tariff_id", None)
            if u1_tariff_id:
                u1_tariff = resolve_germany_u1_tariff(db, health_fund_code, u1_tariff_id, as_of=payroll_date, jurisdiction_pack_id=pack_id)
        if getattr(profile, "de_health_insurance_status", None) != "PRIVATE":
            try:
                category = resolve_pv_child_category(profile)
                is_saxony = bool(getattr(profile, "de_saxony", False))
                pv_configuration = resolve_germany_pv_configuration(db, category, is_saxony, as_of=payroll_date, jurisdiction_pack_id=pack_id)
            except GermanyCalculationError:
                # Category itself can't be determined from this profile —
                # left None here; germany.py's calculate() re-derives the
                # category itself and raises the precise
                # GermanyStatutoryProfileMissingError, rather than this
                # resolver guessing or swallowing the real reason.
                pv_configuration = None

        # Phase 8AM — resolve church-tax exception (sub-Land override, e.g.
        # Bad Wimpfen Roman Catholic 9% within Baden-Württemberg's 8%).
        # Only resolved when all three required profile fields are present:
        # de_church_tax_land, de_church_tax_denomination,
        # de_church_tax_municipality_postal_code. Returns None (never
        # raises, never guesses) if any field is missing or no PUBLISHED
        # exception matches — the engine then falls back to the ordinary
        # Land rate exactly as before this phase.
        church_tax_land = getattr(profile, "de_church_tax_land", None)
        church_tax_denomination = getattr(profile, "de_church_tax_denomination", None)
        church_tax_municipality_postal_code = getattr(profile, "de_church_tax_municipality_postal_code", None)
        if church_tax_land and church_tax_denomination and church_tax_municipality_postal_code:
            church_tax_exception = resolve_germany_church_tax_exception(
                db, church_tax_land, church_tax_denomination, church_tax_municipality_postal_code, as_of=payroll_date,
                jurisdiction_pack_id=pack_id,
            )

    # Phase 8X — resolve the four-dimension earning taxability (spec §15)
    # for the two earning types the current engine actually receives as
    # discrete inputs: REGULAR_SALARY (steady RE4 wage = gross net of the
    # bonus) and BONUS_ANNUAL_BONUS (the SONSTB-routed bonus). Absent /
    # unpublished -> None -> the engine surfaces NOT_CONFIGURED in its
    # trace instead of assuming a classification. Resolving both here keeps
    # the engine/frontend and the batch path agreeing on which rows applied
    # for one employee on one payroll date.
    earning_taxability = {
        "REGULAR_SALARY": resolve_germany_earning_taxability_rule(db, "REGULAR_SALARY", as_of=payroll_date, jurisdiction_pack_id=pack_id),
        "BONUS_ANNUAL_BONUS": resolve_germany_earning_taxability_rule(db, "BONUS_ANNUAL_BONUS", as_of=payroll_date, jurisdiction_pack_id=pack_id),
    }
    # Phase 8BK — resolved once per calculation, exactly like
    # earning_taxability above; None entries mean "fall back to the
    # hardcoded default" (see engine/countries/germany.py's
    # _resolve_minijob_midijob_value).
    minijob_midijob_parameters = resolve_all_minijob_midijob_parameters(db, as_of=payroll_date, jurisdiction_pack_id=pack_id)

    return dict(
        statutory_profile=profile,
        pap_asset=pap_asset,
        health_fund=health_fund,
        u1_tariff=u1_tariff,
        ceiling_gkv_pv=ceiling_gkv_pv,
        ceiling_rv_alv=ceiling_rv_alv,
        pv_configuration=pv_configuration,
        earning_taxability=earning_taxability,
        church_tax_exception=church_tax_exception,
        minijob_midijob_parameters=minijob_midijob_parameters,
        # Phase 8DI — audit/debug metadata: which pack version (if any)
        # governed this calculation. Not consumed by germany.py's math,
        # only carried through for traceability (Phase 18's payslip-
        # snapshot requirement — see the report for how far this was wired
        # into the persisted payslip this phase).
        applicable_germany_pack_id=pack_id,
        applicable_germany_pack_version=(applicable_pack.version if applicable_pack is not None else None),
    )


def preview_germany_calculation(db: Session, organization_id: int, employee_id: int, payroll_date=None) -> dict:
    """Phase 7 QA/diagnostic endpoint (spec's own §27 allowance for "a
    protected diagnostic endpoint... genuinely useful for QA"). Read-only —
    never writes anything, never mutates a finalized payroll, never
    accepts a caller-supplied PAP version/statutory rate (every value is
    server-resolved from the authoritative registries, exactly like a
    real run would). Returns either the full resolved calculation (never
    reachable today — see germany.py) or the block code/message/trace, so
    Tax Operations/QA can see exactly what's missing before attempting a
    real payroll run for this employee."""
    from app.modules.payroll.engine.resolver import calculate_payroll, build_context_from_employee
    from app.modules.payroll.engine.jurisdictions.germany.pap.core import GermanyCalculationError
    from app.modules.payroll.engine.countries.france import FranceCalculationBlockedError

    employee = get_employee_by_id(db, employee_id, organization_id)
    payroll_date = payroll_date or date.today()
    country = _resolve_employee_country(db, organization_id, getattr(employee, "country_code", None))
    if country != "DE":
        raise BadRequestException(
            f"Employee {employee_id}'s resolved country is '{country}', not 'DE' — "
            "this diagnostic endpoint is Germany-specific."
        )

    ctc = Decimal(str(getattr(employee, "ctc", 0) or 0))
    monthly_gross = _round2(ctc / MONTHS_PER_YEAR) if ctc else Decimal("0")
    org_opted_in = _org_uses_canonical_tax_pack(db, organization_id)
    rate_map, slabs, _canonical_rates, _pack = _resolve_effective_rate_inputs(
        db, organization_id, country, payroll_date, org_opted_in,
    )
    resolved = _resolve_germany_calc_inputs(db, organization_id, employee, payroll_date)

    ctx = build_context_from_employee(
        employee, gross=monthly_gross, basic=monthly_gross,
        country=country, rate_map=rate_map, slabs=slabs,
        germany_statutory_profile=resolved["statutory_profile"],
        germany_pap_asset=resolved["pap_asset"],
        germany_health_fund=resolved["health_fund"],
        germany_u1_tariff=resolved["u1_tariff"],
        germany_earning_taxability=resolved["earning_taxability"],
        germany_ceiling_gkv_pv=resolved["ceiling_gkv_pv"],
        germany_ceiling_rv_alv=resolved["ceiling_rv_alv"],
        germany_pv_configuration=resolved["pv_configuration"],
        germany_church_tax_exception=resolved["church_tax_exception"],
        germany_minijob_midijob_parameters=resolved["minijob_midijob_parameters"],
        germany_employee_id=employee.id,
        germany_organization_id=organization_id,
        germany_payroll_date=payroll_date,
    )
    try:
        result = calculate_payroll(ctx, "standard")
    except GermanyCalculationError as exc:
        return {
            "employeeId": employee_id,
            "payrollDate": str(payroll_date),
            "blocked": True,
            "blockedReasonCode": exc.code,
            "blockedReasonMessage": exc.message,
            "trace": exc.trace.to_dict() if exc.trace else None,
        }
    return {
        "employeeId": employee_id,
        "payrollDate": str(payroll_date),
        "blocked": False,
        "result": {
            "monthlyGross": float(result.gross),
            "monthlyEmployeePf": float(result.employee_pf),
            "monthlyEmployerPf": float(result.employer_pf),
            "monthlyEmployeeEsi": float(result.employee_esi),
            "monthlyEmployerEsi": float(result.employer_esi),
            "monthlyChurchTax": float(result.church_tax),
            "monthlyTax": float(result.tds),
            "monthlyNet": float(result.net_pay),
        },
        "trace": result.germany_calculation_snapshot,
    }


# ── UK: centralized configuration resolver ─────────────────────────────
# One resolver for every UK calculation entry point (preview, generation,
# recalculation, manual payslip) — see build_context_from_employee's
# callers. Layers, in precedence order:
#   UK National (canonical or org-synced, via _resolve_effective_rate_inputs —
#       already org-override-aware, so "organization override" isn't a
#       separate step here, it falls out of calling this with the real
#       organization_id)
#       overridden-by
#   Sub-jurisdiction (England/Scotland/Wales/Northern Ireland, via
#       get_state_scoped_config)
# "Employee-specific statutory profile" (tax_code/ni_category/
# study_loan_plan) isn't a rate_map layer either — engine/countries/uk.py
# reads those straight off PayrollContext and applies them at calculation
# time (tax-code interpretation, NI category bands), not as a config
# merge step. Hardcoded module constants in uk.py remain the emergency
# fallback of last resort, used only when NOTHING resolves at any layer —
# resolve_jurisdiction_parameter already logs when that happens.
_UK_SUB_JURISDICTIONS = {
    "england": "England", "scotland": "Scotland", "wales": "Wales", "northern ireland": "Northern Ireland",
}
# ZP-TAX-UK-2026-27-001 section 6.1: the S/C tax-code prefix is the ONLY
# HMRC-sanctioned region signal ("Do not infer a Scottish or Welsh tax
# regime from the employer's office or worksite"). No prefix means
# England/Northern Ireland/main UK PAYE — this map only ever names the
# two nations that actually have a distinct prefix.
_UK_TAX_CODE_REGION_PREFIX = {"S": "Scotland", "C": "Wales"}


def _normalize_uk_sub_jurisdiction(work_state: Optional[str]) -> Optional[str]:
    """The ONE place a UK jurisdiction name is ever compared against —
    engine/countries/uk.py itself never does `if work_state == "Scotland"`;
    it only reads whatever this resolver already put into
    ctx.state_slabs/ctx.state_rate_map. Unrecognized/blank work_state
    resolves to None (no sub-jurisdiction — national rules only), exactly
    like today's behavior for any non-Scotland employee."""
    if not work_state:
        return None
    return _UK_SUB_JURISDICTIONS.get(work_state.strip().lower())


def _resolve_org_jurisdiction_state_fallback(db: Session, organization_id: int, country: str) -> Optional[str]:
    """The organization's own configured jurisdiction state (Company
    Details / Compliance) — used ONLY as a fallback when an employee has
    no work_state of their own set. Real-world default: most employees
    work wherever the organization itself is registered unless told
    otherwise, so a state-scoped component (India's Professional Tax, US
    state income tax, ...) shouldn't silently resolve to nothing just
    because the employee record's work_state field was never filled in.
    Only applies when the org's own jurisdiction country matches —
    otherwise this org has no state to offer for THIS country anyway."""
    if not organization_id:
        return None
    compliance = (
        db.query(CompanyComplianceDetails)
        .filter(CompanyComplianceDetails.organization_id == organization_id)
        .first()
    )
    if not compliance or not compliance.jurisdiction_state:
        return None
    if _normalize_country(compliance.jurisdiction_country) != _normalize_country(country):
        return None
    return compliance.jurisdiction_state



# ZP-TAX-CA-2026-001 §5 — Province of Employment (POE). Covers the
# single-physical-establishment, TRUE multi-establishment (via
# EmployeeEstablishment — see _resolve_ca_multi_establishment_poe),
# remote-attachment, payroll-fallback and CA-XP (Phase 9) cases.
_CA_PROVINCES_TERRITORIES = {"ON", "QC", "BC", "AB", "MB", "SK", "NS", "NB", "NL", "PE", "YT", "NT", "NU"}
# CA-XP (§3: "In Canada beyond limits of a province/territory") — a
# deliberately-typed work_state, not an inferred one. Recognizing it
# here only affects poe_result/poe_reason (the audit snapshot) and which
# state-scoped config attempts to load (none, same as before this
# existed, since "XP" was never a real province) — it does NOT change
# ctx.work_state itself (every calculate() call site already reads the
# employee's RAW work_state directly, not this resolved value, as
# documented everywhere else in this file), so this needs no rollout
# switch: no existing employee could have had "XP" mean anything before
# Phase 8's beyond-province surtax existed to consume it, and the actual
# tax calculation for such an employee is unchanged by this fix — only
# its audit trail improves from the misleading "UNRESOLVED" to the
# doc's own correct "BEYOND_LIMITS" vocabulary.
_CA_BEYOND_LIMITS_CODE = "XP"


def _resolve_ca_multi_establishment_poe(establishments: Optional[list]) -> tuple[Optional[str], str]:
    """§5 step 3: an employee who physically reports to TWO OR MORE
    employer establishments resolves to whichever they spend the most
    time at (EmployeeEstablishment.time_allocation_pct), tie-broken by
    whichever they most recently worked (last_worked_date — NULL/never-
    worked always loses a tie against a real date). `establishments` is
    the raw list of a single employee's EmployeeEstablishment rows (or
    dicts with the same keys — either works, only attribute/dict access
    differs below).

    Returns (None, "UNRESOLVED") when fewer than two ACTIVE, recognized-
    province rows are given: an employee with 0 or 1 such row has no
    "multi" case to resolve, and the caller falls through to the
    existing single-work_state/remote/fallback chain completely
    unaffected, exactly as if this table didn't exist for them."""
    def _get(e, key):
        return e.get(key) if isinstance(e, dict) else getattr(e, key, None)

    active = [
        e for e in (establishments or [])
        if _get(e, "is_active") is not False
        and _get(e, "province")
        and str(_get(e, "province")).strip().upper() in _CA_PROVINCES_TERRITORIES
    ]
    if len(active) < 2:
        return None, "UNRESOLVED"

    def _sort_key(e):
        pct = _get(e, "time_allocation_pct") or Decimal("0")
        last_worked = _get(e, "last_worked_date") or date.min
        return (pct, last_worked)

    best = max(active, key=_sort_key)
    return str(_get(best, "province")).strip().upper(), "PHYSICAL_MULTI"


def _resolve_ca_poe_with_source(
    work_state: Optional[str], org_jurisdiction_state: Optional[str],
    remote_work_agreement: bool = False, remote_attachment_province: Optional[str] = None,
    establishments: Optional[list] = None,
) -> tuple[Optional[str], str]:
    """Returns (poe_result, poe_reason) using the doc's own machine-
    readable reason-code vocabulary, checked in the doc's own §5
    precedence order: BEYOND_LIMITS (work_state is literally the CA-XP
    code "XP" — a deliberate declaration, per §3/§5 step 7, that this
    employer/employee genuinely has no Canadian establishment; see
    _CA_BEYOND_LIMITS_CODE's own comment for why this needs no rollout
    switch) wins first, ahead of every physical-establishment check
    since "XP" is never itself a real province code, so they can never
    collide; PHYSICAL_MULTI (§5 step 3 — two or more active
    EmployeeEstablishment rows on file; see
    _resolve_ca_multi_establishment_poe) next, since a genuinely
    multi-establishment employee's single work_state field is at best a
    stale snapshot of wherever they were last assigned, not this
    resolver's real answer once establishment records exist for them;
    PHYSICAL_SINGLE (the employee's own recorded work_state — treated as
    their one physical reporting establishment) next; REMOTE_ATTACHED (a
    full-time remote-work agreement is on file, with a declared
    attachment province) only applies when there's no physical
    work_state — an employee who reports somewhere physical is never
    overridden by a stale/unrelated remote-agreement flag;
    PAYROLL_FALLBACK (none of the above; falls back to the org's own
    jurisdiction state, same fallback every other country already uses);
    or UNRESOLVED (nothing is a recognized province/territory code and
    no explicit CA-XP declaration either — returns None rather than
    passing bad data through to jurisdiction-scoped config lookup, or
    guessing that an employee with simply-not-yet-entered data is
    somehow genuinely beyond-province). remote_agreement_effective_from
    is stored as evidence but not enforced against the payroll date here
    — no other employee declaration field (TD1, tax_code,
    w4_filing_status, ...) in this codebase enforces its own effective-
    dating at this layer either, only the current value is ever read."""
    if work_state and work_state.strip().upper() == _CA_BEYOND_LIMITS_CODE:
        return _CA_BEYOND_LIMITS_CODE, "BEYOND_LIMITS"
    multi_result, multi_reason = _resolve_ca_multi_establishment_poe(establishments)
    if multi_result:
        return multi_result, multi_reason
    if work_state and work_state.strip().upper() in _CA_PROVINCES_TERRITORIES:
        return work_state.strip().upper(), "PHYSICAL_SINGLE"
    if remote_work_agreement and remote_attachment_province and remote_attachment_province.strip().upper() in _CA_PROVINCES_TERRITORIES:
        return remote_attachment_province.strip().upper(), "REMOTE_ATTACHED"
    if org_jurisdiction_state and org_jurisdiction_state.strip().upper() in _CA_PROVINCES_TERRITORIES:
        return org_jurisdiction_state.strip().upper(), "PAYROLL_FALLBACK"
    return None, "UNRESOLVED"


def _resolve_country_aware_state(country: str, employee, literal_state: Optional[str], db: Session = None, organization_id: int = None) -> tuple[Optional[str], Optional[str]]:
    """Returns (resolution_state, poe_reason) — resolution_state is the
    value actually passed to _resolve_effective_rate_inputs's/
    get_state_scoped_config's `state` param for rate/slab lookup;
    poe_reason is only ever non-None for CA (ZP-TAX-CA-2026-001 §5's
    machine-readable reason-code vocabulary — see
    _resolve_ca_poe_with_source), None for every other country. Callers
    that don't need the reason can discard it (`state, _reason = ...`).

    Base layer (every country): if the employee has no work_state of
    their own, fall back to the organization's own configured
    jurisdiction state (_resolve_org_jurisdiction_state_fallback) —
    without this, a state-scoped component silently computes to zero for
    every employee who was never assigned a work_state, even when the
    organization itself has a clear, single jurisdiction on file.

    UK layer (on top): the tax-code-prefix-derived sub-jurisdiction wins
    over either of the above when the employee's own HMRC code carries
    one — see _resolve_uk_sub_jurisdiction_with_source.

    CA layer (on top): resolved via the POE reason-code resolver above
    (multi-establishment -> physical work_state -> remote attachment ->
    payroll fallback) instead of the raw fallback chain, so an
    unrecognized province code resolves to no jurisdiction rather than
    being passed through as-is — see _resolve_ca_poe_with_source.
    Previously this reason was computed and immediately discarded
    (ZP-TAX-CA-2026-001 CA-D03/AC-07 require it persisted into the
    calculation snapshot) — see _compute_payslip_values'/
    add_payslip_item's `poe_snapshot`."""
    org_fallback_state = None
    if not literal_state and db is not None:
        org_fallback_state = _resolve_org_jurisdiction_state_fallback(db, organization_id, country)
    effective_state = literal_state or org_fallback_state

    if country == "UK":
        sub_jurisdiction, _source = _resolve_uk_sub_jurisdiction_with_source(getattr(employee, "tax_code", None), effective_state)
        return sub_jurisdiction, None
    if country == "CA":
        establishments = []
        employee_id = getattr(employee, "id", None)
        if db is not None and employee_id:
            establishments = (
                db.query(EmployeeEstablishment)
                .filter(
                    EmployeeEstablishment.employee_id == employee_id,
                    EmployeeEstablishment.is_active.is_(True),
                )
                .all()
            )
        poe_result, reason = _resolve_ca_poe_with_source(
            literal_state, org_fallback_state,
            remote_work_agreement=bool(getattr(employee, "remote_work_agreement", False)),
            remote_attachment_province=getattr(employee, "remote_attachment_province", None),
            establishments=establishments,
        )
        return poe_result, reason
    return effective_state, None


def _resolve_uk_sub_jurisdiction_with_source(tax_code: Optional[str], work_state: Optional[str]) -> tuple[Optional[str], str]:
    """Region determination per ZP-TAX-UK-2026-27-001 AC-03/AC-04: the
    employee's own HMRC tax-code prefix wins whenever it's present —
    work_state (a worksite/location field) is only a fallback for an
    employee who has no tax code yet (e.g. a brand-new starter still
    pending their first HMRC notice). Returns (sub_jurisdiction, source)
    where source is "TAX_CODE_PREFIX" or "WORK_STATE_FALLBACK", so the
    caller can persist and display which rule actually decided."""
    from app.modules.payroll.engine.countries.uk import interpret_tax_code

    region_prefix = interpret_tax_code(tax_code, Decimal("0"))["region_prefix"]
    if region_prefix:
        return _UK_TAX_CODE_REGION_PREFIX[region_prefix], "TAX_CODE_PREFIX"
    return _normalize_uk_sub_jurisdiction(work_state), "WORK_STATE_FALLBACK"


@dataclass
class ResolvedUKPayrollConfiguration:
    """Return type of resolve_uk_configuration() — field names deliberately
    match build_context_from_employee()'s kwargs so a caller can spread
    the relevant ones straight in. `source_map` and the two pack
    references exist for traceability (Section 16: a payslip should be
    able to name which pack version applied) — snapshotting them onto the
    payslip is the caller's job, this resolver only exposes them."""
    rate_map: dict
    slabs: list
    state_rate_map: dict
    state_slabs: list
    sub_jurisdiction: Optional[str]
    sub_jurisdiction_source: str
    national_pack: Optional["JurisdictionPack"]
    sub_pack: Optional["JurisdictionPack"]
    canonical_rates: list
    source_map: dict


def resolve_uk_configuration(
    db: Session, organization_id: int, employee, payroll_date, tax_regime: Optional[str] = None,
) -> "ResolvedUKPayrollConfiguration":
    """The one centralized UK configuration resolver. Every UK calculation
    entry point should call this instead of assembling rate_map/slabs/
    state_rate_map/state_slabs ad hoc — see preview_payroll_run,
    _compute_payslip_values, and add_payslip_item, all updated to call
    this."""
    org_opted_in = _org_uses_canonical_tax_pack(db, organization_id)
    national_rate_map, national_slabs, canonical_rates, national_pack = _resolve_effective_rate_inputs(
        db, organization_id, "UK", payroll_date, org_opted_in, state=None, tax_regime=tax_regime,
    )

    sub_jurisdiction, sub_jurisdiction_source = _resolve_uk_sub_jurisdiction_with_source(
        getattr(employee, "tax_code", None), getattr(employee, "work_state", None),
    )
    sub_rate_map, sub_slabs = get_state_scoped_config(db, "UK", sub_jurisdiction, as_of=payroll_date)

    source_map = {key: "NATIONAL" for key in national_rate_map}
    source_map.update({key: "SUB_JURISDICTION" for key in sub_rate_map})
    # Sub-jurisdiction rate_map rows are layered OVER national, not a
    # replacement — real UK NI/Pension/thresholds aren't devolved at all
    # (this dict is empty for every sub-jurisdiction today), but a future
    # genuinely devolved parameter would correctly take precedence here
    # without any code change.
    resolved_rate_map = {**national_rate_map, **sub_rate_map}

    sub_pack = None
    if sub_jurisdiction:
        # Routed through the one canonical pack resolver (engine/tax_resolver.py)
        # instead of this function's own prior ad-hoc query — that query
        # didn't apply effective_from/effective_to filtering the way
        # _find_active_tax_pack does, which is exactly the class of bug
        # that silently made India's canonical pack unresolvable for
        # months (see the Fallback Removal effort). This function has no
        # live callers today, so the fix changes no observable behavior;
        # it closes the gap before this becomes a live one.
        from app.modules.payroll.engine.tax_resolver import find_active_tax_pack
        sub_pack = find_active_tax_pack(db, "UK", state=sub_jurisdiction, as_of=payroll_date)

    return ResolvedUKPayrollConfiguration(
        rate_map=resolved_rate_map, slabs=national_slabs,
        state_rate_map=sub_rate_map, state_slabs=sub_slabs,
        sub_jurisdiction=sub_jurisdiction, sub_jurisdiction_source=sub_jurisdiction_source,
        national_pack=national_pack, sub_pack=sub_pack,
        canonical_rates=canonical_rates or [], source_map=source_map,
    )


def sync_org_rates_from_canonical(
    db: Session, organization_id: int, country: str, state: Optional[str] = None,
    tax_regime: Optional[str] = None, payroll_date=None,
) -> dict:
    """Populate an org's own ContributionRate/TaxSlab rows (the ones the
    engine actually reads) FROM the canonical Super-Admin-owned rows for
    this jurisdiction, via engine/tax_resolver.py. Extends the exact
    pattern super_admin/service.py's seed_global_statutory_rates_from_defaults
    already established — idempotent, safe to call repeatedly.

    No-ops (returns synced=False) if no canonical tax pack exists yet for
    this jurisdiction, leaving the org's existing rows/hardcoded-default
    seed path completely untouched — this function only ever ADDS a new
    source, it never removes the fallback.
    """
    from app.modules.payroll.engine.tax_resolver import resolve_tax_configuration

    country = _normalize_country(country)
    canonical_rates, canonical_slabs, pack = resolve_tax_configuration(
        db, country, state=state, tax_regime=tax_regime, payroll_date=payroll_date,
    )
    if not pack:
        return {"synced": False, "reason": "no canonical tax pack configured for this jurisdiction"}

    # Additive state layer (India's state-scoped Professional Tax, etc.):
    # resolve_tax_configuration above is winner-take-all — for a state
    # whose own pack has no income-tax slabs (e.g. Telangana's PT-only
    # pack), it correctly returns the COUNTRY pack instead (the 2026-08-21
    # PT-pack-override fix), which means a single sync call can never
    # produce both the country's income-tax brackets AND the state's own
    # PT_FLAT brackets — whichever call happened last would wipe the
    # other's rows out of this org's cache (TaxSlab sync below is a full
    # delete-then-recreate per (org, country), not additive). Folding in
    # get_state_scoped_config's rows here — the SAME additive lookup the
    # live engine already uses for ctx.state_rate_map/ctx.state_slabs —
    # closes that gap: MARGINAL_RATE rows are excluded from this extra
    # layer so a state that legitimately has its OWN real income-tax pack
    # (UK Scotland) never gets its rows duplicated (they're already in
    # canonical_slabs via resolve_tax_configuration itself in that case).
    if state:
        state_rate_map, state_slabs = get_state_scoped_config(db, country, state, as_of=payroll_date)
        existing_rate_keys = {_normalize_engine_component_key(cr.component_key) for cr in canonical_rates}
        canonical_rates = canonical_rates + [
            cr for key, cr in state_rate_map.items() if key not in existing_rate_keys
        ]
        existing_slab_ids = {s.id for s in canonical_slabs}
        canonical_slabs = canonical_slabs + [
            s for s in state_slabs
            if s.id not in existing_slab_ids and getattr(s, "rule_type", None) not in (None, "MARGINAL_RATE")
        ]

    for cr in canonical_rates:
        existing = (
            db.query(ContributionRate)
            .filter(
                ContributionRate.organization_id == organization_id,
                ContributionRate.jurisdiction_country == country,
                ContributionRate.component_key == cr.component_key,
            )
            .first()
        )
        if not existing and cr.label:
            # The canonical row's component_key may not be spelled the same
            # way as the org's existing row for the same real-world
            # component (e.g. Super Admin typed "PF"/"ESI"/"PT" in
            # Statutory Rates while the org's own seed used "pf"/"esi"/
            # "pt", or the labels differ only by a trailing abbreviation —
            # "Employee State Insurance" vs "Employee State Insurance
            # (ESI)") — an exact-key miss would otherwise INSERT a second,
            # visibly-duplicate row instead of updating the org's existing
            # one. Matching on the label with any trailing "(...)" suffix
            # stripped catches that, WITHOUT the false-positive risk a
            # broader substring/synonym search would have here — e.g. it
            # must never conflate the unrelated "ESI Wage Ceiling
            # (monthly)" Tax Parameter with the "esi" contribution rate
            # just because both mention "ESI"; stripping only a trailing
            # parenthetical and requiring the REST of the label to match
            # exactly avoids that (their non-parenthetical text differs).
            wanted_key = _strip_trailing_paren(cr.label)
            for candidate in (
                db.query(ContributionRate)
                .filter(ContributionRate.organization_id == organization_id, ContributionRate.jurisdiction_country == country)
                .all()
            ):
                if candidate.label and _strip_trailing_paren(candidate.label) == wanted_key:
                    existing = candidate
                    break
        fields = dict(
            # Normalized here too, not just at the canonical write path —
            # a canonical row saved before that fix existed can still carry
            # a wrong-cased key, and every sync is the self-healing point
            # for exactly that (matches the label-based dedup pass below,
            # which already exists to clean up this same class of issue).
            component_key=_normalize_engine_component_key(cr.component_key),
            label=cr.label, employee_share=cr.employee_share, employer_share=cr.employer_share,
            total=cr.total, employee_rate_pct=cr.employee_rate_pct, employer_rate_pct=cr.employer_rate_pct,
            flat_amount=cr.flat_amount, sort_order=cr.sort_order,
            jurisdiction_pack_id=pack.id,
            # filing_status/tax_regime: same "field added to the model after
            # this copy list was first written, never retrofitted" gap found
            # 2026-09-17 in TaxSlab's own sync just above/below (see that
            # fix's own comment) — found here too on a full audit of this
            # function's OTHER copy list. filing_status is what AU's
            # AU_PAYG_COEFFICIENT/AU_STSL_COEFFICIENT bands and US's
            # filing-status-specific rows (e.g. a MFJ medicare_addl_thresh)
            # are keyed on; tax_regime is what India's Old/New regime split
            # is keyed on (get_contribution_rates' own regime-aware filter)
            # — without it, a synced row silently becomes "regime-agnostic"
            # instead of staying scoped to the regime it was actually
            # configured for.
            filing_status=cr.filing_status, tax_regime=cr.tax_regime,
        )
        if country == "SE":
            # Sweden's temporary youth reduction is defined by the ROW's own
            # payment-date window (SE-005) and sweden.py re-checks it from
            # these fields — dropping them here would turn a windowed rate
            # into an open-ended one on every synced org row. Scoped to SE so
            # no other country's synced rows change shape.
            fields.update(effective_from=cr.effective_from, effective_to=cr.effective_to,
                          text_value=cr.text_value)
        if existing:
            for k, v in fields.items():
                setattr(existing, k, v)
        else:
            db.add(ContributionRate(organization_id=organization_id, jurisdiction_country=country, **fields))
    db.flush()

    # Self-healing cleanup: a sync from before the label-fallback match
    # above (or a manual edit) may have already left two rows for the same
    # real-world component under different component_key spellings — same
    # label, two different values shown side by side on the org's
    # Compliance page. Collapse any such group down to the most-recently-
    # touched row (the one this sync just updated, or the latest manual
    # edit) so re-running this sync actually converges instead of leaving
    # old duplicates to drift forever.
    rows = (
        db.query(ContributionRate)
        .filter(ContributionRate.organization_id == organization_id, ContributionRate.jurisdiction_country == country)
        .all()
    )
    by_label: dict = {}
    for row in rows:
        if not row.label:
            continue
        key = _strip_trailing_paren(row.label)
        if not key:
            continue
        by_label.setdefault(key, []).append(row)
    def _last_touched(row):
        ts = row.updated_at or row.created_at
        # (has-a-timestamp, timestamp-or-placeholder, id) — every row compares
        # on the same shape regardless of whether ts ended up None, and id
        # (monotonically increasing, always set) breaks ties deterministically.
        return (ts is not None, ts or row.id, row.id)

    for group in by_label.values():
        if len(group) <= 1:
            continue
        group.sort(key=_last_touched, reverse=True)
        for stale in group[1:]:
            db.delete(stale)

    if canonical_slabs:
        # TaxSlab has no natural per-bracket unique key (brackets are
        # replaced as a whole set when the canonical version changes) —
        # the org's cached copy is fully regenerable from canonical data,
        # so replace-in-place is safe here, unlike ContributionRate above.
        db.query(TaxSlab).filter(
            TaxSlab.organization_id == organization_id, TaxSlab.jurisdiction_country == country,
        ).delete()
        for ts in canonical_slabs:
            db.add(TaxSlab(
                organization_id=organization_id, jurisdiction_country=country,
                min_amount=ts.min_amount, max_amount=ts.max_amount, rate_pct=ts.rate_pct,
                rate_label=ts.rate_label, tax_formula=ts.tax_formula, sort_order=ts.sort_order,
                rule_type=ts.rule_type, formula_expression=ts.formula_expression,
                # PT_FLAT (flat_amount/adjustment_amount) and NI_BAND
                # (ni_category/employer_rate_pct) fields were added to the
                # TaxSlab model after this copy list was first written and
                # were never added here — every org-scoped PT_FLAT/NI_BAND
                # row synced through this path silently lost its actual
                # amount/category, even though it was correctly selected
                # and copied for every other field.
                flat_amount=ts.flat_amount, adjustment_amount=ts.adjustment_amount,
                ni_category=ts.ni_category, employer_rate_pct=ts.employer_rate_pct,
                # filing_status: same "added after this copy list was
                # written, never retrofitted" gap as the fields above —
                # found 2026-09-17 via a real end-to-end AU payroll run
                # for a brand-new org. AU's Schedule 1/8 coefficient bands
                # (AU_PAYG_COEFFICIENT/AU_STSL_COEFFICIENT) and Extra-Pay
                # Calendar (AU_EXTRA_PAY_WITHHOLDING) all key their entire
                # band lookup on this column (the Scale/declaration-state/
                # calendar identifier — see models.TaxSlab's own rule_type
                # docstring) — every AU org auto-seeded through this path
                # (i.e. any org never explicitly "Apply Tax & Sync Rates"-
                # assigned to a canonical pack) silently computed $0 PAYG/
                # STSL/extra-pay withholding, logged only as a quiet
                # [au-payg-unconfigured]-style warning, never a visible
                # error. US's filing-status-tagged ContributionRate rows
                # were unaffected (a different table/function), but any
                # future country overloading TaxSlab.filing_status the
                # same way AU does would have hit this identically.
                filing_status=ts.filing_status,
                # Sweden (ZP-SE-ENG-001 §5): which authority table/column a
                # band belongs to — NULL on every other country's rows, so
                # copying it is inert elsewhere.
                tax_table_number=ts.tax_table_number, tax_column=ts.tax_column,
                # AMOUNT/PERCENT band basis + row dating, Sweden only: the SE
                # engine refuses a band with no declared basis, so dropping it
                # would block every synced org; scoped so SG/UK bands (which
                # also use assessment_basis) keep today's exact sync shape.
                **(dict(assessment_basis=ts.assessment_basis, effective_from=ts.effective_from,
                        effective_to=ts.effective_to) if country == "SE" else {}),
                # Each slab keeps its OWN originating pack id (a state
                # layer row folded in above came from a different pack
                # than `pack` itself) rather than being force-tagged with
                # the single resolved `pack.id` — otherwise a state PT
                # bracket's traceability would wrongly point at the
                # country income-tax pack it has nothing to do with.
                jurisdiction_pack_id=getattr(ts, "jurisdiction_pack_id", None) or pack.id,
            ))

    db.commit()
    return {
        "synced": True, "packId": pack.pack_id, "packVersion": pack.version,
        "contributionRates": len(canonical_rates), "taxSlabs": len(canonical_slabs),
    }


def list_canonical_tax_slabs(
    db: Session, jurisdiction_pack_id: Optional[int] = None, country: Optional[str] = None,
) -> List[TaxSlab]:
    query = db.query(TaxSlab).filter(TaxSlab.organization_id.is_(None))
    if jurisdiction_pack_id:
        query = query.filter(TaxSlab.jurisdiction_pack_id == jurisdiction_pack_id)
    if country:
        query = query.filter(TaxSlab.jurisdiction_country == _normalize_country(country))
    return query.order_by(TaxSlab.sort_order, TaxSlab.min_amount).all()


def _refuse_hk_generic_statutory_edit(pack) -> None:
    """Hong Kong only (statutory configuration administration): HK statutory
    rows are edited through the governed HK editor (source document + reason
    required, hong_kong_service.update_row) — never through the generic
    canonical-row editor, which carries no source. Other countries unchanged."""
    if pack is not None and pack.jurisdiction_country == "HK":
        raise BadRequestException(
            "Hong Kong statutory rows are edited in Compliance → Hong Kong → Statutory Configuration "
            "(a source document and a change reason are required)."
        )


def upsert_canonical_tax_slab(db: Session, data: CanonicalTaxSlabUpsert, actor_id: Optional[int] = None) -> TaxSlab:
    pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == data.jurisdictionPackId).first()
    if not pack:
        raise NotFoundException("JurisdictionPack", data.jurisdictionPackId)
    if pack.pack_type != "tax":
        raise BadRequestException("Canonical tax slabs can only be attached to a pack_type='tax' JurisdictionPack.")
    _refuse_hk_generic_statutory_edit(pack)
    _require_editable_pack(pack)
    _invalidate_pack_approval_on_edit(pack)

    fields = dict(
        jurisdiction_country=_normalize_country(data.jurisdictionCountry),
        jurisdiction_state=data.jurisdictionState,
        jurisdiction_locality=data.jurisdictionLocality,
        tax_regime=data.taxRegime,
        filing_status=data.filingStatus,
        min_amount=data.minAmount, max_amount=data.maxAmount,
        rate_pct=data.ratePct, rate_label=data.rateLabel, tax_formula=data.taxFormula,
        rule_type=data.ruleType, formula_expression=data.formulaExpression,
        flat_amount=data.flatAmount, adjustment_amount=data.adjustmentAmount,
        assessment_basis=data.assessmentBasis,
        ni_category=data.niCategory, employer_rate_pct=data.employerRatePct,
        sort_order=data.sortOrder, jurisdiction_pack_id=data.jurisdictionPackId,
    )
    # Sweden table/column discriminators — only when explicitly sent, so a
    # form that doesn't know about them never wipes a band's table/column.
    if "taxTableNumber" in data.model_fields_set:
        fields["tax_table_number"] = data.taxTableNumber
    if "taxColumn" in data.model_fields_set:
        fields["tax_column"] = data.taxColumn
    # Row dating only when explicitly sent (see CanonicalTaxSlabUpsert).
    if "effectiveFrom" in data.model_fields_set:
        fields["effective_from"] = data.effectiveFrom
    if "effectiveTo" in data.model_fields_set:
        fields["effective_to"] = data.effectiveTo
    if fields.get("effective_from") and fields.get("effective_to") and fields["effective_to"] < fields["effective_from"]:
        raise BadRequestException("effectiveTo cannot be before effectiveFrom.")
    action = "update" if data.id else "create"
    old_value = None
    if data.id:
        row = db.query(TaxSlab).filter(TaxSlab.id == data.id, TaxSlab.organization_id.is_(None)).first()
        if not row:
            raise NotFoundException("Canonical TaxSlab", data.id)
        # Snapshot every field this call can mutate, not just 3 of ~13 —
        # the old narrow capture meant a changed rule_type, formula_expression,
        # label, or jurisdiction_state was invisible in the audit trail.
        old_value = {k: (str(getattr(row, k)) if getattr(row, k) is not None else None) for k in fields}
        for k, v in fields.items():
            setattr(row, k, v)
    else:
        row = TaxSlab(organization_id=None, **fields)
        db.add(row)
    db.commit()
    db.refresh(row)
    record_tax_audit(
        db, actor_id=actor_id, action=action, entity_type="tax_slab", entity_id=row.id,
        jurisdiction_pack_id=pack.id, tax_version=pack.version,
        old_value=old_value, new_value={k: (str(v) if v is not None else None) for k, v in fields.items()},
        reason=data.reason,
    )
    _invalidate_tax_config_cache_on_canonical_write()
    return row


def list_canonical_contribution_rates(
    db: Session, jurisdiction_pack_id: Optional[int] = None, country: Optional[str] = None,
) -> List[ContributionRate]:
    query = db.query(ContributionRate).filter(ContributionRate.organization_id.is_(None))
    if jurisdiction_pack_id:
        query = query.filter(ContributionRate.jurisdiction_pack_id == jurisdiction_pack_id)
    if country:
        query = query.filter(ContributionRate.jurisdiction_country == _normalize_country(country))
    return query.order_by(ContributionRate.sort_order).all()


def upsert_canonical_contribution_rate(
    db: Session, data: CanonicalContributionRateUpsert, actor_id: Optional[int] = None,
) -> ContributionRate:
    pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == data.jurisdictionPackId).first()
    if not pack:
        raise NotFoundException("JurisdictionPack", data.jurisdictionPackId)
    if pack.pack_type != "tax":
        raise BadRequestException("Canonical contribution rates can only be attached to a pack_type='tax' JurisdictionPack.")
    _refuse_hk_generic_statutory_edit(pack)
    _require_editable_pack(pack)
    _invalidate_pack_approval_on_edit(pack)

    # employee_rate_pct/employer_rate_pct store the plain percentage number
    # (12.00 for 12%), matching every other ContributionRate row in the
    # system (org-scoped rows, the _CONTRIBUTION_RATES_BY_COUNTRY seed
    # dicts) — the engine divides by 100 itself at calculation time
    # (engine/standard.py: `basic * (pf_rate.employee_rate_pct / 100)`).
    # Dividing again here would silently store a value 100x too small.
    employee_pct = data.employeeSharePct
    employer_pct = data.employerSharePct
    # A flat-amount-only row has no employee/employer percentage to sum —
    # the old unconditional f"{... or 0}%" silently displayed "0%" for
    # every one of these instead of the real amount. Two different shapes
    # share the same flatAmount slot though: most (Professional Tax,
    # Standard Deduction, ESI Wage Ceiling, Section 87A limits) are genuine
    # currency thresholds, but a few Tax Parameters (surcharge_cap_pct,
    # cess_pct, ...) are percentages that just happen to be stored via
    # flatAmount too — the "_pct" component_key suffix is the existing,
    # already-established convention distinguishing the two.
    is_flat_only = employee_pct is None and employer_pct is None and data.flatAmount is not None
    if is_flat_only and data.componentKey.endswith("_pct"):
        total_display = f"{data.flatAmount}%"
    elif is_flat_only:
        total_display = f"{_get_currency_symbol(data.jurisdictionCountry)}{data.flatAmount:,.2f}"
    else:
        total_display = f"{(employee_pct or 0) + (employer_pct or 0)}%"
    fields = dict(
        jurisdiction_country=_normalize_country(data.jurisdictionCountry),
        jurisdiction_state=data.jurisdictionState,
        jurisdiction_locality=data.jurisdictionLocality,
        tax_regime=data.taxRegime,
        filing_status=data.filingStatus,
        component_key=_normalize_engine_component_key(data.componentKey), label=data.label,
        employee_share=f"{data.employeeSharePct}%" if data.employeeSharePct is not None else "",
        employer_share=f"{data.employerSharePct}%" if data.employerSharePct is not None else "",
        total=total_display,
        employee_rate_pct=employee_pct, employer_rate_pct=employer_pct, flat_amount=data.flatAmount,
        text_value=data.textValue,
        sort_order=data.sortOrder, jurisdiction_pack_id=data.jurisdictionPackId,
    )
    action = "update" if data.id else "create"
    old_value = None
    if data.id:
        row = db.query(ContributionRate).filter(ContributionRate.id == data.id, ContributionRate.organization_id.is_(None)).first()
        if not row:
            raise NotFoundException("Canonical ContributionRate", data.id)
        # Full-field snapshot (see the matching comment in
        # upsert_canonical_tax_slab) — was previously just 3 of ~13 fields.
        old_value = {k: (str(getattr(row, k)) if getattr(row, k) is not None else None) for k in fields}
        for k, v in fields.items():
            setattr(row, k, v)
    else:
        row = ContributionRate(organization_id=None, **fields)
        db.add(row)
    db.commit()
    db.refresh(row)
    record_tax_audit(
        db, actor_id=actor_id, action=action,         entity_type="contribution_rate", entity_id=row.id,
        jurisdiction_pack_id=pack.id, tax_version=pack.version,
        old_value=old_value, new_value={k: (str(v) if v is not None else None) for k, v in fields.items()},
        reason=data.reason,
    )
    _invalidate_tax_config_cache_on_canonical_write()
    return row


def delete_canonical_contribution_rate(db: Session, rate_id: int, actor_id: Optional[int] = None) -> None:
    """Permanently remove one canonical ContributionRate row from a tax
    pack. Unlike hard-deleting a whole JurisdictionPack, this needs no
    org-assignment/payslip-history guard: org-scoped ContributionRate rows
    are point-in-time SNAPSHOT copies (via sync_org_rates_from_canonical),
    not live references back to this row, and PayslipItem's historical
    snapshot (tax_rule_snapshot) is a JSON copy of the values, not an FK —
    so deleting this row can never retroactively change an org's already-
    synced rates or an already-issued payslip's recorded figures."""
    row = db.query(ContributionRate).filter(ContributionRate.id == rate_id, ContributionRate.organization_id.is_(None)).first()
    if not row:
        raise NotFoundException("Canonical ContributionRate", rate_id)
    old_value = {
        "componentKey": row.component_key, "label": row.label,
        "employee_rate_pct": str(row.employee_rate_pct) if row.employee_rate_pct is not None else None,
        "employer_rate_pct": str(row.employer_rate_pct) if row.employer_rate_pct is not None else None,
        "flat_amount": str(row.flat_amount) if row.flat_amount is not None else None,
    }
    jurisdiction_pack_id = row.jurisdiction_pack_id
    pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == jurisdiction_pack_id).first() if jurisdiction_pack_id else None
    # Real gap this closes: this function previously had NO status check
    # at all — a rate could be deleted from a currently-Active, in-force
    # pack, silently zeroing that component for every future calculation
    # against it (no new-version safety net, unlike an edit). Same
    # immutability contract upsert_canonical_contribution_rate already
    # enforces for edits, applied here for deletes too.
    if pack:
        _refuse_hk_generic_statutory_edit(pack)
        _require_editable_pack(pack)
        _invalidate_pack_approval_on_edit(pack)
    db.delete(row)
    db.commit()
    record_tax_audit(
        db, actor_id=actor_id, action="delete", entity_type="contribution_rate", entity_id=rate_id,
        jurisdiction_pack_id=jurisdiction_pack_id, tax_version=pack.version if pack else None,
        old_value=old_value, new_value=None,
    )
    _invalidate_tax_config_cache_on_canonical_write()


# ── US: bulk "New State Import" (Production-Readiness Plan Phase 3) ──────
# Today the ONLY way to add a brand-new state's full bracket table is
# hand-writing a Python dict into hardcoded_defaults.py and running a seed
# script — there's no Super Admin UI path at all (contrast with the
# Locality Dataset Manager, which DOES have a real import flow for
# locality-level data). This gives Tax Ops a single-submit path that
# reuses the EXACT SAME Draft->Approved->Active JurisdictionPack lifecycle
# and publish gates every other US pack already goes through — no new
# calculation logic, no new lifecycle mechanism, just a bulk entry point
# in front of upsert_jurisdiction_pack/upsert_canonical_tax_slab/
# upsert_canonical_contribution_rate, so a bulk import and a manual
# one-row-at-a-time edit stay byte-for-byte consistent (same validation,
# same audit trail, same immutability guard).

def bulk_import_state_tax_pack(
    db: Session, *, jurisdiction_state: str, version: str,
    bracket_rows: List[dict], standard_deduction_rows: Optional[List[dict]] = None,
    pack_id: Optional[str] = None, effective_from=None,
    source_document_id: Optional[int] = None, actor_id: Optional[int] = None,
) -> JurisdictionPack:
    """Creates a brand-new Draft JurisdictionPack (pack_type="tax",
    country=US) for `jurisdiction_state` and bulk-populates it with
    canonical MARGINAL_RATE TaxSlab rows (`bracket_rows`: dicts with
    filingStatus/minAmount/maxAmount/ratePct/rateLabel/taxFormula) and
    ContributionRate "state_standard_deduction" rows (`standard_deduction_
    rows`: dicts with filingStatus/label/flatAmount). Always creates a NEW
    pack — never appends onto an existing one, so two Tax Ops users can't
    silently race to import the same state twice into one pack. The new
    pack starts life exactly like a manually-created one: Draft, no
    approver, nothing published — Approve/Activate still go through
    set_jurisdiction_pack_status's existing gates (source artifact,
    effective date, golden-test variance, distinct approver)."""
    jurisdiction_state = (jurisdiction_state or "").strip().upper()
    if not jurisdiction_state:
        raise BadRequestException("A state code is required.")
    if not bracket_rows:
        raise BadRequestException("At least one tax bracket row is required.")
    standard_deduction_rows = standard_deduction_rows or []

    pack = upsert_jurisdiction_pack(db, JurisdictionPackUpsert(
        packId=(pack_id or f"US-{jurisdiction_state}-STATE-TAX").strip(),
        jurisdictionCountry="US", jurisdictionState=jurisdiction_state,
        packType="tax", version=version, status="Draft",
        effectiveFrom=effective_from,
        changeSummary=(
            f"Bulk state tax import — {len(bracket_rows)} bracket row(s), "
            f"{len(standard_deduction_rows)} standard-deduction row(s)."
        ),
    ), actor_id=actor_id)
    if source_document_id:
        pack.source_document_id = source_document_id
        db.commit()

    for i, r in enumerate(bracket_rows):
        upsert_canonical_tax_slab(db, CanonicalTaxSlabUpsert(
            jurisdictionPackId=pack.id, jurisdictionCountry="US", jurisdictionState=jurisdiction_state,
            filingStatus=r.get("filingStatus"),
            minAmount=r["minAmount"], maxAmount=r.get("maxAmount"),
            ratePct=r["ratePct"], rateLabel=r.get("rateLabel") or f"{r['ratePct']}%",
            taxFormula=r.get("taxFormula") or "", ruleType="MARGINAL_RATE", sortOrder=i,
        ), actor_id=actor_id)

    for i, r in enumerate(standard_deduction_rows):
        upsert_canonical_contribution_rate(db, CanonicalContributionRateUpsert(
            jurisdictionPackId=pack.id, jurisdictionCountry="US", jurisdictionState=jurisdiction_state,
            filingStatus=r.get("filingStatus"), componentKey="state_standard_deduction",
            label=r.get("label") or "Standard Deduction", flatAmount=r["flatAmount"],
            sortOrder=len(bracket_rows) + i,
        ), actor_id=actor_id)

    db.refresh(pack)
    return pack


def delete_canonical_tax_slab(db: Session, slab_id: int, actor_id: Optional[int] = None) -> None:
    """Permanently remove one canonical TaxSlab row from a tax pack — same
    no-retroactive-effect reasoning as delete_canonical_contribution_rate."""
    row = db.query(TaxSlab).filter(TaxSlab.id == slab_id, TaxSlab.organization_id.is_(None)).first()
    if not row:
        raise NotFoundException("Canonical TaxSlab", slab_id)
    old_value = {
        "min_amount": str(row.min_amount), "max_amount": str(row.max_amount) if row.max_amount is not None else None,
        "rate_pct": str(row.rate_pct), "rate_label": row.rate_label,
    }
    jurisdiction_pack_id = row.jurisdiction_pack_id
    pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == jurisdiction_pack_id).first() if jurisdiction_pack_id else None
    # Same real gap/fix as delete_canonical_contribution_rate above — no
    # status check previously existed here at all.
    if pack:
        _refuse_hk_generic_statutory_edit(pack)
        _require_editable_pack(pack)
        _invalidate_pack_approval_on_edit(pack)
    db.delete(row)
    db.commit()
    record_tax_audit(
        db, actor_id=actor_id, action="delete", entity_type="tax_slab", entity_id=slab_id,
        jurisdiction_pack_id=jurisdiction_pack_id, tax_version=pack.version if pack else None,
        old_value=old_value, new_value=None,
    )
    _invalidate_tax_config_cache_on_canonical_write()


def get_active_tax_configuration_for_display(db: Session, country: str, state: Optional[str] = None) -> dict:
    """Read-only: the canonical rates/slabs from whichever tax pack is
    currently Active for this jurisdiction — powers the Statutory Rates
    page's "Platform Default Rates" summary. This is the exact same
    resolution the live payroll engine uses (resolve_tax_configuration),
    just surfaced for display; it never writes anything. Editing these
    values happens on the Compliance page's Rates editor.

    Returns {"pack": None, "rates": [], "slabs": []} when no canonical
    tax pack is Active for this jurisdiction yet — an expected, valid
    state (see resolve_tax_configuration's own docstring), not an error."""
    from app.modules.payroll.engine.tax_resolver import resolve_tax_configuration

    country = _normalize_country(country)
    rates, slabs, pack = resolve_tax_configuration(db, country, state=state, payroll_date=date.today())
    return {"pack": pack, "rates": rates, "slabs": slabs}


def list_all_jurisdiction_packs(
    db: Session, country: Optional[str] = None, state: Optional[str] = None,
    status: Optional[str] = None, search: Optional[str] = None, pack_type: Optional[str] = None,
) -> List[JurisdictionPack]:
    """Cross-jurisdiction policy list for Super Admin Compliance — unlike
    list_jurisdiction_packs (which requires a single country and returns
    every version of its packs), this spans every jurisdiction and, per
    pack_id, returns only the latest version — i.e. one row per policy,
    which is what a review/listing screen needs. Use
    get_jurisdiction_pack_versions() to drill into one policy's history.

    `pack_type` ("tax" | "policy") lets the Taxes and Policies tabs query
    this same table with different filters instead of needing two tables.

    Once `country` is scoped, `state` follows the same "None means
    country-level only" convention list_jurisdiction_packs already uses —
    NOT "every state mixed together" — otherwise a jurisdiction-detail view
    scoped to e.g. India with no state picked would silently show
    Telangana's and Maharashtra's packs blended into one list, breaking
    the per-state isolation the jurisdiction-first UI depends on. Only
    when no country is given at all (a genuine global cross-jurisdiction
    browse) does an absent state leave every state unfiltered."""
    query = db.query(JurisdictionPack)
    if country:
        query = query.filter(JurisdictionPack.jurisdiction_country == country)
        if state:
            query = query.filter(JurisdictionPack.jurisdiction_state == state)
        else:
            query = query.filter(JurisdictionPack.jurisdiction_state.is_(None))
    elif state:
        query = query.filter(JurisdictionPack.jurisdiction_state == state)
    if status:
        query = query.filter(JurisdictionPack.status == status)
    if pack_type:
        query = query.filter(JurisdictionPack.pack_type == pack_type)
    if search:
        like = f"%{search}%"
        query = query.filter(
            or_(
                JurisdictionPack.pack_id.ilike(like),
                JurisdictionPack.jurisdiction_country.ilike(like),
                JurisdictionPack.compliance_category.ilike(like),
                JurisdictionPack.regulatory_authority.ilike(like),
            )
        )
    rows = query.order_by(JurisdictionPack.pack_id, JurisdictionPack.created_at.desc()).all()

    latest_by_pack_id = {}
    for row in rows:
        if row.pack_id not in latest_by_pack_id:
            latest_by_pack_id[row.pack_id] = row
    return list(latest_by_pack_id.values())


def get_jurisdiction_pack_versions(db: Session, pack_id: str) -> List[JurisdictionPack]:
    """Full version history for one policy, oldest first — nothing is ever
    overwritten (see upsert_jurisdiction_pack), so this reconstructs the
    complete traceable chain."""
    return (
        db.query(JurisdictionPack)
        .filter(JurisdictionPack.pack_id == pack_id)
        .order_by(JurisdictionPack.created_at.asc())
        .all()
    )


def se_activation_blockers(db: Session, pack) -> list:
    """ZP-SE-ENG-001 §37/§16 — why a Sweden tax pack may NOT go Active yet
    (empty list = complete). Checks the pack's OWN canonical rows, not an
    org's cache: every parameter the engine requires (fallback_registry) is
    configured, and every SE_TAX_TABLE / SE_ONE_TIME_PAYMENT row declares an
    AMOUNT/PERCENT basis (an unfilled Draft scaffold never activates)."""
    from app.modules.payroll.engine.countries.sweden import SE_ONE_TIME_PAYMENT_RULE, SE_TAX_TABLE_RULE
    from app.modules.payroll.engine.fallback_registry import get_required_parameter_keys

    blockers = []
    rates = {
        _normalize_engine_component_key(r.component_key): r
        for r in db.query(ContributionRate).filter(
            ContributionRate.jurisdiction_pack_id == pack.id, ContributionRate.organization_id.is_(None))
    }
    for req in get_required_parameter_keys("SE"):
        row = rates.get(req["key"])
        configured = row is not None and (
            getattr(row, f"{req['side']}_rate_pct", None) is not None if req["side"] else row.flat_amount is not None)
        if not configured:
            blockers.append(f"missing {req['key']} ({req['label']})")
    slabs = db.query(TaxSlab).filter(TaxSlab.jurisdiction_pack_id == pack.id, TaxSlab.organization_id.is_(None)).all()
    tables = [s for s in slabs if s.rule_type == SE_TAX_TABLE_RULE]
    if not tables:
        blockers.append("no SE_TAX_TABLE bands configured")
    unfilled = [s for s in slabs if s.rule_type in (SE_TAX_TABLE_RULE, SE_ONE_TIME_PAYMENT_RULE)
                and (s.assessment_basis or "").upper() not in ("AMOUNT", "PERCENT")]
    if unfilled:
        blockers.append(f"{len(unfilled)} tax-table/one-time row(s) are unfilled Draft scaffolds "
                        f"(e.g. {unfilled[0].rate_label})")
    return blockers


# Display names for the per-country opt-in activation gates below.
_GATED_PACK_COUNTRY_NAMES = {"US": "United States", "DE": "Germany", "SG": "Singapore", "SE": "Sweden", "HK": "Hong Kong",
                             "CH": "Switzerland"}
# Phase 6.0 F2: countries whose pack approver may never be its activator.
_APPROVER_NOT_ACTIVATOR_COUNTRIES = ("SG", "SE", "HK", "CH")  # SE: ZP-SE-ENG-001 §14/§16 four-eyes, same opt-in as SG; CH: CH Step 12
# Phase 6.5: countries whose pack approver may never be the Super Admin who
# last edited / submitted the pack (refused at the Approve step itself).
_SELF_APPROVAL_REFUSED_COUNTRIES = ("SG", "SE", "HK", "CH")  # SE: ZP-SE-ENG-001 §14/§16 four-eyes, same opt-in as SG; CH: CH Step 12
# Phase 6.5: countries whose REFUSED pack / report-template governance
# actions are themselves audited (action "refused"). Same per-country opt-in
# pattern as F2; other countries keep their existing, unaudited refusals.
_REFUSAL_AUDIT_COUNTRIES = ("SG", "SE", "HK", "CH")  # SE: ZP-SE-ENG-001 §14/§16 four-eyes, same opt-in as SG; CH: CH Step 12
# Singapore completion programme (2026-09-29): countries whose TAX packs follow
# an explicit transition graph. Before this, only the Active-downgrade guard
# applied, so a Superseded / Retired Singapore pack could be moved back to
# Draft, edited through upsert and re-activated, and any string was accepted
# as a status. Same per-country opt-in pattern as the constants above; other
# countries keep their existing free lifecycle (DE keeps its downgrade guard).
_PACK_TRANSITION_GRAPH_COUNTRIES = ("SG", "SE", "HK", "CH")  # SE: ZP-SE-ENG-001 §14/§16 four-eyes, same opt-in as SG; CH: CH Step 12
TAX_PACK_TRANSITIONS = {
    "Draft": ("In Review", "QA", "Approved", "Active"),
    "In Review": ("Draft", "QA", "Approved", "Active"),
    "QA": ("Draft", "In Review", "Approved", "Active"),
    "Approved": ("Draft", "In Review", "QA", "Active"),
    # Active -> Active is the idempotent re-activation the hotfix path uses.
    "Active": ("Active", "Deprecated", "Retired", "Superseded"),
    "Deprecated": ("Retired", "Superseded"),
    "Retired": (),
    "Superseded": (),
}


def _audit_refusal(db: Session, model, entity_type: str, entity_id: int, attempted: str, actor_id: Optional[int],
                   message: str, path: Optional[str] = None) -> None:
    """Record one "refused" TaxConfigurationAudit row for an opted-in
    country's pack / report template. Rolls back first, so the refused call
    leaves nothing pending behind it (the Phase 6.3 phantom-approval class of
    defect) and the audit row is its only trace. Actor, time (created_at),
    attempted action, current status and the refusal reason are kept; the
    reason is the governance message itself, never payroll or personal data."""
    row = db.query(model).filter(model.id == entity_id).first()
    if row is None or row.jurisdiction_country not in _REFUSAL_AUDIT_COUNTRIES:
        return
    db.rollback()
    row = db.query(model).filter(model.id == entity_id).first()
    record_tax_audit(
        db, actor_id=actor_id, action="refused", entity_type=entity_type, entity_id=entity_id,
        jurisdiction_pack_id=entity_id if model is JurisdictionPack else None, tax_version=row.version,
        old_value={"status": row.status},
        new_value={"attempted": attempted, "result": "REFUSED", **({"path": path} if path else {})},
        reason=message,
    )


def set_jurisdiction_pack_status(
    db: Session, pack_row_id: int, status: str, actor_id: Optional[int] = None,
    bypass_approver_check: bool = False, reason: Optional[str] = None,
) -> JurisdictionPack:
    """Phase 6.5 wrapper: every refusal (BadRequestException) of an opted-in
    country's pack is audited before it propagates — see
    _set_jurisdiction_pack_status for the gates themselves. `reason` (optional,
    every country) is kept on the tax pack's status_change audit row."""
    try:
        return _set_jurisdiction_pack_status(db, pack_row_id, status, actor_id=actor_id,
                                             bypass_approver_check=bypass_approver_check, reason=reason)
    except BadRequestException as exc:
        _audit_refusal(db, JurisdictionPack, "jurisdiction_pack", pack_row_id, status, actor_id, exc.message,
                       path="hotfix" if bypass_approver_check else None)
        raise


def _set_jurisdiction_pack_status(
    db: Session, pack_row_id: int, status: str, actor_id: Optional[int] = None,
    bypass_approver_check: bool = False, reason: Optional[str] = None,
) -> JurisdictionPack:
    """`bypass_approver_check`: ONLY set by activate_jurisdiction_pack_hotfix
    (never by the ordinary Approve/Publish/Activate path) — see that
    function's own docstring for why. Found 2026-09-17 via live AU data
    entry: hotfix mode's own "self-approve, if not already approved by
    someone else" step sets approved_by_id = actor_id, but for a pack a
    single actor created AND edited (updated_by_id already == that same
    actor_id from every prior upsert_canonical_tax_slab/_contribution_
    rate call), approved_by_id == updated_by_id afterward — the exact
    condition the check below exists to catch — so hotfix mode's own
    distinct-approver bypass silently failed to bypass anything in a
    genuine single-Super-Admin session. The one existing test for this
    (test_hotfix_activation_bypasses_distinct_approver_gate_and_records_
    activation) never caught it because its pack was constructed via a
    raw ORM insert that left updated_by_id NULL, never equal to any real
    actor_id — a test-setup blind spot, not a passing proof of the real
    scenario."""
    row = db.query(JurisdictionPack).filter(JurisdictionPack.id == pack_row_id).first()
    if not row:
        raise NotFoundException("JurisdictionPack", pack_row_id)
    # Policy packs have only a Draft -> Active lifecycle: no In Review / QA /
    # Approved review stage and no Deprecated/Retired end states (set status
    # back to Draft to unpublish). Tax packs keep the full 7-status spec
    # lifecycle — this branch fires for policy packs only.
    if row.pack_type == "policy" and status not in ("Draft", "Active"):
        raise BadRequestException(
            f"Policy packs only support 'Draft' and 'Active' statuses (got {status!r}) — "
            "a policy's lifecycle has no review/approval stage."
        )

    # Phase 8DJ — Germany-only downgrade guard, precedent-matched to the
    # existing US-only certification gate immediately below (same
    # function, same per-country-opt-in pattern): once a Germany tax pack
    # is Active, it must never move directly back to a pre-Active status
    # (that would silently strip governance from a version that may
    # already be resolving real registry-linked payroll — Phase 8DI/8DJ's
    # whole point). Deliberately scoped to DE only — every other
    # jurisdiction's existing Active->Draft workflow (already relied upon
    # for corrections) is left completely untouched, exactly as the
    # existing US gate was scoped to avoid a bigger, unreviewed
    # cross-jurisdiction change.
    # SG opted in 2026-09-23 (ZP-SG-ENG-001 §2: "never edit 2026 rows in
    # place") — a brand-new jurisdiction with no existing Active->Draft
    # correction workflow to disturb.
    if (
        row.pack_type == "tax" and row.jurisdiction_country in ("DE", "SG", "HK")
        and row.status == "Active" and status not in ("Active", "Deprecated", "Retired", "Superseded")
    ):
        raise BadRequestException(
            f"This {_GATED_PACK_COUNTRY_NAMES[row.jurisdiction_country]} tax pack is Active and cannot move directly to {status!r} — "
            "supersede it with a new version instead of downgrading it back to a pre-Active status."
        )
    # Completion programme graph (after the downgrade guard above, whose
    # established message still answers Active -> pre-Active).
    if row.pack_type == "tax" and row.jurisdiction_country in _PACK_TRANSITION_GRAPH_COUNTRIES:
        if status not in TAX_PACK_TRANSITIONS:
            raise BadRequestException(
                f"{status!r} is not a tax pack lifecycle status — use one of {', '.join(TAX_PACK_TRANSITIONS)}."
            )
        allowed = TAX_PACK_TRANSITIONS.get(row.status, ())
        if status not in allowed:
            raise BadRequestException(
                f"Pack {row.pack_id} v{row.version} cannot move from {row.status} to {status} — "
                + (f"allowed: {', '.join(allowed)}." if allowed else
                   f"{row.status} is final; create a new pack version instead.")
            )

    if status == "Active" and row.pack_type == "tax":
        # No source artifact / no effective date -> cannot publish
        # (ZP-TAX-US-2026-001 §11.2's own publish-gate list, gap-closure
        # Plan Phase 4). Deliberately scoped to US packs only — this
        # function governs EVERY country's tax-pack activation, and a
        # live-DB check before adding this found 8 pre-existing non-US
        # Draft packs (UK/AU/DE/IN "FALLBACK-DEFAULTS"/provisional rows)
        # that have never had a source artifact linked; a global gate
        # would have silently blocked those countries' own existing
        # workflows, which is a materially bigger, unreviewed change than
        # what this plan's own document asked for. A future pass can
        # extend this per-country once each one's own existing Draft
        # packs are individually reviewed/backfilled.
        # SG opted in 2026-09-23 (ZP-SG-ENG-001 SG-003: only APPROVED,
        # evidenced, certified content may activate) — same gate as US,
        # plus the stricter "a real PASS run must exist" check below.
        # HK opted in 2026-09-30 (ZP-HK-ENG-001 §16: live Hong Kong payroll
        # stays disabled until the release gates are evidenced).
        # SE opted in 2026-09-30 (ZP-SE-ENG-001 §16: primary-source statutory
        # pack approved before activation) — the SG gate, verbatim.
        if row.jurisdiction_country in ("US", "SG", "SE", "HK"):
            if not row.source_document_id:
                raise BadRequestException(
                    "This pack needs a linked Source Evidence artifact before it can go Active — "
                    f"see Super Admin > Compliance > {_GATED_PACK_COUNTRY_NAMES[row.jurisdiction_country]} > Source Evidence."
                )
            if not row.effective_from:
                raise BadRequestException(
                    "This pack needs an Effective From date before it can go Active."
                )
            # Unresolved golden-test variance -> cannot publish (§11.2,
            # gap-closure Plan Phase 4) — connects the Certification
            # Console (run_golden_test_certification/TestCertificationRun)
            # to this gate for the first time; they were previously two
            # completely disconnected systems. No per-pack-version link
            # exists between a pack and a specific test run (TestCertificationRun
            # is country-scoped, not pack-scoped), so this checks the
            # MOST RECENT US run: a real FAIL blocks activating ANY US
            # pack until it's resolved and re-run. NO_REAL_CASES (no real
            # golden fixtures exist for a component yet — a documented,
            # disclosed gap, not a detected mismatch) and "no run at all
            # yet" both deliberately do NOT block — blocking on the mere
            # absence of test coverage would be a much bigger, unreviewed
            # change than this gate is meant to make.
            # Phase 6.4: id breaks a run_at tie (server-side now() — whole
            # seconds on SQLite), so a PASS right after a FAIL is never read
            # as the older of the two, nor the reverse.
            latest_run = (
                db.query(TestCertificationRun)
                .filter(TestCertificationRun.jurisdiction_country == row.jurisdiction_country)
                .order_by(TestCertificationRun.run_at.desc(), TestCertificationRun.id.desc())
                .first()
            )
            if latest_run is not None and latest_run.status == "FAIL":
                raise BadRequestException(
                    f"The most recent {row.jurisdiction_country} golden-test certification run (#{latest_run.id}) has "
                    f"{latest_run.failed_cases} unresolved failure(s) — resolve and re-run "
                    f"Test Certification before activating any {row.jurisdiction_country} pack."
                )
            # Singapore only: absence of a run, or NO_REAL_CASES, is not a
            # pass — the spec requires golden vectors passing before
            # activation (SG-003/SG-049). US keeps its existing, more
            # lenient behavior above unchanged.
            if row.jurisdiction_country in ("SG", "SE", "HK") and (latest_run is None or latest_run.status != "PASS"):
                name = _GATED_PACK_COUNTRY_NAMES[row.jurisdiction_country]
                raise BadRequestException(
                    f"{name} packs need a passing golden-vector certification run before they can go Active — "
                    f"run Test Certification for {row.jurisdiction_country} first."
                )
            # Sweden §37 completeness gate: every engine-required parameter
            # present in THIS pack and no inert tax-table scaffold left.
            if row.jurisdiction_country == "SE":
                blockers = se_activation_blockers(db, row)
                if blockers:
                    raise BadRequestException(
                        "This Sweden pack is not complete enough to go Active: " + "; ".join(blockers[:5])
                        + (f" (+{len(blockers) - 5} more)" if len(blockers) > 5 else "")
                    )
        # Prevent two simultaneously-Active tax versions for the same
        # country+state+regime whose EFFECTIVE DATE RANGES actually overlap
        # (Phase 22 duplicate/overlap guard). Originally compared tax_year
        # equality instead of real date ranges — that blocked legitimate
        # non-overlapping same-year splits (e.g. Canada's CA-2026-H1
        # Jan-Jun / CA-2026-H2 Jul-Dec, both tax_year "2026") from ever
        # being Active together, even though _find_active_tax_pack's own
        # resolver already picks between multiple Active packs by date
        # range. A NULL effective_to is treated as open-ended (unbounded).
        far_future = date(9999, 12, 31)
        far_past = date(1, 1, 1)
        target_from = row.effective_from or far_past
        target_to = row.effective_to or far_future
        if row.jurisdiction_country == "HK":
            # Serialize concurrent Hong Kong activations: lock the jurisdiction's
            # tax packs (row locks on PostgreSQL, in id order) so a second
            # activation waits, then sees the first one's Active row below and is
            # refused — never two overlapping Active versions.
            db.query(JurisdictionPack).filter(
                JurisdictionPack.jurisdiction_country == "HK", JurisdictionPack.pack_type == "tax",
            ).order_by(JurisdictionPack.id).with_for_update().all()
        conflict = (
            db.query(JurisdictionPack)
            .filter(
                JurisdictionPack.id != row.id,
                JurisdictionPack.pack_type == "tax",
                JurisdictionPack.status == "Active",
                JurisdictionPack.jurisdiction_country == row.jurisdiction_country,
                JurisdictionPack.jurisdiction_state == row.jurisdiction_state,
                JurisdictionPack.tax_regime == row.tax_regime,
                JurisdictionPack.effective_from <= target_to,
                or_(JurisdictionPack.effective_to.is_(None), JurisdictionPack.effective_to >= target_from),
            )
            .first()
        )
        if conflict:
            raise BadRequestException(
                f"Pack {conflict.pack_id} v{conflict.version} is already Active for this "
                f"country/state/regime and its effective dates overlap with this pack's — "
                f"supersede it before activating a new version."
            )
        # Same inverted-date guard as upsert_jurisdiction_pack — belt and
        # suspenders, since a pack saved before that guard existed could
        # still be activated here without ever going back through upsert.
        if row.effective_from and row.effective_to and row.effective_to < row.effective_from:
            raise BadRequestException(
                "This pack's Effective To date is before its Effective From date — "
                "fix the date range before activating it; it would never resolve for any calculation."
            )
        # Phase 6.10 (Singapore): G1 accepted, the golden vectors re-run
        # against THIS pack's own rows, and a wage-month-aligned start. After
        # the structural guards above (their refusals keep their messages),
        # before the approver checks, and on the hotfix path too — none of it
        # is an approver check.
        if row.jurisdiction_country == "SG":
            refusal = _sg_activation_evidence_refusal(db, row)
            if refusal:
                raise BadRequestException(refusal)
        # Hong Kong (ZP-HK-ENG-001 §16): G1 statutory-content evidence
        # accepted by a second Super Admin, and the golden vectors re-run
        # against THIS pack's own rows — on the hotfix path too.
        if row.jurisdiction_country == "HK":
            refusal = jurisdiction_hooks.call("HK", "pack_activation_refusal", db, row)
            if refusal:
                raise BadRequestException(refusal)
        # Minimum viable maker-checker gate (ZP-TAX-UK-2026-27-001 section
        # 19.2: "author cannot self-approve a production statutory
        # version"). `row.updated_by_id` here is whoever last edited the
        # pack's substance — captured BEFORE this call's own
        # `row.updated_by_id = actor_id` assignment below can overwrite
        # it, so activating a pack doesn't retroactively count as
        # approving your own edit.
        if not bypass_approver_check and (not row.approved_by_id or row.approved_by_id == row.updated_by_id):
            raise BadRequestException(
                "This pack needs a distinct approver before it can go Active — "
                "use \"Approve\" (a different Super Admin than whoever last edited it)."
            )
    if status == "Active" and row.pack_type == "policy":
        # Production-readiness fix plan, Phase 6 (2026-09-18): policy packs
        # previously had NO approval gate at all — Draft -> Active was a
        # single unilateral action, unlike every tax pack (see the
        # maker-checker block above) and every OTHER registry in this
        # module (Germany health funds, PAP assets, contribution ceilings,
        # U1 tariffs all require a distinct approver before publishing).
        # policy_defaults governs real compliance-relevant settings
        # (calculation_mode/employee_categories/overtime_rule defaults AND
        # whether an org may override them) — the same "author cannot
        # self-approve a production statutory version" principle applies
        # here too, not just to tax packs. Deliberately NOT reusing any of
        # the tax-only sub-checks above (source artifact, date-range
        # overlap, golden-test certification) — those concepts genuinely
        # don't apply to a policy pack's defaults; only the distinct-
        # approver check is shared. See set_jurisdiction_pack_approver's
        # matching change, which now allows policy packs to record an
        # approver instead of unconditionally rejecting that action.
        if not bypass_approver_check and (not row.approved_by_id or row.approved_by_id == row.updated_by_id):
            raise BadRequestException(
                "This pack needs a distinct approver before it can go Active — "
                "use \"Approve\" (a different Super Admin than whoever last edited it)."
            )
    # Singapore hotfix policy FOLLOW_UP_REQUIRED: no normal-path activation
    # while a Singapore hotfix awaits its review (the hotfix path checks it
    # itself, before recording its own activation row).
    if (status == "Active" and row.pack_type == "tax" and row.jurisdiction_country == "SG" and not bypass_approver_check
            and SG_HOTFIX_POLICY == "FOLLOW_UP_REQUIRED" and _sg_unreviewed_hotfixes(db)):
        raise BadRequestException(
            "A Singapore hotfix is still awaiting its retrospective review — the Singapore hotfix policy "
            "(FOLLOW_UP_REQUIRED) blocks further activations until it is reviewed."
        )
    # Phase 6.0 F2 — approver != activator (Singapore opt-in, same per-country
    # pattern as the DE/SG downgrade guard and the US/SG evidence gate). The
    # gates above compare the approver with the LAST EDITOR; a seeded pack has
    # no editor (updated_by_id NULL), so one Super Admin could approve it and
    # then activate it alone. For opted-in countries the approver can never be
    # the activator. Other countries keep their existing "checker approves and
    # activates" workflow unchanged (owner decision, 2026-09-28). Hotfix
    # activation keeps its own documented bypass_approver_check path.
    if (status == "Active" and not bypass_approver_check and row.jurisdiction_country in _APPROVER_NOT_ACTIVATOR_COUNTRIES
            and row.approved_by_id is not None and row.approved_by_id == actor_id):
        raise BadRequestException(
            "The Super Admin who approved this pack cannot also activate it — "
            "a different Super Admin must activate an approved pack (maker-checker)."
        )
    old_status = row.status
    row.status = status
    row.updated_by_id = actor_id
    db.commit()
    db.refresh(row)
    if row.pack_type == "tax":
        record_tax_audit(
            db, actor_id=actor_id, action="status_change", entity_type="jurisdiction_pack", entity_id=row.id,
            jurisdiction_pack_id=row.id, tax_version=row.version,
            old_value={"status": old_status}, new_value={"status": status},
            reason=(reason or "").strip() or None,
        )
        # A pack's status alone decides whether it is resolvable at all
        # (tax_resolver._find_active_tax_pack filters status == "Active"),
        # so this transition changes what every future payroll for this
        # jurisdiction resolves to even though no rate or slab row was
        # touched. Omitting the invalidation here was the one gap that
        # would let a just-Activated pack keep serving the "no canonical
        # pack configured" answer until the TTL expired.
        _invalidate_tax_config_cache_on_canonical_write()
    return row


def set_jurisdiction_pack_approver(db: Session, pack_row_id: int, actor_id: Optional[int] = None) -> JurisdictionPack:
    """Sets approved_by_id to the calling Super Admin — a distinct,
    lightweight action from the general Edit flow so it means something:
    "I, this specific person, reviewed and approve this configuration."

    Auto-advances status Draft -> Approved so the two-step maker-checker
    sequence (editor drafts -> a DIFFERENT Super Admin approves -> status
    visibly reflects that -> that pack can then be moved to Active) is
    reflected without a separate manual dropdown pick for the first step.
    Only fires from Draft — a pack someone deliberately moved to "In
    Review"/"QA" first keeps that status; approving it still records the
    approver (still required before Active, per set_jurisdiction_pack_status's
    gate below), it just doesn't overwrite a status chosen on purpose.
    Approving a pack already past Draft (Approved/Active/...) does not
    move it backwards."""
    row = db.query(JurisdictionPack).filter(JurisdictionPack.id == pack_row_id).first()
    if not row:
        raise NotFoundException("JurisdictionPack", pack_row_id)
    # Policy packs previously had no approval stage at all (Draft ->
    # Active directly, no distinct-approver requirement) — fixed as part
    # of the production-readiness fix plan's Phase 6 (2026-09-18), which
    # closed that gap in set_jurisdiction_pack_status's own maker-checker
    # check. This action now works identically for both pack types: it
    # still does NOT auto-advance a policy pack's status (policy packs
    # have no "Approved" status in their vocabulary — see this table's
    # own status docstring — Draft stays Draft until Active), it only
    # records who reviewed it, which set_jurisdiction_pack_status now
    # requires before allowing Draft -> Active for a policy pack too.
    # Phase 6.5 (Singapore opt-in): refuse the self-approval HERE instead of
    # recording it and leaving activation to refuse it later. updated_by_id is
    # whoever last edited or submitted the pack (upserts and status changes
    # both set it); a seeded, never-edited pack has none, and F2 then keeps its
    # approver from also activating it.
    if (row.jurisdiction_country in _SELF_APPROVAL_REFUSED_COUNTRIES and actor_id is not None
            and row.updated_by_id is not None and row.updated_by_id == actor_id):
        message = ("The Super Admin who last edited or submitted this pack cannot approve it — "
                   "a different Super Admin must approve (maker-checker).")
        _audit_refusal(db, JurisdictionPack, "jurisdiction_pack", pack_row_id, "approve", actor_id, message)
        raise BadRequestException(message)
    # Hong Kong statutory rows are edited one by one through the governed
    # editor (hong_kong_service.update_row): the approver must have made NONE of
    # this version's edits — not only the last one.
    if row.jurisdiction_country == "HK" and row.pack_type == "tax" and actor_id is not None:
        if actor_id in jurisdiction_hooks.call("HK", "statutory_editors", db, row):
            message = ("You edited statutory rows of this pack version — a Super Admin who made none of its edits "
                       "must approve it (maker-checker).")
            _audit_refusal(db, JurisdictionPack, "jurisdiction_pack", pack_row_id, "approve", actor_id, message)
            raise BadRequestException(message)
    # Completion programme (Singapore opt-in, same list as above): only a
    # pre-release version can be approved. The approval on an Active /
    # Deprecated / Retired / Superseded pack is its release evidence — it was
    # previously overwritable, replacing who attested the in-force content.
    # Same rule report templates already follow (set_report_template_approver).
    if (row.pack_type == "tax" and row.jurisdiction_country in _SELF_APPROVAL_REFUSED_COUNTRIES
            and row.status not in _EDITABLE_PACK_STATUSES):
        message = (f"Pack {row.pack_id} v{row.version} is {row.status} — its approval is release evidence and "
                   "cannot be replaced; create a new pack version to approve changed content.")
        _audit_refusal(db, JurisdictionPack, "jurisdiction_pack", pack_row_id, "approve", actor_id, message)
        raise BadRequestException(message)
    old_approver = row.approved_by_id
    old_status = row.status
    row.approved_by_id = actor_id
    if row.status == "Draft" and row.pack_type == "tax":
        row.status = "Approved"
    db.commit()
    db.refresh(row)
    if row.pack_type == "tax":
        record_tax_audit(
            db, actor_id=actor_id, action="update", entity_type="jurisdiction_pack", entity_id=row.id,
            jurisdiction_pack_id=row.id, tax_version=row.version,
            old_value={"approved_by_id": old_approver, "status": old_status},
            new_value={"approved_by_id": actor_id, "status": row.status},
            reason="Approver set",
        )
    return row


def get_pack_applicable_organizations(db: Session, pack_row_id: int) -> List[dict]:
    """Organizations currently assigned to this policy version, via the
    existing CompanyComplianceDetails.active_pack_id column — reused as-is
    rather than introducing a new assignment table."""
    from app.modules.organizations.models import Organization

    rows = (
        db.query(Organization.id, Organization.organization_name, Organization.organization_code)
        .join(CompanyComplianceDetails, CompanyComplianceDetails.organization_id == Organization.id)
        .filter(CompanyComplianceDetails.active_pack_id == pack_row_id)
        .all()
    )
    return [{"id": r.id, "organizationName": r.organization_name, "organizationCode": r.organization_code} for r in rows]


def get_organizations_eligible_for_pack(db: Session, pack_row_id: int) -> List[dict]:
    """Organizations whose own jurisdiction matches this pack's, for the
    "Apply Tax & Sync Rates" / "Assign Policy" picker — so a Telangana-only
    Professional Tax pack only ever lists Telangana organizations, not
    every organization on the platform.

    An org's jurisdiction is its own CompanyComplianceDetails
    jurisdiction_country/jurisdiction_state when set (the same field every
    other Compliance query in this codebase treats as authoritative);
    falls back to deriving it from Organization.country/state (the same
    mapping get_company_details' lazy backfill uses) for an org that
    hasn't opened Compliance yet and so has no compliance row at all, or
    one still at its blank/default jurisdiction.

    Country-level packs (jurisdiction_state is None) match any organization
    in that country, regardless of state; a state-level pack only matches
    organizations in that exact state.
    """
    from app.modules.organizations.models import Organization

    pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == pack_row_id).first()
    if not pack:
        raise NotFoundException("JurisdictionPack", pack_row_id)

    rows = (
        db.query(Organization, CompanyComplianceDetails)
        .outerjoin(CompanyComplianceDetails, CompanyComplianceDetails.organization_id == Organization.id)
        .all()
    )

    eligible = []
    for org, details in rows:
        country_code = details.jurisdiction_country if details and details.jurisdiction_country else None
        state = details.jurisdiction_state if details and details.jurisdiction_state else None
        if not country_code:
            country_code = _jurisdiction_code_for_org_country(org.country)
            state = org.state or None
        if country_code != pack.jurisdiction_country:
            continue
        if pack.jurisdiction_state and state != pack.jurisdiction_state:
            continue
        eligible.append({"id": org.id, "organizationName": org.organization_name, "organizationCode": org.organization_code})
    return eligible


# ── Automated Impact Preview (Super Admin UI Part 11, §19, 2026-09-09) ──
# Before publishing/activating a pack version change, show which orgs/
# employees/scheduled runs would actually be affected — reuses the
# jurisdiction-matching already proven correct by get_organizations_
# eligible_for_pack (the same picker "Assign Policy"/"Apply Tax" already
# use) rather than re-deriving country/state matching a second way.
def get_jurisdiction_pack_impact_preview(db: Session, pack_row_id: int) -> dict:
    """For a TAX pack, an org is only genuinely affected if it's opted
    into canonical tracking (_org_uses_canonical_tax_pack) — an org NOT
    opted in reads its own org-scoped cached ContributionRate/TaxSlab
    rows and is completely unaffected by this pack's own status change,
    exactly the same distinction this session's UK/Canada work already
    had to account for live. For a POLICY pack, "affected" instead means
    directly assigned via CompanyComplianceDetails.active_pack_id (no
    canonical/cached-copy split exists for policy packs).

    `unfinalized_run_count` — Draft/Review PayrollRuns for that org: the
    runs that would actually pick up this pack's new numbers once it
    goes Active, as opposed to an already-Approved/Paid run whose
    figures are frozen."""
    pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == pack_row_id).first()
    if not pack:
        raise NotFoundException("JurisdictionPack", pack_row_id)

    eligible_orgs = get_organizations_eligible_for_pack(db, pack_row_id)
    affected = []
    total_employees = 0
    total_unfinalized_runs = 0
    for org in eligible_orgs:
        org_id = org["id"]
        if pack.pack_type == "tax":
            opted_in = _org_uses_canonical_tax_pack(db, org_id)
            if not opted_in:
                affected.append({**org, "optedIntoCanonicalTracking": False, "activeEmployeeCount": 0, "unfinalizedRunCount": 0})
                continue
        else:
            details = db.query(CompanyComplianceDetails).filter(CompanyComplianceDetails.organization_id == org_id).first()
            if not details or details.active_pack_id != pack_row_id:
                continue
            opted_in = True

        employee_count = (
            db.query(PayrollEmployee)
            .filter(PayrollEmployee.organization_id == org_id, PayrollEmployee.status == EmployeeStatus.ACTIVE)
            .count()
        )
        unfinalized_count = (
            db.query(PayrollRun)
            .filter(PayrollRun.organization_id == org_id, PayrollRun.status.in_([PayrollStatus.DRAFT, PayrollStatus.REVIEW]))
            .count()
        )
        total_employees += employee_count
        total_unfinalized_runs += unfinalized_count
        affected.append({
            **org, "optedIntoCanonicalTracking": opted_in,
            "activeEmployeeCount": employee_count, "unfinalizedRunCount": unfinalized_count,
        })

    orgs_genuinely_affected = [o for o in affected if o["optedIntoCanonicalTracking"]]
    return {
        "packRowId": pack_row_id, "packId": pack.pack_id, "packVersion": pack.version, "packType": pack.pack_type,
        "organizations": affected,
        "totalOrganizationsEligible": len(affected),
        "totalOrganizationsGenuinelyAffected": len(orgs_genuinely_affected),
        "totalActiveEmployeesAffected": total_employees,
        "totalUnfinalizedRunsAffected": total_unfinalized_runs,
    }


# ── Tax Year / Release Manager: version compare (gap-closure Plan Phase
# 4, 2026-09-14) ─────────────────────────────────────────────────────────
# "Compare" was previously entirely absent — USVersionsSection.jsx only
# ever listed versions side by side with no rate-level diff, so seeing
# WHAT actually changed between two published releases meant manually
# reading both packs' Tax Components tabs. Mirrors
# diff_locality_dataset's own added/removed/changed shape (Phase 3).

def diff_jurisdiction_pack_versions(db: Session, from_pack_row_id: int, to_pack_row_id: int) -> dict:
    from_pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == from_pack_row_id).first()
    if not from_pack:
        raise NotFoundException("JurisdictionPack", from_pack_row_id)
    to_pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == to_pack_row_id).first()
    if not to_pack:
        raise NotFoundException("JurisdictionPack", to_pack_row_id)

    def _rate_key(r):
        return (r.component_key, r.filing_status, r.jurisdiction_locality)

    def _rate_fields(r):
        return dict(
            employeeRatePct=str(r.employee_rate_pct) if r.employee_rate_pct is not None else None,
            employerRatePct=str(r.employer_rate_pct) if r.employer_rate_pct is not None else None,
            flatAmount=str(r.flat_amount) if r.flat_amount is not None else None,
            textValue=r.text_value,
        )

    def _slab_key(s):
        return (s.filing_status, s.sort_order)

    def _slab_fields(s):
        return dict(
            minAmount=str(s.min_amount) if s.min_amount is not None else None,
            maxAmount=str(s.max_amount) if s.max_amount is not None else None,
            ratePct=str(s.rate_pct) if s.rate_pct is not None else None,
            formulaExpression=s.formula_expression,
        )

    def _diff(from_rows, to_rows, key_fn, fields_fn):
        from_by_key = {key_fn(r): r for r in from_rows}
        to_by_key = {key_fn(r): r for r in to_rows}
        added, removed, changed = [], [], []
        for key, row in to_by_key.items():
            if key not in from_by_key:
                added.append({"key": [str(k) for k in key], **fields_fn(row)})
                continue
            old_fields, new_fields = fields_fn(from_by_key[key]), fields_fn(row)
            row_changes = {f: {"before": old_fields[f], "after": new_fields[f]} for f in new_fields if old_fields[f] != new_fields[f]}
            if row_changes:
                changed.append({"key": [str(k) for k in key], "changes": row_changes})
        for key in from_by_key:
            if key not in to_by_key:
                removed.append({"key": [str(k) for k in key]})
        return {"added": added, "removed": removed, "changed": changed}

    from_rates = db.query(ContributionRate).filter(ContributionRate.jurisdiction_pack_id == from_pack.id).all()
    to_rates = db.query(ContributionRate).filter(ContributionRate.jurisdiction_pack_id == to_pack.id).all()
    from_slabs = db.query(TaxSlab).filter(TaxSlab.jurisdiction_pack_id == from_pack.id).all()
    to_slabs = db.query(TaxSlab).filter(TaxSlab.jurisdiction_pack_id == to_pack.id).all()

    return {
        "fromPackRowId": from_pack.id, "fromVersion": from_pack.version,
        "toPackRowId": to_pack.id, "toVersion": to_pack.version,
        "contributionRates": _diff(from_rates, to_rates, _rate_key, _rate_fields),
        "taxSlabs": _diff(from_slabs, to_slabs, _slab_key, _slab_fields),
    }


# ── Emergency Hotfix Mode (Super Admin UI Part 11, §19, 2026-09-09) ─────
def activate_jurisdiction_pack_hotfix(
    db: Session, pack_row_id: int, incident_id: str, justification: str, actor_id: Optional[int] = None,
) -> JurisdictionPack:
    """Activates a pack bypassing ONLY the distinct-approver maker-checker
    gate (self-approval allowed) — every other set_jurisdiction_pack_
    status guard (date-range overlap, inverted dates) still applies
    unchanged, since those protect against a genuinely broken pack, not
    against a rushed approval. Requires a non-blank incident_id/
    justification and ALWAYS creates a PackHotfixActivation row flagged
    for mandatory retrospective review — the accountability normal
    maker-checker provides is deferred to that after-the-fact review,
    never silently skipped.

    Passes bypass_approver_check=True to set_jurisdiction_pack_status
    (fixed 2026-09-17, found via live AU data entry): self-approving
    below sets approved_by_id = actor_id, which for a pack this SAME
    actor also last edited (updated_by_id already == actor_id from every
    prior canonical rate/slab upsert) leaves approved_by_id ==
    updated_by_id — exactly the condition set_jurisdiction_pack_status's
    own maker-checker check exists to reject. Without this flag, hotfix
    mode's "self-approval allowed" promise silently failed for any real
    single-Super-Admin session, which is the ONLY scenario hotfix mode
    exists for in the first place."""
    for missing, message in ((not incident_id or not incident_id.strip(),
                              "An incident_id is required to activate a pack via hotfix mode."),
                             (not justification or not justification.strip(),
                              "A justification is required to activate a pack via hotfix mode.")):
        if missing:
            _audit_refusal(db, JurisdictionPack, "jurisdiction_pack", pack_row_id, "Active", actor_id, message,
                           path="hotfix")
            raise BadRequestException(message)

    row = db.query(JurisdictionPack).filter(JurisdictionPack.id == pack_row_id).first()
    if not row:
        raise NotFoundException("JurisdictionPack", pack_row_id)

    # Hotfix mode exists solely to bypass the distinct-approver maker-checker
    # gate — policy packs have no approval step at all (Draft -> Active is
    # already a direct action), so hotfix would bypass nothing. Tax-only.
    if row.pack_type == "policy":
        raise BadRequestException(
            "Policy packs have no approval gate, so hotfix activation is not applicable — "
            "set the pack's status directly to 'Active' instead."
        )
    if row.jurisdiction_country == "HK":
        # No Hong Kong hotfix: a first activation must be the full
        # maker-checker path (ZP-HK-ENG-001 §16 G7 launch authority).
        refusal = ("Hong Kong hotfix activation is not permitted — activate through the normal maker-checker path "
                   "after the release gates are evidenced.")
        _audit_refusal(db, JurisdictionPack, "jurisdiction_pack", pack_row_id, "Active", actor_id, refusal, path="hotfix")
        raise BadRequestException(refusal)
    if row.jurisdiction_country == "SE":
        # ZP-SE-ENG-001 §14: four-eyes is REQUIRED for country-content
        # activation, and hotfix mode exists to self-approve — so Sweden has
        # no hotfix path at all (the SG "PROHIBITED" policy, fixed).
        refusal = ("Sweden hotfix activation is not permitted — Swedish statutory content must be activated "
                   "through the normal four-eyes path (ZP-SE-ENG-001 §14).")
        _audit_refusal(db, JurisdictionPack, "jurisdiction_pack", pack_row_id, "Active", actor_id, refusal,
                       path="hotfix")
        raise BadRequestException(refusal)
    if row.jurisdiction_country == "SG":
        policy_refusal = None
        if SG_HOTFIX_POLICY == "PROHIBITED":
            policy_refusal = ("Singapore hotfix activation is PROHIBITED by the Singapore hotfix policy — activate "
                              "through the normal maker-checker path.")
        elif SG_HOTFIX_POLICY == "FOLLOW_UP_REQUIRED" and _sg_unreviewed_hotfixes(db):
            policy_refusal = ("A Singapore hotfix is still awaiting its retrospective review — the Singapore hotfix "
                              "policy (FOLLOW_UP_REQUIRED) blocks further activations until it is reviewed.")
        if policy_refusal:
            _audit_refusal(db, JurisdictionPack, "jurisdiction_pack", pack_row_id, "Active", actor_id, policy_refusal,
                           path="hotfix")
            raise BadRequestException(policy_refusal)

    # Self-approve, if not already approved by someone else — this is
    # the ONE gate hotfix mode is allowed to bypass. Phase 6.3: the
    # self-approval is held uncommitted until the activation succeeds (the
    # same session object is what set_jurisdiction_pack_status re-reads and
    # commits). Committing it first left a REFUSED hotfix (e.g. no SG
    # golden PASS, no source evidence) with a phantom approval and no
    # approval audit row, which a second Super Admin could then activate
    # through the normal path as if the first had approved it.
    if not row.approved_by_id:
        row.approved_by_id = actor_id

    # Phase 6.6: the hotfix record is added BEFORE the activation, so the one
    # commit inside set_jurisdiction_pack_status persists the Active status
    # and its PackHotfixActivation together — previously a second, separate
    # commit, so a failure between the two left an Active pack with no hotfix
    # evidence. A refused or failed activation rolls both back.
    activation = PackHotfixActivation(
        jurisdiction_pack_id=pack_row_id, incident_id=incident_id.strip(), justification=justification.strip(),
        activated_by_id=actor_id,
    )
    db.add(activation)
    try:
        updated = set_jurisdiction_pack_status(db, pack_row_id, "Active", actor_id=actor_id, bypass_approver_check=True,
                                               reason=f"Hotfix {incident_id.strip()}: {justification.strip()}")
    except Exception:
        db.rollback()
        raise

    # No log_activity() call here — PayrollActivityLog is org-scoped
    # (organization_id NOT NULL) and this is a cross-org, Super-Admin-
    # level event with no single owning org. The PackHotfixActivation row
    # itself (plus set_jurisdiction_pack_status's own record_tax_audit
    # call for tax packs) IS the audit trail for this action.
    return updated


def list_pack_hotfix_activations(db: Session, reviewed: Optional[bool] = None) -> List[PackHotfixActivation]:
    query = db.query(PackHotfixActivation)
    if reviewed is not None:
        query = query.filter(PackHotfixActivation.reviewed == reviewed)
    return query.order_by(PackHotfixActivation.activated_at.desc()).all()


# Phase 6.6: countries whose hotfix retrospective review is the deferred
# maker-checker in full — the reviewer must differ from the Super Admin who
# ran the hotfix, and a completed review is final (never replaced). Same
# per-country opt-in pattern as F2; other countries keep their existing
# review behaviour (hotfix mode exists for single-Super-Admin sessions).
_HOTFIX_DISTINCT_REVIEWER_COUNTRIES = ("SG", "SE", "CH")  # SE: ZP-SE-ENG-001 §14/§16 four-eyes, same opt-in as SG; CH: CH Step 12

# Singapore hotfix policy — OWNER DECISION D2 (docs/SINGAPORE_FINAL_
# IMPLEMENTATION_STATUS.md §20). The default reproduces the behaviour in force
# before the switch existed, so no business decision is made here; choosing
# another value IS the decision and is a reviewed one-line change.
#   RESTRICTED          hotfix allowed; every activation gate except the
#                       approver checks still applies; a DISTINCT Super Admin's
#                       retrospective review is required and is final.
#   PROHIBITED          no Singapore hotfix activation at all.
#   FOLLOW_UP_REQUIRED  RESTRICTED, plus: while any Singapore hotfix awaits its
#                       review, no further Singapore pack may be activated
#                       (hotfix or normal path).
SG_HOTFIX_POLICIES = ("RESTRICTED", "PROHIBITED", "FOLLOW_UP_REQUIRED")
SG_HOTFIX_POLICY = "RESTRICTED"


def _sg_unreviewed_hotfixes(db: Session) -> list:
    return (db.query(PackHotfixActivation.id)
            .join(JurisdictionPack, JurisdictionPack.id == PackHotfixActivation.jurisdiction_pack_id)
            .filter(JurisdictionPack.jurisdiction_country == "SG", PackHotfixActivation.reviewed.is_(False))
            .order_by(PackHotfixActivation.id).all())


def review_pack_hotfix_activation(db: Session, activation_id: int, review_notes: str, actor_id: Optional[int] = None) -> PackHotfixActivation:
    activation = db.query(PackHotfixActivation).filter(PackHotfixActivation.id == activation_id).first()
    if not activation:
        raise NotFoundException("PackHotfixActivation", activation_id)
    pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == activation.jurisdiction_pack_id).first()
    if pack is not None and pack.jurisdiction_country in _HOTFIX_DISTINCT_REVIEWER_COUNTRIES:
        message = None
        if activation.reviewed:
            message = ("This hotfix activation has already been reviewed — its review is retained evidence and "
                       "cannot be replaced.")
        elif actor_id is None or actor_id == activation.activated_by_id:
            message = ("The Super Admin who ran this hotfix cannot review it — a different Super Admin must perform "
                       "the retrospective review (maker-checker).")
        if message:
            _audit_refusal(db, JurisdictionPack, "jurisdiction_pack", pack.id, "hotfix_review", actor_id, message,
                           path="hotfix")
            raise BadRequestException(message)
    activation.reviewed = True
    activation.reviewed_by_id = actor_id
    activation.reviewed_at = datetime.utcnow()
    activation.review_notes = review_notes
    db.commit()
    db.refresh(activation)
    # Completion programme: the retrospective review — the deferred half of
    # the hotfix maker-checker — is itself audit evidence on the pack's trail
    # (it was only a field change on the activation row). Opted-in countries.
    if pack is not None and pack.jurisdiction_country in _HOTFIX_DISTINCT_REVIEWER_COUNTRIES:
        record_tax_audit(
            db, actor_id=actor_id, action="update", entity_type="jurisdiction_pack", entity_id=pack.id,
            jurisdiction_pack_id=pack.id, tax_version=pack.version,
            old_value={"hotfixActivationId": activation.id, "reviewed": False},
            new_value={"hotfixActivationId": activation.id, "reviewed": True, "incidentId": activation.incident_id,
                       "activatedById": activation.activated_by_id},
            reason=f"Hotfix review: {review_notes}" if review_notes else "Hotfix review",
        )
    return activation


def hard_delete_jurisdiction_pack(db: Session, pack_row_id: int) -> dict:
    """NOT EXPOSED over HTTP — the Super Admin "Hard Delete Pack" UI action
    and its backend route were deliberately removed (Production-Grade
    Refactor: Remove Hardcoded Payroll Fallbacks, Enforce Active Compliance
    Packs). A production compliance pack should never be casually,
    permanently destroyed. Use set_jurisdiction_pack_status(..., "Retired")
    for normal lifecycle retirement instead — every pack resolver already
    filters on status=="Active", so a Retired pack is already unresolvable
    to any calculation or onboarding check, without losing its history.

    This function is kept only as a one-off maintenance escape hatch (e.g.
    cleaning up a test pack created by mistake) — call it directly from a
    script/shell if that's ever genuinely needed. Do not re-add an HTTP
    route to this without explicit product sign-off.

    Permanently delete a Tax or Policy pack — the pack row itself, its
    canonical ContributionRate/TaxSlab rows, and its TaxConfigurationAudit
    trail. Unlike set_jurisdiction_pack_status("Retired"), nothing about
    this pack survives.

    Blocked (BadRequestException) in either of two cases, both checked
    BEFORE anything is touched:
      1. Any organization is currently assigned to this pack
         (CompanyComplianceDetails.active_pack_id) — reuses
         get_pack_applicable_organizations, the same check the "Assign"
         UI already uses to show who's on a pack.
      2. Any payslip, for any organization, past or present, was ever
         generated using this pack's rates (PayslipItem.tax_policy_pack_id)
         — per the model's own comment on that column, a payslip's figures
         "MUST NOT change... reproducible even if the pack row is later
         retired," so a pack with real payroll history is retirable, never
         deletable.

    When neither block applies, two more FK relationships are cleaned up
    (not blocked on, since neither is organization or payslip data):
      - Any OTHER org's own ContributionRate/TaxSlab row that still
        carries a stale jurisdiction_pack_id pointing at this pack (left
        over from a past sync to a component_key the org's *current*
        pack no longer has) gets that pointer nulled — the org's actual
        rate values are untouched, only the provenance breadcrumb clears.
        Safe specifically because block #1 above already confirmed no
        org is CURRENTLY assigned to this pack.
      - Any other JurisdictionPack whose previous_version_id points at
        this one (version-chain metadata) gets that pointer nulled.
    """
    pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == pack_row_id).first()
    if not pack:
        raise NotFoundException("JurisdictionPack", pack_row_id)

    assigned_orgs = get_pack_applicable_organizations(db, pack.id)
    if assigned_orgs:
        names = ", ".join(o["organizationName"] for o in assigned_orgs[:5])
        raise BadRequestException(
            f"{pack.pack_id} v{pack.version} is still assigned to {len(assigned_orgs)} "
            f"organization(s) ({names}{'…' if len(assigned_orgs) > 5 else ''}) — unassign them before deleting."
        )

    has_payslip_history = (
        db.query(PayslipItem.id).filter(PayslipItem.tax_policy_pack_id == pack.id).first() is not None
    )
    if has_payslip_history:
        raise BadRequestException(
            f"{pack.pack_id} v{pack.version} has real payroll history — at least one payslip was "
            f"generated using its rates and must keep referencing it. Retire it instead of deleting."
        )

    db.query(ContributionRate).filter(
        ContributionRate.jurisdiction_pack_id == pack.id, ContributionRate.organization_id.isnot(None),
    ).update({"jurisdiction_pack_id": None}, synchronize_session=False)
    db.query(TaxSlab).filter(
        TaxSlab.jurisdiction_pack_id == pack.id, TaxSlab.organization_id.isnot(None),
    ).update({"jurisdiction_pack_id": None}, synchronize_session=False)
    db.query(JurisdictionPack).filter(JurisdictionPack.previous_version_id == pack.id).update(
        {"previous_version_id": None}, synchronize_session=False,
    )

    db.query(TaxConfigurationAudit).filter(TaxConfigurationAudit.jurisdiction_pack_id == pack.id).delete()
    db.query(ContributionRate).filter(ContributionRate.jurisdiction_pack_id == pack.id).delete()
    db.query(TaxSlab).filter(TaxSlab.jurisdiction_pack_id == pack.id).delete()

    pack_id_label, version_label = pack.pack_id, pack.version
    db.delete(pack)
    db.commit()

    import logging
    logging.getLogger("zoiko").info(
        f"[compliance] Super Admin permanently deleted jurisdiction pack {pack_id_label} v{version_label} (id={pack_row_id})."
    )
    return {"packId": pack_id_label, "version": version_label}


