def _run_has_country_payslips(db: Session, run: PayrollRun, country: str) -> bool:
    return db.query(PayslipItem.id).filter(
        PayslipItem.payroll_run_id == run.id, PayslipItem.country_code == country).first() is not None


def advance_payroll_run_status(
    db: Session, run_id: int, approver_id: int, organization_id: int = None,
    background_tasks: "BackgroundTasks" = None,
) -> PayrollRun:
    """Moves a run one step forward in its lifecycle
    (Draft → Review → Approved → Authorized → Paid → Closed).
    Backs the single "Approve" button in the UI.

    Notification emails (and, for the Paid transition, payslip PDF generation)
    are dispatched via `background_tasks` when the caller provides one, so the
    HTTP response doesn't wait on N blocking SMTP sends / PDF renders for an
    n-employee run. Falls back to running them inline if no background_tasks
    is passed (e.g. from a script or test)."""
    run = get_payroll_run_by_id(db, run_id, organization_id)
    if _sg_run_has_payslips(db, run):
        _sg_lock_run(db, run)
        db.refresh(run)                   # the status another (serialised) caller may just have committed
    current_idx = PAYROLL_STATUS_ORDER.index(run.status)
    if current_idx >= len(PAYROLL_STATUS_ORDER) - 1:
        raise HTTPException(http_status.HTTP_409_CONFLICT, detail="This run has already reached its final status.")

    next_status = PAYROLL_STATUS_ORDER[current_idx + 1]
    if next_status == PayrollStatus.PAID:
        unresolved_statuses = {
            item_status for (item_status,) in db.query(PayslipItem.status).filter(
                PayslipItem.payroll_run_id == run.id,
            ).all()
            if item_status != PayslipStatus.PENDING.value
        }
        if unresolved_statuses:
            statuses = ", ".join(sorted(str(value) for value in unresolved_statuses))
            raise HTTPException(
                http_status.HTTP_409_CONFLICT,
                detail=(
                    "Cannot mark this payroll run as Paid while payslips have "
                    f"unresolved statuses: {statuses}. Resolve or recalculate them first."
                ),
            )
    # Singapore (SG-gated): preflight blocks approval; a later step re-verifies
    # the approval fingerprint (SG-032). Runs without SG payslips skip this.
    _sg_before_run_transition(db, run, next_status, approver_id)
    # Switzerland (CH-gated): preflight + preparer/approver separation at
    # approval; fingerprint re-verification at authorize / pay.
    _ch_before_run_transition(db, run, next_status, approver_id)
    # Jurisdiction statutory modules (Hong Kong): the preflight's BLOCK checks
    # are statutory exceptions, so they refuse approval. A run without that
    # jurisdiction's payslips never reaches its module.
    for country in jurisdiction_hooks.countries():
        if _run_has_country_payslips(db, run, country):
            jurisdiction_hooks.call(country, "before_run_transition", db, run, next_status, approver_id)
    run.status = next_status
    if next_status == PayrollStatus.APPROVED:
        run.approved_by = approver_id
        run.approved_at = datetime.utcnow()
    if next_status == PayrollStatus.AUTHORIZED:
        run.authorized_by = approver_id
        run.authorized_at = datetime.utcnow()
    if next_status == PayrollStatus.PAID:
        run.paid_by = approver_id
        run.processed_at = datetime.utcnow()
        db.query(PayslipItem).filter(PayslipItem.payroll_run_id == run.id).update(
            {PayslipItem.status: PayslipStatus.PAID, PayslipItem.paid_at: datetime.utcnow()}
        )
    db.commit()
    db.refresh(run)
    if next_status == PayrollStatus.APPROVED:
        _sg_after_run_approved(db, run, approver_id)
        _ch_after_run_approved(db, run, approver_id)

    log_activity(db, organization_id, f"Payroll run '{run.period_label}' advanced to {next_status.value}.",
                 ActivityStatus.SUCCESS, actor_id=approver_id)

    notify_kind = "approved" if next_status == PayrollStatus.APPROVED else (
        "paid" if next_status == PayrollStatus.PAID else None
    )
    if notify_kind:
        if background_tasks is not None:
            background_tasks.add_task(_run_notifications_in_background, run.id, organization_id, notify_kind)
        elif notify_kind == "approved":
            _notify_payroll_run_approved(db, run, organization_id)
        else:
            _notify_payslips_ready(db, run, organization_id)

    return run


def _reverse_run_ytd_postings(db: Session, run: PayrollRun) -> None:
    """Reverse every payslip's posted YTD within a run before the run itself
    is deleted — DELETE-payroll-run integrity. Iterated newest-first so the
    ADDITIVE employer-level rows rewind their last_updated_payslip_id
    ownership chain back to the run's predecessor (or NULL) instead of a
    payslip this deletion is about to cascade-remove; rows are only left with
    a previous writer that still exists. Fail-closed (YtdPostingConflict) on
    an ABSOLUTE row a later payslip — in another run — already built on,
    exactly like delete_payslip: deleting the run would silently abandon
    that total's provenance."""
    items = (db.query(PayslipItem)
             .filter(PayslipItem.payroll_run_id == run.id)
             .order_by(PayslipItem.id.desc()).all())
    for item in items:
        postings = _ytd_postings_of(item)
        if postings is not None:
            _ytd_reverse_postings(db, item, postings, require_latest=True, delete_created=True)
        else:
            _ytd_reverse_legacy(db, item)


def delete_payroll_run(db: Session, run_id: int, organization_id: int = None):
    run = get_payroll_run_by_id(db, run_id, organization_id)
    if run.status != PayrollStatus.DRAFT:
        raise HTTPException(http_status.HTTP_409_CONFLICT, detail="Only Draft runs can be deleted.")
    if (run.notes or "").startswith("[HK-CORRECTION]"):
        raise HTTPException(http_status.HTTP_409_CONFLICT, detail=(
            "This is a Hong Kong correction run — reject the correction instead (its record is kept for audit)."))
    _deleted_run_period = run.period_label
    _deleted_run_code = run.run_code
    # Year-to-date accumulators (every YTD jurisdiction): reverse what every
    # payslip in this run posted before the run itself is deleted — never
    # leave a stale total or a dangling last_updated_payslip_id pointing at a
    # cascade-removed payslip. Refused (fail-closed) when a later payslip
    # already built on one of this run's absolute totals.
    try:
        _reverse_run_ytd_postings(db, run)
    except YtdPostingConflict as exc:
        db.rollback()
        raise HTTPException(http_status.HTTP_409_CONFLICT, detail=f"Cannot delete this payroll run: {exc}")
    db.delete(run)
    db.commit()
    _notify_payroll_run_deleted(db, _deleted_run_period or "", _deleted_run_code or "", organization_id, run_id=run_id)


def delete_payslip(db: Session, payslip_id: int, organization_id: int = None):
    query = db.query(PayslipItem)
    query = _apply_org_filter(query, PayslipItem, organization_id)
    query = query.filter(PayslipItem.id == payslip_id)
    item = query.first()
    if not item:
        raise NotFoundException(f"Payslip {payslip_id} not found.")
    run = db.query(PayrollRun).filter(PayrollRun.id == item.payroll_run_id).first()
    if run and run.status != PayrollStatus.DRAFT:
        raise HTTPException(http_status.HTTP_409_CONFLICT, detail="Only payslips in Draft runs can be deleted.")
    if run and (run.notes or "").startswith("[HK-CORRECTION]"):
        raise HTTPException(http_status.HTTP_409_CONFLICT, detail=(
            "This is a Hong Kong correction delta — reject the correction instead (its record is kept for audit)."))
    # Phase 8AS: fail-closed — refuse to delete a payslip that has Germany
    # overtime premium components still ATTACHED. Deleting would silently
    # erase money the operator explicitly attached (the credited allowance
    # line and the applied gross/SI/net deltas) while the component rows
    # remain ATTACHED pointing at now-deleted rows. The operator must detach
    # premium components first (detach reverses the money and flips them to
    # DETACHED), then delete the payslip — mirroring the same "never silently
    # destroy an attached financial fact" discipline every attach/detach
    # guard in this module enforces.
    attached_ot = _attached_germany_overtime_components_for_item(db, item.id, organization_id)
    if attached_ot:
        raise HTTPException(
            http_status.HTTP_409_CONFLICT,
            detail=(
                "Cannot delete this payslip: it has Germany overtime premium components "
                "still attached. Detach them first (this reverses their money), then delete."
            ),
        )
    # Singapore IR21: a payslip that carries (or is covered by) a RELEASED
    # tax-clearance release is part of a released statutory amount.
    if (item.country_code or "").upper() == "SG" and run is not None:
        try:
            _sg_guard_later_same_month_payslip(db, item.employee_id, run, "delete")
        except BadRequestException as exc:
            raise HTTPException(http_status.HTTP_409_CONFLICT, detail=exc.detail)
        released = next((c for c in _sg_ir21_open_cases_for(db, item.organization_id, {item.employee_id}, run.pay_date)
                         if c.status == "RELEASED" or c.final_payslip_id == item.id), None)
        if released is not None:
            raise HTTPException(
                http_status.HTTP_409_CONFLICT,
                detail=f"Cannot delete this payslip: IR21 case {released.id} ({released.status}) covers it.",
            )
    # Year-to-date accumulators (every YTD jurisdiction): reverse what this
    # payslip posted, or refuse when a later payslip already built on it —
    # never leave a stale total or a dangling last_updated_payslip_id.
    postings = _ytd_postings_of(item)
    try:
        if postings is not None:
            _ytd_reverse_postings(db, item, postings, require_latest=True, delete_created=True)
        else:
            _ytd_reverse_legacy(db, item)
    except YtdPostingConflict as exc:
        db.rollback()
        raise HTTPException(http_status.HTTP_409_CONFLICT, detail=f"Cannot delete this payslip: {exc}")
    db.delete(item)
    db.commit()
    _notify_payslip_deleted(db, item, run, organization_id)


# ── Payslip Items ──────────────────────────────────────────────────────

def add_payslip_item(db: Session, run_id: int, data: PayslipItemCreate, organization_id: int = None) -> PayslipItem:
    run = get_payroll_run_by_id(db, run_id, organization_id)
    employee = db.query(PayrollEmployee).filter(
        PayrollEmployee.id == data.employee_id,
        PayrollEmployee.organization_id == organization_id,
    ).first()
    if not employee:
        raise NotFoundException(f"Employee {data.employee_id} not found.")

    # Employee's own jurisdiction overrides the org default — same
    # resolution generate_payslips_for_run/regenerate_employee_payslip
    # already use (_resolve_employee_country). Previously this looked only
    # at the org's compliance details, silently ignoring an employee's own
    # country_code override for manually-added payslips specifically.
    country = _resolve_employee_country(db, organization_id, getattr(employee, "country_code", None))
    _ch_refuse_locked_run(run, country)

    # Same canonical-pack substitution generate_payslips_for_run uses (see
    # _resolve_effective_rate_inputs) — a manually-added payslip should be
    # governed by the same period-correct rates a normal run would use.
    org_opted_in = _org_uses_canonical_tax_pack(db, organization_id)
    work_state = getattr(employee, "work_state", None)
    resolution_state, poe_reason = _resolve_country_aware_state(country, employee, work_state, db=db, organization_id=organization_id)
    poe_snapshot = {"poe_result": resolution_state, "poe_reason": poe_reason} if country == "CA" else None
    rate_map, slabs, canonical_rates, pack = _resolve_effective_rate_inputs(
        db, organization_id, country, _sg_wage_date(run) if country == "SG" else run.pay_date, org_opted_in,
        state=resolution_state, tax_regime=getattr(employee, "tax_regime", None),
        filing_status=getattr(employee, "w4_filing_status", None),
    )
    # Region-specific rules (Scotland's own tax bands, India's state PT,
    # ...) — the SAME call generate_payslips_for_run's per-employee
    # compute already makes. Without this, a manually-added payslip for a
    # region-scoped employee could silently use national-only figures
    # while a real run for the same employee correctly used their
    # region's config.
    state_rate_map, state_slabs = get_state_scoped_config(
        db, country, resolution_state, as_of=run.pay_date, filing_status=getattr(employee, "w4_filing_status", None),
    )
    # Phase 8U: Germany accident insurance (spec §14) reuses this SAME
    # agency-assigned-rate mechanism as US SUI — an employer's
    # Berufsgenossenschaft-issued risk-class rate is exactly the same
    # statutory shape (assigned by an agency, own account number, own
    # evidence trail) EmployerTaxProfile already models; jurisdiction_id
    # "DE" (no state) resolves it, component_code "DE_ACCIDENT_INSURANCE".
    jurisdiction_id = (
        f"{country}-{resolution_state}" if (country in ("US", "CA", "AU") and resolution_state)
        else "DE" if country == "DE"
        # Dominican Republic SRL — see the matching comment in
        # _resolve_employee_calc_inputs.
        else "DO" if country == "DO"
        else None
    )
    employer_tax_profiles = get_employer_tax_profiles(db, organization_id, jurisdiction_id, as_of=run.pay_date)
    # EI's reduced-employer-rate authorization — see the matching comment
    # in _resolve_employee_calc_inputs.
    if country == "CA":
        employer_tax_profiles = {
            **get_employer_tax_profiles(db, organization_id, "CA", as_of=run.pay_date),
            **employer_tax_profiles,
        }
    reciprocity = _resolve_us_reciprocity(db, employee, country, resolution_state, as_of=run.pay_date)
    locality_rate = (
        get_locality_rate(db, country, getattr(employee, "work_locality", None), as_of=run.pay_date)
        if country == "US" else None
    )
    residence_locality_rate = (
        get_locality_rate(db, country, getattr(employee, "residence_locality", None), as_of=run.pay_date)
        if country == "US" else None
    )

    calculation_mode = getattr(run, "calculation_mode", None) or _resolve_calculation_mode(db, organization_id)
    gross = data.basic_salary + (data.hra or 0) + (data.special_allowance or 0) + (data.overtime or 0)

    # Germany (Phase 8E): a manually-added payslip for a Germany employee must
    # consume the SAME effective-dated statutory inputs and fail-closed
    # behavior as a generated run — the same _resolve_germany_calc_inputs the
    # batch path (_compute_payslip_values) uses for DE. Without this, a manual
    # DE payslip would bypass statutory-profile/health-fund/ceiling/PV wiring
    # and could not be reproducibly snapshotted.
    france_inputs = (
        _resolve_france_calc_inputs(db, organization_id, employee, run.pay_date, exclude_run_id=run.id)
        if country == "FR" else None
    )
    # Ireland (ZP-IE-ENG-001): a manually-added IE payslip must consume the
    # SAME frozen RPN / MyFutureFund / YTD inputs as a generated run, or it
    # would bypass the statutory wiring and could not be reproducibly
    # snapshotted.
    ireland_inputs = (
        _resolve_ie_calc_inputs(db, organization_id, employee, run.pay_date, exclude_run_id=run.id)
        if country == "IE" else None
    )
    sweden_inputs = (
        _resolve_se_calc_inputs(db, organization_id, employee, run.pay_date, exclude_run_id=run.id)
        if country == "SE" else None
    )
    italy_inputs = (
        _italy_service.resolve_it_calc_inputs(
            db, organization_id, employee, run.pay_date,
            period_start=run.period_start, period_end=run.period_end, exclude_run_id=run.id)
        if country == "IT" else None
    )
    switzerland_attrs = (
        _switzerland_service.ch_calc_context(
            db, organization_id, employee, run.pay_date, run.period_start, run.period_end,
            _switzerland_service.ch_earnings(data.basic_salary, data.hra or Decimal("0"),
                                             data.special_allowance or Decimal("0"), data.overtime or Decimal("0"),
                                             Decimal("0")))
        if country == "CH" else None
    )
    germany_kwargs = {}
    if country == "DE":
        resolved_de = _resolve_germany_calc_inputs(db, organization_id, employee, run.pay_date)
        germany_kwargs = dict(
            germany_statutory_profile=resolved_de["statutory_profile"],
            germany_pap_asset=resolved_de["pap_asset"],
            germany_health_fund=resolved_de["health_fund"],
            germany_u1_tariff=resolved_de["u1_tariff"],
            germany_earning_taxability=resolved_de["earning_taxability"],
            germany_ceiling_gkv_pv=resolved_de["ceiling_gkv_pv"],
            germany_ceiling_rv_alv=resolved_de["ceiling_rv_alv"],
            germany_pv_configuration=resolved_de["pv_configuration"],
            germany_church_tax_exception=resolved_de["church_tax_exception"],
            germany_minijob_midijob_parameters=resolved_de["minijob_midijob_parameters"],
            germany_employee_id=employee.id,
            germany_organization_id=organization_id,
            germany_payroll_date=run.pay_date,
        )

    # Canada YTD — READ before calculating (see _load_ca_ytd's docstring);
    # this path DOES persist a real PayslipItem below, so it also WRITEs
    # the resulting post-period state back once the item has a real id
    # (the "manually add a payslip" path — easy to miss, and CPP/CPP2/EI
    # would silently regress to the old annualized-only behavior here even
    # after the run-generation path is fixed, if this weren't wired too).
    ytd_inputs = (
        _load_ca_ytd(db, employee.id, run.pay_date, work_state) if country == "CA"
        else _load_uk_director_ytd(db, employee.id, run.pay_date) if country == "UK"
        else _load_us_ytd(db, employee.id, run.pay_date) if country == "US"
        else {**_load_au_sg_ytd(db, employee.id, run.pay_date), **_load_au_whm_ytd(db, employee.id, run.pay_date)} if country == "AU"
        else _load_ky_pension_ytd(db, employee.id, run.pay_date) if country == "KY"
        else _load_gy_paye_credit_ytd(db, employee.id, run.pay_date) if country == "GY"
        else _load_pr_ytd(db, employee.id, run.pay_date) if country == "PR"
        else _load_sg_cpf_ytd(db, employee.id, run.pay_date, lock=True, current_run_id=run.id, wage_date=_sg_wage_date(run)) if country == "SG"
        else {}
    )

    # Ontario EHT / BC EHT / Manitoba HE Levy / NL HAPSET org-level read —
    # same helper generate_payslips_for_run's loop uses (see its own
    # docstring): a manually-added payslip for one of these four
    # jurisdictions must consume the org's running total exactly like a
    # normal run would, or the levy would silently regress to 0 here.
    org_levy_inputs = (
        _ca_org_levy_read_inputs(db, organization_id, run.pay_date, work_state) if country == "CA"
        else _load_uk_org_levy_ytd(db, organization_id, run.pay_date) if country == "UK"
        else _au_org_payroll_tax_read_inputs(db, organization_id, run.pay_date, work_state) if country == "AU"
        else _load_jm_heart_ytd(db, organization_id, run.pay_date) if country == "JM"
        else {}
    )
    option2_inputs = (
        _load_ca_option2_ytd(db, employee.id, run.pay_date, work_state) if country == "CA" else {}
    )

    # Delegate to the strategy engine (no attendance data for manual payslips)
    from app.modules.payroll.engine.resolver import calculate_payroll, build_context_from_employee
    from app.modules.payroll.engine.jurisdictions.germany.pap.core import GermanyCalculationError
    from app.modules.payroll.engine.countries.france import FranceCalculationBlockedError
    from app.core.exceptions import GermanyCalculationBlockedException
    ni_category_override = (
        _resolve_uk_ni_category_override(db, employee, run.pay_date, rate_map) if country == "UK" else None
    )
    code_wages_rules = (
        get_code_wages_classification(db, country, organization_id, as_of=run.pay_date) if country == "IN" else {}
    )
    epf_base_rules = (
        get_epf_base_classification(db, country, organization_id, as_of=run.pay_date) if country == "IN" else {}
    )
    esi_base_rules = (
        get_esi_base_classification(db, country, organization_id, as_of=run.pay_date) if country == "IN" else {}
    )
    pt_base_rules = (
        get_pt_base_classification(db, country, organization_id, as_of=run.pay_date) if country == "IN" else {}
    )
    ca_taxability_rules = (
        get_ca_taxability_rules_bundle(db, organization_id, as_of=run.pay_date) if country == "CA" else {}
    )
    us_taxability_rules = (
        get_us_taxability_rules_bundle(db, organization_id, as_of=run.pay_date) if country == "US" else {}
    )
    au_taxability_rules = (
        get_au_taxability_rules_bundle(db, organization_id, as_of=run.pay_date) if country == "AU" else {}
    )
    au_statutory_deduction_orders = (
        _load_au_active_court_orders(db, employee.id, organization_id, run.pay_date) if country == "AU" else []
    )
    salary_tds_inputs = (
        get_india_salary_tds_inputs(db, organization_id, employee.id, india_tax_year_for_date(run.pay_date))
        if country == "IN" else {}
    )
    pr_certificate_inputs = (
        get_pr_certificate_inputs(db, organization_id, employee.id) if country == "PR" else {}
    )
    ctx = build_context_from_employee(
        employee, gross=gross, basic=data.basic_salary,
        hra=data.hra or Decimal("0"), special_allowance=data.special_allowance or Decimal("0"),
        overtime=data.overtime or Decimal("0"),
        unpaid_leave_days=0,
        country=country, rate_map=rate_map, slabs=slabs,
        code_wages_rules=code_wages_rules,
        epf_base_rules=epf_base_rules, esi_base_rules=esi_base_rules, pt_base_rules=pt_base_rules,
        ca_taxability_rules=ca_taxability_rules,
        us_taxability_rules=us_taxability_rules,
        au_taxability_rules=au_taxability_rules,
        au_statutory_deduction_orders=au_statutory_deduction_orders,
        other_income_for_tds=salary_tds_inputs.get("other_income_for_tds", Decimal("0")),
        tds_already_deducted=salary_tds_inputs.get("tds_already_deducted", Decimal("0")),
        annual_claims_total=salary_tds_inputs.get("claims_total", Decimal("0")),
        annual_perquisites_total=salary_tds_inputs.get("perquisites_total", Decimal("0")),
        work_state=work_state, state_rate_map=state_rate_map, state_slabs=state_slabs,
        employer_tax_profiles=employer_tax_profiles,
        locality_rate=locality_rate,
        residence_locality_rate=residence_locality_rate,
        pay_date=run.pay_date,
        period_start=run.period_start, period_end=run.period_end,
        ni_category_override=ni_category_override,
        calendar_days=_calendar_days(run.period_start, run.period_end),
        **reciprocity,
        **germany_kwargs,
        france_inputs=france_inputs,
        ireland_inputs=ireland_inputs,
        sweden_inputs=sweden_inputs,
        italy_inputs=italy_inputs,
        **ytd_inputs,
        **org_levy_inputs,
        **option2_inputs,
        **pr_certificate_inputs,
    )
    switzerland_frozen = None
    if switzerland_attrs is not None:
        _switzerland_service.apply_ch_context(ctx, switzerland_attrs)
        switzerland_frozen = _switzerland_service.ch_freeze_context(ctx, switzerland_attrs, calculation_mode)
    try:
        calc = calculate_payroll(ctx, calculation_mode)
    except FranceCalculationBlockedError as exc:
        raise _france_blocked(exc)
    except GermanyCalculationError as exc:
        # Same structured 400 the batch path returns — never fabricate a
        # Germany payslip when wage-tax execution is unavailable (§25).
        raise GermanyCalculationBlockedException(
            exc.code, exc.message, trace=(exc.trace.to_dict() if exc.trace else None),
        )

    employee_name = getattr(employee, "name", None) or ""
    if pack is not None:
        tax_snapshot = _pack_to_tax_snapshot(canonical_rates, slabs, pack)
    else:
        tax_snapshot = _resolve_tax_snapshot(db, country, run.pay_date)
    # AC-32 historical-replay gap closure — see _build_overlay_tax_snapshot.
    if tax_snapshot.get("tax_rule_snapshot") is None:
        tax_snapshot["tax_rule_snapshot"] = {}
    tax_snapshot["tax_rule_snapshot"].update(
        _build_overlay_tax_snapshot(state_rate_map, state_slabs, employer_tax_profiles, reciprocity, locality_rate)
    )

    item = PayslipItem(
        payroll_run_id=run_id,
        employee_id=data.employee_id,
        organization_id=organization_id,
        employee_name=employee_name,
        department=getattr(employee, "department", None),
        designation=getattr(employee, "designation", None),
        date_of_joining=getattr(employee, "date_of_joining", None),
        bank_name=getattr(employee, "bank_name", None),
        bank_account=getattr(employee, "bank_account", None),
        pan=getattr(employee, "pan", None),
        uan=getattr(employee, "uan", None),
        ifsc=getattr(employee, "ifsc", None),
        country_code=country,
        compliance_fields=dict(getattr(employee, "compliance_fields", None) or {}),
        ch_calculation_snapshot=_switzerland_service.ch_payslip_snapshot(calc, frozen=switzerland_frozen),
        **tax_snapshot,
        basic_salary=calc.basic,
        hra=calc.hra,
        special_allowance=calc.special_allowance,
        overtime=calc.overtime,
        gross_pay=calc.gross,
        pf=calc.employee_pf,
        esi=calc.employee_esi,
        professional_tax=calc.professional_tax,
        employee_lwf=calc.employee_lwf,
        employer_lwf=calc.employer_lwf,
        social_security=calc.social_security,
        medicare=calc.medicare,
        ni_employee=calc.ni_employee,
        # UK: employer-side National Insurance, Student/Postgraduate Loan,
        # and Apprenticeship Levy — found 2026-09-09 gap-closure Phase 3
        # while wiring the Director NIC/Levy accumulators through this
        # exact manual-add path: all four were computed into `calc`
        # correctly but never written onto a manually-added payslip item,
        # so a manually-added UK payslip always showed 0 for these despite
        # a normal run-generated payslip (_compute_payslip_values) getting
        # study/postgrad loan right already.
        employer_ni=calc.employer_ni,
        study_loan_deduction=calc.study_loan_deduction,
        postgrad_loan_deduction=calc.postgrad_loan_deduction,
        employer_apprenticeship_levy=calc.employer_apprenticeship_levy,
        auto_enrolment_status=calc.auto_enrolment_status,
        tax_week=calc.tax_week,
        tax_month=calc.tax_month,
        employee_pension=calc.employee_pension,
        # Canada: CPP2 — genuinely missing here before (computed and
        # deducted from net_pay correctly via total_employee_deductions,
        # but never actually written onto a manually-added payslip item,
        # so its own line always showed 0 despite reducing net pay).
        cpp2=calc.cpp2,
        cpp_base_amount=calc.cpp_base_amount,
        cpp_first_additional_amount=calc.cpp_first_additional_amount,
        tds=calc.tds,
        # Germany (Phase 8BN): Kirchensteuer — same "computed and deducted
        # from net_pay but never persisted" defect class as cpp2/studyLoan
        # above. engine/standard.py folds church_tax into
        # total_employee_deductions, so a manually-added German payslip's
        # net_pay was real but its church_tax column stayed 0 — the payslip
        # then showed "Kirchensteuer 0.00" alongside a net pay that had
        # actually been reduced. The engine's `church_tax` (a PayrollResult
        # field, populated by engine/countries/germany.py) is persisted here
        # exactly like the batch path persists it via _compute_payslip_values.
        church_tax=calc.church_tax,
        # Germany (Phase 8BN): Solidaritätszuschlag — mirrored onto a
        # manually-added payslip exactly like church_tax above, so the new
        # PayslipItem.soli column never silently stays 0 on a manual row
        # whose engine PayrollResult genuinely carried Soli (informational:
        # tds/net_pay are unaffected — Soli was already folded into them).
        soli=calc.soli,
        # US: broken-out federal/state/local tax — added alongside tds
        # above so a manually-added US payslip doesn't reintroduce the
        # same "totals right, detail columns silently zero" gap this field
        # split was specifically meant to close (see engine/countries/us.py).
        federal_income_tax=calc.federal_income_tax,
        state_income_tax=calc.state_income_tax,
        local_tax=calc.local_tax,
        state_disability_insurance=calc.state_disability_insurance,
        state_program_deductions=calc.state_program_deductions,
        total_deductions=calc.total_deductions,
        employer_pf=calc.employer_pf,
        employer_eps=calc.employer_eps,
        employer_pf_residual=calc.employer_pf_residual,
        employer_edli=calc.employer_edli,
        employer_nps=calc.employer_nps,
        employer_esi=calc.employer_esi,
        employer_social_security=calc.employer_social_security,
        employer_medicare=calc.employer_medicare,
        employer_pension=calc.employer_pension,
        employer_sui=calc.employer_sui,
        employer_state_program_contributions=calc.employer_state_program_contributions,
        employer_cpp2=calc.employer_cpp2,
        employer_cpp_base=calc.employer_cpp_base,
        employer_cpp_first_additional=calc.employer_cpp_first_additional,
        employer_eht=calc.employer_eht,
        employer_bc_eht=calc.employer_bc_eht,
        employer_mb_he_levy=calc.employer_mb_he_levy,
        employer_nl_hapset=calc.employer_nl_hapset,
        employer_qc_hsf=calc.employer_qc_hsf,
        employer_qc_labour_standards=calc.employer_qc_labour_standards,
        employer_payroll_tax=calc.employer_payroll_tax,
        au_statutory_deductions_total=calc.au_statutory_deductions_total,
        au_workers_compensation_premium=calc.au_workers_compensation_premium,
        au_calculation_trace=calc.au_calculation_trace,
        sgp_calculation_trace=calc.sgp_calculation_trace,
        net_pay=calc.net_pay,
        unpaid_leave_days=calc.unpaid_leave_days,
        attendance_deduction=calc.attendance_deduction,
        per_day_salary=calc.per_day_salary,
        payable_days=Decimal(calc.payable_days),
        total_working_days=Decimal(calc.calendar_days),
        # Germany (Phase 7/8E) — frozen statutory provenance, same as the
        # batch path; None for every non-German manual payslip.
        employee_statutory_profile_id=calc.germany_statutory_profile_id,
        germany_calculation_snapshot=calc.germany_calculation_snapshot,
        fr_calculation_snapshot=_fr_payslip_snapshot(calc),
        # Phase 8BU: same PARTIAL-vs-PENDING decision as the batch path
        # (_generate_single_payslip) — a manually-added Germany payslip
        # must not silently present a PARTIAL calculation as complete.
        status=(PayslipStatus.PARTIAL if getattr(calc, "germany_unavailable_components", None) else PayslipStatus.PENDING),
        notes=data.notes,
        ytd_snapshot=(
            {
                "cpp": {"ytd_before": str(ctx.ytd_pensionable_earnings), "ytd_after": str(calc.ytd_pensionable_earnings)},
                "cpp2": {"ytd_before": str(ctx.ytd_cpp2_pensionable_earnings), "ytd_after": str(calc.ytd_cpp2_pensionable_earnings)},
                "ei": {"ytd_before": str(ctx.ytd_insurable_earnings), "ytd_after": str(calc.ytd_insurable_earnings)},
                "cpp_basic_exemption": {"ytd_before": str(ctx.ytd_basic_exemption_used), "ytd_after": str(calc.ytd_basic_exemption_used)},
            } if calc.ytd_pensionable_earnings is not None else
            {
                "social_security": {"ytd_before": str(ctx.ytd_ss_wages_before), "ytd_after": str(calc.ytd_ss_wages_after)},
                "futa": {"ytd_before": str(ctx.ytd_futa_wages_before), "ytd_after": str(calc.ytd_futa_wages_after)},
                "medicare_additional": {"ytd_before": str(ctx.ytd_medicare_wages_before), "ytd_after": str(calc.ytd_medicare_wages_after)},
            } if calc.ytd_ss_wages_after is not None else
            {
                # Singapore CPF annual-ceiling accumulators (SG-010) — frozen
                # before/after per component, same contract as CA/US above.
                "cpf_ow_subject": {"ytd_before": str(ctx.ytd_cpf_ow_subject_before), "ytd_after": str(calc.ytd_cpf_ow_subject_after)},
                "cpf_aw_subject": {"ytd_before": str(ctx.ytd_cpf_aw_subject_before), "ytd_after": str(calc.ytd_cpf_aw_subject_after)},
                "cpf_aw_paid": {"ytd_before": str(ctx.ytd_cpf_aw_paid_before), "ytd_after": str(calc.ytd_cpf_aw_paid_after)},
            } if calc.ytd_cpf_ow_subject_after is not None else
            {
                **({"sg_qualifying_earnings": {"ytd_before": str(ctx.ytd_sg_qualifying_earnings_before), "ytd_after": str(calc.ytd_sg_qualifying_earnings_after)}} if calc.ytd_sg_qualifying_earnings_after is not None else {}),
                **({"whm_earnings": {"ytd_before": str(ctx.ytd_whm_earnings_before), "ytd_after": str(calc.ytd_whm_earnings_after)}} if calc.ytd_whm_earnings_after is not None else {}),
            } if (calc.ytd_sg_qualifying_earnings_after is not None or calc.ytd_whm_earnings_after is not None) else None
        ),
        poe_snapshot=poe_snapshot,
    )
    ytd_pre_state = _ytd_capture_state(db, employee.id, organization_id)
    db.add(item)
    if calc.ytd_pensionable_earnings is not None:
        db.flush()  # need item.id for last_updated_payslip_id
        _upsert_ca_ytd_accumulator(db, employee.id, run.pay_date, work_state, calc, payslip_id=item.id)
    if calc.ytd_director_ni_gross is not None:
        db.flush()  # need item.id for last_updated_payslip_id
        _upsert_uk_director_ytd_accumulator(db, employee.id, run.pay_date, calc, payslip_id=item.id)
    if calc.ytd_ss_wages_after is not None:
        db.flush()  # need item.id for last_updated_payslip_id
        _upsert_us_ytd_accumulator(db, employee.id, run.pay_date, calc, payslip_id=item.id)
    if calc.ytd_sg_qualifying_earnings_after is not None:
        db.flush()  # need item.id for last_updated_payslip_id/payslip_item_id
        _upsert_au_sg_ytd_accumulator(db, employee.id, run.pay_date, calc, payslip_id=item.id)
        # Payday Super (§10): manually-added payslip path — the "easy to
        # miss" case _upsert_ca_ytd_accumulator's own comment above warns
        # about applies identically here.
        create_au_sg_liability(
            db, organization_id, employee.id, run.pay_date,
            qualifying_earnings=calc.sg_qualifying_earnings_period,
            sg_rate_pct=calc.sg_rate_pct, sg_amount=calc.employer_pension,
            ytd_qualifying_earnings_after=calc.ytd_sg_qualifying_earnings_after,
            mcb_reached=calc.sg_mcb_reached, payslip_item_id=item.id,
        )
    if calc.ytd_whm_earnings_after is not None:
        db.flush()  # need item.id for last_updated_payslip_id
        _upsert_au_whm_ytd_accumulator(db, employee.id, run.pay_date, calc, payslip_id=item.id)
    if calc.ie_ytd_after:
        db.flush()  # need item.id for last_payslip_id
        # Ireland (ZP-IE-ENG-001) manually-added payslip path — this one DOES
        # persist a real payslip, so it must advance USC/PRSI/MyFutureFund
        # cumulative state exactly like a generated run, or those bases would
        # silently regress to zero-only behaviour here.
        _upsert_ie_ytd_accumulator(db, employee.id, organization_id, run.pay_date, calc, payslip_id=item.id)
    if calc.ytd_ky_mandatory_pensionable_earnings_after is not None:
        db.flush()  # need item.id for last_updated_payslip_id
        _upsert_ky_pension_ytd_accumulator(db, employee.id, run.pay_date, calc, payslip_id=item.id)
    if calc.ytd_gy_paye_credit_after is not None:
        db.flush()  # need item.id for last_updated_payslip_id
        _upsert_gy_paye_credit_ytd_accumulator(db, employee.id, run.pay_date, calc, payslip_id=item.id)
    if calc.ytd_pr_ss_wages_after is not None:
        db.flush()  # need item.id for last_updated_payslip_id
        _upsert_pr_ytd_accumulator(db, employee.id, run.pay_date, calc, payslip_id=item.id)
    if calc.ytd_cpf_ow_subject_after is not None:
        db.flush()  # need item.id for last_updated_payslip_id
        _upsert_sg_cpf_ytd_accumulator(db, employee.id, _sg_wage_date(run), calc, payslip_id=item.id)
    if calc.au_statutory_deductions_detail:
        _apply_au_statutory_deduction_collections(db, calc.au_statutory_deductions_detail)
    if calc.option2_cumulative_gross_after is not None:
        db.flush()  # need item.id for last_updated_payslip_id
        _upsert_ca_option2_ytd_accumulator(db, employee.id, run.pay_date, work_state, calc, payslip_id=item.id)
    org_levy_increments = {
        **({"on_eht": calc.on_eht_ytd_remuneration_after - ctx.on_eht_ytd_remuneration_before}
           if calc.on_eht_ytd_remuneration_after is not None else {}),
        **({"bc_eht": calc.bc_eht_ytd_remuneration_after - ctx.bc_eht_ytd_remuneration_before}
           if calc.bc_eht_ytd_remuneration_after is not None else {}),
        **({"mb_he_levy": calc.mb_he_levy_ytd_remuneration_after - ctx.mb_he_levy_ytd_remuneration_before}
           if calc.mb_he_levy_ytd_remuneration_after is not None else {}),
        **({"nl_hapset": calc.nl_hapset_ytd_remuneration_after - ctx.nl_hapset_ytd_remuneration_before}
           if calc.nl_hapset_ytd_remuneration_after is not None else {}),
        **({"qc_hsf": calc.qc_hsf_ytd_remuneration_after - ctx.qc_hsf_ytd_remuneration_before}
           if calc.qc_hsf_ytd_remuneration_after is not None else {}),
        # Australia state/territory payroll tax — same "component name
        # resolved from work_state" shape as _compute_payslip_values's
        # own _org_levy_result construction above.
        **(
            {
                _AU_PAYROLL_TAX_COMPONENT_BY_WORK_STATE[(work_state or "").strip().upper()]:
                    calc.au_state_payroll_tax_ytd_remuneration_after - ctx.au_state_payroll_tax_ytd_remuneration_before
            }
            if calc.au_state_payroll_tax_ytd_remuneration_after is not None else {}
        ),
    }
    if org_levy_increments:
        db.flush()  # need item.id for last_updated_payslip_id
        _upsert_ca_org_levy_ytd(
            db, organization_id, run.pay_date, org_levy_increments, payslip_id=item.id,
            tax_year=_au_ytd_tax_year(run.pay_date) if country == "AU" else None,
        )
    if calc.appr_levy_ytd_pay_bill_after is not None or calc.employer_ni_ytd_after is not None:
        db.flush()  # need item.id for last_updated_payslip_id
        uk_levy_increment = (
            calc.appr_levy_ytd_pay_bill_after - ctx.appr_levy_ytd_pay_bill_before
            if calc.appr_levy_ytd_pay_bill_after is not None else None
        )
        uk_employer_ni_increment = (
            calc.employer_ni_ytd_after - ctx.employer_ni_ytd_before
            if calc.employer_ni_ytd_after is not None else None
        )
        _upsert_uk_org_levy_ytd(db, organization_id, run.pay_date, uk_levy_increment, uk_employer_ni_increment, payslip_id=item.id)
    if calc.jm_heart_ytd_remuneration_after is not None:
        db.flush()  # need item.id for last_updated_payslip_id
        jm_heart_increment = calc.jm_heart_ytd_remuneration_after - ctx.jm_heart_ytd_remuneration_before
        _upsert_jm_heart_ytd(db, organization_id, run.pay_date, jm_heart_increment, payslip_id=item.id)
    _ytd_record_postings(db, item, ytd_pre_state)
    db.commit()
    db.refresh(item)
    _recompute_run_aggregates(db, run)
    return item


def get_payslips_for_run(db: Session, run_id: int, organization_id: int = None) -> List[PayslipItem]:
    get_payroll_run_by_id(db, run_id, organization_id)  # 404s if missing/not in org
    query = db.query(PayslipItem).filter(PayslipItem.payroll_run_id == run_id)
    return _apply_org_filter(query, PayslipItem, organization_id).all()


def get_run_leave_summary(db: Session, run_id: int, organization_id: int = None) -> dict:
    """Read-only Leave Summary for the Run Details view, per employee, for the
    run's pay period. Does NOT touch PayslipItem/payroll calculations — this
    is a supplementary query against attendance records only, because
    PayslipItem itself only tracks unpaid_leave_days (the one figure that
    actually affects pay), not a paid/sick/casual breakdown."""
    run = get_payroll_run_by_id(db, run_id, organization_id)
    items = get_payslips_for_run(db, run_id, organization_id)
    employee_ids = [item.employee_id for item in items]
    if not employee_ids:
        return {}

    query = db.query(PayrollAttendanceRecord).filter(
        PayrollAttendanceRecord.organization_id == organization_id,
        PayrollAttendanceRecord.employee_id.in_(employee_ids),
        PayrollAttendanceRecord.date >= run.period_start,
        PayrollAttendanceRecord.date <= run.period_end,
    )
    summary = {
        emp_id: {"present": 0, "absent": 0, "paidLeave": 0, "unpaidLeave": 0, "sickLeave": 0, "casualLeave": 0}
        for emp_id in employee_ids
    }
    for record in query.all():
        bucket = summary[record.employee_id]
        if record.status == "present":
            bucket["present"] += 1
        elif record.status == "absent":
            bucket["absent"] += 1
        elif record.status == "leave":
            leave_key = {
                "paid": "paidLeave", "unpaid": "unpaidLeave",
                "sick": "sickLeave", "casual": "casualLeave",
            }.get(record.leave_type, "unpaidLeave")
            bucket[leave_key] += 1
    return summary


# ── Bank Transfer File (post-approval) ──────────────────────────────────
# See app/modules/payroll/bank_export/ for the exporter implementations.
# This section only assembles rows from already-computed PayslipItem/
# PayrollRun data and hands them to an exporter — it never recomputes pay.

def get_bank_transfer_summary(db: Session, run_id: int, organization_id: int = None) -> dict:
    """Read-only preview shown in the Approval Dialog before a file is generated."""
    from app.modules.payroll.policy.service import get_active_policy

    run = get_payroll_run_by_id(db, run_id, organization_id)
    items = get_payslips_for_run(db, run_id, organization_id)
    policy = get_active_policy(db, organization_id)
    company = db.query(CompanyComplianceDetails).filter(
        CompanyComplianceDetails.organization_id == organization_id
    ).first()

    return {
        "runId": run.id,
        "period": run.period_label,
        "totalEmployees": len(items),
        "grossPayroll": float(run.total_gross or 0),
        # run.total_deductions already includes tds (run.total_taxes is the
        # same tds amount, kept separately only for the "Total Taxes" stat) —
        # adding both here double-counted tds and made Gross − Deductions
        # come out short of the (correct) Net Payroll shown below.
        "totalDeductions": float(run.total_deductions or 0),
        "netPayroll": float(run.total_net or 0),
        "paymentDate": run.pay_date,
        "bankFormat": policy.bank_export_format,
        "companyName": getattr(company, "name", None) or "",
    }


def _build_bank_export_rows(db: Session, run: PayrollRun, items: List[PayslipItem], organization_id: int, org_currency: str = None) -> list:
    from app.modules.payroll.bank_export import BankExportRow
    from app.modules.payroll import bank_routing

    company = db.query(CompanyComplianceDetails).filter(
        CompanyComplianceDetails.organization_id == organization_id
    ).first() if organization_id else None

    # Use the org's explicit currency override if set, otherwise derive
    # from the jurisdiction — implements the Super Admin → Org Admin
    # inheritance model for currency. A bank transfer file is a real
    # payment instruction, so an org with no jurisdiction configured
    # anywhere raises here rather than silently paying out under an
    # assumed (India) currency.
    country = _resolve_org_country(db, organization_id, required=True)
    currency_code = org_currency or _get_currency_code(country)
    company_name = getattr(company, "name", None) or ""

    # Singapore IR21: monies under an open tax-clearance case are withheld
    # (IRAS) — those payslips are left out of the payment file; a RELEASED
    # case pays its approved released amount once, on its final payslip.
    # Every other payslip (and every other country) is untouched.
    ir21 = _sg_ir21_payment_treatment(db, organization_id, run, items) if organization_id else {}
    if any((i.country_code or "").upper() == "SG" for i in items):
        if _sg_bank_hold_active(db, run.id):          # SG-047: disaster-recovery hold until bank reconciliation
            raise HTTPException(status_code=409, detail=(
                "This run's bank export is on hold after a database restore (SG-047) — record the bank reconciliation "
                "before any file is produced; a restored database is never permission to pay again."))
        _sg_verify_run_approval(db, run)              # SG-032: bank data / payslips unchanged since approval

    # Hong Kong IR56G: payslips under an active tax-clearance hold (or final
    # pay whose IR56G filing is unresolved) are left out of the payment file;
    # their net pay stays owed and is traced on the hold's ledger lines.
    hk_holds = {}
    if organization_id and any((i.country_code or "").upper() == "HK" for i in items):
        hk_holds = jurisdiction_hooks.call("HK", "payment_treatment", db, organization_id, run, items)
        db.commit()
    rows = []
    for item in items:
        if item.id in hk_holds:
            continue
        treatment, released = ir21.get(item.id, (None, None))
        if treatment in ("HELD", "COVERED") or (treatment == "RELEASE" and not released):
            continue
        amount = float(released) if treatment == "RELEASE" else float(item.net_pay or 0)
        # Multi-jurisdiction routing (ZP-MJR-2026-001): each row's own
        # snapshotted country wins; rows generated before PayslipItem
        # snapshotted a country fall back to the resolved org jurisdiction
        # (same country used for the currency above). India keeps its
        # `ifsc` slot populated so existing consumers of BankExportRow.ifsc
        # are untouched.
        row_country = (item.country_code or country) if hasattr(item, "country_code") else country
        rows.append(BankExportRow(
            employee_name=item.employee_name,
            employee_id=str(item.employee_id),
            bank_name=item.bank_name or "",
            account_number=item.bank_account or "",
            ifsc=item.ifsc or "",
            branch=None,   # not captured anywhere upstream — left blank rather than fabricated
            amount=amount,
            reference_number=item.payslip_number or f"RUN{run.id}-{item.employee_id}",
            narration=f"IR21 release {run.period_label}" if treatment == "RELEASE" else f"Salary {run.period_label}",
            payment_date=run.pay_date.isoformat(),
            currency=currency_code,
            company_name=company_name,
            routing_label=bank_routing.btf_routing_label(row_country),
            routing_value=bank_routing.btf_routing_value(item, row_country),
        ))
    return rows


def generate_bank_transfer_file(db: Session, run_id: int, organization_id: int = None, actor_id: int = None,
                                 format_override: Optional[str] = None):
    """Returns (file_bytes, content_type, file_extension, filename) for the
    run's bank transfer file. Defaults to the format configured on the org's
    active Banking Policy (PayrollPolicy.bank_export_format); pass
    format_override to download the same run's data in a different format
    (csv/xlsx/txt/pdf) without changing that policy setting."""
    from app.modules.payroll.bank_export import get_exporter
    from app.modules.payroll.policy.service import get_active_policy

    run = get_payroll_run_by_id(db, run_id, organization_id)
    items = get_payslips_for_run(db, run_id, organization_id)
    policy = get_active_policy(db, organization_id)

    # Resolve the org's explicit currency override for bank exports.
    from app.modules.organizations.models import Organization
    org_row = db.query(Organization).filter(Organization.id == organization_id).first()
    org_currency = org_row.currency if org_row else None

    export_format = format_override or policy.bank_export_format
    rows = _build_bank_export_rows(db, run, items, organization_id, org_currency=org_currency)
    try:
        exporter = get_exporter(export_format)
    except ValueError as exc:
        raise BadRequestException(str(exc))
    # Prompt 3: EVALUATION workspaces are marked 'PREVIEW — EVALUATION ONLY'
    # on document exports (PDF). CSV/TXT/XLSX carry no visible document, but
    # the flag is still threaded through so a future live-transfer exporter
    # can't miss it (per the bank_export/factory.py guard comment).
    evaluation = bool(org_row) and org_row.workspace_type == "EVALUATION"
    file_bytes = exporter.generate(rows, evaluation=evaluation)

    log_activity(
        db, organization_id,
        f"Bank transfer file ({export_format.upper()}) generated for run '{run.period_label}'.",
        ActivityStatus.SUCCESS, actor_id=actor_id,
    )
    filename = f"bank-transfer_{run.run_code or run.id}.{exporter.file_extension}"
    return file_bytes, exporter.content_type, exporter.file_extension, filename


def _resolve_org_country(db: Session, organization_id: int = None, *, required: bool = False) -> Optional[str]:
    """The org's current jurisdiction country — payslips/runs don't snapshot
    a country of their own, so this always reflects the org's *current*
    Compliance setting, same as the PDF generators already do.

    Prefers CompanyComplianceDetails.jurisdiction_country (set on the
    Compliance page); when that's blank — the default state of every
    organization until someone explicitly saves that page — falls back to
    Organization.country (set at registration, before Compliance Details is
    ever touched) rather than silently assuming India. When NEITHER is set:
    `required=True` raises a clear error (used where guessing wrong has a
    real financial/data-integrity consequence — employee jurisdiction
    assignment, bank export currency); `required=False` (default) returns
    None and leaves the caller's own already-graceful "unknown jurisdiction"
    handling to take over (an empty report list, a neutral $/USD display,
    the generic statutory-column set) instead of a guessed country."""
    company = db.query(CompanyComplianceDetails).filter(
        CompanyComplianceDetails.organization_id == organization_id
    ).first() if organization_id else None
    raw = getattr(company, "jurisdiction_country", None)
    if not raw and organization_id:
        from app.modules.organizations.models import Organization
        org_row = db.query(Organization).filter(Organization.id == organization_id).first()
        raw = getattr(org_row, "country", None)
    if not raw:
        if required:
            raise BadRequestException(
                "This organization hasn't configured a jurisdiction yet — "
                "set it under Compliance > Company Details before continuing."
            )
        return None
    return _normalize_country(raw)




def _serialize_payslip(item: PayslipItem, run: PayrollRun, country: str = None) -> dict:
    # additional_compensation (and, defensively, the other money columns) can
    # be NULL on rows created before that column existed — the model's
    # `default=0` only applies to new INSERTs, not to pre-existing rows. An
    # unguarded None here fails PayslipItemResponse's Decimal validation and
    # was taking down the *entire* payslip list/detail response with a 500,
    # not just the affected row. Coalesce to 0 so old rows still serialize.
    z = Decimal("0")
    return {
        "id": item.id,
        "runId": item.payroll_run_id,
        "payslipNumber": item.payslip_number,
        "employee": item.employee_name,
        "employeeId": item.employee_id,
        "department": item.department,
        "designation": item.designation,
        "dateOfJoining": item.date_of_joining,
        "country": country,
        "workState": item.work_state,
        "workLocality": item.work_locality,
        "period": run.period_label,
        "payDate": run.pay_date,
        "salary": item.gross_pay or z,
        "basicPay": item.basic_salary or z,
        "hra": item.hra or z,
        "specialAllowance": item.special_allowance or z,
        "allowanceItems": [
            {"key": a.key, "label": a.label, "amount": a.amount or z} for a in (item.allowance_items or [])
        ],
        "overtime": item.overtime or z,
        "additionalCompensation": item.additional_compensation or z,
        "payableDays": item.payable_days,        # None on old rows generated before this
        "totalWorkingDays": item.total_working_days,  # column existed — genuinely unknown, not 0
        "unpaidLeaveDays": item.unpaid_leave_days,
        "attendanceDeduction": item.attendance_deduction or z,
        "tds": item.tds or z,
        "surcharge": item.surcharge or z,
        "cess": item.cess or z,
        # Germany (Kirchensteuer): computed by the Germany engine and
        # persisted on PayslipItem.church_tax, but this serializer never
        # emitted it — so every payslip API response silently dropped the
        # value (the same computed-but-never-serialized defect class as
        # cpp2/studyLoanDeduction above). Surfaced now as its own line.
        "churchTax": item.church_tax or z,
        # Germany (Solidaritätszuschlag): same computed-but-unserialized
        # defect class as churchTax above — persisted on PayslipItem.soli
        # but never emitted, so every payslip API response dropped it and
        # the summary report could only report UNAVAILABLE. Surfaced now
        # as its own informational line; `tds` remains the COMBINED
        # statutory total for backward compatibility (Soli is folded in).
        "soli": item.soli or z,
        # US: federal/state/local income tax broken out separately — `tds`
        # above remains the correct COMBINED total for backward
        # compatibility (existing reports/consumers that sum `tds` still
        # get the right total). Zero for every non-US payslip and for any
        # US payslip generated before this split existed (see
        # jurisdictionLabels.js's getIncomeTaxLines for how the frontend
        # falls back to the combined `tds` line in that case).
        "federalIncomeTax": item.federal_income_tax or z,
        "stateIncomeTax": item.state_income_tax or z,
        "localTax": item.local_tax or z,
        "stateDisabilityInsurance": item.state_disability_insurance or z,
        "stateProgramDeductions": item.state_program_deductions or z,
        "pf": item.pf or z,
        "esi": item.esi or z,
        "professionalTax": item.professional_tax or z,
        "employeeLwf": item.employee_lwf or z,
        "employerLwf": item.employer_lwf or z,
        "socialSecurity": item.social_security or z,
        "medicare": item.medicare or z,
        "niEmployee": item.ni_employee or z,
        "employeePension": item.employee_pension or z,
        # Canada: CPP2 — computed and persisted (see PayslipItem.cpp2) and
        # already correctly folded into total_deductions/net_pay, but this
        # dict never actually serialized it, so no payslip API response
        # ever surfaced the number despite it genuinely reducing net pay.
        "cpp2": item.cpp2 or z,
        # UK: Student/Postgraduate Loan deduction — correctly reduces net_pay
        # (engine/standard.py's total_employee_deductions) since it was
        # calculated, but was never added to this dict, so it never reached
        # any payslip API response despite being a real, persisted column.
        "studyLoanDeduction": item.study_loan_deduction or z,
        "postgradLoanDeduction": item.postgrad_loan_deduction or z,
        "employerPf": item.employer_pf or z,
        "employerEps": item.employer_eps or z,
        "employerPfResidual": item.employer_pf_residual or z,
        "employerEdli": item.employer_edli or z,
        "employerNps": item.employer_nps or z,
        "employerEsi": item.employer_esi or z,
        "employerSs": item.employer_social_security or z,
        "employerMedicare": item.employer_medicare or z,
        "employerPension": item.employer_pension or z,
        # UK: employer-side National Insurance — same "computed, persisted,
        # never serialized" gap as studyLoanDeduction above.
        "employerNi": item.employer_ni or z,
        # UK: Apprenticeship Levy — same "computed, persisted, never
        # serialized" gap, found 2026-09-09 gap-closure Phase 3 while
        # enabling the org-level accumulator this depends on.
        "employerApprenticeshipLevy": item.employer_apprenticeship_levy or z,
        # US: employer-side FUTA/SUI/state-program contributions — computed
        # and persisted (see _compute_payslip_values) but never reached any
        # payslip API response before this fix (found 2026-09-15 Org Admin
        # visibility audit, same gap pattern as the UK fields above).
        "employerFuta": item.employer_futa or z,
        "employerSui": item.employer_sui or z,
        "employerStateProgramContributions": item.employer_state_program_contributions or z,
        # Australia: computed+persisted since the AU 2026-27 build but
        # never reached any payslip API response before this fix (found
        # 2026-09-17 production-readiness pass) — same "computed,
        # persisted, never serialized" gap as employerFuta/employerSui
        # above, just never caught for AU. employerPayrollTax/
        # auWorkersCompensationPremium are employer-liability-only
        # (AU-D05, never affect netPay); auStatutoryDeductionsTotal is a
        # real employee deduction already folded into totalDeductions/
        # netPay below.
        "employerPayrollTax": item.employer_payroll_tax or z,
        "auStatutoryDeductionsTotal": item.au_statutory_deductions_total or z,
        "auWorkersCompensationPremium": item.au_workers_compensation_premium or z,
        "auCalculationTrace": item.au_calculation_trace,
        "sgpCalculationTrace": item.sgp_calculation_trace,
        "hkgCalculationTrace": item.hk_calculation_trace,
        "hkTaxClearanceHold": (jurisdiction_hooks.call("HK", "payslip_hold_view", item)
                               if (item.country_code or "").upper() == "HK" else None),
        # UK: Automatic Enrolment assessment (gap-closure Part 3) —
        # informational classification, not a monetary field.
        "autoEnrolmentStatus": item.auto_enrolment_status,
        # UK: HMRC tax week/month (gap-closure Part 6) — pure calendar metadata.
        "taxWeek": item.tax_week,
        "taxMonth": item.tax_month,
        "employerCpp2": item.employer_cpp2 or z,
        "totalDeductions": item.total_deductions or z,
        "netPay": item.net_pay or z,
        "bankName": item.bank_name,
        "bankAccount": item.bank_account,
        "pan": item.pan,
        "uan": item.uan,
        "ifsc": item.ifsc,
        # Multi-jurisdiction routing (ZP-MJR-2026-001): additive — ifsc/pan/
        # uan/complianceFields above are unchanged, `routing` adds the
        # jurisdiction-correct list of [{key,label,value}] read from the
        # payslip snapshot (India -> IFSC in the `ifsc` column; every other
        # country -> its compliance_fields routing codes).
        "routing": bank_routing.resolve_routing(item, country=country),
        "complianceFields": item.compliance_fields or {},
        "status": item.status,
        "notes": item.notes,
        # Phase 8BS: Germany's germany_calculation_snapshot (RV/ALV/GKV/PV
        # trace, blocked-reason, wage-tax provenance) was persisted since
        # Phase 7 but never reached ANY payslip API response — meaning no
        # frontend surface could ever show a block reason, or distinguish
        # an INTERNAL_FUNCTIONAL_REFERENCE wage-tax result from a future
        # official BMF-certified one. Never exposes the raw snapshot here
        # (some of it — resolved registry ids/rates — is more detail than
        # a general payslip API response should carry); only the specific,
        # already-designed-to-be-public fields a UI actually needs.
        "calculationMode": (item.germany_calculation_snapshot or {}).get("papVersion") if country == "DE" else None,
        "blockedReasonCode": (item.germany_calculation_snapshot or {}).get("blockedReasonCode") if country == "DE" else None,
        "blockedReasonMessage": (item.germany_calculation_snapshot or {}).get("blockedReasonMessage") if country == "DE" else None,
        # Phase 8BU: PARTIAL-status support — the explicit list of
        # components this calculation could NOT produce (e.g. ["wage_tax",
        # "soli", "church_tax"]), so the frontend/PDF can label exactly
        # which figures are unavailable instead of inferring it from a 0
        # value (a genuinely-zero church tax and a forced-zero placeholder
        # are otherwise indistinguishable by value alone).
        "germanyUnavailableComponents": (item.germany_calculation_snapshot or {}).get("unavailableComponents") if country == "DE" else None,
        "calculationStatus": (item.germany_calculation_snapshot or {}).get("calculationStatus") if country == "DE" else None,
    }


def list_payslips(db: Session, organization_id: int = None, search: str = None,
                   period: str = None, employee_id: int = None) -> List[dict]:
    query = (
        db.query(PayslipItem, PayrollRun)
        .join(PayrollRun, PayslipItem.payroll_run_id == PayrollRun.id)
        .options(selectinload(PayslipItem.allowance_items))
    )
    query = _apply_org_filter(query, PayslipItem, organization_id)
    if period:
        query = query.filter(PayrollRun.period_label == period)
    if employee_id:
        query = query.filter(PayslipItem.employee_id == employee_id)
    if search:
        query = query.filter(PayslipItem.employee_name.ilike(f"%{search}%"))

    rows = query.order_by(PayrollRun.pay_date.desc()).all()
    # Each payslip's own snapshotted country_code (its employee's jurisdiction
    # at generation time) takes priority — falls back to the org's current
    # default only for rows generated before that column existed.
    org_country = _resolve_org_country(db, organization_id)
    return [_serialize_payslip(item, run, country=item.country_code or org_country) for item, run in rows]


def get_payslip_by_id(db: Session, payslip_id: int, organization_id: int = None) -> dict:
    query = (
        db.query(PayslipItem, PayrollRun)
        .join(PayrollRun, PayslipItem.payroll_run_id == PayrollRun.id)
        .options(selectinload(PayslipItem.allowance_items))
    )
    query = query.filter(PayslipItem.id == payslip_id)
    query = _apply_org_filter(query, PayslipItem, organization_id)
    row = query.first()
    if not row:
        raise NotFoundException(f"Payslip {payslip_id} not found.")
    item, run = row
    country = item.country_code or _resolve_org_country(db, organization_id)
    return _serialize_payslip(item, run, country=country), item, run


def _get_currency_symbol(country: str) -> str:
    """Return the currency symbol for a jurisdiction country code or ISO 4217 code."""
    # First check if it's already an ISO currency code
    _iso_to_sym = {
        "INR": "\u20b9", "USD": "$", "GBP": "\u00a3",
        "AUD": "A$", "EUR": "\u20ac", "CAD": "C$",
        "AED": "AED", "BDT": "\u09f3", "BHD": "BHD", "BRL": "R$",
        "CHF": "CHF", "CNY": "\u00a5", "DKK": "kr", "GHS": "\u20b5",
        "HKD": "HK$", "JPY": "\u00a5", "KES": "KSh", "KRW": "\u20a9",
        "KWD": "KWD", "LKR": "\u20a8", "MXN": "MX$", "MYR": "RM",
        "NGN": "\u20a6", "NOK": "kr", "NPR": "\u20a8", "NZD": "NZ$",
        "OMR": "OMR", "PKR": "\u20a8", "QAR": "QAR", "RWF": "RF",
        "SAR": "SAR", "SEK": "kr", "SGD": "S$", "THB": "\u0e3f",
        "TZS": "TSh", "UGX": "USh", "ZAR": "R",
        # Caribbean production jurisdictions (2026-09-21) + Puerto Rico
        # (2026-09-23) \u2014 symbols mirror frontend/src/utils/currency.js's
        # CURRENCY_MASTER exactly so the BTF/payslip PDF never disagrees
        # with the frontend's own currency display.
        "BBD": "Bds$", "KYD": "CI$", "DOP": "RD$", "GYD": "G$",
        "JMD": "J$", "BSD": "B$", "TTD": "TT$",
    }
    if country and country.upper() in _iso_to_sym:
        return _iso_to_sym[country.upper()]
    return {
        "IN": "\u20b9", "US": "$", "UK": "\u00a3",
        "AU": "A$", "DE": "\u20ac", "CA": "C$",
        "BB": "Bds$", "KY": "CI$", "DO": "RD$", "GY": "G$",
        "JM": "J$", "BS": "B$", "TT": "TT$", "PR": "$",
        # Ireland (ZP-IE-ENG-001) uses the euro. Without this row IE silently
        # fell through to the "$" default below, which is a silently wrong
        # currency rather than a visible failure.
        "IE": "\u20ac", "FR": "\u20ac",
    }.get(country, "$")


def _get_currency_code(country: str) -> str:
    """Return the ISO currency code for a jurisdiction country code.
    Also passes through ISO 4217 codes unchanged."""
    _iso_codes = {
        "INR", "USD", "GBP", "AUD", "EUR", "CAD", "AED", "BDT", "BHD",
        "BRL", "CHF", "CNY", "DKK", "GHS", "HKD", "JPY", "KES", "KRW",
        "KWD", "LKR", "MXN", "MYR", "NGN", "NOK", "NPR", "NZD", "OMR",
        "PKR", "QAR", "RWF", "SAR", "SEK", "SGD", "THB", "TZS", "UGX", "ZAR",
        # Caribbean production jurisdictions (2026-09-21) + Puerto Rico
        # (2026-09-23) — mirrors frontend/src/utils/currency.js exactly.
        "BBD", "KYD", "DOP", "GYD", "JMD", "BSD", "TTD",
    }
    if country and country.upper() in _iso_codes:
        return country.upper()
    return {
        "IN": "INR", "US": "USD", "UK": "GBP",
        "AU": "AUD", "DE": "EUR", "CA": "CAD",
        "BB": "BBD", "KY": "KYD", "DO": "DOP", "GY": "GYD",
        "JM": "JMD", "BS": "BSD", "TT": "TTD", "PR": "USD",
        # Ireland (ZP-IE-ENG-001) uses the euro; without this row IE silently
        # fell through to the "USD" default below.
        "IE": "EUR", "FR": "EUR",
    }.get(country, "USD")


def get_currency_for_jurisdiction(jurisdiction_code: str) -> str:
    """Public wrapper — returns the ISO 4217 currency code for a jurisdiction."""
    return _get_currency_code(jurisdiction_code)


def _amount_to_words(amount):
    """Convert a numeric amount to Indian English words for payslip display."""
    amount = int(round(float(amount or 0)))
    if amount == 0:
        return "Zero"
    ones = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven",
            "Eight", "Nine", "Ten", "Eleven", "Twelve", "Thirteen",
            "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"]
    tens = ["", "", "Twenty", "Thirty", "Forty", "Fifty",
            "Sixty", "Seventy", "Eighty", "Ninety"]

    def _two_digits(n):
        if n < 20:
            return ones[n]
        return (tens[n // 10] + (" " + ones[n % 10] if n % 10 else "")).strip()

    def _three_digits(n):
        if n == 0:
            return ""
        if n < 100:
            return _two_digits(n)
        return (ones[n // 100] + " Hundred"
                + (" " + _two_digits(n % 100) if n % 100 else ""))

    neg = amount < 0
    amount = abs(amount)

    crore, amount = divmod(amount, 10_000_000)
    lakh, amount = divmod(amount, 100_000)
    thousand, hundred = divmod(amount, 1000)

    parts = []
    if crore > 0:
        parts.append(_two_digits(crore) + (" Crore" if crore == 1 else " Crores"))
    if lakh > 0:
        parts.append(_two_digits(lakh) + (" Lakh" if lakh == 1 else " Lakhs"))
    if thousand > 0:
        parts.append(_two_digits(thousand) + " Thousand")
    if hundred > 0:
        parts.append(_three_digits(hundred))
    result = " ".join(parts).strip()
    if neg:
        result = "Minus " + result
    return result


def _register_rupee_font(c):
    """Attempt to register a Unicode-capable TTF font (regular + bold) so the
    rupee symbol renders correctly.  Falls back silently to Helvetica if no
    suitable font is found."""
    import os
    from reportlab.pdfbase import pdfmetrics
    from reportlab.pdfbase.ttfonts import TTFont

    candidates = [
        ("/usr/share/fonts/truetype/dejavu/DejaVuSans.ttf",
         "/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf"),
        ("/usr/share/fonts/truetype/liberation/LiberationSans-Regular.ttf",
         "/usr/share/fonts/truetype/liberation/LiberationSans-Bold.ttf"),
        ("/usr/share/fonts/truetype/noto/NotoSans-Regular.ttf",
         "/usr/share/fonts/truetype/noto/NotoSans-Bold.ttf"),
        ("/usr/share/fonts/TTF/DejaVuSans.ttf",
         "/usr/share/fonts/TTF/DejaVuSans-Bold.ttf"),
        (os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts", "arial.ttf"),
         os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts", "arialbd.ttf")),
        (os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts", "tahoma.ttf"),
         os.path.join(os.environ.get("WINDIR", r"C:\Windows"), "Fonts", "tahomabd.ttf")),
        ("/System/Library/Fonts/Supplemental/Arial.ttf",
         "/System/Library/Fonts/Supplemental/Arial Bold.ttf"),
        ("/Library/Fonts/Arial.ttf", "/Library/Fonts/Arial Bold.ttf"),
    ]
    for regular_path, bold_path in candidates:
        if not os.path.isfile(regular_path):
            continue
        try:
            pdfmetrics.registerFont(TTFont("RupeeFont", regular_path))
        except Exception:
            continue
        try:
            bold_source = bold_path if os.path.isfile(bold_path) else regular_path
            pdfmetrics.registerFont(TTFont("RupeeFont-Bold", bold_source))
        except Exception:
            pdfmetrics.registerFont(TTFont("RupeeFont-Bold", regular_path))
        return "RupeeFont"
    return None


def _ssn_last_four(value) -> Optional[str]:
    """US SSN as printed on a wage statement: XXX-XX-1234."""
    digits = "".join(ch for ch in str(value or "") if ch.isdigit())
    return f"XXX-XX-{digits[-4:]}" if len(digits) >= 4 else None


def _payslip_identity_rows(country: str, data: dict) -> list:
    """Country-appropriate identity/bank-routing fields for the payslip's
    three PAN/UAN/IFSC row slots. India uses its own dedicated pan/uan/ifsc
    columns; every other jurisdiction reads its own identifiers out of the
    compliance_fields snapshot (see employee_validation.py for the full
    per-country field list) — those fields previously never appeared on a
    non-India payslip at all, which always showed blank PAN/UAN/IFSC rows
    regardless of the employee's actual jurisdiction."""
    if country == "IN":
        return [("PAN / Tax ID", data.get("pan")), ("UAN", data.get("uan")), ("IFSC", data.get("ifsc"))]
    cf = data.get("complianceFields") or {}
    rows_by_country = {
        # SSN: last four digits only — California Labor Code §226(a)(7) requires
        # a wage statement to show "only the last four digits of their social
        # security number" (verified against leginfo.legislature.ca.gov,
        # Phase 4A). Other identifiers below are unchanged until their own
        # payslip-content rules are verified from an authoritative source.
        "US": [("SSN", _ssn_last_four(cf.get("ssn"))), ("Filing Status", cf.get("w4_filing_status")), ("ABA Routing No.", cf.get("aba_routing_number"))],
        "UK": [("NINO", cf.get("nino")), ("Tax Code", cf.get("paye_tax_code")), ("Sort Code", cf.get("sort_code"))],
        "AU": [("TFN", cf.get("tfn")), ("Super Fund USI", cf.get("super_fund_usi")), ("BSB Code", cf.get("bsb_code"))],
        "CA": [("SIN", cf.get("sin")), ("Province", cf.get("province")), ("Transit No.", cf.get("transit_number"))],
        "DE": [("Steuer-ID", cf.get("steuer_id")), ("Steuerklasse", cf.get("steuerklasse")), ("IBAN", cf.get("iban"))],
        # Caribbean production jurisdictions (ZP-MJR-2026-002, 2026-09-24) —
        # mirrors frontend/src/utils/jurisdictionLabels.js's IDENTITY_FIELD.
        # This data was already captured end-to-end (compliance_fields);
        # only this display mapping was missing, so these payslips
        # previously fell through to the generic fallback below.
        # Countries with only one captured statutory identifier fill the
        # middle slot with the jurisdiction's real payment-rail name
        # (bank_routing.payment_mode_label) rather than a fabricated/blank
        # field — every other row on this table is a real value.
        "BB": [("TAMIS TIN", cf.get("tamis_tin")), ("NIS Number", cf.get("nis_number")), ("Bank/Branch Code", cf.get("bank_branch_code"))],
        "KY": [("NIB Member No.", cf.get("nib_member_number")), ("Payment Mode", bank_routing.payment_mode_label(country)), ("Bank/Branch Code", cf.get("bank_branch_code"))],
        "DO": [("Cédula", cf.get("cedula")), ("Payment Mode", bank_routing.payment_mode_label(country)), ("Bank/Branch Code", cf.get("bank_branch_code"))],
        "GY": [("GRA TIN", cf.get("gra_tin")), ("NIS Number", cf.get("nis_number")), ("Bank/Branch Code", cf.get("bank_branch_code"))],
        "JM": [("TRN", cf.get("trn")), ("Payment Mode", bank_routing.payment_mode_label(country)), ("Bank/Branch Code", cf.get("bank_branch_code"))],
        "BS": [("NIB Number", cf.get("nib_number")), ("Payment Mode", bank_routing.payment_mode_label(country)), ("ACH Routing No.", cf.get("ach_routing_number"))],
        "TT": [("BIR File No.", cf.get("bir_file_number")), ("NIBTT No.", cf.get("nibtt_number")), ("Bank/Branch Code", cf.get("bank_branch_code"))],
        "PR": [("SSN", cf.get("ssn")), ("Payment Mode", bank_routing.payment_mode_label(country)), ("ACH Routing No.", cf.get("ach_routing_number"))],
        # Singapore: partial NRIC/FIN only (PDPC NRIC guidelines §5.2 — last 3
        # digits + checksum); MOM's itemised-payslip items need no NRIC at all.
        "SG": [("NRIC / FIN", mask_nric_fin(cf.get("nric_fin"))), ("CPF Status", cf.get("cpf_residency_status")),
               ("Work Pass", cf.get("work_pass_type"))],
        # Hong Kong: masked HKID only (HK-022 / PCPD HR Code — identity
        # masked in ordinary output).
        # Three slots like every country (the layout unpacks three rows): the
        # third is the HKICL bank-branch code in the bank-file format.
        "HK": [("HKID", mask_identifier(cf.get("hkid") or cf.get("passport_number"))),
               ("MPF Account", mask_identifier(cf.get("mpf_member_account"))),
               ("Bank-Branch Code", "-".join(v for v in (cf.get("bank_code"), cf.get("branch_code")) if v) or None)],
    }
    return rows_by_country.get(country, [("Tax ID", None), ("Reference", None), ("Routing", None)])


def _is_evaluation_workspace(db: Session, organization_id: int = None) -> bool:
    """True when the given org's live workspace_type is EVALUATION — payslip/
    report PDF renderers then overlay a 'PREVIEW — EVALUATION ONLY' watermark
    (Prompt 3). Reads Organization live (same row the ELSTER guard reads), so
    converting the workspace to PRODUCTION later automatically removes the
    watermark — no expiry/flag dance."""
    if not organization_id:
        return False
    from app.modules.organizations.models import Organization
    org = db.query(Organization).filter(Organization.id == organization_id).first()
    return bool(org) and org.workspace_type == "EVALUATION"


def _draw_evaluation_watermark(c, width: float, height: float, font_name: str = "Helvetica-Bold") -> None:
    """Overlays a centred, rotated 'PREVIEW — EVALUATION ONLY' watermark on
    the current reportlab page. Call once AFTER all page content has been
    drawn and BEFORE c.showPage()/c.save(), and (for multi-page documents)
    immediately after every interior c.showPage() so each page gets stamped.
    Self-contained — imports what it needs internally so callers don't have
    to."""
    from reportlab.lib import colors
    from reportlab.pdfbase.pdfmetrics import stringWidth

    text = "PREVIEW — EVALUATION ONLY"
    size = 38
    c.saveState()
    c.setFillColor(colors.HexColor("#1E3A8A"))
    c.setStrokeColor(colors.HexColor("#1E3A8A"))
    c.setFont(font_name, size)
    try:
        c.setFillAlpha(0.25)
        c.setStrokeAlpha(0.25)
    except Exception:
        pass
    c.translate(width / 2, height / 2)
    c.rotate(45)
    tw = stringWidth(text, font_name, size)
    c.drawCentredString(0, 0, text)
    c.restoreState()


def generate_payslip_pdf_bytes(db: Session, payslip_id: int, organization_id: int = None) -> bytes:
    """Renders a professional PDF payslip document styled after the Nova Tech
    Solutions template: navy blue header, bordered grid tables, side-by-side
    earnings/deductions, summary box, net-in-words, and disclaimer footer.
    Requires ``reportlab``."""
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import mm
    from reportlab.lib import colors
    from reportlab.pdfgen import canvas

    data, item, run = get_payslip_by_id(db, payslip_id, organization_id)

    # ── Company info for header ──
    company = db.query(CompanyComplianceDetails).filter(
        CompanyComplianceDetails.organization_id == organization_id
    ).first() if organization_id else None
    company_name = getattr(company, "name", None) or "Company Name"
    company_address = getattr(company, "address", None) or ""

    # Prompt 3: EVALUATION workspaces get a 'PREVIEW — EVALUATION ONLY'
    # watermark (read live from Organization, so converting to PRODUCTION
    # removes it automatically).
    evaluation = _is_evaluation_workspace(db, organization_id)

    # A statutorily-blocked payslip (PayslipStatus.FAILED — today: Germany
    # PAP unavailable / no effective EmployeeStatutoryProfile, recorded as
    # Phase 8BI's FAILED sentinel) carries ZERO monetary figures. Rendering
    # the normal layout here would fabricate a €0.00 payslip document —
    # explicitly forbidden (§25: never fabricate zero). Render the explicit
    # blocked-state document instead, which contains NO monetary amounts.
    if item.status == PayslipStatus.FAILED:
        return _render_blocked_payslip_pdf_bytes(data, item, run, company_name, company_address, evaluation=evaluation)

    # Phase 8BU: a PARTIALLY_CALCULATED Germany payslip (Part 21 — "remove
    # unnecessary internal blocking") DOES carry real, non-fabricated
    # figures for whichever components resolved (SI contributions, gross,
    # employer levies) but NOT for wage tax/Soli/church tax when those are
    # the unavailable component(s). The normal payslip layout below cannot
    # render this correctly — its `fmt()` helper can't distinguish a real
    # €0.00 from an unavailable one — so route to a dedicated renderer that
    # shows the real figures plainly and marks only the actually-unavailable
    # ones as "UNAVAILABLE" text, never as a numeric zero.
    if item.status == PayslipStatus.PARTIAL:
        return _render_partial_payslip_pdf_bytes(data, item, run, company_name, company_address, evaluation=evaluation)

    # data["country"] is get_payslip_by_id()'s already-resolved country —
    # the payslip's own snapshotted jurisdiction (its employee's country at
    # generation time), not the org's current default. Re-deriving it here
    # from the org's CompanyComplianceDetails (as this used to do) meant a
    # non-default-jurisdiction employee's PDF showed the wrong currency,
    # income-tax label, and statutory terminology.
    country = _normalize_country(data.get("country") or "IN")
    sym = _get_currency_symbol(country)

    def fmt(val):
        v = float(val or 0)
        if v == 0:
            return f"{sym} 0.00"
        return f"{sym} {v:,.2f}"

    def fmt_plain(val):
        return f"{float(val or 0):,.2f}"

    def fmt_date(v):
        if not v:
            return "-"
        if isinstance(v, str):
            try:
                v = datetime.strptime(v[:10], "%Y-%m-%d").date()
            except Exception:
                return v
        try:
            return v.strftime("%d-%b-%Y")
        except Exception:
            return str(v)

    def mask_account(acc):
        if not acc:
            return "-"
        s = str(acc)
        if len(s) <= 4:
            return s
        return "X" * (len(s) - 4) + s[-4:]

    currency_word = {"IN": "Rupees", "US": "Dollars", "UK": "Pounds"}.get(country, "")

    # ── Build earnings & deduction items (pre-computed for layout) ──
    earnings_items = [
        ("Basic Salary", data["basicPay"]),
        ("Housing Allowance" if country == "HK" else "House Rent Allowance (HRA)", data["hra"]),
    ]
    # Named allowance components (Transport/Medical/Other/...), if this org
    # has any configured — shown as their own line items, same as Overtime/
    # Additional Compensation below. Special Allowance stays the final
    # catch-all, listed after these named slices.
    for allowance in data.get("allowanceItems") or []:
        earnings_items.append((allowance["label"], allowance["amount"]))
    earnings_items.append(("Special Allowance", data["specialAllowance"]))
    ov = float(data.get("overtime", 0) or 0)
    if ov > 0:
        earnings_items.append(("Overtime", ov))
    add_comp = float(data.get("additionalCompensation", 0) or 0)
    if add_comp > 0:
        # Singapore: this is exactly the CPF Additional Wages figure the
        # engine used (engine/countries/singapore.py — OW = gross − AW).
        earnings_items.append(("Additional Wages (AW)" if country == "SG" else "Additional Compensation", add_comp))
    earnings_total = float(data["salary"] or 0)

    deduction_items = []
    attendance_ded = float(data.get("attendanceDeduction", 0) or 0)
    if attendance_ded > 0:
        unpaid_days = data.get("unpaidLeaveDays")
        lbl = "No-pay Leave Deduction" if country == "HK" else "LOP Deduction"
        if unpaid_days:
            lbl += f" ({float(unpaid_days):g} day{'s' if float(unpaid_days) != 1 else ''})"
        deduction_items.append((lbl, attendance_ded))
    # Every jurisdiction routes its income-tax withholding through the same
    # `tds` field (India-named historically) — label it with each
    # jurisdiction's own plain term (not a generic "Income Tax" gloss) so a
    # German/UK/Australian/etc. payslip reads the way that country's own
    # payslips actually do.
    income_tax_labels = {
        "IN": "TDS", "US": "Federal Withholding", "UK": "PAYE",
        "AU": "PAYG", "DE": "Lohnsteuer", "CA": "Federal Tax",
        # Ireland (ZP-IE-ENG-001) routes PAYE through `tds`; without this row
        # an Irish payslip read the "TDS" default, which is India's term.
        "IE": "PAYE", "FR": "Prélèvement à la Source",
        # Caribbean production jurisdictions (ZP-MJR-2026-002, 2026-09-24) —
        # real terms verified from each country's own engine module
        # docstring (engine/countries/*.py), not guessed. Bahamas/Cayman
        # deliberately have no entry here: `tds` is always Decimal("0") for
        # both (no personal income tax — see bahamas.py/cayman_islands.py's
        # own module docstrings), so the existing `if v > 0` filter below
        # already omits the line correctly; adding a label would risk it
        # being read as "this country's income tax happened to be zero".
        "BB": "PAYE", "DO": "ISR", "GY": "PAYE", "JM": "PAYE", "TT": "PAYE",
        "PR": "Hacienda Withholding",
    }
    # US: federal/state/local are stored (and shown here) as three separate
    # lines instead of one combined "Federal Withholding" figure — `tds`
    # remains the correct combined total, only used here as a fallback for
    # a payslip generated before this split existed (all three would be
    # exactly 0 in that case, never partially populated), so an old US
    # payslip's PDF is unaffected. Same fallback rule as
    # jurisdictionLabels.js's getIncomeTaxLines on the frontend.
    us_split_total = float(data.get("federalIncomeTax", 0) or 0) + float(data.get("stateIncomeTax", 0) or 0) + float(data.get("localTax", 0) or 0)
    if country == "US" and us_split_total > 0:
        income_tax_line_items = [
            ("Federal Withholding", "federalIncomeTax"),
            ("State Tax", "stateIncomeTax"),
            ("Local Tax", "localTax"),
        ]
    elif country == "DE" and float(data.get("soli", 0) or 0) > 0:
        # Phase 8BR: `tds` for Germany is (Lohnsteuer + Soli)/12 combined
        # (engine/countries/germany.py's monthly_lohnsteuer_soli) — shown
        # here as two separate lines (Lohnsteuer alone, then Soli) so the
        # PDF doesn't mislabel the combined figure as pure Lohnsteuer.
        # `data["lohnsteuerOnly"]` is computed just below; falls back to
        # the old combined-under-"Lohnsteuer" behavior if soli is 0.
        data["lohnsteuerOnly"] = float(data.get("tds", 0) or 0) - float(data.get("soli", 0) or 0)
        income_tax_line_items = [
            ("Lohnsteuer", "lohnsteuerOnly"),
            ("Solidaritätszuschlag (Soli)", "soli"),
        ]
    else:
        income_tax_line_items = [(income_tax_labels.get(country, "TDS"), "tds")]
    pf_esi_labels = {
        "DE": {"pf": "Pension Insurance", "esi": "Social Insurance (Health / Unemployment / Care)"},
        "CA": {"esi": "Employment Insurance (EI)"},
    }.get(country, {})
    # Trinidad reuses the `professional_tax` field for its Health Surcharge
    # (see trinidad_and_tobago.py's own comment on that field) — it was
    # previously shown under the literal "Professional Tax" for every
    # country, mislabeling Trinidad's deduction with an India-specific term.
    # Singapore reuses professional_tax for its Self-Help Group deduction
    # (CDAC/ECF/MBMF/SINDA) — see engine/countries/singapore.py.
    professional_tax_label = {"TT": "Health Surcharge", "SG": "SHG Contribution"}.get(country, "Professional Tax")
    for lbl, key in [
        *income_tax_line_items,
        (pf_esi_labels.get("pf", "Provident Fund (PF)"), "pf"),
        (pf_esi_labels.get("esi", "Employee State Insurance (ESI)"), "esi"),
        (professional_tax_label, "professionalTax"),
    ]:
        v = float(data.get(key, 0) or 0)
        if v > 0:
            deduction_items.append((lbl, v))
    # Germany: Kirchensteuer (church tax) is a statutory deduction from the
    # employee's pay when de_church_tax_liable is set — persisted in
    # PayslipItem.church_tax and populated by the engine. Only shown when
    # the value is actually nonzero.
    if country == "DE":
        # Key is the serializer's camelCase "churchTax" (emitted by
        # _serialize_payslip) — the previous snake_case key never existed
        # in the data dict, so this branch was dead and Kirchensteuer
        # never appeared on a German PDF.
        church_tax_val = float(data.get("churchTax", 0) or 0)
        if church_tax_val > 0:
            deduction_items.append(("Kirchensteuer", church_tax_val))
    other_labels = {
        "CA": {"socialSecurity": "Canada Pension Plan (CPP)"},
        "AU": {"medicare": "Medicare Levy"},
        # Caribbean production jurisdictions (ZP-MJR-2026-002, 2026-09-24) —
        # real terms verified from each country's own engine module
        # docstring. `employeePension` and `niEmployee` are both reused/
        # repurposed fields in these countries, NOT a literal pension or UK
        # National Insurance — see barbados.py/dominican_republic.py/
        # jamaica.py's own comments on those fields.
        "BB": {"socialSecurity": "NIS", "employeePension": "Reserve & Retraining (R&R) Levy"},
        "DO": {"socialSecurity": "SFS (Seguro Familiar de Salud)", "employeePension": "Pension (SVDS)"},
        "GY": {"socialSecurity": "NIS"},
        "JM": {"socialSecurity": "NIS", "employeePension": "National Housing Trust (NHT)", "niEmployee": "Education Tax"},
        "TT": {"socialSecurity": "NIS"},
        "BS": {"socialSecurity": "NIB"},
        "KY": {"socialSecurity": "NIB Pension"},
        # Singapore reuses employee_pension for employee CPF.
        "SG": {"employeePension": "CPF (Employee)"},
        # Hong Kong: MPF employee mandatory contribution — never an income
        # tax line (no `tds` is ever set for HK).
        "HK": {"employeePension": "MPF Mandatory Contribution (Employee)"},
    }.get(country, {})
    for lbl, key in [
        (other_labels.get("socialSecurity", "Social Security"), "socialSecurity"),
        (other_labels.get("medicare", "Medicare"), "medicare"),
        (other_labels.get("niEmployee", "National Insurance"), "niEmployee"),
        # UK: Workplace Pension (employee side) and Student/Postgraduate
        # Loan — both correctly computed/persisted but previously invisible
        # on every UK payslip PDF (see _serialize_payslip's own fix note).
        (other_labels.get("employeePension", "Workplace Pension"), "employeePension"),
        ("Student Loan Deduction", "studyLoanDeduction"),
        ("Postgraduate Loan Deduction", "postgradLoanDeduction"),
    ]:
        v = float(data.get(key, 0) or 0)
        if v > 0:
            deduction_items.append((lbl, v))
    # US: State Disability Insurance / other state payroll-program employee
    # deductions (CA SDI, NY/NJ/RI TDI, CT/MA/WA/CO/OR/etc. paid-leave
    # employee share) — computed and persisted but never shown on the PDF
    # before this fix (found 2026-09-15 Org Admin visibility audit).
    if country == "US":
        for lbl, key in [
            ("State Disability Insurance", "stateDisabilityInsurance"),
            ("State Payroll Programs (e.g. Paid Leave/TDI)", "stateProgramDeductions"),
        ]:
            v = float(data.get(key, 0) or 0)
            if v > 0:
                deduction_items.append((lbl, v))
    # Employer-side contributions (Employer PF/ESI/Social Security/Medicare/
    # Pension/NI) are deliberately NOT shown here — this is the employee's
    # own payslip, and none of these are amounts deducted from the
    # employee's pay. They were previously mixed into this same
    # "Deductions" list (mislabeled, since they're the employer's own
    # cost, not the employee's) — removed at Venu's request. They remain
    # visible to admins on the Payroll Register / Run Detail views, which
    # are internal cost-review screens, not the payslip document itself.
    deductions_total = float(data["totalDeductions"] or 0)

    import io
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=A4)
    width, height = A4

    # ── Font setup: register Unicode font for rupee symbol ──
    base_font = _register_rupee_font(c)
    F = base_font or "Helvetica"
    FB = f"{base_font}-Bold" if base_font else "Helvetica-Bold"
    try:
        c.setFont(FB, 9)
    except Exception:
        FB = F

    # ── Colors ──
    navy = colors.HexColor("#1e3a8a")
    value_blue = colors.HexColor("#1d4ed8")
    gray_100 = colors.HexColor("#F3F4F6")
    gray_300 = colors.HexColor("#D1D5DB")
    gray_500 = colors.HexColor("#6B7280")
    gray_900 = colors.HexColor("#111827")
    green_600 = colors.HexColor("#16A34A")
    green_bg = colors.HexColor("#ECFDF5")
    white = colors.white

    card_margin = 6 * mm
    card_x = card_margin
    card_r_edge = width - card_margin
    card_w = card_r_edge - card_x

    margin_l = 14 * mm
    margin_r = width - 14 * mm
    page_w = margin_r - margin_l
    col_mid = width / 2
    y = height - card_margin
    card_top = y

    # ── Compute dynamic gaps so content fills the A4 page ──
    cell_h = 9.0 * mm
    hdr_h = 10.0 * mm
    row_h = 9.0 * mm
    sum_row_h = 9.5 * mm
    pd_row_h = 9.0 * mm

    min_gap_after_sub = 9 * mm
    min_gap_after_emp = 11 * mm
    min_gap_after_tables = 6 * mm
    min_gap_after_summary = 5 * mm
    min_gap_after_net_words = 7 * mm
    min_gap_after_payment = 3 * mm

    earnings_table_h = hdr_h + len(earnings_items) * cell_h + cell_h
    deductions_table_h = hdr_h + len(deduction_items) * cell_h + cell_h
    table_h = max(earnings_table_h, deductions_table_h)

    total_min_content = (
        24 * mm +           # header
        14 * mm +           # sub-header
        6 * mm +            # employee details heading
        5 * row_h +         # 5 employee rows
        6 * mm +            # earnings heading
        table_h +
        3 * sum_row_h +     # summary
        6 * mm +            # net-in-words heading
        8 * mm +            # net-in-words text
        2 * pd_row_h        # payment details table body
        + min_gap_after_sub + min_gap_after_emp + min_gap_after_tables
        + min_gap_after_summary + min_gap_after_net_words + min_gap_after_payment
    )
    available_h = (height - card_margin) - 10 * mm
    extra_h = max(0, available_h - total_min_content)
    per_gap = extra_h / 6 if extra_h > 0 else 0

    gap_after_sub = min_gap_after_sub + per_gap
    gap_after_emp = min_gap_after_emp + per_gap
    gap_after_tables = min_gap_after_tables + per_gap
    gap_after_summary = min_gap_after_summary + per_gap
    gap_after_net_words = min_gap_after_net_words + per_gap
    gap_after_payment = min_gap_after_payment + per_gap

    # ══════════════════════════════════════════════════════════════════════
    # 1. HEADER - Navy banner, left-aligned company name/address
    # ══════════════════════════════════════════════════════════════════════
    header_h = 24 * mm
    c.setFillColor(navy)
    c.rect(card_x, y - header_h, card_w, header_h, fill=True, stroke=False)

    c.setFillColor(white)
    c.setFont(FB, 20)
    c.drawString(margin_l + 5 * mm, y - 9 * mm, company_name.upper())
    if company_address:
        c.setFont(F, 10.5)
        c.drawString(margin_l + 5 * mm, y - 16 * mm, company_address)
    y -= header_h

    # ══════════════════════════════════════════════════════════════════════
    # 2. SUB-HEADER - Gray band, centered "PAYSLIP" + "Salary Month"
    # ══════════════════════════════════════════════════════════════════════
    sub_h = 14 * mm
    c.setFillColor(gray_100)
    c.rect(card_x, y - sub_h, card_w, sub_h, fill=True, stroke=False)

    c.setFillColor(gray_900)
    c.setFont(FB, 18)
    c.drawCentredString(col_mid, y - 5.5 * mm, "PAYSLIP")
    c.setFont(FB, 10.5)
    c.setFillColor(gray_500)
    salary_month = run.period_start.strftime("%B %Y")
    c.drawCentredString(col_mid, y - 11.5 * mm, f"Salary Month : {salary_month}")
    y -= sub_h + gap_after_sub

    # ══════════════════════════════════════════════════════════════════════
    # 3. EMPLOYEE DETAILS - plain heading + full-width grid table
    # ══════════════════════════════════════════════════════════════════════
    c.setFillColor(gray_900)
    c.setFont(FB, 13.5)
    c.drawString(margin_l, y, "Employee Details")
    y -= 6 * mm

    label_w = page_w * 0.20
    value_w = page_w * 0.30
    col_x = [margin_l, margin_l + label_w, margin_l + label_w + value_w,
             margin_l + 2 * label_w + value_w, margin_r]

    def draw_detail_row(y_top, row_h, cells):
        """cells: [(label, value), (label, value)]. Draws one bordered row."""
        c.setStrokeColor(gray_300)
        c.setLineWidth(0.4)
        c.rect(margin_l, y_top - row_h, page_w, row_h, fill=False, stroke=True)
        for cx in col_x[1:-1]:
            c.line(cx, y_top, cx, y_top - row_h)
        baseline = y_top - row_h / 2 - 1.6 * mm
        for i, (lbl, val) in enumerate(cells):
            lx = col_x[i * 2]
            vx = col_x[i * 2 + 1]
            c.setFillColor(gray_900)
            c.setFont(FB, 10)
            c.drawString(lx + 3 * mm, baseline, lbl)
            c.setFillColor(gray_900)
            c.setFont(F, 10)
            c.drawString(vx + 3 * mm, baseline, str(val))

    id_row1, id_row2, id_row3 = _payslip_identity_rows(country, data)
    emp_rows = [
        [("Employee Name", data["employee"]), ("Employee ID", str(data["employeeId"]))],
        [("Department", data["department"] or "-"), ("Designation", data.get("designation") or "-")],
        [("Date of Joining", fmt_date(data.get("dateOfJoining"))), (id_row1[0], id_row1[1] or "-")],
        [(id_row2[0], id_row2[1] or "-"), ("Bank", data.get("bankName") or "-")],
        [("Account No.", mask_account(data["bankAccount"])), (id_row3[0], id_row3[1] or "-")],
    ]
    for row in emp_rows:
        draw_detail_row(y, row_h, row)
        y -= row_h
    y -= gap_after_emp

    # ══════════════════════════════════════════════════════════════════════
    # 4. EARNINGS & DEDUCTIONS - plain headings + navy-header mini tables
    # ══════════════════════════════════════════════════════════════════════
    half_w = page_w / 2 - 1 * mm
    table_l = margin_l
    table_r = margin_l + half_w + 2 * mm

    c.setFillColor(gray_900)
    c.setFont(FB, 13.5)
    c.drawString(margin_l, y, "Earnings")
    c.drawString(table_r, y, "Deductions")
    y -= 6 * mm

    # Draw EARNINGS table
    ey = y
    c.setFillColor(navy)
    c.rect(table_l, ey - hdr_h, half_w, hdr_h, fill=True, stroke=False)
    c.setFillColor(white)
    c.setFont(FB, 9.5)
    c.drawString(table_l + 3 * mm, ey - hdr_h + 3.3 * mm, "Component")
    c.drawRightString(table_l + half_w - 3 * mm, ey - hdr_h + 3.3 * mm, f"Amount ({sym})")
    ey -= hdr_h

    for lbl, val in earnings_items:
        c.setStrokeColor(gray_300)
        c.setLineWidth(0.3)
        c.rect(table_l, ey - cell_h, half_w, cell_h, fill=False, stroke=True)
        c.setFillColor(gray_900)
        c.setFont(F, 10)
        c.drawString(table_l + 3 * mm, ey - cell_h + 3.1 * mm, lbl)
        c.drawRightString(table_l + half_w - 3 * mm, ey - cell_h + 3.1 * mm, fmt_plain(val))
        ey -= cell_h

    # Earnings total row
    c.setFillColor(navy)
    c.rect(table_l, ey - cell_h, half_w, cell_h, fill=True, stroke=False)
    c.setFillColor(white)
    c.setFont(FB, 10)
    c.drawString(table_l + 3 * mm, ey - cell_h + 3.1 * mm, "Total Earnings")
    c.drawRightString(table_l + half_w - 3 * mm, ey - cell_h + 3.1 * mm, fmt_plain(earnings_total))
    ey -= cell_h

    # Draw DEDUCTIONS table
    dy = y
    c.setFillColor(navy)
    c.rect(table_r, dy - hdr_h, half_w, hdr_h, fill=True, stroke=False)
    c.setFillColor(white)
    c.setFont(FB, 9.5)
    c.drawString(table_r + 3 * mm, dy - hdr_h + 3.3 * mm, "Component")
    c.drawRightString(table_r + half_w - 3 * mm, dy - hdr_h + 3.3 * mm, f"Amount ({sym})")
    dy -= hdr_h

    for lbl, val in deduction_items:
        c.setStrokeColor(gray_300)
        c.setLineWidth(0.3)
        c.rect(table_r, dy - cell_h, half_w, cell_h, fill=False, stroke=True)
        c.setFillColor(gray_900)
        c.setFont(F, 10)
        c.drawString(table_r + 3 * mm, dy - cell_h + 3.1 * mm, lbl)
        c.drawRightString(table_r + half_w - 3 * mm, dy - cell_h + 3.1 * mm, fmt_plain(val))
        dy -= cell_h

    # Deductions total row
    c.setFillColor(navy)
    c.rect(table_r, dy - cell_h, half_w, cell_h, fill=True, stroke=False)
    c.setFillColor(white)
    c.setFont(FB, 10)
    c.drawString(table_r + 3 * mm, dy - cell_h + 3.1 * mm, "Total Deductions")
    c.drawRightString(table_r + half_w - 3 * mm, dy - cell_h + 3.1 * mm, fmt_plain(deductions_total))
    dy -= cell_h

    # Sync y to the lower of the two tables
    y = min(ey, dy) - gap_after_tables

    # ══════════════════════════════════════════════════════════════════════
    # 5. SUMMARY BOX - right half only: Gross / Deductions / NET PAY
    # ══════════════════════════════════════════════════════════════════════
    sum_row_h = 9.5 * mm
    sum_x = table_r
    sum_w = half_w

    c.setStrokeColor(gray_300)
    c.setLineWidth(0.5)

    # Row 1: Gross Salary
    c.rect(sum_x, y - sum_row_h, sum_w, sum_row_h, fill=False, stroke=True)
    c.setFillColor(gray_900)
    c.setFont(FB, 10.5)
    c.drawString(sum_x + 3 * mm, y - sum_row_h + 3.3 * mm, "Gross Salary")
    c.drawRightString(sum_x + sum_w - 3 * mm, y - sum_row_h + 3.3 * mm, fmt(earnings_total))
    y -= sum_row_h

    # Row 2: Total Deductions
    c.rect(sum_x, y - sum_row_h, sum_w, sum_row_h, fill=False, stroke=True)
    c.setFillColor(gray_900)
    c.setFont(FB, 10.5)
    c.drawString(sum_x + 3 * mm, y - sum_row_h + 3.3 * mm, "Total Deductions")
    c.drawRightString(sum_x + sum_w - 3 * mm, y - sum_row_h + 3.3 * mm, fmt(deductions_total))
    y -= sum_row_h

    # Row 3: Net Pay (green highlighted)
    c.setFillColor(green_bg)
    c.rect(sum_x, y - sum_row_h, sum_w, sum_row_h, fill=True, stroke=False)
    c.setStrokeColor(green_600)
    c.setLineWidth(0.8)
    c.rect(sum_x, y - sum_row_h, sum_w, sum_row_h, fill=False, stroke=True)
    c.setFillColor(green_600)
    c.setFont(FB, 13)
    c.drawString(sum_x + 3 * mm, y - sum_row_h + 3.3 * mm, "NET PAY")
    c.drawRightString(sum_x + sum_w - 3 * mm, y - sum_row_h + 3.3 * mm, fmt(data["netPay"]))
    y -= sum_row_h

    y -= gap_after_summary

    # ══════════════════════════════════════════════════════════════════════
    # 6. NET SALARY IN WORDS
    # ══════════════════════════════════════════════════════════════════════
    words = _amount_to_words(float(data["netPay"] or 0))
    c.setFillColor(gray_900)
    c.setFont(FB, 12)
    c.drawString(margin_l, y, "Net Salary in Words")
    y -= 6 * mm
    c.setFont(F, 12)
    suffix = f"{currency_word} Only." if currency_word else "Only."
    c.drawString(margin_l, y, f"{words} {suffix}")
    y -= gap_after_net_words

    # ══════════════════════════════════════════════════════════════════════
    # 7. PAYMENT DETAILS - 2x2 table (label row + value row)
    # ══════════════════════════════════════════════════════════════════════
    pd_row_h = 9.0 * mm
    c.setStrokeColor(gray_300)
    c.setLineWidth(0.4)
    c.rect(margin_l, y - 2 * pd_row_h, page_w, 2 * pd_row_h, fill=False, stroke=True)
    c.line(col_mid, y, col_mid, y - 2 * pd_row_h)
    c.line(margin_l, y - pd_row_h, margin_r, y - pd_row_h)

    c.setFillColor(gray_900)
    c.setFont(FB, 10)
    c.drawString(margin_l + 3 * mm, y - pd_row_h + 3.2 * mm, "Payment Mode")
    c.drawString(col_mid + 3 * mm, y - pd_row_h + 3.2 * mm, "Salary Credit Date")

    c.setFont(F, 10.5)
    c.drawString(margin_l + 3 * mm, y - 2 * pd_row_h + 3.2 * mm, "Bank Transfer" if country == "HK" else "Bank Transfer (NEFT)")
    c.drawString(col_mid + 3 * mm, y - 2 * pd_row_h + 3.2 * mm, fmt_date(data["payDate"]))
    y -= 2 * pd_row_h + gap_after_payment

    # ══════════════════════════════════════════════════════════════════════
    # 9. FOOTER - separator line + disclaimer
    # ══════════════════════════════════════════════════════════════════════
    c.setStrokeColor(gray_300)
    c.setLineWidth(0.4)
    c.line(margin_l, 10 * mm, margin_r, 10 * mm)
    c.setFont(F, 9.5)
    c.setFillColor(gray_500)
    c.drawCentredString(width / 2, 6.5 * mm,
                        "This is a computer-generated payslip and does not require a signature.")

    # ══════════════════════════════════════════════════════════════════════
    # 10. OUTER CARD FRAME - subtle border around the whole document
    # ══════════════════════════════════════════════════════════════════════
    card_bottom = card_margin
    c.setStrokeColor(gray_300)
    c.setLineWidth(0.8)
    c.rect(card_x, card_bottom, card_w, card_top - card_bottom, fill=0, stroke=1)

    if evaluation:
        _draw_evaluation_watermark(c, width, height, F)

    c.showPage()
    c.save()
    return buf.getvalue()


def _render_blocked_payslip_pdf_bytes(data: dict, item: PayslipItem, run: PayrollRun,
                                       company_name: str, company_address: str,
                                       *, evaluation: bool = False) -> bytes:
    """Renders the explicit blocked-state document for a statutorily-blocked
    payslip (PayslipStatus.FAILED — e.g. Germany PAP unavailable or no
    effective EmployeeStatutoryProfile, recorded as Phase 8BI's FAILED
    sentinel).

    Deliberately NOT a payslip: the document contains ZERO monetary figures.
    The FAILED row stores none (every money column is 0 by construction), so
    a normal payslip layout would fabricate a €0.00 document — explicitly
    forbidden (§25: never fabricate zero). Instead it states that no
    statutory payroll amount could be calculated for this employee for the
    period and surfaces the already-redacted blocker (blockedReasonCode /
    blockedReasonMessage) stored in the sentinel's
    germany_calculation_snapshot, for operator traceability."""
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import mm
    from reportlab.lib import colors
    from reportlab.pdfgen import canvas

    import io
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=A4)
    width, height = A4

    base_font = _register_rupee_font(c)
    F = base_font or "Helvetica"
    FB = f"{base_font}-Bold" if base_font else "Helvetica-Bold"
    try:
        c.setFont(FB, 9)
    except Exception:
        FB = F

    navy = colors.HexColor("#1e3a8a")
    gray_100 = colors.HexColor("#F3F4F6")
    gray_300 = colors.HexColor("#D1D5DB")
    gray_500 = colors.HexColor("#6B7280")
    gray_900 = colors.HexColor("#111827")
    red_600 = colors.HexColor("#DC2626")
    red_bg = colors.HexColor("#FEF2F2")
    amber_600 = colors.HexColor("#92400E")
    amber_bg = colors.HexColor("#FEF3C7")
    white = colors.white

    card_margin = 6 * mm
    card_x = card_margin
    card_w = width - 2 * card_margin
    margin_l = 14 * mm
    margin_r = width - 14 * mm
    page_w = margin_r - margin_l
    col_mid = width / 2
    y = height - card_margin

    snapshot = dict(item.germany_calculation_snapshot or {})
    blocked_reason_code = snapshot.get("blockedReasonCode")
    blocked_reason_message = snapshot.get("blockedReasonMessage")
    salary_month = run.period_start.strftime("%B %Y") if run.period_start else (run.period_label or "")

    def text_line(x, yy, val, font, size, color):
        c.setFillColor(color)
        c.setFont(font, size)
        c.drawString(x, yy, val)

    # ── 1. Header — navy banner, company name/address ──
    header_h = 24 * mm
    c.setFillColor(navy)
    c.rect(card_x, y - header_h, card_w, header_h, fill=True, stroke=False)
    text_line(margin_l + 5 * mm, y - 9 * mm, company_name.upper(), FB, 20, white)
    if company_address:
        text_line(margin_l + 5 * mm, y - 16 * mm, company_address, F, 10.5, white)
    y -= header_h

    # ── 2. Sub-header — gray band, "PAYSLIP" + blocked status ──
    sub_h = 14 * mm
    c.setFillColor(gray_100)
    c.rect(card_x, y - sub_h, card_w, sub_h, fill=True, stroke=False)
    salary_month_label = "Salary Month : {}".format(salary_month) if salary_month else ""
    text_line(margin_l, y - 5.5 * mm, salary_month_label, F, 10.5, gray_500)
    text_line(col_mid - 60, y - 5.5 * mm, "PAYSLIP", FB, 18, gray_900)
    text_line(margin_r - 78, y - 5.5 * mm, "STATUS : BLOCKED", FB, 10.5, red_600)
    y -= sub_h + 6 * mm

    # ── 3. Red banner — no amounts issued ──
    c.setFillColor(red_bg)
    c.rect(card_x, y - 30 * mm, card_w, 30 * mm, fill=True, stroke=False)
    c.setStrokeColor(red_600)
    c.setLineWidth(1)
    c.rect(card_x, y - 30 * mm, card_w, 30 * mm, fill=False, stroke=True)
    text_line(margin_l + 4 * mm, y - 10 * mm, "NO PAYSLIP ISSUED - PAYROLL CALCULATION BLOCKED", FB, 13, red_600)
    text_line(margin_l + 4 * mm, y - 17 * mm,
              "A statutory payroll amount could NOT be calculated for this employee for the stated period.",
              F, 10.5, gray_900)
    text_line(margin_l + 4 * mm, y - 23 * mm,
              "No monetary figures are shown on this document because none were legally calculable.",
              F, 10.5, gray_900)
    y -= 30 * mm + 6 * mm

    # ── 4. Employee details ──
    text_line(margin_l, y, "Employee Details", FB, 13, gray_900)
    y -= 6 * mm

    row_h = 9 * mm
    label_w = page_w * 0.20
    value_w = page_w * 0.30
    col_x = [margin_l, margin_l + label_w, margin_l + label_w + value_w,
             margin_l + 2 * label_w + value_w, margin_r]

    id_row1, id_row2, id_row3 = _payslip_identity_rows(_normalize_country(data.get("country") or "IN"), data)
    emp_rows = [
        [("Employee Name", data["employee"] if data.get("employee") else f"Employee #{item.employee_id}"),
         ("Employee ID", str(item.employee_id))],
        [("Department", data.get("department") or "-"), ("Designation", data.get("designation") or "-")],
        [("Period", run.period_label or "-"), (id_row1[0], id_row1[1] or "-")],
        [(id_row2[0], id_row2[1] or "-"), ("Bank", data.get("bankName") or "-")],
        [("Account No.", str(data.get("bankAccount") or "-")), (id_row3[0], id_row3[1] or "-")],
    ]
    for row in emp_rows:
        c.setStrokeColor(gray_300)
        c.setLineWidth(0.4)
        c.rect(margin_l, y - row_h, page_w, row_h, fill=False, stroke=True)
        for cx in col_x[1:-1]:
            c.line(cx, y, cx, y - row_h)
        baseline = y - row_h / 2 - 1.6 * mm
        for i, (lbl, val) in enumerate(row):
            lx = col_x[i * 2]
            vx = col_x[i * 2 + 1]
            text_line(lx + 3 * mm, baseline, lbl, FB, 10, gray_900)
            text_line(vx + 3 * mm, baseline, str(val), F, 10, gray_900)
        y -= row_h
    y -= 6 * mm

    # ── 5. Blocked reason panel ──
    panel_h = 46 * mm
    c.setFillColor(amber_bg)
    c.rect(card_x, y - panel_h, card_w, panel_h, fill=True, stroke=False)
    c.setStrokeColor(gray_300)
    c.setLineWidth(0.8)
    c.rect(card_x, y - panel_h, card_w, panel_h, fill=False, stroke=True)
    text_line(margin_l + 4 * mm, y - 9 * mm, "Why this employee is blocked", FB, 12, amber_600)
    reason_code = blocked_reason_code or "UNKNOWN"
    text_line(margin_l + 4 * mm, y - 17 * mm, "Block code : {}".format(reason_code), FB, 10, gray_900)
    message = blocked_reason_message or "No statutory payroll result could be calculated for this employee."
    y_text = y - 24 * mm
    chunks = []
    words = str(message).split()
    line = ""
    for w in words:
        trial = (line + " " + w).strip()
        if len(trial) <= 90:
            line = trial
        else:
            chunks.append(line)
            line = w
    if line:
        chunks.append(line)
    for chunk in chunks[:5]:
        text_line(margin_l + 4 * mm, y_text, chunk, F, 10, gray_900)
        y_text -= 4.6 * mm
    text_line(margin_l + 4 * mm, y - 40 * mm,
              "Resolve the blocker (e.g. in Germany Compliance / Statutory Configuration) and recalculate once cleared.",
              F, 10, gray_500)

    # ── 6. Footer + outer frame ──
    c.setStrokeColor(gray_300)
    c.setLineWidth(0.4)
    c.line(margin_l, 12 * mm, margin_r, 12 * mm)
    text_line(margin_l, 8 * mm,
              "This document confirms that no statutory payroll result could be calculated for this employee for this period.",
              F, 9, gray_500)
    text_line(margin_l, 4.5 * mm,
              "It is NOT a payslip and contains no monetary amounts.",
              F, 9, gray_500)

    card_bottom = card_margin
    c.setStrokeColor(gray_300)
    c.setLineWidth(0.8)
    c.rect(card_x, card_bottom, card_w, y + card_margin - card_bottom, fill=0, stroke=1)

    if evaluation:
        _draw_evaluation_watermark(c, width, height, F)

    c.showPage()
    c.save()
    return buf.getvalue()


_GERMANY_COMPONENT_LABELS = {
    "wage_tax": "Lohnsteuer (wage tax)",
    "soli": "Solidaritätszuschlag (Soli)",
    "church_tax": "Kirchensteuer (church tax)",
}


def _render_partial_payslip_pdf_bytes(data: dict, item: PayslipItem, run: PayrollRun,
                                        company_name: str, company_address: str,
                                        *, evaluation: bool = False) -> bytes:
    """Renders a Germany PARTIALLY_CALCULATED payslip (PayslipStatus.PARTIAL
    — Phase 8BU, Part 21 "remove unnecessary internal blocking").

    Unlike ``_render_blocked_payslip_pdf_bytes`` (which shows zero monetary
    figures because NOTHING was calculable), this document shows the REAL,
    non-fabricated figures for whichever components the engine actually
    resolved this period (gross pay, RV, ALV+GKV+PV) while explicitly
    labelling the specific unavailable component(s) (typically wage tax /
    Soli / church tax, per ``germanyUnavailableComponents``) as
    "UNAVAILABLE" text rather than a numeric €0.00 — the same "never
    fabricate zero" rule the blocked-document renderer already follows."""
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.units import mm
    from reportlab.lib import colors
    from reportlab.pdfgen import canvas

    import io
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=A4)
    width, height = A4

    base_font = _register_rupee_font(c)
    F = base_font or "Helvetica"
    FB = f"{base_font}-Bold" if base_font else "Helvetica-Bold"
    try:
        c.setFont(FB, 9)
    except Exception:
        FB = F

    navy = colors.HexColor("#1e3a8a")
    gray_100 = colors.HexColor("#F3F4F6")
    gray_300 = colors.HexColor("#D1D5DB")
    gray_500 = colors.HexColor("#6B7280")
    gray_900 = colors.HexColor("#111827")
    amber_600 = colors.HexColor("#92400E")
    amber_bg = colors.HexColor("#FEF3C7")
    white = colors.white

    sym = _get_currency_symbol("DE")

    def fmt_real(val):
        return f"{sym} {float(val or 0):,.2f}"

    card_margin = 6 * mm
    card_x = card_margin
    card_w = width - 2 * card_margin
    margin_l = 14 * mm
    margin_r = width - 14 * mm
    page_w = margin_r - margin_l
    col_mid = width / 2
    y = height - card_margin

    unavailable = list(data.get("germanyUnavailableComponents") or [])
    unavailable_labels = [_GERMANY_COMPONENT_LABELS.get(c_, c_) for c_ in unavailable]
    salary_month = run.period_start.strftime("%B %Y") if run.period_start else (run.period_label or "")

    def text_line(x, yy, val, font, size, color):
        c.setFillColor(color)
        c.setFont(font, size)
        c.drawString(x, yy, val)

    # ── 1. Header ──
    header_h = 24 * mm
    c.setFillColor(navy)
    c.rect(card_x, y - header_h, card_w, header_h, fill=True, stroke=False)
    text_line(margin_l + 5 * mm, y - 9 * mm, company_name.upper(), FB, 20, white)
    if company_address:
        text_line(margin_l + 5 * mm, y - 16 * mm, company_address, F, 10.5, white)
    y -= header_h

    # ── 2. Sub-header ──
    sub_h = 14 * mm
    c.setFillColor(gray_100)
    c.rect(card_x, y - sub_h, card_w, sub_h, fill=True, stroke=False)
    salary_month_label = "Salary Month : {}".format(salary_month) if salary_month else ""
    text_line(margin_l, y - 5.5 * mm, salary_month_label, F, 10.5, gray_500)
    text_line(col_mid - 60, y - 5.5 * mm, "PAYSLIP", FB, 18, gray_900)
    text_line(margin_r - 108, y - 5.5 * mm, "STATUS : PARTIALLY CALCULATED", FB, 10.5, amber_600)
    y -= sub_h + 6 * mm

    # ── 3. Amber banner — explains what is/isn't available ──
    banner_h = 30 * mm
    c.setFillColor(amber_bg)
    c.rect(card_x, y - banner_h, card_w, banner_h, fill=True, stroke=False)
    c.setStrokeColor(amber_600)
    c.setLineWidth(1)
    c.rect(card_x, y - banner_h, card_w, banner_h, fill=False, stroke=True)
    text_line(margin_l + 4 * mm, y - 10 * mm, "PARTIAL PAYROLL RESULT — SOME COMPONENTS UNAVAILABLE", FB, 12.5, amber_600)
    text_line(margin_l + 4 * mm, y - 17 * mm,
              "The figures below marked with a value ARE real, calculated amounts. Components marked",
              F, 10, gray_900)
    unavailable_str = ", ".join(unavailable_labels) if unavailable_labels else "one or more tax components"
    text_line(margin_l + 4 * mm, y - 23 * mm,
              "\"UNAVAILABLE\" ({}) could NOT be calculated and are never shown as zero.".format(unavailable_str),
              F, 10, gray_900)
    y -= banner_h + 6 * mm

    # ── 4. Employee details ──
    text_line(margin_l, y, "Employee Details", FB, 13, gray_900)
    y -= 6 * mm

    row_h = 9 * mm
    label_w = page_w * 0.20
    value_w = page_w * 0.30
    col_x = [margin_l, margin_l + label_w, margin_l + label_w + value_w,
             margin_l + 2 * label_w + value_w, margin_r]

    id_row1, id_row2, id_row3 = _payslip_identity_rows(_normalize_country(data.get("country") or "DE"), data)
    emp_rows = [
        [("Employee Name", data["employee"] if data.get("employee") else f"Employee #{item.employee_id}"),
         ("Employee ID", str(item.employee_id))],
        [("Department", data.get("department") or "-"), ("Designation", data.get("designation") or "-")],
        [("Period", run.period_label or "-"), (id_row1[0], id_row1[1] or "-")],
        [(id_row2[0], id_row2[1] or "-"), ("Bank", data.get("bankName") or "-")],
        [("Account No.", str(data.get("bankAccount") or "-")), (id_row3[0], id_row3[1] or "-")],
    ]
    for row in emp_rows:
        c.setStrokeColor(gray_300)
        c.setLineWidth(0.4)
        c.rect(margin_l, y - row_h, page_w, row_h, fill=False, stroke=True)
        for cx in col_x[1:-1]:
            c.line(cx, y, cx, y - row_h)
        baseline = y - row_h / 2 - 1.6 * mm
        for i, (lbl, val) in enumerate(row):
            lx = col_x[i * 2]
            vx = col_x[i * 2 + 1]
            text_line(lx + 3 * mm, baseline, lbl, FB, 10, gray_900)
            text_line(vx + 3 * mm, baseline, str(val), F, 10, gray_900)
        y -= row_h
    y -= 6 * mm

    # ── 5. Available-vs-unavailable figures table ──
    text_line(margin_l, y, "Payroll Components", FB, 13, gray_900)
    y -= 6 * mm

    def is_unavailable(component_key: str) -> bool:
        return component_key in unavailable

    rows = [
        ("Gross Salary", fmt_real(data.get("salary")), False),
        ("Pension Insurance (RV, employee)", fmt_real(data.get("pf")), False),
        ("Social Insurance — ALV/GKV/PV (employee)", fmt_real(data.get("esi")), False),
        ("Lohnsteuer (wage tax)", "UNAVAILABLE" if is_unavailable("wage_tax") else fmt_real(data.get("tds")), is_unavailable("wage_tax")),
        ("Solidaritätszuschlag (Soli)", "UNAVAILABLE" if is_unavailable("soli") else fmt_real(data.get("soli")), is_unavailable("soli")),
        ("Kirchensteuer (church tax)", "UNAVAILABLE" if is_unavailable("church_tax") else fmt_real(data.get("churchTax")), is_unavailable("church_tax")),
        ("NET PAY", "UNAVAILABLE", True),
    ]
    tbl_row_h = 8 * mm
    label_col_w = page_w * 0.62
    for lbl, val, unavail in rows:
        c.setStrokeColor(gray_300)
        c.setLineWidth(0.4)
        c.rect(margin_l, y - tbl_row_h, page_w, tbl_row_h, fill=False, stroke=True)
        c.line(margin_l + label_col_w, y, margin_l + label_col_w, y - tbl_row_h)
        baseline = y - tbl_row_h / 2 - 1.6 * mm
        text_line(margin_l + 3 * mm, baseline, lbl, FB if lbl == "NET PAY" else F, 10, gray_900)
        val_color = amber_600 if unavail else gray_900
        text_line(margin_l + label_col_w + 3 * mm, baseline, val, FB if unavail else F, 10, val_color)
        y -= tbl_row_h
    y -= 6 * mm

    # ── 6. Why this is partial ──
    reason_h = 22 * mm
    c.setFillColor(gray_100)
    c.rect(card_x, y - reason_h, card_w, reason_h, fill=True, stroke=False)
    c.setStrokeColor(gray_300)
    c.setLineWidth(0.8)
    c.rect(card_x, y - reason_h, card_w, reason_h, fill=False, stroke=True)
    text_line(margin_l + 4 * mm, y - 8 * mm, "Why this payslip is partial", FB, 11, gray_900)
    text_line(margin_l + 4 * mm, y - 15 * mm,
              "The above unavailable component(s) require configuration/certification not yet available for this",
              F, 9.5, gray_500)
    text_line(margin_l + 4 * mm, y - 19.5 * mm,
              "employee. Recalculate once resolved — the real figures already shown will not change retroactively.",
              F, 9.5, gray_500)
    y -= reason_h + 4 * mm

    # ── 7. Footer + outer frame ──
    c.setStrokeColor(gray_300)
    c.setLineWidth(0.4)
    c.line(margin_l, 12 * mm, margin_r, 12 * mm)
    text_line(margin_l, 8 * mm,
              "This document reflects only the payroll components that were actually calculated for this period.",
              F, 9, gray_500)
    text_line(margin_l, 4.5 * mm,
              "Amounts marked UNAVAILABLE are not zero — they could not be calculated and are excluded from Net Pay.",
              F, 9, gray_500)

    card_bottom = card_margin
    c.setStrokeColor(gray_300)
    c.setLineWidth(0.8)
    c.rect(card_x, card_bottom, card_w, y + card_margin - card_bottom, fill=0, stroke=1)

    if evaluation:
        _draw_evaluation_watermark(c, width, height, F)

    c.showPage()
    c.save()
    return buf.getvalue()


def _enrich_attendance_record(db: Session, record: PayrollAttendanceRecord, organization_id: int) -> dict:
    """Attach employee name/name fields to an AttendanceRecordResponse (scoped to tenant)."""
    employee = _apply_employee_filter(
        db.query(PayrollEmployee).filter(PayrollEmployee.id == record.employee_id),
        organization_id,
    ).first()
    name = getattr(employee, "name", None) if employee else None
    department = getattr(employee, "department", None) if employee else None
    designation = getattr(employee, "designation", None) if employee else None
    return {
        "id": record.id,
        "employee_id": record.employee_id,
        "name": name,
        "department": department,
        "designation": designation,
        "date": record.date,
        "check_in": record.check_in,
        "check_out": record.check_out,
        "status": record.status,
        "leave_type": record.leave_type,
        "hours": record.hours,
        "rewards": record.rewards,
        "bonus": record.bonus,
        "other_compensation": record.other_compensation,
        "notes": record.notes,
    }


def _normalize_name(s: str) -> str:
    """Collapse whitespace and lowercase for comparison."""
    import re
    return re.sub(r"\s+", " ", s.strip().lower())


# ── Attendance ↔ Leave Sync Helpers ──────────────────────────────────


def _sync_attendance_to_leave(
    db: Session,
    employee_id: int,
    date_val: date,
    status: str,
    leave_type: Optional[str],
    is_half_day: bool,
    organization_id: int,
) -> Optional[int]:
    """Sync a single attendance record to the Leaves module.

    Returns the PayrollLeaveRequest id if one was created/updated, else None.
    No-op for present/absent/holiday/weekend statuses.
    """
    if status not in ("leave",):
        return None

    resolved_leave_type = _resolve_leave_type(leave_type, is_half_day)
    if not resolved_leave_type:
        return None

    existing = _find_matching_leave_request(db, employee_id, date_val, organization_id)

    if existing:
        return existing.id

    leave_req = PayrollLeaveRequest(
        organization_id=organization_id,
        employee_id=employee_id,
        leave_type=resolved_leave_type,
        start_date=date_val,
        end_date=date_val,
        days=1,
        reason="Auto-created from attendance",
        status="approved",
    )
    from app.core.code_generation import generate_business_code
    leave_req.request_code = generate_business_code(db, organization_id, "LV", PayrollLeaveRequest, "request_code")
    db.add(leave_req)
    db.flush()

    _update_leave_balance(db, employee_id, resolved_leave_type, organization_id)

    try:
        log_activity(db, organization_id,
            f"Leave auto-created from attendance: emp={employee_id}, type={resolved_leave_type}, date={date_val}.",
            ActivityStatus.INFO)
    except Exception:
        pass

    return leave_req.id


def _sync_attendance_update_to_leave(
    db: Session,
    record: PayrollAttendanceRecord,
    organization_id: int,
) -> None:
    """When attendance is updated, sync the change to linked leave request."""
    old_status = record.status
    old_leave_type = record.leave_type
    old_is_half_day = record.is_half_day
    leave_req_id = record.leave_request_id

    if leave_req_id and old_status != "leave":
        record.leave_request_id = None
        db.flush()
        _maybe_remove_leave_request(db, leave_req_id, organization_id)
        return

    if old_status == "leave":
        resolved = _resolve_leave_type(old_leave_type, old_is_half_day)
        if leave_req_id:
            _update_existing_leave_request(db, leave_req_id, resolved, organization_id)
        else:
            new_id = _sync_attendance_to_leave(
                db, record.employee_id, record.date, old_status, old_leave_type, old_is_half_day, organization_id,
            )
            if new_id:
                record.leave_request_id = new_id


def _resolve_leave_type(leave_type: Optional[str], is_half_day: bool) -> Optional[str]:
    """Map attendance leave_type + is_half_day to PayrollLeaveRequest leave_type.

    Falls back to "unpaid" when no explicit type is set (or an unrecognized
    value like "lop" is passed), matching the Attendance page's own display
    convention where a missing leave_type is shown as an unpaid leave. This
    ensures every "leave" status always produces a matching PayrollLeaveRequest
    instead of silently skipping the Leave Management sync.
    """
    if is_half_day:
        return leave_type or "unpaid"
    if leave_type in ("paid", "unpaid", "sick", "casual", "compOff"):
        return leave_type
    return "unpaid"


def _backfill_orphaned_leave_syncs(db: Session, organization_id: int) -> int:
    """Create missing PayrollLeaveRequest rows for attendance records marked
    "leave" that were never synced — e.g. records saved before
    _resolve_leave_type() defaulted a blank leave_type to "unpaid", which used
    to silently skip the sync. Idempotent (matches existing requests via
    _find_matching_leave_request), so it's safe to call on every fetch.
    """
    # with_for_update() serializes concurrent callers on Postgres: two page-load
    # requests hitting this at once would otherwise both see the same
    # not-yet-linked row and each create their own PayrollLeaveRequest for it,
    # producing duplicates. Postgres re-checks the WHERE clause once a lock is
    # released, so the second caller correctly sees the row as no longer
    # orphaned. SQLite (dev fallback) silently ignores this clause; its
    # coarser whole-database write lock is the only guard there.
    orphans = db.query(PayrollAttendanceRecord).filter(
        PayrollAttendanceRecord.organization_id == organization_id,
        PayrollAttendanceRecord.status == "leave",
        PayrollAttendanceRecord.leave_request_id.is_(None),
    ).with_for_update().all()
    if not orphans:
        return 0

    synced = 0
    for rec in orphans:
        if rec.leave_request_id:
            continue
        req_id = _sync_attendance_to_leave(
            db, rec.employee_id, rec.date, rec.status, rec.leave_type, rec.is_half_day, organization_id,
        )
        if req_id:
            rec.leave_request_id = req_id
            synced += 1

    if synced:
        db.commit()
    return synced


def _dedupe_auto_created_leave_requests(db: Session, organization_id: int) -> int:
    """Merge duplicate auto-created leave requests for the same employee +
    type + date range. These can only arise from the backfill race above (now
    closed) creating more than one request before either committed. Keeps the
    oldest row, re-links any attendance records pointing at a duplicate, and
    deletes the rest. Idempotent — safe to call on every fetch."""
    rows = db.query(PayrollLeaveRequest).filter(
        PayrollLeaveRequest.organization_id == organization_id,
        PayrollLeaveRequest.reason == "Auto-created from attendance",
    ).order_by(PayrollLeaveRequest.id.asc()).all()

    groups: dict[tuple, list] = {}
    for r in rows:
        key = (r.employee_id, r.leave_type, r.start_date, r.end_date)
        groups.setdefault(key, []).append(r)

    removed = 0
    for group in groups.values():
        if len(group) < 2:
            continue
        keeper, *dupes = group
        for dup in dupes:
            db.query(PayrollAttendanceRecord).filter(
                PayrollAttendanceRecord.leave_request_id == dup.id,
            ).update({"leave_request_id": keeper.id}, synchronize_session=False)
            db.delete(dup)
            removed += 1

    if removed:
        db.commit()
    return removed


def _recompute_leave_balances_used(db: Session, organization_id: int) -> None:
    """Recompute each employee's per-type "used" day count from approved
    PayrollLeaveRequest rows — the authoritative source — instead of trusting
    it to have been correctly incremented in place elsewhere. Cheap, and safe
    to call on every Leave Management fetch.

    Also seeds a PayrollLeaveAllocation row (default totals matching the
    frontend's own LEAVE_TYPES fallback: paid 20 / unpaid 10 / sick 12 /
    compOff 5) for any employee who doesn't have one yet — without it, there
    is nothing for the "used" recompute below to write into, and the Leave
    Management page silently falls back to displaying frontend-only defaults
    for every employee.
    """
    DEFAULT_LEAVE_TOTALS = {"paid": 20, "unpaid": 10, "sick": 12, "compOff": 5}

    allocations = db.query(PayrollLeaveAllocation).filter(
        PayrollLeaveAllocation.organization_id == organization_id,
    ).all()

    existing_emp_ids = {a.employee_id for a in allocations}
    all_emp_ids = {
        row.id for row in db.query(PayrollEmployee.id).filter(
            PayrollEmployee.organization_id == organization_id,
        ).all()
    }
    missing_emp_ids = all_emp_ids - existing_emp_ids
    dirty = bool(missing_emp_ids)
    if missing_emp_ids:
        for emp_id in missing_emp_ids:
            alloc = PayrollLeaveAllocation(
                organization_id=organization_id,
                employee_id=emp_id,
                leave_balances={lt: {"used": 0, "total": total} for lt, total in DEFAULT_LEAVE_TOTALS.items()},
            )
            db.add(alloc)
            allocations.append(alloc)
        db.flush()

    if not allocations:
        return

    approved = db.query(
        PayrollLeaveRequest.employee_id,
        PayrollLeaveRequest.leave_type,
        sa_func.sum(PayrollLeaveRequest.days),
    ).filter(
        PayrollLeaveRequest.organization_id == organization_id,
        PayrollLeaveRequest.status == "approved",
    ).group_by(
        PayrollLeaveRequest.employee_id, PayrollLeaveRequest.leave_type,
    ).all()

    used_by_emp: dict[int, dict[str, int]] = {}
    for emp_id, lt, total_days in approved:
        used_by_emp.setdefault(emp_id, {})[lt] = int(total_days or 0)

    for alloc in allocations:
        emp_used = used_by_emp.get(alloc.employee_id, {})
        updated = copy.deepcopy(alloc.leave_balances or {})
        row_changed = False
        for lt, used_days in emp_used.items():
            if lt in updated and updated[lt].get("used", 0) != used_days:
                updated[lt]["used"] = used_days
                row_changed = True
        if row_changed:
            alloc.leave_balances = updated
            dirty = True

    if dirty:
        db.commit()


def _find_matching_leave_request(
    db: Session,
    employee_id: int,
    date_val: date,
    organization_id: int,
) -> Optional[PayrollLeaveRequest]:
    """Find an existing approved leave request covering this employee+date."""
    return db.query(PayrollLeaveRequest).filter(
        PayrollLeaveRequest.organization_id == organization_id,
        PayrollLeaveRequest.employee_id == employee_id,
        PayrollLeaveRequest.start_date <= date_val,
        PayrollLeaveRequest.end_date >= date_val,
        PayrollLeaveRequest.status == "approved",
    ).first()


def _update_leave_balance(
    db: Session,
    employee_id: int,
    leave_type: str,
    organization_id: int,
) -> None:
    """Deduct one day from leave balance. Prevents negative balance."""
    alloc = db.query(PayrollLeaveAllocation).filter(
        PayrollLeaveAllocation.organization_id == organization_id,
        PayrollLeaveAllocation.employee_id == employee_id,
    ).first()
    if not alloc:
        return
    # Deep-copy before mutating: `leave_balances` is a plain JSON column (no
    # MutableDict tracking), so reassigning the SAME dict object SQLAlchemy
    # already has loaded is a no-op — it never gets flushed to the DB.
    balances = copy.deepcopy(alloc.leave_balances or {})
    if leave_type not in balances:
        return
    used = balances[leave_type].get("used", 0)
    total = balances[leave_type].get("total", 0)
    if used < total:
        balances[leave_type]["used"] = used + 1
        alloc.leave_balances = balances


def _restore_leave_balance(
    db: Session,
    employee_id: int,
    leave_type: str,
    organization_id: int,
) -> None:
    """Restore one day from leave balance (attendance reverted from leave)."""
    alloc = db.query(PayrollLeaveAllocation).filter(
        PayrollLeaveAllocation.organization_id == organization_id,
        PayrollLeaveAllocation.employee_id == employee_id,
    ).first()
    if not alloc:
        return
    balances = copy.deepcopy(alloc.leave_balances or {})
    if leave_type not in balances:
        return
    used = balances[leave_type].get("used", 0)
    if used > 0:
        balances[leave_type]["used"] = used - 1
        alloc.leave_balances = balances


def _maybe_remove_leave_request(db: Session, leave_request_id: int, organization_id: int) -> None:
    """Remove an auto-created leave request if no attendance records link to it."""
    if not leave_request_id:
        return
    linked = db.query(PayrollAttendanceRecord).filter(
        PayrollAttendanceRecord.leave_request_id == leave_request_id,
    ).first()
    if linked:
        return
    req = db.query(PayrollLeaveRequest).filter(
        PayrollLeaveRequest.id == leave_request_id,
        PayrollLeaveRequest.organization_id == organization_id,
    ).first()
    if req and req.reason == "Auto-created from attendance":
        lt = req.leave_type
        db.delete(req)
        _restore_leave_balance(db, req.employee_id, lt, organization_id)


def _update_existing_leave_request(
    db: Session,
    leave_request_id: int,
    new_leave_type: Optional[str],
    organization_id: int,
) -> None:
    """Update leave type on an existing auto-created leave request."""
    if not leave_request_id:
        return
    req = db.query(PayrollLeaveRequest).filter(
        PayrollLeaveRequest.id == leave_request_id,
        PayrollLeaveRequest.organization_id == organization_id,
    ).first()
    if req and req.reason == "Auto-created from attendance" and new_leave_type:
        old_lt = req.leave_type
        req.leave_type = new_leave_type
        if old_lt != new_leave_type:
            _restore_leave_balance(db, req.employee_id, old_lt, organization_id)
            _update_leave_balance(db, req.employee_id, new_leave_type, organization_id)


def _sync_leave_to_attendance(
    db: Session,
    leave_request: PayrollLeaveRequest,
    organization_id: int,
) -> None:
    """Create/update attendance records for a leave request's date range."""
    current = date.today()
    d = leave_request.start_date
    while d <= leave_request.end_date:
        existing = db.query(PayrollAttendanceRecord).filter(
            PayrollAttendanceRecord.organization_id == organization_id,
            PayrollAttendanceRecord.employee_id == leave_request.employee_id,
            PayrollAttendanceRecord.date == d,
        ).first()
        if existing:
            old_status = existing.status
            old_leave_type = existing.leave_type
            existing.status = "leave"
            existing.leave_type = leave_request.leave_type
            existing.leave_request_id = leave_request.id
            if old_status == "leave" and old_leave_type != leave_request.leave_type:
                _restore_leave_balance(db, existing.employee_id, old_leave_type, organization_id)
                _update_leave_balance(db, existing.employee_id, leave_request.leave_type, organization_id)
        else:
            rec = PayrollAttendanceRecord(
                organization_id=organization_id,
                employee_id=leave_request.employee_id,
                date=d,
                status="leave",
                leave_type=leave_request.leave_type,
                leave_request_id=leave_request.id,
            )
            db.add(rec)
        d += timedelta(days=1)
    db.flush()


def _remove_linked_attendance(
    db: Session,
    leave_request: PayrollLeaveRequest,
    organization_id: int,
) -> None:
    """Revert attendance records linked to a rejected/cancelled leave request."""
    records = db.query(PayrollAttendanceRecord).filter(
        PayrollAttendanceRecord.organization_id == organization_id,
        PayrollAttendanceRecord.employee_id == leave_request.employee_id,
        PayrollAttendanceRecord.leave_request_id == leave_request.id,
    ).all()
    for rec in records:
        old_lt = rec.leave_type
        rec.status = "absent"
        rec.leave_type = None
        rec.leave_request_id = None
        if old_lt:
            _restore_leave_balance(db, rec.employee_id, old_lt, organization_id)
    db.flush()


def bulk_save_attendance(db: Session, data: BulkAttendanceRequest, organization_id: int) -> dict:
    """Upsert attendance records for a date. Matches on (employee_id, date)
    to update existing records instead of creating duplicates.

    Returns a dict with saved records and skipped-row details so the frontend
    can surface exactly what succeeded and what didn't."""
    # ── 1. Single query: fetch all payroll employees for this org ──────
    emp_rows = db.query(
        PayrollEmployee.id,
        PayrollEmployee.name,
        PayrollEmployee.employee_code,
        PayrollEmployee.status,
    ).filter(PayrollEmployee.organization_id == organization_id).all()

    valid_emp_ids = {row.id for row in emp_rows}
    inactive_emp_ids = {row.id for row in emp_rows if row.status and row.status.lower() != "active"}

    # code→id (e.g. "ZOI_3E00001"→5) for employee_code resolution
    code_to_id: dict[str, int] = {}
    # id→normalized_name for post-resolution cross-validation
    id_to_normalized_name: dict[int, str] = {}
    for row in emp_rows:
        if row.employee_code:
            code_to_id[row.employee_code.strip()] = row.id
        id_to_normalized_name[row.id] = _normalize_name((row.name or "").strip())

    # name→id (normalised full name)
    name_to_id: dict[str, int] = {}
    # first token→[ids], last token→[ids] for fuzzy fallback (tokens derived
    # from the single `name` field — no separate first/last columns anymore)
    first_name_to_ids: dict[str, list[int]] = {}
    last_name_to_ids: dict[str, list[int]] = {}
    # normalized full name→id (for reversed-name matching)
    all_names_normalized: dict[str, int] = {}

    for row in emp_rows:
        full = (row.name or "").strip()
        parts = full.split()
        fn = parts[0] if parts else ""
        ln = parts[-1] if len(parts) > 1 else ""
        full_n = _normalize_name(full)
        if full_n:
            name_to_id[full_n] = row.id
            all_names_normalized[full_n] = row.id
        # Also index reversed token order (e.g. "Shaik Ashraf" for "Ashraf Shaik")
        if len(parts) > 1:
            reversed_n = _normalize_name(" ".join([parts[-1]] + parts[:-1]))
            if reversed_n and reversed_n != full_n:
                all_names_normalized[reversed_n] = row.id
        if fn.lower() in first_name_to_ids:
            first_name_to_ids[fn.lower()].append(row.id)
        else:
            first_name_to_ids[fn.lower()] = [row.id]
        if ln.lower() in last_name_to_ids:
            last_name_to_ids[ln.lower()].append(row.id)
        else:
            last_name_to_ids[ln.lower()] = [row.id]

    # ── 2. Resolve employee IDs & build upsert payloads ────────────────
    to_upsert: list[dict] = []          # dicts with employee_id, date_val, mapped fields
    skipped_details: list[dict] = []

    for item in data.records:
        payload = item.model_dump()
        employee_id = payload.pop("employeeId")
        record_name = (payload.pop("name", None) or "").strip()
        date_val = payload.pop("date")

        # --- resolve employee_id ---
        resolved = False
        if employee_id and employee_id in valid_emp_ids:
            resolved = True
        elif employee_id and isinstance(employee_id, str) and employee_id.strip() in code_to_id:
            employee_id = code_to_id[employee_id.strip()]
            resolved = True
        elif employee_id and isinstance(employee_id, str) and employee_id.strip().lower() in {k.lower(): v for k, v in code_to_id.items()}:
            for k, v in code_to_id.items():
                if k.lower() == employee_id.strip().lower():
                    employee_id = v
                    resolved = True
                    break
        elif record_name:
            norm = _normalize_name(record_name)
            # 1. exact full-name match (first last)
            rid = name_to_id.get(norm)
            if rid:
                employee_id = rid
                resolved = True
            else:
                # 2. reversed order (last first)
                rid = all_names_normalized.get(norm)
                if rid:
                    employee_id = rid
                    resolved = True
                else:
                    # 3. first-name only (unambiguous)
                    first_part = record_name.split()[0].lower() if record_name else ""
                    candidates = first_name_to_ids.get(first_part, [])
                    if len(candidates) == 1:
                        employee_id = candidates[0]
                        resolved = True
                    else:
                        # 4. last-name only (unambiguous)
                        last_part = record_name.split()[-1].lower() if record_name else ""
                        ln_candidates = last_name_to_ids.get(last_part, [])
                        if len(ln_candidates) == 1:
                            employee_id = ln_candidates[0]
                            resolved = True

        if not resolved:
            skipped_details.append({
                "rowName": record_name or None,
                "rowId": employee_id if employee_id else None,
                "reason": "No matching employee found",
                "date": date_val,
            })
            continue

        # ── Check: is the employee active? ──
        if employee_id and employee_id in inactive_emp_ids:
            skipped_details.append({
                "rowName": record_name or None,
                "rowId": employee_id,
                "reason": "Employee is not active",
                "date": date_val,
            })
            continue

        # ── Cross-validate: does the uploaded name match the resolved employee? ──
        if record_name and employee_id in id_to_normalized_name:
            resolved_name_n = id_to_normalized_name[employee_id]
            uploaded_name_n = _normalize_name(record_name)
            if resolved_name_n and uploaded_name_n and resolved_name_n != uploaded_name_n:
                uploaded_words = set(uploaded_name_n.split())
                resolved_words = set(resolved_name_n.split())
                # Allow partial matches (e.g. first-name-only uploads) — only
                # flag when NO meaningful word (≥3 chars) overlaps.
                overlap = [w for w in uploaded_words if len(w) >= 3 and w in resolved_words]
                if not overlap:
                    skipped_details.append({
                        "rowName": record_name or None,
                        "rowId": employee_id,
                        "reason": f"Name mismatch: employee {employee_id} is \"{resolved_name_n}\", not \"{record_name}\"",
                        "date": date_val,
                    })
                    continue

        is_half_day = payload.pop("isHalfDay", False)
        to_upsert.append({
            "employee_id": employee_id,
            "date_val": date_val,
            "check_in": payload.pop("checkIn", None),
            "check_out": payload.pop("checkOut", None),
            "status": payload.pop("status", "present"),
            "leave_type": payload.pop("leaveType", None),
            "is_half_day": is_half_day,
            "hours": payload.pop("hours", None),
            "rewards": payload.pop("rewards", Decimal("0")),
            "bonus": payload.pop("bonus", Decimal("0")),
            "other_compensation": payload.pop("otherCompensation", Decimal("0")),
            "notes": payload.pop("notes", None),
        })

    if not to_upsert:
        return {
            "saved": 0,
            "skipped": len(skipped_details),
            "skippedDetails": skipped_details,
            "records": [],
        }

    # ── 3. Batch-fetch existing records (single query instead of N) ────
    emp_date_pairs = {(r["employee_id"], r["date_val"]) for r in to_upsert}
    existing_records = db.query(PayrollAttendanceRecord).filter(
        PayrollAttendanceRecord.organization_id == organization_id,
        tuple_(
            PayrollAttendanceRecord.employee_id,
            PayrollAttendanceRecord.date,
        ).in_(emp_date_pairs),
    ).all()
    existing_map: dict[tuple, PayrollAttendanceRecord] = {
        (r.employee_id, r.date): r for r in existing_records
    }

    results = []
    sync_actions: list[dict] = []
    for r in to_upsert:
        key = (r["employee_id"], r["date_val"])
        mapped = {k: v for k, v in r.items() if k not in ("employee_id", "date_val")}
        existing = existing_map.get(key)
        if existing:
            prev_status = existing.status
            prev_leave_type = existing.leave_type
            for field, value in mapped.items():
                setattr(existing, field, value)
            results.append(existing)
            if prev_status != existing.status or prev_leave_type != existing.leave_type:
                sync_actions.append({
                    "record": existing,
                    "prev_status": prev_status,
                    "prev_leave_type": prev_leave_type,
                })
        else:
            rec = PayrollAttendanceRecord(
                organization_id=organization_id,
                employee_id=r["employee_id"],
                date=r["date_val"],
                **mapped,
            )
            db.add(rec)
            results.append(rec)
            sync_actions.append({
                "record": rec,
                "prev_status": None,
                "prev_leave_type": None,
            })

    db.flush()

    for sa in sync_actions:
        rec = sa["record"]
        prev_status = sa["prev_status"]
        prev_leave_type = sa["prev_leave_type"]
        if rec.status == "leave" and prev_status != "leave":
            req_id = _sync_attendance_to_leave(
                db, rec.employee_id, rec.date, rec.status, rec.leave_type, rec.is_half_day, organization_id,
            )
            if req_id:
                rec.leave_request_id = req_id
        elif rec.status == "leave" and prev_status == "leave" and rec.leave_type != prev_leave_type:
            _sync_attendance_update_to_leave(db, rec, organization_id)
        elif prev_status == "leave" and rec.status != "leave":
            _maybe_remove_leave_request(db, rec.leave_request_id, organization_id)
            rec.leave_request_id = None

    # Ids are assigned by the flush above; read them before commit expires
    # the objects, then reload everything in a few batched queries instead of
    # one db.refresh() round trip per row (thousands of rows on a bulk save
    # against a remote database used to run past the proxy timeout).
    result_ids = [r.id for r in results]
    db.commit()
    fresh: dict[int, PayrollAttendanceRecord] = {}
    for i in range(0, len(result_ids), 1000):
        chunk = result_ids[i:i + 1000]
        for row in db.query(PayrollAttendanceRecord).filter(PayrollAttendanceRecord.id.in_(chunk)).all():
            fresh[row.id] = row
    results = [fresh[i] for i in result_ids if i in fresh]

    # ── 4. Batch-enrich employee details (single query instead of N) ──
    all_emp_ids = list({r.employee_id for r in results})
    emp_detail_rows = db.query(PayrollEmployee).filter(
        PayrollEmployee.id.in_(all_emp_ids),
    ).all()
    emp_detail_map = {e.id: e for e in emp_detail_rows}

    enriched = []
    for r in results:
        emp = emp_detail_map.get(r.employee_id)
        name = getattr(emp, "name", None) if emp else None
        enriched.append({
            "id": r.id,
            "employee_id": r.employee_id,
            "name": name,
            "department": getattr(emp, "department", None) if emp else None,
            "designation": getattr(emp, "designation", None) if emp else None,
            "date": r.date,
            "check_in": r.check_in,
            "check_out": r.check_out,
            "status": r.status,
            "leave_type": r.leave_type,
            "is_half_day": r.is_half_day,
            "leave_request_id": r.leave_request_id,
            "hours": r.hours,
            "rewards": r.rewards,
            "bonus": r.bonus,
            "other_compensation": r.other_compensation,
            "notes": r.notes,
        })

    return {
        "saved": len(enriched),
        "skipped": len(skipped_details),
        "skippedDetails": skipped_details,
        "records": enriched,
    }


def import_attendance_xlsx(
    db: Session,
    organization_id: int,
    file_source: Any,
    chunk_size: int = 500,
    skip_duplicates: bool = False,
) -> dict:
    """Stream XLSX attendance file and bulk upsert records (Phases 2.3, 2.4, 2.5)."""
    from app.modules.payroll.attendance_importer import import_attendance_from_stream
    return import_attendance_from_stream(
        db, organization_id, file_source, chunk_size=chunk_size, skip_duplicates=skip_duplicates
    )


def _attendance_records_base_query(
    db: Session,
    organization_id: int,
    *,
    start_date: Optional[date] = None,
    end_date: Optional[date] = None,
    employee_id: Optional[int] = None,
    with_employee_columns: bool = True,
):
    """Shared filtered query for attendance reads.

    Employee name/department/designation come from an outer join so an
    attendance row survives an employee record that has since been removed.
    Pass with_employee_columns=False for the COUNT path: counting the joined
    projection would wrap the whole select in a subquery, and the join cannot
    duplicate attendance rows (employee_id is the join key) so it is not needed
    to get an accurate total.
    """
    columns = (
        (
            PayrollAttendanceRecord,
            PayrollEmployee.name,
            PayrollEmployee.department,
            PayrollEmployee.designation,
        )
        if with_employee_columns
        else (PayrollAttendanceRecord,)
    )
    query = db.query(*columns).outerjoin(
        PayrollEmployee,
        (PayrollAttendanceRecord.employee_id == PayrollEmployee.id) &
        (PayrollEmployee.organization_id == organization_id)
    ).filter(
        PayrollAttendanceRecord.organization_id == organization_id
    )
    if start_date:
        query = query.filter(PayrollAttendanceRecord.date >= start_date)
    if end_date:
        query = query.filter(PayrollAttendanceRecord.date <= end_date)
    if employee_id:
        query = query.filter(PayrollAttendanceRecord.employee_id == employee_id)
    return query


def _attendance_row_to_dict(record, name, department, designation) -> dict:
    return {
        "id": record.id,
        "employee_id": record.employee_id,
        "name": name,
        "department": department,
        "designation": designation,
        "date": record.date,
        "check_in": record.check_in,
        "check_out": record.check_out,
        "status": record.status,
        "leave_type": record.leave_type,
        "is_half_day": record.is_half_day,
        "leave_request_id": record.leave_request_id,
        "hours": record.hours,
        "rewards": record.rewards,
        "bonus": record.bonus,
        "other_compensation": record.other_compensation,
        "notes": record.notes,
    }


def get_attendance_records(
    db: Session,
    organization_id: int,
    *,
    start_date: Optional[date] = None,
    end_date: Optional[date] = None,
    employee_id: Optional[int] = None,
    limit: int = 1000,
    offset: int = 0,
) -> List[dict]:
    """Fetch attendance records with optional date range and employee filter.

    Paginated: limit/offset default to 1000/0 for backwards compatibility.

    Returns a bare list, so the caller cannot tell a short page from the end of
    the data. Callers that need to page should use
    get_attendance_records_page(), which also reports the total.
    """
    query = _attendance_records_base_query(
        db, organization_id,
        start_date=start_date, end_date=end_date, employee_id=employee_id,
    )
    query = query.order_by(PayrollAttendanceRecord.date.desc())
    if limit > 0:
        query = query.limit(limit)
    if offset > 0:
        query = query.offset(offset)

    return [
        _attendance_row_to_dict(record, name, department, designation)
        for record, name, department, designation in query.all()
    ]


def get_attendance_records_page(
    db: Session,
    organization_id: int,
    *,
    start_date: Optional[date] = None,
    end_date: Optional[date] = None,
    employee_id: Optional[int] = None,
    limit: int = 100,
    offset: int = 0,
) -> dict:
    """Page through attendance records with an exact total.

    Returns {items, total, limit, offset, hasMore}. `total` is a COUNT over the
    same predicates, so a client can show "showing 100 of 4,312" and know
    whether another fetch is worth making, instead of inferring the end of the
    data from a short page.
    """
    total = _attendance_records_base_query(
        db, organization_id,
        start_date=start_date, end_date=end_date, employee_id=employee_id,
        with_employee_columns=False,
    ).count()

    # Fetch one extra row so hasMore is exact without a second COUNT query:
    # LIMIT n+1 answers "is there more" directly.
    rows = (
        _attendance_records_base_query(
            db, organization_id,
            start_date=start_date, end_date=end_date, employee_id=employee_id,
        )
        .order_by(PayrollAttendanceRecord.date.desc(), PayrollAttendanceRecord.id.desc())
        .limit(limit + 1)
        .offset(offset)
        .all()
    )
    has_more = len(rows) > limit
    page = rows[:limit]

    # Oldest/newest date in the filtered set, so a client paging through rows
    # can still report the true span of the range instead of the span of
    # whichever page it happens to hold.
    span = (
        _attendance_records_base_query(
            db, organization_id,
            start_date=start_date, end_date=end_date, employee_id=employee_id,
            with_employee_columns=False,
        )
        .with_entities(
            sa_func.min(PayrollAttendanceRecord.date),
            sa_func.max(PayrollAttendanceRecord.date),
        )
        .one()
    )
    first_date, last_date = span if span else (None, None)

    return {
        "items": [
            _attendance_row_to_dict(record, name, department, designation)
            for record, name, department, designation in page
        ],
        "total": total,
        "limit": limit,
        "offset": offset,
        "hasMore": has_more,
        "firstDate": first_date,
        "lastDate": last_date,
    }


def _parse_attendance_hours(raw) -> float:
    """Coerce the text `hours` column to a number, treating junk as 0.

    `hours` is String(10) holding things like "8" / "8.5", and it is optional.
    The previous client-side aggregation did `Number(rec.hours || 0)`, which
    turns "N/A" into NaN and poisons the whole running total. Anything that
    is not a finite number is treated as 0 here instead, so one bad row cannot
    corrupt an employee's hours.
    """
    if raw is None:
        return 0.0
    try:
        value = float(str(raw).strip())
    except (TypeError, ValueError):
        return 0.0
    return value if value == value and value not in (float("inf"), float("-inf")) else 0.0


_EMPTY_ATTENDANCE_TOTALS = {
    "totalDays": 0, "present": 0, "absent": 0, "leave": 0,
    "unpaidLeaves": 0, "paidLeaves": 0,
}


def get_attendance_summary_by_employee(
    db: Session,
    organization_id: int,
    *,
    start_date: Optional[date] = None,
    end_date: Optional[date] = None,
    search: Optional[str] = None,
    limit: int = 100,
    offset: int = 0,
) -> dict:
    """Per-employee attendance aggregates over a date range, paged.

    This exists so the Summary tab no longer has to download every attendance
    row in order to count days. Counts are aggregated by the database; the
    remaining fields need grouping over *distinct* values rather than rows, so
    they are grouped in SQL by (employee_id, value) and finished in Python.
    That keeps the work bounded by the number of distinct check-in times and
    hour strings per employee instead of by the number of attendance rows,
    and avoids casting the text `hours` column in SQL -- `CAST('' AS NUMERIC)`
    raises on Postgres while silently yielding 0 on SQLite, so a cast here
    would be a portability landmine.

    Semantics deliberately mirror the previous client-side aggregation:
      * future-dated rows are excluded, so scheduled attendance never counts
        toward completed stats;
      * leaveType "paid" counts as paid leave; "unpaid" or missing/legacy
        (null) counts as unpaid; sick/casual count toward Leave Days only;
      * "totalDays" counts every recorded day, whatever the status;
      * avgCheckIn/avgCheckOut are the MOST FREQUENT recorded times, not
        arithmetic means;
      * avgBreak is always 0 -- payroll_attendance_records has no
        break_minutes column, so there is no data source for it. The previous
        client code read a field that never existed on the record and rendered
        0; that is preserved rather than invented.
    """
    today = date.today()

    base = _attendance_records_base_query(
        db, organization_id,
        start_date=start_date, end_date=end_date, with_employee_columns=False,
    ).filter(PayrollAttendanceRecord.date <= today)

    # Free-text employee search has to happen here, not in the browser, or it
    # would only ever match the page that happens to be loaded.
    search = (search or "").strip()
    if search:
        like = f"%{search}%"
        matching_ids = [
            e.id
            for e in db.query(PayrollEmployee.id)
            .filter(
                PayrollEmployee.organization_id == organization_id,
                or_(
                    PayrollEmployee.name.ilike(like),
                    PayrollEmployee.department.ilike(like),
                ),
            )
            .all()
        ]
        if not matching_ids:
            return {
                "items": [], "total": 0, "limit": limit, "offset": offset,
                "hasMore": False, "totals": _EMPTY_ATTENDANCE_TOTALS,
            }
        base = base.filter(PayrollAttendanceRecord.employee_id.in_(matching_ids))

    def _grouped(*extra):
        cols = [PayrollAttendanceRecord.employee_id, *extra]
        return base.with_entities(*cols).group_by(*cols)

    def _counts_for(emp_ids):
        """Day/status counts for a specific set of employees."""
        if not emp_ids:
            return {}
        rows = (
            base
            .with_entities(
                PayrollAttendanceRecord.employee_id,
                sa_func.count().label("days"),
                sa_func.sum(
                    sa_case(
                        (PayrollAttendanceRecord.status == "present", 1), else_=0,
                    )
                ).label("present"),
                sa_func.sum(
                    sa_case(
                        (PayrollAttendanceRecord.status == "absent", 1), else_=0,
                    )
                ).label("absent"),
                sa_func.sum(
                    sa_case(
                        (PayrollAttendanceRecord.status == "leave", 1), else_=0,
                    )
                ).label("leave"),
                sa_func.sum(
                    sa_case(
                        (
                            sa_and_(
                                PayrollAttendanceRecord.status == "leave",
                                # "paid" is deliberately absent: the old client-side
                                # logic was an if/else-if chain, so a paid day was
                                # counted as paid and never also as unpaid.
                                or_(
                                    PayrollAttendanceRecord.leave_type.is_(None),
                                    PayrollAttendanceRecord.leave_type == "unpaid",
                                ),
                            ),
                            1,
                        ),
                        else_=0,
                    )
                ).label("unpaid"),
                sa_func.sum(
                    sa_case(
                        (
                            sa_and_(
                                PayrollAttendanceRecord.status == "leave",
                                PayrollAttendanceRecord.leave_type == "paid",
                            ),
                            1,
                        ),
                        else_=0,
                    )
                ).label("paid"),
            )
            .filter(PayrollAttendanceRecord.employee_id.in_(emp_ids))
            .group_by(PayrollAttendanceRecord.employee_id)
            .all()
        )
        return {
            r.employee_id: {
                "totalDays": int(r.days or 0),
                "present": int(r.present or 0),
                "absent": int(r.absent or 0),
                "leave": int(r.leave or 0),
                "unpaidLeaves": int(r.unpaid or 0),
                "paidLeaves": int(r.paid or 0),
            }
            for r in rows
        }

    def _counts_for_all():
        """Same counts, summed across every employee in the filtered set.

        Deliberately computed in SQL rather than by summing the page in Python:
        the page is a slice, so summing it would under-report as soon as there
        is a second page.
        """
        row = (
            base
            .with_entities(
                sa_func.count().label("days"),
                sa_func.sum(sa_case(
                    (PayrollAttendanceRecord.status == "present", 1), else_=0,
                )).label("present"),
                sa_func.sum(sa_case(
                    (PayrollAttendanceRecord.status == "absent", 1), else_=0,
                )).label("absent"),
                sa_func.sum(sa_case(
                    (PayrollAttendanceRecord.status == "leave", 1), else_=0,
                )).label("leave"),
                sa_func.sum(sa_case(
                    (
                        sa_and_(
                            PayrollAttendanceRecord.status == "leave",
                            or_(
                                PayrollAttendanceRecord.leave_type.is_(None),
                                PayrollAttendanceRecord.leave_type == "unpaid",
                            ),
                        ),
                        1,
                    ),
                    else_=0,
                )).label("unpaid"),
                sa_func.sum(sa_case(
                    (
                        sa_and_(
                            PayrollAttendanceRecord.status == "leave",
                            PayrollAttendanceRecord.leave_type == "paid",
                        ),
                        1,
                    ),
                    else_=0,
                )).label("paid"),
            )
            .one()
        )
        if row is None:
            return dict(_EMPTY_ATTENDANCE_TOTALS)
        return {
            "totalDays": int(row.days or 0),
            "present": int(row.present or 0),
            "absent": int(row.absent or 0),
            "leave": int(row.leave or 0),
            "unpaidLeaves": int(row.unpaid or 0),
            "paidLeaves": int(row.paid or 0),
        }

    # The employee list is the paging unit, so the page has to be chosen in SQL.
    employee_ids = [
        row.employee_id
        for row in (
            _grouped()
            .order_by(PayrollAttendanceRecord.employee_id)
            .limit(limit + 1)
            .offset(offset)
            .all()
        )
    ]
    has_more = len(employee_ids) > limit
    employee_ids = employee_ids[:limit]
    total_employees = _grouped().count()

    # Org-wide totals for the whole filtered set, not just this page. The
    # Summary tab's stat cards sum across every employee, so summing only the
    # loaded page would quietly under-report. This is an aggregate, so it stays
    # cheap in the database -- the cost being avoided is shipping thousands of
    # rows to the browser and counting them there.
    totals = _counts_for_all()

    if not employee_ids:
        return {
            "items": [], "total": total_employees, "limit": limit,
            "offset": offset, "hasMore": False, "totals": totals,
        }

    people = {
        e.id: e
        for e in db.query(PayrollEmployee).filter(
            PayrollEmployee.organization_id == organization_id,
            PayrollEmployee.id.in_(employee_ids),
        ).all()
    }
    counts = _counts_for(employee_ids)

    # Hours: sum over DISTINCT hour strings, not over every attendance row.
    hours_by_emp: dict = {eid: 0.0 for eid in employee_ids}
    for eid, raw, n in (
        base
        .with_entities(
            PayrollAttendanceRecord.employee_id,
            PayrollAttendanceRecord.hours,
            sa_func.count().label("n"),
        )
        .filter(PayrollAttendanceRecord.employee_id.in_(employee_ids))
        .group_by(PayrollAttendanceRecord.employee_id, PayrollAttendanceRecord.hours)
        .all()
    ):
        hours_by_emp[eid] = hours_by_emp.get(eid, 0.0) + _parse_attendance_hours(raw) * int(n or 0)

    def _modal_times(column):
        """Most frequent non-empty value per employee, ties broken by first
        appearance in (date, id) order so the result is deterministic."""
        winners: dict = {}
        for eid, value, n in (
            base
            .with_entities(
                PayrollAttendanceRecord.employee_id,
                column,
                sa_func.count().label("n"),
            )
            .filter(PayrollAttendanceRecord.employee_id.in_(employee_ids))
            .group_by(PayrollAttendanceRecord.employee_id, column)
            .order_by(PayrollAttendanceRecord.employee_id, sa_func.count().desc())
            .all()
        ):
            if not value:
                continue
            key = int(eid)
            best = winners.get(key)
            if best is None or int(n or 0) > best[0]:
                winners[key] = (int(n or 0), value)
        return {k: v[1] for k, v in winners.items()}

    top_in = _modal_times(PayrollAttendanceRecord.check_in)
    top_out = _modal_times(PayrollAttendanceRecord.check_out)

    items = []
    for eid in employee_ids:
        emp = people.get(eid)
        agg = counts.get(eid, {
            "totalDays": 0, "present": 0, "absent": 0, "leave": 0,
            "unpaidLeaves": 0, "paidLeaves": 0,
        })
        items.append({
            "employeeId": eid,
            "name": getattr(emp, "name", None) or f"Employee {eid}",
            "department": getattr(emp, "department", None) or "",
            "designation": getattr(emp, "designation", None) or "",
            **agg,
            "totalHours": round(hours_by_emp.get(eid, 0.0), 2),
            "avgCheckIn": top_in.get(eid, ""),
            "avgCheckOut": top_out.get(eid, ""),
            "avgBreak": 0,
        })

    return {
        "items": items,
        "total": total_employees,
        "limit": limit,
        "offset": offset,
        "hasMore": has_more,
        "totals": totals,
    }


def clear_attendance_records(
    db: Session,
    organization_id: int,
    start_date: str | None = None,
    end_date: str | None = None,
) -> int:
    """Delete attendance records for the given organization, optionally scoped to a date range.
    Also cleans up orphaned auto-created leave requests."""
    from datetime import date as _date
    q = db.query(PayrollAttendanceRecord).filter(
        PayrollAttendanceRecord.organization_id == organization_id
    )
    if start_date:
        q = q.filter(PayrollAttendanceRecord.date >= _date.fromisoformat(start_date))
    if end_date:
        q = q.filter(PayrollAttendanceRecord.date <= _date.fromisoformat(end_date))

    linked_ids = [r.leave_request_id for r in q.all() if r.leave_request_id]
    deleted = q.delete(synchronize_session=False)

    if linked_ids:
        orphaned = db.query(PayrollLeaveRequest).filter(
            PayrollLeaveRequest.id.in_(linked_ids),
            PayrollLeaveRequest.reason == "Auto-created from attendance",
        ).all()
        for req in orphaned:
            still_linked = db.query(PayrollAttendanceRecord).filter(
                PayrollAttendanceRecord.leave_request_id == req.id,
            ).first()
            if not still_linked:
                db.delete(req)

    db.commit()
    return deleted


def get_attendance_summary(db: Session, organization_id: int) -> dict:
    """Aggregate today's attendance counts."""
    today = date.today()
    records = db.query(PayrollAttendanceRecord).filter(
        PayrollAttendanceRecord.organization_id == organization_id,
        PayrollAttendanceRecord.date == today,
    ).all()
    total = len(records)
    present = sum(1 for r in records if r.status == "present")
    absent = sum(1 for r in records if r.status == "absent")
    leave = sum(1 for r in records if r.status == "leave")
    return {
        "total": total,
        "present": present,
        "absent": absent,
        "leave": leave,
    }


