# Legacy local-disk location for compliance documents. Production stores
# uploads in Cloud Storage via app/core/object_storage.py; this constant is
# kept only so old local-dev rows/paths still resolve.
_COMPLIANCE_DOC_UPLOAD_DIR = _os.environ.get(
    "PAYROLL_COMPLIANCE_DOC_UPLOAD_DIR",
    os.path.join(_os.environ.get("UPLOAD_BASE_DIR", "/tmp/uploads"), "payroll_compliance_documents"),
)


def list_compliance_documents(
    db: Session,
    organization_id: int,
    *,
    country: Optional[str] = None,
) -> List[ComplianceDocument]:
    query = db.query(ComplianceDocument).filter(ComplianceDocument.organization_id == organization_id)
    if country:
        query = query.filter(ComplianceDocument.country == country)
    return query.order_by(ComplianceDocument.uploaded_at.desc()).all()


def delete_compliance_document(db: Session, document_id: int, organization_id: int) -> None:
    from app.core.object_storage import delete_ref

    doc = db.query(ComplianceDocument).filter(
        ComplianceDocument.id == document_id,
        ComplianceDocument.organization_id == organization_id,
    ).first()
    if not doc:
        raise NotFoundException("Compliance document", document_id)

    delete_ref(doc.file_path)

    db.delete(doc)
    db.commit()
    log_activity(db, organization_id, f"Compliance document '{doc.title}' deleted.", ActivityStatus.INFO)


def _ocr_image_file(image_data: bytes) -> str:
    # NOTE: previously this caught every exception (including a missing
    # `pytesseract`/`PIL` package or a missing system `tesseract` binary)
    # and returned "", which was indistinguishable from "OCR ran and found
    # no statutory rates in the image." Letting it raise means
    # upload_compliance_document() now records a real "failed" status +
    # error message instead of silently pretending extraction succeeded.
    import io as _io

    from PIL import Image  # type: ignore
    import pytesseract  # type: ignore

    image = Image.open(_io.BytesIO(image_data))
    try:
        text = pytesseract.image_to_string(image)
    finally:
        image.close()
    return text or ""


def _extract_text_from_uploaded_document(file_ref: str) -> str:
    """Extract raw text from a stored upload. `file_ref` is whatever the
    DB row holds — a gs:// Cloud Storage URI (production) or a local path
    (dev/tests); both resolve to bytes via the object-storage layer."""
    if not file_ref:
        return ""

    from app.core.object_storage import read_bytes

    data = read_bytes(file_ref)

    ext = _os.path.splitext(file_ref)[1].lower()
    if ext == ".txt":
        return data.decode("utf-8", errors="ignore")
    if ext == ".csv":
        return data.decode("utf-8", errors="ignore")
    if ext in {".pdf"}:
        import io as _io

        import pypdf  # type: ignore
        reader = pypdf.PdfReader(_io.BytesIO(data))
        return "\n".join(page.extract_text() or "" for page in reader.pages)
    if ext in {".png", ".jpg", ".jpeg", ".tif", ".tiff", ".bmp", ".webp"}:
        return _ocr_image_file(data)
    return ""


_DASH_TOKENS = {"—", "–", "-", "n/a", "N/A", "\ufffd"}

# Per-jurisdiction vocabulary. This is the fix for the core bug: the old
# code only knew about India's components (PF/ESI/PT/TDS), so uploading a
# US or UK notice silently returned [] no matter what was in the document —
# which then let the *frontend's* generic policy fallback quietly display
# whichever country's canned numbers happened to be selected in the UI tab,
# mislabeled as "extracted from this document". Detecting the document's
# own jurisdiction and only matching that jurisdiction's real statutory
# components closes that gap.
#
# Each component is ("key", "match pattern", "display label", "pct" | "flat").
# "pct"  components pull percentage cells (employee / employer / total).
# "flat" components pull currency-amount cells (e.g. a flat monthly fee).
_COUNTRY_EXTRACTION_CONFIG = {
    "IN": {
        "currency": "₹",
        "detect": r"jurisdiction:\s*india",
        "components": [
            ("pf",  r"provident fund|\bpf\b(?!\w)", "Employee Provident Fund (EPF)", "pct"),
            ("esi", r"state insurance|\besi\b", "Employee State Insurance (ESI)", "pct"),
            ("pt",  r"professional tax", "Professional Tax (PT)", "flat"),
            ("lwf", r"labour welfare fund", "Labour Welfare Fund", "flat"),
            ("tds", r"\btds\b", "TDS / Income Tax", "pct"),
        ],
    },
    "US": {
        "currency": "$",
        "detect": r"jurisdiction:\s*united states",
        "components": [
            ("social_security", r"social security", "Social Security (FICA)", "pct"),
            ("medicare",        r"medicare", "Medicare (FICA)", "pct"),
            ("futa",            r"federal unemployment|\bfuta\b", "Federal Unemployment (FUTA)", "pct"),
            ("sui",             r"state unemployment|\bsui\b", "State Unemployment Insurance (SUI)", "pct"),
            ("sdi",             r"\bsdi\b|state disability", "State Disability Insurance (SDI)", "pct"),
        ],
    },
    "UK": {
        "currency": "£",
        "detect": r"jurisdiction:\s*united kingdom",
        "components": [
            ("national_insurance", r"national insurance|ni contributions|\bnic\b|class 1\s+ni", "National Insurance", "pct"),
            ("pension",            r"pension\s+auto.?enrolment|workplace\s+pension|auto.?enrolment(?!\s+declaration)", "Workplace Pension (Auto-Enrolment)", "pct"),
            ("apprenticeship_levy",r"apprenticeship levy", "Apprenticeship Levy", "pct"),
            ("ssp",                r"statutory sick pay|\bssp\b", "Statutory Sick Pay (SSP)", "flat"),
        ],
    },
}

_SECTION_END_MARKERS = {
    "IN": "Income Tax Slabs",
    "US": "Federal Income Tax Brackets",
    "UK": "Income Tax Bands",
}


def detect_country_from_text(text: str) -> Optional[str]:
    """Detects the jurisdiction a compliance document is actually *about*
    by reading its own content, rather than trusting the currently-selected
    UI tab. Falls back to None (unknown) if no known jurisdiction phrase is
    found — callers should fall back to the country the user supplied on
    upload in that case."""
    if not text:
        return None
    for code, cfg in _COUNTRY_EXTRACTION_CONFIG.items():
        if re.search(cfg["detect"], text, re.I):
            return code
    return None


def _strip_parenthetical_notes(line: str) -> str:
    # Wage-base / threshold notes like "(up to $176,100 wage base)" or
    # "(above £242/week)" sit inside parentheses next to the real rate and
    # would otherwise get mistaken for a second employee/employer column.
    return re.sub(r"\([^)]*\)", " ", line)


def _extract_contribution_rates(text: str, country: Optional[str]) -> List[dict]:
    """Per-jurisdiction extraction of statutory contribution rates.

    Many PDFs render table cells as individual text lines (pypdf outputs
    each cell on a separate line), so after finding the component keyword
    on a line we scan the next several lines for the cell values instead
    of requiring everything on the same line.

    Reads the first three real cells positionally — employee share,
    employer share, total — so the column order in the PDF must match
    (Component / Employee / Employer / Total).
    """
    cfg = _COUNTRY_EXTRACTION_CONFIG.get(country)
    if not cfg:
        return []

    rates: List[dict] = []
    lines = text.splitlines()
    n = len(lines)

    for key, pattern, label, kind in cfg["components"]:
        if kind == "pct":
            cell_re = re.compile(r"\d+(?:\.\d+)?\s*%\+?|—|–|\ufffd|N/A", re.I)
        else:
            cell_re = re.compile(
                rf"{re.escape(cfg['currency'])}\s?[\d,]+(?:\.\d+)?(?:/\w+)?|—|–|\ufffd|N/A",
                re.I,
            )

        for i, line in enumerate(lines):
            if not re.search(pattern, line, re.I):
                continue
            # Found the component line — collect cell values from subsequent lines
            cells: List[str] = []
            for j in range(i + 1, min(i + 8, n)):
                candidate = _strip_parenthetical_notes(lines[j]).strip()
                if not candidate:
                    continue
                found = cell_re.findall(candidate)
                if found:
                    cells.extend(found)
                if len(cells) >= 3:
                    break
            if not cells:
                break
            employee = cells[0] if len(cells) > 0 else "—"
            employer = cells[1] if len(cells) > 1 else "—"
            total    = cells[2] if len(cells) > 2 else (employer if len(cells) == 2 else employee)
            rates.append({
                "id": key,
                "label": label,
                "employee": "—" if employee in _DASH_TOKENS else employee,
                "employer": "—" if employer in _DASH_TOKENS else employer,
                "total": total,
            })
            break
    return rates


def _extract_tax_slabs(text: str, country: Optional[str]) -> List[dict]:
    """Parses the income-tax slab table using the correct currency symbol
    for the document's own jurisdiction (previously this hardcoded ₹ onto
    every document, so a US or UK slab table came back stamped with rupee
    signs on dollar/pound figures). Scoped to the slab section only, so
    unrelated numbers elsewhere in the document (reference numbers, dates)
    can't be mistaken for a slab row."""
    currency = _COUNTRY_EXTRACTION_CONFIG.get(country, {}).get("currency", "")
    marker = _SECTION_END_MARKERS.get(country)
    section = text.split(marker, 1)[1] if marker and marker in text else text
    section = section.split("Compliance Requirements", 1)[0]

    slabs: List[dict] = []
    pattern = re.compile(
        re.escape(currency) + r"?\s?([\d,]+)\s*(?:-|to|–|—)\s*([\d,]+|above)\s*(nil|\d+(?:\.\d+)?%)",
        re.I,
    )
    for i, match in enumerate(pattern.finditer(section)):
        low, high, rate = match.groups()
        rate_label = "Nil" if rate.lower() == "nil" else rate
        slabs.append({
            "id": f"doc-slab-{i}",
            "min": f"{currency}{low}",
            "max": "Above" if high.lower() == "above" else f"{currency}{high}",
            "rate": rate_label,
            "tax": f"{rate_label} in this band",
        })
    return slabs


def _extract_requirements(text: str) -> List[dict]:
    """Pulls short freeform lines that look like compliance requirements
    (contain words like 'must'/'shall'/'required'). Capped so a large
    document doesn't dump its entire body into the preview."""
    requirements: List[dict] = []
    keywords = ("must", "shall", "required", "mandatory", "due by", "deadline")
    for line in text.splitlines():
        clean = line.strip()
        if not clean or len(clean) > 200:
            continue
        if any(k in clean.lower() for k in keywords):
            requirements.append({"label": clean[:150]})
        if len(requirements) >= 5:
            break
    return requirements


_ENTITY_RULES = {
    "UK": [
        ("name",
         [r"(?:company|employer|organisation|business)\s+name\s*:\s*(.+)"],
         [r"^company\s+(legal\s+)?name$", r"^employer\s+name$"]),
        ("registrationNumber",
         [r"(?:company\s+registration\s+(?:number|no)|crn|registration\s+no)\s*:?\s*([a-z0-9/]+(?:\s+[a-z0-9/]+)*)"],
         [r"^companies\s+house\s+(number|no)$", r"^company\s+registration\s+(number|no)$"]),
        ("vatNumber",
         [r"vat\s+(?:registration\s+)?(?:number|no)\s*:?\s*((?:gb)?\d{9,12})"],
         [r"^vat\s+(?:registration\s+)?(?:number|no)$"]),
        ("payeReference",
         [r"paye\s+(?:reference|ref|no)\s*:?\s*([\d/]+[a-z0-9]*)"],
         [r"^paye\s+reference$"]),
        ("utr",
         [r"(?:utr|unique\s+taxpayer\s+reference)\s*:?\s*(\d{10})"],
         [r"^unique\s+taxpayer\s+reference$", r"^utr$"]),
        ("address",
         [r"(?:registered\s+(?:office|address)|business\s+address)\s*:?\s*(.+)"],
         [r"^registered\s+(?:office|address)$", r"^business\s+address$"]),
        ("accountsReferenceDate",
         [r"(?:accounts\s+reference\s+date|ard|accounting\s+ref)\s*:?\s*(.+)"],
         [r"^accounts\s+reference\s+date$", r"^ard$"]),
    ],
    "IN": [
        ("name",
         [r"(?:company|employer|organisation|business)\s+name\s*:\s*(.+)"],
         [r"^company\s+(legal\s+)?name$", r"^employer\s+name$", r"^name\s+of\s+(the\s+)?(company|employer)$"]),
        ("pan",
         [r"pan\s+(?:number|no)?\s*:?\s*([a-z]{5}\d{4}[a-z])"],
         [r"^pan\s+(?:number|no)?$", r"^permanent\s+account\s+number$"]),
        ("tan",
         [r"tan\s+(?:number|no)?\s*:?\s*([a-z]{4}\d{5}[a-z])"],
         [r"^tan\s+(?:number|no)?$", r"^tax\s+deduction\s+account\s+number$"]),
        ("gst",
         [r"gst\s+(?:number|no|in)?\s*:?\s*(\d{2}[a-z]{5}\d{4}[a-z]\d[z][a-z\d])"],
         [r"^gst\s+(?:number|no|in)?$", r"^gstin$"]),
        ("pfCode",
         [r"(?:pf|provident\s+fund)\s+(?:code|number|no|account)\s*:?\s*([a-z0-9/]+(?:\s+[a-z0-9/]+)*)"],
         [r"^pf\s+(?:code|number|no|account)", r"^provident\s+fund\s+(?:code|number|no|account)"]),
        ("esiCode",
         [r"(?:esi|state\s+insurance)\s+(?:code|number|no)\s*:?\s*([a-z0-9/]+(?:\s+[a-z0-9/]+)*)"],
         [r"^esi\s+(?:code|number|no)", r"^state\s+insurance\s+(?:code|number|no)"]),
        ("address",
         [r"(?:registered\s+(?:office|address)|business\s+address)\s*:?\s*(.+)"],
         [r"^registered\s+(?:office|address)$", r"^business\s+address$"]),
    ],
    "US": [
        ("name",
         [r"(?:company|employer|organisation|business)\s+name\s*:\s*(.+)"],
         [r"^company\s+(legal\s+)?name$", r"^employer\s+name$", r"^business\s+name$"]),
        ("ein",
         [r"(?:ein|employer\s+identification\s+number|federal\s+id)\s*:?\s*(\d{2}[-\s]?\d{7})"],
         [r"^ein$", r"^employer\s+identification\s+number$", r"^federal\s+(?:id|identification)\s+number$"]),
        ("stateId",
         [r"(?:state\s+(?:id|identification|number)|unemployment\s+(?:id|account))\s*:?\s*([a-z0-9]+(?:[-/][a-z0-9]+)*)"],
         [r"^state\s+(?:id|identification|number)$", r"^unemployment\s+(?:id|account\s+number)$"]),
        ("naicsCode",
         [r"naics\s*(?:code)?\s*:?\s*(\d{6})"],
         [r"^naics\s+code$"]),
        ("address",
         [r"(?:registered\s+(?:office|address)|business\s+address|legal\s+address)\s*:?\s*(.+)"],
         [r"^registered\s+(?:office|address)$", r"^business\s+address$", r"^legal\s+address$"]),
    ],
}


def _extract_registered_entity_details(text: str, country: Optional[str] = None) -> dict:
    """Extracts registered-entity metadata from a compliance notice.

    Handles two common PDF text-layouts:
      1.  "Label: Value" on the same line
      2.  "Label" on line N, "Value" on line N+1

    Uses country-specific patterns so each jurisdiction's expected fields
    (UK: Companies House / PAYE / UTR;  IN: PAN / TAN / GST / PF / ESI;
    US: EIN / State ID / NAICS) are matched correctly."""
    rules = _ENTITY_RULES.get(country, _ENTITY_RULES.get("UK", []))
    details: dict = {}
    lines = text.splitlines()
    n = len(lines)

    for key, same_line, next_line in rules:
        # Try same-line first:  "Label: Value"
        for pat in same_line:
            for line in lines:
                m = re.search(pat, line.strip(), re.I)
                if m:
                    val = m.group(1).strip().strip(",;")
                    if val:
                        details[key] = val
                        break
            if key in details:
                break
        if key in details:
            continue
        # Fallback to next-line:  "Label" then value on line below
        for i, line in enumerate(lines):
            stripped = line.strip()
            if any(re.match(pat, stripped, re.I) for pat in next_line):
                if i + 1 < n:
                    val = lines[i + 1].strip().strip(",;")
                    if val:
                        details[key] = val
                break

    return details


def _extract_compliance_data(text: str, country: Optional[str]) -> dict:
    """Assembles the exact `extracted` object the frontend contract in
    payrollService.js documents: { contributionRates, taxSlabs, requirements }.
    `country` should be the jurisdiction *detected from the document's own
    text* (see detect_country_from_text) wherever possible — using the
    uploader's currently-selected UI tab instead is what caused rates from
    the wrong jurisdiction to be shown as "extracted from this document."
    This is returned to the client as a per-document preview only — it does
    NOT write into the org's live ContributionRate/TaxSlab policy tables,
    matching the "reference only, nothing is auto-applied" copy already
    shown in ComplianceDocuments.jsx. Applying extracted values to live
    policy should be an explicit, separate user action if that's wanted."""
    if not text:
        return {"contributionRates": [], "taxSlabs": [], "requirements": []}
    return {
        "contributionRates": _extract_contribution_rates(text, country),
        "taxSlabs": _extract_tax_slabs(text, country),
        "requirements": _extract_requirements(text),
        "registeredEntityDetails": _extract_registered_entity_details(text, country),
    }


def upload_compliance_document(
    db: Session,
    *,
    title: str,
    category: str,
    file_path: str,
    file_name: str,
    file_size: int,
    mime_type: str,
    organization_id: int,
    country: Optional[str] = None,
    description: Optional[str] = None,
    document_type: Optional[str] = None,
    uploaded_by: Optional[int] = None,
) -> ComplianceDocument:
    doc = ComplianceDocument(
        organization_id=organization_id,
        title=title,
        document_type=document_type,
        category=category,
        description=description,
        file_path=file_path,
        file_name=file_name,
        file_size=file_size,
        mime_type=mime_type,
        uploaded_by=uploaded_by,
        country=country,
        status=ComplianceDocumentStatus.PROCESSING.value,
    )
    db.add(doc)
    db.commit()
    db.refresh(doc)

    # Extraction runs synchronously here (fine for typical single-page
    # notices/PDFs). If this ever needs to handle large multi-page scans,
    # move this to a background task/queue and have the client keep
    # polling GET /compliance/documents — the "processing" status above and
    # the polling loop already in ComplianceDocuments.jsx are built for
    # exactly that, they just weren't being fed real status until now.
    try:
        extracted_text = _extract_text_from_uploaded_document(file_path)

        # Trust the document's own content over whatever jurisdiction tab
        # was active in the UI when the file was dropped — that mismatch
        # (uploading a US notice while the India tab is selected, say) was
        # the actual root cause of "wrong country" extraction results.
        detected_country = detect_country_from_text(extracted_text)
        resolved_country = detected_country or country

        doc.extracted_data = _extract_compliance_data(extracted_text, resolved_country)
        doc.status = ComplianceDocumentStatus.PARSED.value

        # If the document names a jurisdiction that differs from the one it
        # was uploaded under, record what the document actually says so the
        # frontend can show a mismatch warning instead of silently mixing
        # this document's numbers into the wrong tab.
        if detected_country and country and detected_country != country:
            doc.country = detected_country
            doc.error_message = (
                f"This document appears to be for {detected_country}, "
                f"but was uploaded under {country}."
            )
        elif detected_country and not country:
            doc.country = detected_country

        # Populate CompanyComplianceDetails from extracted entity data so
        # the Compliance Overview tab shows jurisdiction, Tax ID, etc.
        # without the user having to fill the form manually.
        try:
            entity = (doc.extracted_data or {}).get("registeredEntityDetails") or {}
            if entity or resolved_country:
                company_row = get_company_details(db, organization_id)
                needs_commit = False

                if entity.get("name") and not company_row.name:
                    company_row.name = entity["name"]
                    needs_commit = True
                if entity.get("address") and not company_row.address:
                    company_row.address = entity["address"]
                    needs_commit = True
                if resolved_country and not company_row.jurisdiction_country:
                    company_row.jurisdiction_country = resolved_country
                    needs_commit = True
                if resolved_country and not company_row.compliance_pack:
                    pack_map = {"IN": "India Statutory", "US": "US Federal & State", "UK": "UK HMRC"}
                    company_row.compliance_pack = pack_map.get(resolved_country, "")
                    needs_commit = True

                # Country-specific tax-id / employer-id mapping
                if resolved_country == "IN":
                    if entity.get("pan") and not company_row.tax_no:
                        company_row.tax_no = entity["pan"].upper()
                        needs_commit = True
                    if entity.get("pfCode") and not company_row.employer_id:
                        company_row.employer_id = entity["pfCode"]
                        needs_commit = True
                elif resolved_country == "UK":
                    if entity.get("utr") and not company_row.tax_no:
                        company_row.tax_no = entity["utr"]
                        needs_commit = True
                    if entity.get("payeReference") and not company_row.employer_id:
                        company_row.employer_id = entity["payeReference"]
                        needs_commit = True
                elif resolved_country == "US":
                    if entity.get("ein") and not company_row.tax_no:
                        company_row.tax_no = entity["ein"]
                        needs_commit = True

                if needs_commit:
                    db.commit()
        except Exception:  # noqa: S110 - best-effort, must not break the upload
            pass
    except Exception as exc:  # noqa: BLE001 - surface it instead of swallowing it
        doc.status = ComplianceDocumentStatus.FAILED.value
        doc.error_message = f"Could not extract text from this document: {exc}"

    db.add(doc)
    db.commit()
    db.refresh(doc)

    log_activity(db, organization_id, f"Compliance document '{title}' uploaded.", ActivityStatus.INFO)
    return doc


# ── Compliance ─────────────────────────────────────────────────────────

# Registration collects a full country name (matches the standalone
# Compliance dropdown's supported set); jurisdiction_country stores the
# 2-letter code that dropdown actually uses as its option value. Mirrors
# enterprise/service.py's SUPPORTED_COUNTRY_CODES universe.
_COUNTRY_NAME_TO_JURISDICTION_CODE = {
    "india": "IN",
    "united states": "US",
    "united kingdom": "UK",
    "australia": "AU",
    "germany": "DE",
    "canada": "CA",
    "france": "FR",
    "ireland": "IE",
}


def _jurisdiction_code_for_org_country(country_name: Optional[str]) -> Optional[str]:
    """Resolve Organization.country (a full name) to the 2-letter jurisdiction
    code. Falls back to app.core.jurisdiction's complete registry for
    countries not in the small dict above (the Caribbean jurisdictions +
    Puerto Rico) instead of returning None and silently skipping the
    Compliance-row jurisdiction backfill for those orgs."""
    if not country_name:
        return None
    code = _COUNTRY_NAME_TO_JURISDICTION_CODE.get(country_name.strip().lower())
    if code:
        return code
    from app.core.jurisdiction import get_jurisdiction_code
    return get_jurisdiction_code(country_name)


def _merge_tax_identifiers(existing: dict | None, incoming: dict | None) -> dict:
    """Merge two tax-identifier maps, keeping existing values for any key that
    is already set — the deduplication rule for compliance sync. New keys (or
    blank values) from registration never overwrite a value the admin already
    entered/overrode in the Compliance tab."""
    merged = dict(existing or {})
    for key, value in (incoming or {}).items():
        if not value:
            continue
        if key not in merged or not merged.get(key):
            merged[key] = value
    return merged or None


def get_company_details(db: Session, organization_id: int) -> CompanyComplianceDetails:
    row = db.query(CompanyComplianceDetails).filter(
        CompanyComplianceDetails.organization_id == organization_id
    ).first()
    if not row:
        row = CompanyComplianceDetails(organization_id=organization_id)
        db.add(row)
        db.commit()
        db.refresh(row)

    # Pre-fill from data the org already gave elsewhere (registration /
    # billing signup) instead of asking them to retype it on this form.
    # Only ever fills fields still at their blank default — never
    # overwrites anything already entered here.
    needs_basic_backfill = not row.name or not row.tax_no or not row.industry or not row.address \
        or not row.employer_id or not row.email or not row.phone or not row.type
    # Legacy rows created before the "" default (see CompanyComplianceDetails)
    # may still carry the old literal "India" placeholder — treat that the
    # same as blank. Deliberately NOT gated on configured_at: configured_at
    # flips true on ANY Compliance save (e.g. saving just the Tax No field),
    # not specifically a deliberate jurisdiction choice, so a row can reach
    # configured_at=True while jurisdiction_country is still just the unset
    # placeholder. Once a real code is present this condition is false
    # forever, so this can never overwrite an actual choice — see the lock
    # in update_company_details for what stops a REAL value being changed,
    # and verify_jurisdiction for how Enterprise mode later owns the field.
    needs_jurisdiction_backfill = (
        row.jurisdiction_country in ("", "India") or not row.jurisdiction_state
    )

    if needs_basic_backfill or needs_jurisdiction_backfill:
        from app.modules.organizations.models import Organization

        org = db.query(Organization).filter(Organization.id == organization_id).first()
        changed = False
        if org and needs_basic_backfill:
            if not row.name and org.organization_name:
                row.name = org.organization_name
                changed = True
            if not row.tax_no and org.tax_no:
                row.tax_no = org.tax_no
                changed = True
            if not row.employer_id and org.registration_number:
                row.employer_id = org.registration_number
                changed = True
            if not row.industry and org.industry:
                row.industry = org.industry
                changed = True
            if not row.type and org.company_type:
                row.type = org.company_type
                changed = True
            if not row.address and org.address:
                row.address = org.address
                changed = True
            if not row.email and org.email:
                row.email = org.email
                changed = True
            if not row.phone and org.phone:
                row.phone = org.phone
                changed = True
        if org and needs_jurisdiction_backfill:
            code = _jurisdiction_code_for_org_country(org.country)
            if code and row.jurisdiction_country != code:
                row.jurisdiction_country = code
                changed = True
            if org.state and not row.jurisdiction_state:
                row.jurisdiction_state = org.state
                changed = True
        # Sync the jurisdiction tax/registration IDs captured at registration.
        # Only fills keys the compliance row doesn't already hold (see
        # _merge_tax_identifiers) so a value the admin later overrode is never
        # clobbered by a re-registration/resubmission — reuse, not duplicates.
        if org and org.tax_identifiers:
            merged = _merge_tax_identifiers(row.tax_identifiers, org.tax_identifiers)
            if merged != (row.tax_identifiers or None):
                row.tax_identifiers = merged
                changed = True
        if changed:
            db.commit()
            db.refresh(row)

    # Inherit pack defaults from the Super Admin's jurisdiction pack when
    # fields are still blank — implements the inheritance model for compliance.
    pack_changed = _backfill_compliance_from_pack(row, db)
    if pack_changed:
        db.commit()
        db.refresh(row)

    return row


def _backfill_compliance_from_pack(row: "CompanyComplianceDetails", db: Session) -> bool:
    """Pre-fill compliance fields from the Super Admin's active JurisdictionPack
    when they haven't been set yet. Returns True if any field was changed.

    This implements the Super Admin → Org Admin inheritance model for
    compliance details: the Super Admin declares pack values, the Org Admin
    inherits them by default, and can overwrite where permitted."""
    if not row.active_pack_id:
        return False
    pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == row.active_pack_id).first()
    if not pack:
        return False

    changed = False
    # Pack ID — the compliance pack identifier
    if not row.compliance_pack and pack.pack_id:
        row.compliance_pack = pack.pack_id
        changed = True
    # Jurisdiction country — inherit from pack if not set
    if not row.jurisdiction_country and pack.jurisdiction_country:
        row.jurisdiction_country = pack.jurisdiction_country
        changed = True
    # State — inherit from pack if not set
    if not row.jurisdiction_state and pack.jurisdiction_state:
        row.jurisdiction_state = pack.jurisdiction_state
        changed = True
    return changed


def update_company_details(db: Session, organization_id: int, data: CompanyDetailsUpdate) -> CompanyComplianceDetails:
    row = get_company_details(db, organization_id)

    # Jurisdiction lock: once a REAL jurisdiction has been chosen, it can no
    # longer be changed through this endpoint — every Payroll sub-module
    # (Employees, Payroll Runs, Payslips, Reports, statutory calculations,
    # currency) is keyed off this single field, so a silent mid-stream switch
    # would invalidate historical payroll data. A real jurisdiction change
    # needs a controlled migration process, not a dropdown edit. Gated on the
    # value itself being real (not blank/legacy "India" placeholder) rather
    # than on configured_at alone — configured_at flips true on ANY Compliance
    # save, not specifically a deliberate jurisdiction choice, so a row can
    # reach configured_at=True while jurisdiction_country is still unset;
    # locking on that would strand the org unable to ever pick one.
    incoming_country = data.jurisdictionCountry
    jurisdiction_already_chosen = row.jurisdiction_country not in (None, "", "India")
    if (
        jurisdiction_already_chosen
        and incoming_country is not None
        and incoming_country != row.jurisdiction_country
    ):
        raise HTTPException(
            http_status.HTTP_423_LOCKED,
            detail="The payroll jurisdiction is locked after Compliance has been configured and cannot be changed here. Changing jurisdictions requires a controlled migration process.",
        )

    field_map = {
        "name": "name", "type": "type", "taxNo": "tax_no", "employerId": "employer_id",
        "address": "address", "industry": "industry", "email": "email", "phone": "phone",
        "jurisdictionCountry": "jurisdiction_country", "jurisdictionState": "jurisdiction_state",
        "compliancePack": "compliance_pack", "schedule": "schedule",
        "settlementBank": "settlement_bank", "settlementAcc": "settlement_acc",
        # ZP-TAX-CA-2026-001 §15/AC-20 — BC EHT ordinary-vs-charity/
        # nonprofit classification. See CompanyComplianceDetails' own
        # column comment (models.py) — previously no UI set this at all.
        "bcEhtEmployerClassification": "bc_eht_employer_classification",
        # ZP-TAX-CA-2026-001 §13 — Quebec HSF employer category (GENERAL |
        # PRIMARY_MANUFACTURING | PUBLIC_SECTOR). Same "no UI yet" gap as
        # BC's classification above, now closed the same way.
        "qcHsfEmployerCategory": "qc_hsf_employer_category",
        # ZP-TAX-UK-2026-27-001 §18 gap-closure Part 9 — every FPS/EPS
        # needs both. Same "no UI yet" gap as the two CA fields above,
        # closed the same way.
        "payeReference": "paye_reference",
        "accountsOfficeReference": "accounts_office_reference",
    }
    payload = data.model_dump(exclude_unset=True)
    for camel_field, value in payload.items():
        column = field_map.get(camel_field)
        if column:
            setattr(row, column, value)

    # Edit / Override support for the jurisdiction tax/registration IDs.
    # Values are validated against the org's jurisdiction schema, then stored
    # (the admin is explicitly overriding — replace what's there). Only keys
    # the schema defines are persisted, so unknown/blank keys never create
    # duplicate or junk tax records. The primary identifier is mirrored back
    # into tax_no so payroll footers/reports keep reading a single value.
    tax_identifiers_payload = payload.get("taxIdentifiers")
    if tax_identifiers_payload is not None:
        from app.core.jurisdiction import (
            get_jurisdiction_code,
            primary_tax_value,
            validate_tax_identifiers_or_raise,
        )

        jurisdiction_code = get_jurisdiction_code(
            data.jurisdictionCountry or row.jurisdiction_country
        )
        if jurisdiction_code:
            validated = validate_tax_identifiers_or_raise(jurisdiction_code, tax_identifiers_payload)
        else:
            validated = {k: v for k, v in tax_identifiers_payload.items() if v}
        row.tax_identifiers = validated or None
        # Mirror the primary identifier into the legacy tax_no column unless the
        # caller explicitly overrode taxNo in the same payload.
        if "taxNo" not in payload:
            row.tax_no = primary_tax_value(jurisdiction_code, validated) or row.tax_no

    # First explicit admin save unlocks the mandatory Payroll onboarding gate
    # and locks the jurisdiction in place (see check above) — immutable once
    # set.
    if row.configured_at is None:
        row.configured_at = datetime.utcnow()

    db.commit()
    db.refresh(row)
    log_activity(db, organization_id, "Company compliance details updated.", ActivityStatus.SUCCESS)
    return row


def get_compliance_data(db: Session, organization_id: int) -> dict:
    company = get_company_details(db, organization_id)
    # Placeholder for a future FilingRecord model (statutory filing due-dates,
    # e.g. PF/ESI monthly returns, TDS quarterly returns). Returned as an
    # empty list today rather than fabricated entries.
    filings: List[dict] = []
    return {"company": company, "filings": filings}


# ── Reports ─────────────────────────────────────────────────────────────

def get_payroll_reports(db: Session, organization_id: int = None, **_) -> List[dict]:
    """Build report entries from existing payroll runs."""
    q = db.query(PayrollRun)
    if organization_id is not None:
        q = q.filter(PayrollRun.organization_id == organization_id)
    runs = q.order_by(PayrollRun.period_start.desc()).all()

    reports = []
    for run in runs:
        if run.status in ("Draft",):
            continue
        reports.append({
            "id": run.id,
            "name": f"Payroll Report — {run.period_label}",
            "period": run.period_label,
            "generatedAt": run.updated_at.strftime("%b %d, %Y") if run.updated_at else (
                run.created_at.strftime("%b %d, %Y") if run.created_at else "-"
            ),
            # "available" once the run has passed Review (Approved and every
            # later stage — Authorized/Paid/Closed — are all just as final;
            # this used to only recognize Approved/Paid, so an Authorized or
            # Closed run incorrectly showed as "pending" here.
            "status": "available" if PAYROLL_STATUS_ORDER.index(run.status) >= PAYROLL_STATUS_ORDER.index(PayrollStatus.APPROVED) else "pending",
        })
    return reports


def _get_report_run(db: Session, report_id: int, organization_id: int = None):
    """Fetch the PayrollRun for a report, raising if not found."""
    from app.core.exceptions import NotFoundException
    q = db.query(PayrollRun).filter(PayrollRun.id == report_id)
    if organization_id is not None:
        q = q.filter(PayrollRun.organization_id == organization_id)
    run = q.first()
    if not run:
        raise NotFoundException("Payroll report", report_id)
    return run


# ── Germany-specific reporting (Phase 8BI) ───────────────────────────────
# Phase 8BH's audit found NO Germany-specific report existed at all — the
# generic Payroll Register (get_payroll_reports/generate_payroll_register_pdf
# above) is a per-run operational summary shared by every country, labels
# Lohnsteuer as generic "Income Tax," and has no Kirchensteuer column.
# This is a genuinely NEW, Germany-specific statutory summary, built
# directly from real, already-persisted PayslipItem/PayrollRun rows —
# never a new report-template registration, since this is a fixed-shape
# operational/compliance summary, not a user-authorable template.
#
# CALCULATED / BLOCKED / UNAVAILABLE is used deliberately, never
# conflated: CALCULATED means a real, persisted PayslipItem (status
# PENDING or PAID); BLOCKED means a real, persisted FAILED PayslipItem
# (Phase 8BI's own batch-processing fix — see generate_payslips_for_run);
# UNAVAILABLE means a figure this codebase has no path to ever compute
# today (Solidaritätszuschlag has no persisted field at all, correctly
# deferred with PAP activation — see docs/GERMANY_JURISDICTION_PRODUCTION_READINESS_REPORT.md).
# No tax value is ever fabricated for a BLOCKED or UNAVAILABLE figure.

def get_germany_payroll_summary_report(
    db: Session, organization_id: int, period_start: Optional[date] = None, period_end: Optional[date] = None,
) -> dict:
    """Aggregates real, already-persisted Germany PayslipItem rows for one
    organization into a statutory summary. Tenant-scoped by
    `organization_id` (mandatory — this is org-owned payroll data, unlike
    the global PAP/registry data). `period_start`/`period_end` filter by
    the OWNING PayrollRun's own period (inclusive), matching how runs are
    already filtered elsewhere in this module — omit both for an
    all-time summary across every run this org has ever generated."""
    query = (
        db.query(PayslipItem, PayrollRun)
        .join(PayrollRun, PayslipItem.payroll_run_id == PayrollRun.id)
        .filter(PayslipItem.organization_id == organization_id, PayslipItem.country_code == "DE")
    )
    if period_start is not None:
        query = query.filter(PayrollRun.period_end >= period_start)
    if period_end is not None:
        query = query.filter(PayrollRun.period_start <= period_end)
    rows = query.order_by(PayrollRun.period_start.desc()).all()

    classification_counts: dict = {"MINIJOB": 0, "MIDIJOB": 0, "REGULAR": 0, "UNKNOWN": 0}
    blocked_reason_counts: dict = {}
    blocked_employees: List[dict] = []
    # Phase 8BU: PARTIAL is a THIRD, distinct bucket from CALCULATED/
    # BLOCKED — a real, persisted PayslipItem where SOME components
    # calculated (gross/RV/ALV/GKV/PV — always real, folded into the
    # totals below same as CALCULATED) while at least one other
    # component (per-item `unavailableComponents`) did not. That
    # component's own total (net pay / Soli / church tax) must exclude
    # this item's forced-zero placeholder, or the aggregate would
    # silently fabricate a real-looking sum that includes a fake zero.
    partial_count = 0
    partial_employees: List[dict] = []
    net_pay_unavailable_count = 0
    soli_unavailable_count = 0
    church_tax_unavailable_count = 0
    calculated_count = 0
    blocked_count = 0
    gross_total = Decimal("0")
    net_total = Decimal("0")
    pension_insurance_employee_total = Decimal("0")
    pension_insurance_employer_total = Decimal("0")
    social_insurance_combined_employee_total = Decimal("0")
    social_insurance_combined_employer_total = Decimal("0")
    church_tax_total = Decimal("0")
    soli_total = Decimal("0")
    runs_seen: dict = {}
    # Phase 8BS: which wage-tax calculation mode actually produced these
    # CALCULATED figures — surfaced so a viewer never mistakes an internal
    # functional-reference result for an official BMF-certified one.
    calculation_modes_seen: dict = {}

    for item, run in rows:
        snapshot = item.germany_calculation_snapshot or {}
        classification = (snapshot.get("employmentClassification") or "UNKNOWN").upper()
        if classification not in classification_counts:
            classification = "UNKNOWN"
        classification_counts[classification] += 1

        runs_seen.setdefault(run.id, {
            "runId": run.id, "periodLabel": run.period_label, "runStatus": run.status,
            "payDate": run.pay_date.isoformat() if run.pay_date else None,
            "calculatedCount": 0, "blockedCount": 0, "partialCount": 0,
        })

        if item.status == PayslipStatus.FAILED:
            blocked_count += 1
            runs_seen[run.id]["blockedCount"] += 1
            reason_code = snapshot.get("blockedReasonCode") or "UNKNOWN"
            blocked_reason_counts[reason_code] = blocked_reason_counts.get(reason_code, 0) + 1
            blocked_employees.append({
                "employeeId": item.employee_id, "employeeName": item.employee_name,
                "payrollRunId": run.id, "periodLabel": run.period_label,
                "blockedReasonCode": reason_code,
                "blockedReasonMessage": snapshot.get("blockedReasonMessage"),
            })
            continue  # a BLOCKED payslip contributes zero to every monetary sum below

        is_partial = item.status == PayslipStatus.PARTIAL
        unavailable = set(snapshot.get("unavailableComponents") or []) if is_partial else set()

        if is_partial:
            partial_count += 1
            runs_seen[run.id]["partialCount"] += 1
            partial_employees.append({
                "employeeId": item.employee_id, "employeeName": item.employee_name,
                "payrollRunId": run.id, "periodLabel": run.period_label,
                "unavailableComponents": sorted(unavailable),
            })
        else:
            calculated_count += 1
            runs_seen[run.id]["calculatedCount"] += 1

        # Gross pay and social-insurance figures resolve BEFORE the
        # wage-tax stage, so they are always real here — CALCULATED or
        # PARTIAL alike — never a forced zero.
        gross_total += item.gross_pay or Decimal("0")
        pension_insurance_employee_total += item.pf or Decimal("0")
        pension_insurance_employer_total += item.employer_pf or Decimal("0")
        social_insurance_combined_employee_total += item.esi or Decimal("0")
        social_insurance_combined_employer_total += item.employer_esi or Decimal("0")

        # net_pay is forced to 0.00 for EVERY PARTIAL item (engine/standard.py
        # and engine/enterprise.py never present a plausible-looking net pay
        # built on top of an unavailable wage tax) — always exclude it here.
        if is_partial:
            net_pay_unavailable_count += 1
        else:
            net_total += item.net_pay or Decimal("0")

        # church tax / Soli are each forced to 0.00 ONLY when that specific
        # component is in this item's own unavailableComponents — a
        # genuinely-zero (not-liable / below-threshold) figure on a
        # CALCULATED or a still-available-on-this-PARTIAL-item field must
        # still be summed as the real result it is.
        if "church_tax" in unavailable:
            church_tax_unavailable_count += 1
        else:
            church_tax_total += item.church_tax or Decimal("0")
        # Soli is informational (already folded into `tds`): summed from the
        # persisted column, never recomputed, never re-added to any other
        # total. Phase 8BR: genuinely computed (by the internal functional
        # wage-tax calculator, or a future real PAP) whenever a payslip's
        # annual Lohnsteuer exceeds the SolzG exemption threshold — 0.00
        # below it, which is a REAL result, not a placeholder.
        if "soli" in unavailable:
            soli_unavailable_count += 1
        else:
            soli_total += item.soli or Decimal("0")
        pap_version = snapshot.get("papVersion") or "UNKNOWN"
        calculation_modes_seen[pap_version] = calculation_modes_seen.get(pap_version, 0) + 1

    return {
        "organizationId": organization_id,
        "periodStart": period_start.isoformat() if period_start else None,
        "periodEnd": period_end.isoformat() if period_end else None,
        "employeeCounts": {
            "total": calculated_count + blocked_count + partial_count,
            "byClassification": classification_counts,
            "byStatus": {"CALCULATED": calculated_count, "BLOCKED": blocked_count, "PARTIAL": partial_count},
        },
        "grossPay": {"status": "CALCULATED", "amount": str(gross_total)},
        "netPay": {
            "status": "PARTIAL" if net_pay_unavailable_count else "CALCULATED",
            "amount": str(net_total),
            "excludedPartialCount": net_pay_unavailable_count,
            "note": ("Excludes {} PARTIAL payslip(s) whose net pay is unavailable (wage tax not "
                     "calculable) — never summed as a fabricated zero.".format(net_pay_unavailable_count)
                     if net_pay_unavailable_count else None),
        },
        "statutoryContributions": {
            "pensionInsurance": {
                "status": "CALCULATED",
                "employeeAmount": str(pension_insurance_employee_total),
                "employerAmount": str(pension_insurance_employer_total),
            },
            # ALV + GKV + PV combined — PayslipItem has no discrete
            # per-branch columns today (see the phase report's own
            # "Payslip" section); reported honestly as one combined
            # figure rather than fabricating a breakdown that doesn't
            # exist on the underlying row.
            "socialInsuranceCombined": {
                "status": "CALCULATED",
                "employeeAmount": str(social_insurance_combined_employee_total),
                "employerAmount": str(social_insurance_combined_employer_total),
            },
            "churchTax": {
                "status": "PARTIAL" if church_tax_unavailable_count else "CALCULATED",
                "amount": str(church_tax_total),
                "excludedPartialCount": church_tax_unavailable_count,
            },
            "solidaritySurcharge": {
                "status": "PARTIAL" if soli_unavailable_count else "CALCULATED",
                "amount": str(soli_total.quantize(Decimal("0.01"))),
                "excludedPartialCount": soli_unavailable_count,
                "note": "Informational (already folded into Wage Tax / Lohnsteuer incl. Soli). "
                        "Genuinely computed per payslip (real 0.00 for any employee below the "
                        "SolzG exemption threshold, a nonzero real amount above it) — see "
                        "calculationModes below for which calculator produced these figures. "
                        "Excludes any PARTIAL payslip where Soli itself is unavailable.",
            },
        },
        "wageTaxStatus": {
            "calculated": calculated_count, "blocked": blocked_count, "partial": partial_count,
            "blockedReasonCounts": blocked_reason_counts,
        },
        # Phase 8BS: never let a CALCULATED figure be mistaken for an
        # official BMF-certified one. Every real Regular/Midijob wage-tax
        # figure today reads INTERNAL_FUNCTIONAL_REFERENCE-ESTG32A-2023
        # (engine/jurisdictions/germany/tax.py) — a future real PAP executor
        # would report a different, genuinely BMF-certified pap_version
        # string here instead, distinguishable at a glance.
        "calculationModes": calculation_modes_seen,
        "papBlockedPayrollCount": blocked_reason_counts.get("GERMANY_PAP_NOT_AVAILABLE", 0),
        "blockedEmployees": blocked_employees,
        "partialEmployees": partial_employees,
        "payrollRuns": sorted(runs_seen.values(), key=lambda r: r["runId"], reverse=True),
    }


# Per-jurisdiction statutory/contribution columns for the Payroll Register
# PDF — (header, PayslipItem field, width_mm). Field choices mirror the same
# per-country reuse already established for generate_payslip_pdf_bytes's
# income_tax_labels/pf_esi_labels dicts (e.g. Germany's pension/combined
# social-insurance fields reuse pf/esi) — so the register and the payslip
# never disagree about which underlying column backs which country's
# statutory line.
# Fields not computed for a country (e.g. professional_tax reused as
# Canada's "Provincial Tax", pending real provincial tax calculation)
# render as 0 — same field-reuse-over-new-columns approach used throughout
# this module. US previously reused "tds" (the COMBINED federal+state+local
# figure) mislabeled as "Fed. Tax", and "professional_tax" (always 0 for a
# US employee — that's India's field) mislabeled as "State Tax" — now that
# federal_income_tax/state_income_tax/local_tax are real, separately-
# computed PayslipItem columns, US reads its own dedicated fields instead.
_STATUTORY_COLUMNS_BY_COUNTRY = {
    "IN": [("PF", "pf", 13), ("ESI", "esi", 11), ("Prof. Tax", "professional_tax", 12), ("TDS", "tds", 13)],
    "US": [("Fed. Tax", "federal_income_tax", 13), ("State Tax", "state_income_tax", 12), ("Local Tax", "local_tax", 12), ("Soc. Security", "social_security", 16), ("Medicare", "medicare", 13)],
    "UK": [("PAYE", "tds", 13), ("Nat'l Insurance", "ni_employee", 19)],
    "AU": [("PAYG", "tds", 13), ("Superannuation", "employer_pension", 19)],
    # Phase 8BS: was mislabeled "Income Tax" (a generic gloss, not how a
    # German payroll register reads) and omitted Kirchensteuer/Soli
    # entirely, even though both are real, persisted PayslipItem columns
    # — the same defect class the payslip PDF's own income_tax_labels/
    # church-tax fix already addressed (see generate_payslip_pdf_bytes).
    # "lohnsteuer_only" is a synthetic field name (tds - soli), resolved by
    # _resolve_statutory_column_value below — `tds` alone is the COMBINED
    # Lohnsteuer+Soli figure, and showing both raw `tds` and `soli` as
    # separate columns would double-count Soli visually.
    "DE": [
        ("Lohnsteuer", "lohnsteuer_only", 14), ("Kirchensteuer", "church_tax", 14), ("Soli", "soli", 11),
        ("Pension Ins.", "pf", 14), ("Social Ins.", "esi", 14),
    ],
    "CA": [("CPP", "social_security", 12), ("EI", "esi", 10), ("Fed. Tax", "tds", 14), ("Prov. Tax", "professional_tax", 14)],
}
_DEFAULT_STATUTORY_COLUMNS = [("Income Tax", "tds", 15)]


def _resolve_statutory_column_value(item, field: str) -> Decimal:
    """Resolves one `_STATUTORY_COLUMNS_BY_COUNTRY` cell. Almost always a
    direct `getattr` passthrough; the one synthetic field, `lohnsteuer_only`
    (Germany), computes `tds - soli` so a register showing both a
    "Lohnsteuer" and a "Soli" column never double-counts Soli (`tds` alone
    is the combined Lohnsteuer+Soli figure — see PayslipItem.tds /
    engine/countries/germany.py's `monthly_lohnsteuer_soli`)."""
    if field == "lohnsteuer_only":
        return Decimal(str(item.tds or 0)) - Decimal(str(item.soli or 0))
    return Decimal(str(getattr(item, field, 0) or 0))


# Phase 8BU: which `_STATUTORY_COLUMNS_BY_COUNTRY` field each Germany
# `unavailableComponents` entry corresponds to — used by the register
# PDF/CSV to render "N/A" instead of a fabricated €0.00 for a PARTIAL
# item's specific unavailable column, without touching any other
# CALCULATED/BLOCKED row's rendering.
_DE_STATUTORY_FIELD_TO_UNAVAILABLE_COMPONENT = {
    "lohnsteuer_only": "wage_tax", "church_tax": "church_tax", "soli": "soli",
}


def _statutory_cell_text(item, field: str, fmt) -> str:
    """Register PDF/CSV cell text for one statutory column: "N/A" when this
    specific PARTIAL item's own `unavailableComponents` names this field's
    component, the real formatted amount otherwise."""
    if item.status == PayslipStatus.PARTIAL:
        component = _DE_STATUTORY_FIELD_TO_UNAVAILABLE_COMPONENT.get(field)
        unavailable = set((item.germany_calculation_snapshot or {}).get("unavailableComponents") or [])
        if component and component in unavailable:
            return "N/A"
    return fmt(_resolve_statutory_column_value(item, field))


def _net_salary_cell_text(item, fmt) -> str:
    """Register PDF/CSV Net Salary cell: "N/A" for a PARTIAL item (net_pay
    is always forced to 0.00 there — see engine/standard.py — never shown
    as a real figure), the real amount otherwise."""
    if item.status == PayslipStatus.PARTIAL:
        return "N/A"
    return fmt(item.net_pay)
    return Decimal(str(getattr(item, field, 0) or 0))


def generate_report_pdf_bytes(db: Session, report_id: int, organization_id: int = None) -> bytes:
    """Generate a production-level PDF payroll register report.

    Layout (Landscape A4):
      1. Header bar  – Company name, pay period, pay date, status
      2. KPI cards   – Gross, Deductions, Employer Contributions, Net Payable
      3. Employee breakdown table (16 columns) with totals row
      4. Sign-off block – HR Manager & Finance Director signature lines
    """
    from reportlab.lib.pagesizes import landscape, A4
    from reportlab.lib.units import mm
    from reportlab.lib import colors
    from reportlab.pdfgen import canvas as pdf_canvas

    import io

    run = _get_report_run(db, report_id, organization_id)
    items = run.payslip_items or []

    # ── Currency helpers ──
    # None when nothing is configured anywhere — _get_currency_symbol below
    # already falls back to a neutral "$" for an unrecognized (including
    # None) country, rather than assuming India.
    country = _resolve_org_country(db, organization_id)
    # Use the org's explicit currency override if set, otherwise derive
    # from the jurisdiction.
    org_currency_code = None
    if organization_id:
        from app.modules.organizations.models import Organization
        org_row = db.query(Organization).filter(Organization.id == organization_id).first()
        org_currency_code = org_row.currency if org_row else None
    sym = _get_currency_symbol(org_currency_code or country)
    evaluation = _is_evaluation_workspace(db, organization_id)

    def fmt(val):
        v = float(val or 0)
        return f"{sym} {v:,.2f}"

    # ── Company name ──
    org_name = "—"
    if organization_id is not None:
        from app.modules.organizations.models import Organization
        org = db.query(Organization).filter(Organization.id == organization_id).first()
        if org:
            org_name = org.organization_name

    # ── Canvas setup (Landscape A4) ──
    buf = io.BytesIO()
    page_w, page_h = landscape(A4)
    c = pdf_canvas.Canvas(buf, pagesize=landscape(A4))
    width, height = page_w, page_h

    # ── Font setup: register a Unicode-capable font so non-ASCII currency
    # symbols (₹ etc.) actually render instead of silently vanishing under
    # base-14 Helvetica's WinAnsi encoding — same helper the payslip PDF
    # generator already uses. ──
    base_font = _register_rupee_font(c)
    F = base_font or "Helvetica"
    FB = f"{base_font}-Bold" if base_font else "Helvetica-Bold"

    def _draw_col_separators(cx, y_top, h, color=None):
        """Thin vertical rules between every column, for the bordered-grid
        look — drawn per row/header/totals block so it naturally survives
        page breaks without needing cross-page position tracking."""
        c.setStrokeColor(color or slate_200)
        c.setLineWidth(0.3)
        for x in cx:
            c.line(x, y_top, x, y_top - h)

    # ── Palette ──
    teal        = colors.HexColor("#0D9488")
    teal_dark   = colors.HexColor("#0F766E")
    teal_light  = colors.HexColor("#E8F7F5")
    slate_50    = colors.HexColor("#F8FAFC")
    slate_100   = colors.HexColor("#F1F5F9")
    slate_200   = colors.HexColor("#E2E8F0")
    slate_400   = colors.HexColor("#94A3B8")
    slate_600   = colors.HexColor("#475569")
    slate_800   = colors.HexColor("#1E293B")
    white       = colors.white

    margin_l  = 18 * mm
    margin_r  = width - 18 * mm
    content_w = margin_r - margin_l
    # Top margin must leave real, visible padding ABOVE the header bar
    # itself (not just clear the text inside it) — the bar's top edge sits
    # at (y - 5mm + bar_h) = y + 22mm, so y must be low enough that this
    # stays comfortably under the page's physical top edge, or the banner
    # renders flush against the page with its rounded corners clipped off.
    y = height - 28 * mm

    # ════════════════════════════════════════════════════════════════════
    # 1. HEADER BAR
    # ════════════════════════════════════════════════════════════════════
    bar_h = 27 * mm
    c.setFillColor(teal)
    c.roundRect(margin_l, y - 5 * mm, content_w, bar_h, 5, fill=True, stroke=False)

    c.setFillColor(white)
    c.setFont(FB, 20)
    c.drawString(margin_l + 7 * mm, y + 9 * mm, "PAYROLL REGISTER")
    c.setFont(F, 8.5)
    c.drawString(margin_l + 7 * mm, y + 3.5 * mm, "Employee-wise Salary & Statutory Breakdown")

    c.setFont(FB, 9.5)
    c.drawRightString(margin_r - 7 * mm, y + 12 * mm, org_name)
    c.setFont(F, 8)
    c.drawRightString(margin_r - 7 * mm, y + 6.5 * mm, f"Pay Period: {run.period_label}")
    c.drawRightString(margin_r - 7 * mm, y + 2 * mm, f"Pay Date: {run.pay_date}   |   Status: {run.status}")

    y -= bar_h - 2 * mm

    # ════════════════════════════════════════════════════════════════════
    # 2. KPI SUMMARY CARDS
    # ════════════════════════════════════════════════════════════════════
    y -= 5 * mm
    card_h  = 20 * mm
    card_gap = 4 * mm
    kpis = [
        ("Total Gross Pay",        fmt(run.total_gross),               teal),
        ("Total Deductions",       fmt(run.total_deductions),          colors.HexColor("#EF4444")),
        ("Employer Contributions", fmt(run.total_employer_contribution), colors.HexColor("#F59E0B")),
        ("Net Payable",            fmt(run.total_net),                  teal_dark),
    ]
    card_w = (content_w - 3 * card_gap) / 4
    for i, (label, value, accent) in enumerate(kpis):
        cx = margin_l + i * (card_w + card_gap)
        # card background + border for clearer separation from the page
        c.setFillColor(slate_50)
        c.roundRect(cx, y - card_h + 4 * mm, card_w, card_h, 3, fill=True, stroke=False)
        c.setStrokeColor(slate_200)
        c.setLineWidth(0.4)
        c.roundRect(cx, y - card_h + 4 * mm, card_w, card_h, 3, fill=False, stroke=True)
        # accent stripe
        c.setFillColor(accent)
        c.roundRect(cx, y - card_h + 4 * mm, 3, card_h, 1.5, fill=True, stroke=False)
        # label
        c.setFillColor(slate_600)
        c.setFont(FB, 7)
        c.drawString(cx + 6 * mm, y - 0.5 * mm, label.upper())
        # value
        c.setFillColor(slate_800)
        c.setFont(FB, 13)
        c.drawString(cx + 6 * mm, y - 7.5 * mm, value)
        # employee count on first card — always the actual rendered row
        # count, never the (potentially stale) stored run.employee_count.
        if i == 0:
            c.setFillColor(slate_400)
            c.setFont(F, 6.5)
            c.drawString(cx + 6 * mm, y - 13 * mm, f"{len(items)} employees")

    y -= card_h + 5 * mm

    # ════════════════════════════════════════════════════════════════════
    # 3. EMPLOYEE BREAKDOWN TABLE
    # ════════════════════════════════════════════════════════════════════
    # Section title, with a short accent underline for clearer hierarchy
    # between the KPI cards above and the table below.
    c.setFillColor(slate_800)
    c.setFont(FB, 10.5)
    c.drawString(margin_l, y, "Employee Breakdown")
    c.setStrokeColor(teal)
    c.setLineWidth(1.2)
    c.line(margin_l, y - 2 * mm, margin_l + 22 * mm, y - 2 * mm)
    # Enough clearance that the table's own teal header bar (drawn from
    # y - 1mm up to +hdr_h, i.e. ~5.5mm above whatever y is passed in) can't
    # collide with the title/underline above it — 5mm here left them
    # overlapping by ~2.5mm.
    y -= 11 * mm

    if items:
        # total_deductions is always attendance_deduction (LOP) plus exactly
        # these 7 employee-side statutory fields (see StandardStrategy.calculate
        # in engine/standard.py) — unused ones are simply 0 for a given
        # country, so subtracting all 7 universally (rather than only the
        # subset a given jurisdiction renders as its own columns) always
        # isolates just the LOP/attendance deduction, for every jurisdiction.
        def _other_deductions(it):
            total_ded = Decimal(str(it.total_deductions or 0))
            # Phase 8BX (real-UAT finding): this list previously omitted
            # church_tax/employee_lwf/employee_pension/study_loan_deduction/
            # postgrad_loan_deduction/cpp2/state_disability_insurance/
            # state_program_deductions — every one of them IS already
            # summed into total_deductions (engine/standard.py's
            # total_employee_deductions) and already rendered as its own
            # dedicated register column, so omitting them here double-
            # counted them into "Other Deductions" too. Caught because a
            # real Germany church-tax-liable employee's register row
            # didn't reconcile (Gross - every displayed column != Net Pay)
            # by exactly the church-tax amount. Now the complete field list
            # total_deductions is actually built from (attendance_deduction
            # is intentionally excluded — it's rendered as its own LOP line
            # item, never folded into this bucket).
            employee_statutory = sum(
                (Decimal(str(getattr(it, f, 0) or 0)) for f in
                 ("pf", "esi", "professional_tax", "employee_lwf", "tds", "social_security", "medicare",
                  "ni_employee", "study_loan_deduction", "postgrad_loan_deduction", "employee_pension",
                  "church_tax", "cpp2", "state_disability_insurance", "state_program_deductions")),
                Decimal("0"),
            )
            return total_ded - employee_statutory

        statutory_cols = _STATUTORY_COLUMNS_BY_COUNTRY.get(country, _DEFAULT_STATUTORY_COLUMNS)

        # Column definitions: (header, width_mm, getter, align).
        # align: "L" left (identity columns), "C" center (day counts),
        # "R" right (all monetary values).
        col_defs = [
            # Phase 8BU: each shaved 1mm (Employee 4mm) to make exactly
            # 12mm of room for the new Status column below without
            # exceeding content_w — these columns previously summed to
            # exactly content_w by design (see the Status column's own
            # comment).
            ("ID",         9,  lambda it: str(it.employee_id or "-"), "L"),
            ("Employee",   28, lambda it: str(it.employee_name or "-")[:28], "L"),
            ("Paid Days",  11, lambda it: f"{float(it.payable_days or 0):.1f}", "C"),
            ("LOP Days",   11, lambda it: f"{max(float(it.total_working_days or 0) - float(it.payable_days or 0), 0):.1f}", "C"),
            ("Basic",      16, lambda it: fmt(it.basic_salary), "R"),
            ("HRA",        14, lambda it: fmt(it.hra), "R"),
            ("Spl. Allow", 16, lambda it: fmt(it.special_allowance), "R"),
            ("Overtime",   12, lambda it: fmt(it.overtime), "R"),
            ("Addl. Comp", 14, lambda it: fmt(it.additional_compensation), "R"),
            ("Gross",      17, lambda it: fmt(it.gross_pay), "R"),
            *[
                (label, width, (lambda it, f=field: _statutory_cell_text(it, f, fmt)), "R")
                for label, field, width in statutory_cols
            ],
            ("Other Ded.", 15, lambda it: fmt(_other_deductions(it)), "R"),
            ("Net Salary", 19, lambda it: _net_salary_cell_text(it, fmt), "R"),
            # Phase 8BU: makes a BLOCKED/PARTIAL row's all-zero or
            # partially-zero figures legible at a glance instead of
            # reading as an ordinary fully-calculated employee. 12mm,
            # matching exactly what was shaved off the columns above.
            ("Status", 12, lambda it: {"Failed": "BLOCKED", "Partial": "PARTIAL"}.get(it.status, ""), "C"),
        ]

        col_x = [margin_l]
        for _, w, _, _ in col_defs:
            col_x.append(col_x[-1] + w * mm)

        row_h   = 5.6 * mm
        hdr_h   = 6.5 * mm
        bottom_limit = 38 * mm  # reserve space for sign-off block

        def _draw_table_header(c, cx, y_pos):
            """Draw the header row with teal background."""
            c.setFillColor(teal)
            c.roundRect(margin_l, y_pos - 1 * mm, content_w, hdr_h, 2, fill=True, stroke=False)
            c.setFillColor(white)
            c.setFont(FB, 6.2)
            for i, (hdr, _, _, align) in enumerate(col_defs):
                if align == "R":
                    c.drawRightString(cx[i + 1] - 1.5 * mm, y_pos + 1.3 * mm, hdr)
                elif align == "C":
                    c.drawCentredString((cx[i] + cx[i + 1]) / 2, y_pos + 1.3 * mm, hdr)
                else:
                    c.drawString(cx[i] + 1.5 * mm, y_pos + 1.3 * mm, hdr)
            _draw_col_separators(cx, y_pos - 1 * mm + hdr_h, hdr_h, color=colors.HexColor("#0B5F58"))
            return y_pos - hdr_h - 1 * mm

        y = _draw_table_header(c, col_x, y)

        # Data rows
        c.setFont(F, 6.0)
        row_idx = 0
        for item in items:
            if y < bottom_limit:
                if evaluation:
                    _draw_evaluation_watermark(c, width, height, F)
                c.showPage()
                y = height - 18 * mm
                y = _draw_table_header(c, col_x, y)
                c.setFont(F, 6.0)

            # Alternating row background
            if row_idx % 2 == 0:
                c.setFillColor(slate_50)
                c.rect(margin_l, y - 1.5 * mm, content_w, row_h, fill=True, stroke=False)

            c.setFillColor(slate_800)
            for i, (_, _, getter, align) in enumerate(col_defs):
                text = getter(item)
                if align == "R":
                    c.drawRightString(col_x[i + 1] - 1.5 * mm, y, text)
                elif align == "C":
                    c.drawCentredString((col_x[i] + col_x[i + 1]) / 2, y, text)
                else:
                    c.drawString(col_x[i] + 1.5 * mm, y, text)

            _draw_col_separators(col_x, y - 1.5 * mm + row_h, row_h)
            y -= row_h
            row_idx += 1

        # ── Totals / summary box — bordered and set apart from the data
        # rows with a heavier top rule, so it reads as a distinct summary
        # rather than just another table row. ──
        y -= 1 * mm
        c.setStrokeColor(teal)
        c.setLineWidth(1)
        c.line(margin_l, y - 1.5 * mm + row_h + 1 * mm, margin_r, y - 1.5 * mm + row_h + 1 * mm)
        c.setFillColor(slate_100)
        c.rect(margin_l, y - 1.5 * mm, content_w, row_h + 1 * mm, fill=True, stroke=False)
        c.setStrokeColor(slate_400)
        c.setLineWidth(0.4)
        c.rect(margin_l, y - 1.5 * mm, content_w, row_h + 1 * mm, fill=False, stroke=True)
        _draw_col_separators(col_x, y - 1.5 * mm + row_h + 1 * mm, row_h + 1 * mm, color=slate_400)
        c.setFillColor(slate_800)
        c.setFont(FB, 6.2)
        c.drawString(col_x[0] + 1.5 * mm, y, "TOTALS")

        # Summed in Decimal (matching _recompute_run_aggregates) rather than
        # float, so this row can't drift by a cent from the KPI cards above
        # on larger runs. Keyed by column label — not position — so it
        # can't silently misalign if columns are reordered later.
        def _dsum(attr):
            return sum((Decimal(str(getattr(it, attr, 0) or 0)) for it in items), Decimal("0"))

        total_other_ded = sum((_other_deductions(it) for it in items), Decimal("0"))

        totals_by_label = {
            "Basic": _dsum("basic_salary"), "HRA": _dsum("hra"), "Spl. Allow": _dsum("special_allowance"),
            "Overtime": _dsum("overtime"), "Addl. Comp": _dsum("additional_compensation"), "Gross": _dsum("gross_pay"),
            "Other Ded.": total_other_ded, "Net Salary": _dsum("net_pay"),
        }
        for label, field, _width in statutory_cols:
            totals_by_label[label] = _dsum(field)
        for i, (hdr, _, _, _align) in enumerate(col_defs):
            if hdr in totals_by_label:
                c.drawRightString(col_x[i + 1] - 1.5 * mm, y, fmt(totals_by_label[hdr]))

        y -= row_h + 4 * mm
    else:
        c.setFont(F, 8)
        c.setFillColor(slate_600)
        c.drawString(margin_l, y, "No payslip data available for this run.")
        y -= 10 * mm

    # ════════════════════════════════════════════════════════════════════
    # 4. SIGN-OFF BLOCK
    # ════════════════════════════════════════════════════════════════════
    # Always render at the bottom of the last page
    sign_y = 28 * mm
    line_w = 55 * mm

    c.setStrokeColor(slate_200)
    c.setLineWidth(0.5)
    c.line(margin_l, sign_y + 14 * mm, margin_r, sign_y + 14 * mm)

    c.setFillColor(slate_800)
    c.setFont(FB, 7)
    c.drawString(margin_l, sign_y + 8 * mm, "SIGN-OFF")
    c.setFont(F, 6)
    c.setFillColor(slate_600)
    c.drawString(margin_l, sign_y + 3 * mm,
                 f"Generated on {datetime.utcnow().strftime('%b %d, %Y at %H:%M UTC')}   |   "
                 f"Run ID: {run.id}   |   Period: {run.period_label}")

    # HR Manager signature
    c.setStrokeColor(slate_400)
    c.setLineWidth(0.4)
    c.line(margin_l, sign_y - 4 * mm, margin_l + line_w, sign_y - 4 * mm)
    c.setFillColor(slate_600)
    c.setFont(F, 6)
    c.drawString(margin_l, sign_y - 9 * mm, "HR Manager")
    c.setFont(F, 5.5)
    c.drawString(margin_l, sign_y - 13 * mm, "Signature & Date")

    # Finance Director signature
    sig2_x = margin_l + content_w / 2 + 10 * mm
    c.line(sig2_x, sign_y - 4 * mm, sig2_x + line_w, sign_y - 4 * mm)
    c.setFillColor(slate_600)
    c.setFont(F, 6)
    c.drawString(sig2_x, sign_y - 9 * mm, "Finance Director")
    c.setFont(F, 5.5)
    c.drawString(sig2_x, sign_y - 13 * mm, "Signature & Date")

    # ── Footer ──
    c.setFillColor(slate_400)
    c.setFont(F, 5)
    c.drawCentredString(width / 2, 6 * mm, "Confidential — For Internal Use Only")

    if evaluation:
        _draw_evaluation_watermark(c, width, height, F)

    c.save()
    return buf.getvalue()


def generate_report_csv_bytes(db: Session, report_id: int, organization_id: int = None) -> bytes:
    """Generate a CSV summary of a payroll run report — statutory columns
    match the jurisdiction-specific set used by generate_report_pdf_bytes
    (same _STATUTORY_COLUMNS_BY_COUNTRY mapping) so the two exports never
    disagree about which columns represent a given country's payroll."""
    import csv
    import io

    run = _get_report_run(db, report_id, organization_id)
    items = run.payslip_items or []

    # None when nothing is configured anywhere — .get() below already
    # falls back to the generic statutory-column set for any unrecognized
    # (including None) key, so this correctly avoids showing India-specific
    # columns (PF/ESI/PT) on an unconfigured org's compliance export.
    country = _resolve_org_country(db, organization_id)
    statutory_cols = _STATUTORY_COLUMNS_BY_COUNTRY.get(country, _DEFAULT_STATUTORY_COLUMNS)

    def _other_deductions(it):
        total_ded = Decimal(str(it.total_deductions or 0))
        # Phase 8BX: same double-counting fix as generate_report_pdf_bytes's
        # own _other_deductions — see that copy's comment for the full
        # account (a real church-tax-liable employee's CSV row previously
        # failed to reconcile Gross-to-Net by exactly the church-tax amount).
        employee_statutory = sum(
            (Decimal(str(getattr(it, f, 0) or 0)) for f in
             ("pf", "esi", "professional_tax", "employee_lwf", "tds", "social_security", "medicare",
              "ni_employee", "study_loan_deduction", "postgrad_loan_deduction", "employee_pension",
              "church_tax", "cpp2", "state_disability_insurance", "state_program_deductions")),
            Decimal("0"),
        )
        return total_ded - employee_statutory

    buf = io.StringIO()
    writer = csv.writer(buf)
    writer.writerow(
        ["Employee", "Department", "Gross Pay"]
        + [label for label, _field, _width in statutory_cols]
        + ["Other Deductions", "Net Pay", "Status"]
    )
    csv_fmt = lambda v: float(v)
    for item in items:
        writer.writerow(
            [item.employee_name, item.department or "", float(item.gross_pay or 0)]
            + [_statutory_cell_text(item, field, csv_fmt) for _label, field, _width in statutory_cols]
            + [float(_other_deductions(item)), _net_salary_cell_text(item, csv_fmt),
               {"Failed": "BLOCKED", "Partial": "PARTIAL"}.get(item.status, "")]
        )
    return buf.getvalue().encode("utf-8")


# ── Dashboard ──────────────────────────────────────────────────────────

def get_dashboard_summary(db: Session, organization_id: int = None, year: int = None, month: int = None) -> dict:
    employees_query = db.query(PayrollEmployee).filter(PayrollEmployee.organization_id == organization_id)

    headcount = employees_query.count()
    active_count = employees_query.filter(PayrollEmployee.status == EmployeeStatus.ACTIVE).count()
    on_leave_count = employees_query.filter(PayrollEmployee.status == EmployeeStatus.ON_LEAVE).count()
    inactive_count = employees_query.filter(PayrollEmployee.status == EmployeeStatus.INACTIVE).count()

    now = datetime.utcnow()

    def _month_sum(field, start, end=None):
        q = db.query(sa_func.coalesce(sa_func.sum(field), 0)).filter(PayrollRun.period_start >= start)
        if end:
            q = q.filter(PayrollRun.period_start < end)
        if organization_id is not None:
            q = q.filter(PayrollRun.organization_id == organization_id)
        return q.scalar() or Decimal("0")

    def _pending_count(start, end):
        pq = db.query(PayrollRun).filter(
            PayrollRun.period_start >= start,
            PayrollRun.period_start < end,
            PayrollRun.status.in_([PayrollStatus.REVIEW, PayrollStatus.APPROVED, PayrollStatus.AUTHORIZED]),
        )
        pq = _apply_org_filter(pq, PayrollRun, organization_id)
        return pq.count()

    if year and month:
        this_month_start = date(year, month, 1)
        if month == 12:
            this_month_end = date(year + 1, 1, 1)
        else:
            this_month_end = date(year, month + 1, 1)
        if month == 1:
            prev_month_start = date(year - 1, 12, 1)
        else:
            prev_month_start = date(year, month - 1, 1)

        total_net = _month_sum(PayrollRun.total_net, this_month_start, this_month_end)
        total_gross = _month_sum(PayrollRun.total_gross, this_month_start, this_month_end)
        total_taxes = _month_sum(PayrollRun.total_taxes, this_month_start, this_month_end)
        prev_net = _month_sum(PayrollRun.total_net, prev_month_start, this_month_start)
        pending_approvals = _pending_count(this_month_start, this_month_end)

        change_pct = None
        if prev_net and prev_net > 0:
            change_pct = float(_round2((total_net - prev_net) / prev_net * 100))
    else:
        earliest_q = db.query(sa_func.min(PayrollRun.period_start))
        if organization_id is not None:
            earliest_q = earliest_q.filter(PayrollRun.organization_id == organization_id)
        earliest_date = earliest_q.scalar()

        if earliest_date:
            all_start = date(earliest_date.year, earliest_date.month, 1)
        else:
            all_start = date(now.year, now.month, 1)
        all_end = date(now.year, now.month + 1, 1) if now.month < 12 else date(now.year + 1, 1, 1)

        total_net = _month_sum(PayrollRun.total_net, all_start, all_end)
        total_gross = _month_sum(PayrollRun.total_gross, all_start, all_end)
        total_taxes = _month_sum(PayrollRun.total_taxes, all_start, all_end)
        pending_approvals = _pending_count(all_start, all_end)
        change_pct = None

    return {
        "totalPayrollCost": total_net,
        "totalPayrollCostChangePct": change_pct,
        "totalGross": total_gross,
        "totalTaxes": total_taxes,
        "totalAttendanceDeduction": _compute_attendance_deductions(db, organization_id, year, month),
        "totalNet": total_net,
        "headcount": headcount,
        "activeCount": active_count,
        "onLeaveCount": on_leave_count,
        "inactiveCount": inactive_count,
        "pendingApprovals": pending_approvals,
    }


def _compute_attendance_deductions(db: Session, organization_id: int = None, year: int = None, month: int = None) -> Decimal:
    """Compute total attendance deductions across payslips.

    Summed entirely at the SQL level (a single COALESCE/SUM over the stored
    attendance_deduction column) instead of pulling every PayslipItem row
    into Python and looping — this ran on every Dashboard poll tick (every
    30s per open tab) and, with no month filter ("All Months"), scaled
    linearly with the total number of payslips ever generated.

    Previously this reconstructed the total from the payable_days /
    total_working_days proration ratio (full_x − x, where full_x = x /
    (payable_days / total_working_days)). That reconstruction only equaled
    the real deductions while total_working_days was hard-coded to 30;
    with calendar-length (28/29/30/31) periods it would drift. The stored
    attendance_deduction is the actual amount that reduced net pay, so it
    is the exact, stable source.
    """
    q = db.query(sa_func.coalesce(sa_func.sum(PayslipItem.attendance_deduction), 0)).select_from(PayslipItem).join(
        PayrollRun, PayslipItem.payroll_run_id == PayrollRun.id
    )
    q = _apply_org_filter(q, PayslipItem, organization_id)
    if year and month:
        month_start = date(year, month, 1)
        if month == 12:
            month_end = date(year + 1, 1, 1)
        else:
            month_end = date(year, month + 1, 1)
        q = q.filter(PayrollRun.period_start >= month_start, PayrollRun.period_start < month_end)
    total = q.scalar() or Decimal("0")
    return _round2(Decimal(str(total)))


def get_dashboard_trend(db: Session, organization_id: int = None, months: int = 6, year: int = None, month: int = None) -> List[dict]:
    if year and month:
        start_m = month - months + 1
        start_y = year
        while start_m <= 0:
            start_m += 12
            start_y -= 1
        end_m = month + 1
        end_y = year
        while end_m > 12:
            end_m -= 12
            end_y += 1
        window_start = date(start_y, start_m, 1)
        window_end = date(end_y, end_m, 1)
    else:
        now = datetime.utcnow()
        earliest_q = db.query(sa_func.min(PayrollRun.period_start))
        if organization_id is not None:
            earliest_q = earliest_q.filter(PayrollRun.organization_id == organization_id)
        earliest_date = earliest_q.scalar()
        if earliest_date:
            window_start = date(earliest_date.year, earliest_date.month, 1)
        else:
            window_start = date(now.year, now.month, 1)
        window_end = date(now.year, now.month + 1, 1) if now.month < 12 else date(now.year + 1, 1, 1)

    query = db.query(
        sa_func.extract("year", PayrollRun.period_start).label("y"),
        sa_func.extract("month", PayrollRun.period_start).label("m"),
        sa_func.coalesce(sa_func.sum(PayrollRun.total_gross), 0).label("gross"),
        sa_func.coalesce(sa_func.sum(PayrollRun.total_net), 0).label("net"),
    )
    query = _apply_org_filter(query, PayrollRun, organization_id)
    query = query.filter(PayrollRun.period_start >= window_start, PayrollRun.period_start < window_end)
    rows = query.group_by(
        sa_func.extract("year", PayrollRun.period_start),
        sa_func.extract("month", PayrollRun.period_start),
    ).order_by(
        sa_func.extract("year", PayrollRun.period_start),
        sa_func.extract("month", PayrollRun.period_start),
    ).all()

    buckets = {(int(r.y), int(r.m)): {"gross": Decimal(str(r.gross)), "net": Decimal(str(r.net))} for r in rows}

    ordered_keys = sorted(buckets.keys())

    return [
        {
            "month": f"{month_name[m][:3]} {y}",
            "gross": buckets[(y, m)]["gross"],
            "net": buckets[(y, m)]["net"],
        }
        for (y, m) in ordered_keys
    ]


def get_recent_activity(db: Session, organization_id: int = None, limit: int = 20, year: int = None, month: int = None) -> List[dict]:
    query = db.query(PayrollActivityLog)
    query = _apply_org_filter(query, PayrollActivityLog, organization_id)
    if year and month:
        month_start = date(year, month, 1)
        if month == 12:
            month_end = date(year + 1, 1, 1)
        else:
            month_end = date(year, month + 1, 1)
        query = query.filter(PayrollActivityLog.created_at >= month_start, PayrollActivityLog.created_at < month_end)
    rows = query.order_by(PayrollActivityLog.created_at.desc()).limit(limit).all()
    return [
        {
            "id": str(row.id),
            "description": row.description,
            "timestamp": row.created_at,
            "status": row.status,
        }
        for row in rows
    ]


def get_dashboard_breakdowns(db: Session, organization_id: int = None, year: int = None, month: int = None) -> dict:
    """Return department, pay-type, and deduction breakdowns from payslip data.

    All sums are computed at the SQL level (GROUP BY / SUM over 2 queries)
    instead of pulling every PayslipItem row into Python and looping over it
    ~13 times — this ran on every Dashboard poll tick (every 30s per open
    tab) and, with no month filter ("All Months"), scaled linearly with the
    total number of payslips ever generated.
    """
    def _scoped(query):
        query = _apply_org_filter(query, PayslipItem, organization_id)
        if year and month:
            month_start = date(year, month, 1)
            month_end = date(year + 1, 1, 1) if month == 12 else date(year, month + 1, 1)
            query = query.filter(PayrollRun.period_start >= month_start, PayrollRun.period_start < month_end)
        return query

    def _joined(cols):
        return db.query(*cols).select_from(PayslipItem).join(PayrollRun, PayslipItem.payroll_run_id == PayrollRun.id)

    # Department breakdown
    dept_col = sa_func.coalesce(PayslipItem.department, "Unassigned")
    dept_rows = _scoped(
        _joined([dept_col.label("dept"), sa_func.coalesce(sa_func.sum(PayslipItem.gross_pay), 0).label("total")])
    ).group_by(dept_col).all()
    dept_map = {row.dept: Decimal(str(row.total)) for row in dept_rows}
    total_gross_all = sum(dept_map.values(), Decimal("0")) or Decimal("1")
    by_department = sorted(
        [{"name": k, "value": round(float(v / total_gross_all * 100), 1), "amount": float(v)}
         for k, v in dept_map.items()],
        key=lambda x: x["value"], reverse=True,
    )

    # Pay-type and deduction sums — a single aggregate row, no per-row loop
    sum_cols = [
        "basic_salary", "hra", "special_allowance", "overtime", "additional_compensation",
        "attendance_deduction", "tds", "pf", "esi", "professional_tax",
        "social_security", "medicare", "ni_employee",
        "federal_income_tax", "state_income_tax", "local_tax",
    ]
    agg_row = _scoped(
        _joined([sa_func.coalesce(sa_func.sum(getattr(PayslipItem, c)), 0).label(c) for c in sum_cols])
    ).first()
    totals = (
        {c: Decimal(str(getattr(agg_row, c))) for c in sum_cols}
        if agg_row else {c: Decimal("0") for c in sum_cols}
    )

    pay_types = [
        {"name": "Basic Salary", "value": float(totals["basic_salary"])},
        {"name": "HRA", "value": float(totals["hra"])},
        {"name": "Special Allowance", "value": float(totals["special_allowance"])},
    ]
    if totals["overtime"] > 0:
        pay_types.append({"name": "Overtime", "value": float(totals["overtime"])})
    if totals["additional_compensation"] > 0:
        pay_types.append({"name": "Additional", "value": float(totals["additional_compensation"])})

    # Attendance deductions — use the stored attendance_deduction column
    total_att_ded = totals["attendance_deduction"]
    attendance_deductions = []
    if total_att_ded > 0:
        attendance_deductions.append({"name": "LOP Deduction", "total": float(total_att_ded)})

    # Also include statutory deductions for reference. Every jurisdiction routes
    # its withholding through the same fields (tds, pf, esi — India-named
    # historically), so label them per the company's jurisdiction country, the
    # same way generate_payslip_pdf_bytes() does, to avoid showing e.g. a
    # German company's Lohnsteuer/pension/social-insurance totals under Indian
    # statutory names.
    company = db.query(CompanyComplianceDetails).filter(
        CompanyComplianceDetails.organization_id == organization_id
    ).first() if organization_id else None
    country = _normalize_country(getattr(company, "jurisdiction_country", None) or "IN")
    income_tax_labels = {
        "IN": "TDS", "US": "Federal Withholding", "UK": "PAYE",
        "AU": "PAYG", "DE": "Lohnsteuer", "CA": "Federal Tax",
        # Ireland (ZP-IE-ENG-001) — mirrors generate_payslip_pdf_bytes's own
        # label map above.
        "IE": "PAYE", "FR": "Prélèvement à la Source",
        # Caribbean production jurisdictions (ZP-MJR-2026-002, 2026-09-24) —
        # mirrors generate_payslip_pdf_bytes's own label map. Bahamas/Cayman
        # have no entry: `tds` is always 0 for both (no personal income
        # tax), so income_tax_labels.get(country, "TDS") is never reached
        # with a nonzero value for them.
        "BB": "PAYE", "DO": "ISR", "GY": "PAYE", "JM": "PAYE", "TT": "PAYE",
        "PR": "Hacienda Withholding",
    }
    pf_esi_labels = {
        "DE": {"pf": "Pension Insurance", "esi": "Social Insurance (Health / Unemployment / Care)"},
        "CA": {"esi": "Employment Insurance (EI)"},
    }.get(country, {})
    other_labels = {
        "CA": "Canada Pension Plan (CPP)",
        "AU": None,  # AU's "medicare" label is handled separately below
        "BB": "NIS", "DO": "SFS (Seguro Familiar de Salud)", "GY": "NIS",
        "JM": "NIS", "TT": "NIS", "BS": "NIB", "KY": "NIB Pension",
    }.get(country)
    ni_employee_label = "Education Tax" if country == "JM" else "National Insurance"
    professional_tax_label = "Health Surcharge" if country == "TT" else "Professional Tax"
    medicare_label = "Medicare Levy" if country == "AU" else "Medicare"
    # US: federal/state/local shown as three separate slices instead of one
    # combined "Federal Withholding" total — falls back to the combined
    # `tds` figure when the split is all-zero (a US org with no payslips
    # generated under this feature yet), same rule generate_payslip_pdf_bytes
    # and jurisdictionLabels.js's getIncomeTaxLines already use.
    us_split_total = totals["federal_income_tax"] + totals["state_income_tax"] + totals["local_tax"]
    if country == "US" and us_split_total > 0:
        income_tax_fields = [
            ("Federal Withholding", "federal_income_tax"),
            ("State Tax", "state_income_tax"),
            ("Local Tax", "local_tax"),
        ]
    else:
        income_tax_fields = [(income_tax_labels.get(country, "TDS"), "tds")]
    deduction_fields = [
        *income_tax_fields,
        (pf_esi_labels.get("pf", "Provident Fund (PF)"), "pf"),
        (pf_esi_labels.get("esi", "Employee State Insurance (ESI)"), "esi"),
        (professional_tax_label, "professional_tax"),
        (other_labels or "Social Security", "social_security"),
        (medicare_label, "medicare"),
        (ni_employee_label, "ni_employee"),
    ]
    stat_deductions = []
    total_stat_ded = Decimal("0")
    for label, field in deduction_fields:
        total_val = totals[field]
        if total_val > 0:
            stat_deductions.append({"name": label, "total": float(total_val)})
            total_stat_ded += total_val
    
    # Combine: attendance deductions first, then statutory
    all_deductions = attendance_deductions + stat_deductions
    total_ded_all = total_att_ded + total_stat_ded
    for d in all_deductions:
        d["pct"] = round(d["total"] / float(total_ded_all or 1) * 100, 1)

    return {
        "byDepartment": by_department,
        "payTypes": pay_types,
        "deductions": all_deductions,
    }


# ── Leave Allocations ─────────────────────────────────────────────────────

def _enrich_leave_allocation(db: Session, record: PayrollLeaveAllocation, organization_id: int) -> dict:
    emp = _apply_employee_filter(
        db.query(PayrollEmployee).filter(PayrollEmployee.id == record.employee_id),
        organization_id,
    ).first()
    return {
        "id": record.id,
        "employeeId": record.employee_id,
        "employeeName": emp.name if emp else None,
        "department": emp.department if emp else None,
        "leaveBalances": record.leave_balances or {},
        "periodLabel": record.period_label,
        "notes": record.notes,
        "createdAt": record.created_at,
        "updatedAt": record.updated_at,
    }


def bulk_save_leaves(db: Session, data, organization_id: int) -> List[dict]:
    results = []
    for item in data.records:
        payload = item.model_dump()
        employee_id = payload.pop("employeeId")
        leave_balances = payload.pop("leaveBalances", None)
        mapped = {
            "leave_balances": leave_balances,
            "period_label": payload.pop("periodLabel", None),
            "notes": payload.pop("notes", None),
        }

        existing = db.query(PayrollLeaveAllocation).filter(
            PayrollLeaveAllocation.organization_id == organization_id,
            PayrollLeaveAllocation.employee_id == employee_id,
        ).first()

        if existing:
            for field, value in mapped.items():
                if value is not None or field != "leave_balances":
                    setattr(existing, field, value)
            record = existing
        else:
            record = PayrollLeaveAllocation(
                organization_id=organization_id,
                employee_id=employee_id,
                **mapped,
            )
            db.add(record)

        results.append(record)

    db.commit()
    for r in results:
        db.refresh(r)
    return [_enrich_leave_allocation(db, r, organization_id) for r in results]


def get_leave_allocations(
    db: Session,
    organization_id: int,
    *,
    employee_id: Optional[int] = None,
) -> List[dict]:
    _backfill_orphaned_leave_syncs(db, organization_id)
    _dedupe_auto_created_leave_requests(db, organization_id)
    _recompute_leave_balances_used(db, organization_id)

    query = db.query(
        PayrollLeaveAllocation,
        PayrollEmployee.name,
        PayrollEmployee.department,
    ).outerjoin(
        PayrollEmployee,
        (PayrollLeaveAllocation.employee_id == PayrollEmployee.id) &
        (PayrollEmployee.organization_id == organization_id)
    ).filter(
        PayrollLeaveAllocation.organization_id == organization_id
    )
    if employee_id:
        query = query.filter(PayrollLeaveAllocation.employee_id == employee_id)

    rows = query.all()
    return [
        {
            "id": record.id,
            "employeeId": record.employee_id,
            "employeeName": name,
            "department": department,
            "leaveBalances": record.leave_balances or {},
            "periodLabel": record.period_label,
            "notes": record.notes,
            "createdAt": record.created_at,
            "updatedAt": record.updated_at,
        }
        for record, name, department in rows
    ]


def reset_leave_allocations(db: Session, organization_id: int) -> dict:
    """Set every employee's leave balances to empty and delete leave-only attendance records."""
    leaves_reset = db.query(PayrollLeaveAllocation).filter(
        PayrollLeaveAllocation.organization_id == organization_id,
    ).update({"leave_balances": {}}, synchronize_session=False)

    attendance_deleted = db.query(PayrollAttendanceRecord).filter(
        PayrollAttendanceRecord.organization_id == organization_id,
        PayrollAttendanceRecord.status == "leave",
    ).delete(synchronize_session=False)

    db.commit()

    try:
        log_activity(db, organization_id, f"Leave allocations reset for {leaves_reset} employees; {attendance_deleted} leave attendance record(s) cleared.", ActivityStatus.INFO)
    except Exception:
        pass

    return {"leavesReset": leaves_reset, "attendanceCleared": attendance_deleted}


# ── Leave Requests ─────────────────────────────────────────────────────

def _enrich_leave_request(db: Session, record: PayrollLeaveRequest, organization_id: int) -> dict:
    emp = _apply_employee_filter(
        db.query(PayrollEmployee).filter(PayrollEmployee.id == record.employee_id),
        organization_id,
    ).first()
    linked_dates = [
        r.date for r in db.query(PayrollAttendanceRecord.date).filter(
            PayrollAttendanceRecord.leave_request_id == record.id,
        ).all()
    ]
    return {
        "id": record.id,
        "employeeId": record.employee_id,
        "employeeName": emp.name if emp else None,
        "department": emp.department if emp else None,
        "leaveType": record.leave_type,
        "startDate": record.start_date,
        "endDate": record.end_date,
        "days": record.days,
        "reason": record.reason,
        "status": record.status,
        "reviewedBy": record.reviewed_by,
        "reviewedAt": record.reviewed_at,
        "source": record.source,
        "createdAt": record.created_at,
        "updatedAt": record.updated_at,
        "linkedAttendanceDates": [str(d) for d in sorted(linked_dates)],
        "isAutoCreated": record.reason == "Auto-created from attendance",
        "statutoryPayType": record.statutory_pay_type,
        "statutoryAweSnapshot": record.statutory_awe_snapshot,
        "statutoryPayTotalAmount": record.statutory_pay_total_amount,
        "statutoryPayNote": record.statutory_pay_note,
        # Irish statutory sick pay is assessed into its own IE-037 ledger row
        # rather than these UK-shaped columns, so it is surfaced as a nested
        # summary. Absent (null) whenever no assessment exists — which is every
        # country other than Ireland, and Ireland while the G5 rollout switch is
        # off. Never defaulted to zeros, so "not assessed" stays distinguishable
        # from "assessed and nothing was owed".
        "ireStatutorySickLeave": _ie_sick_leave_summary(db, record),
    }


def _ie_sick_leave_summary(db: Session, record: PayrollLeaveRequest) -> Optional[dict]:
    """The IE-037 assessment for a leave request, as a read model for the Leave
    Management screen. Returns None when no assessment row exists.

    Deliberately read-only: it reports what was assessed and why, and does not
    re-derive any of it. A claim's amount is frozen at approval time, so this
    must never recompute it from today's rate pack (the same rule
    IrelandRpnSnapshot and PayslipItem.ie_calculation_snapshot follow).
    """
    row = db.query(IrelandStatutorySickLeaveRecord).filter(
        IrelandStatutorySickLeaveRecord.leave_request_id == record.id,
    ).order_by(IrelandStatutorySickLeaveRecord.id.desc()).first()
    if row is None:
        return None
    return {
        "id": row.id,
        "calendarYear": row.calendar_year,
        "absenceStartDate": row.absence_start_date,
        "absenceEndDate": row.absence_end_date,
        "daysClaimed": row.days_claimed,
        "daysCredited": row.days_credited,
        "daysDisallowed": row.days_disallowed,
        "daysTakenBefore": row.days_taken_before,
        "entitlementDays": row.entitlement_days,
        "entitlementRemainingAfter": row.entitlement_remaining_after,
        "pctApplied": row.pct_applied,
        "dailyCap": row.daily_cap,
        "usualDailyEarnings": row.usual_daily_earnings,
        "dailyRateBeforeCap": row.daily_rate_before_cap,
        "dailyRate": row.daily_rate,
        "capApplied": row.cap_applied,
        "amount": row.amount,
        "serviceStartDate": row.service_start_date,
        "serviceWeeksActual": row.service_weeks_actual,
        "serviceWeeksRequired": row.service_weeks_required,
        "serviceQualified": row.service_qualified,
        "certified": row.certified,
        "eligible": row.eligible,
        "reason": row.reason,
        "status": row.status,
    }


def create_payroll_leave_request(db: Session, data, organization_id: int) -> dict:
    start = data.startDate if hasattr(data, "startDate") else data.start_date
    end = data.endDate if hasattr(data, "endDate") else data.end_date
    days = (end - start).days + 1

    record = PayrollLeaveRequest(
        organization_id=organization_id,
        employee_id=data.employeeId if hasattr(data, "employeeId") else data.employee_id,
        leave_type=data.leaveType if hasattr(data, "leaveType") else data.leave_type,
        start_date=start,
        end_date=end,
        days=max(1, days),
        reason=data.reason if hasattr(data, "reason") else None,
        status="pending",
        source=data.source if hasattr(data, "source") else "manual",
    )
    if organization_id is not None:
        from app.core.code_generation import generate_business_code
        record.request_code = generate_business_code(db, organization_id, "LV", PayrollLeaveRequest, "request_code")
    db.add(record)
    db.commit()
    db.refresh(record)
    _notify_leave_request_submitted(db, record, organization_id)

    try:
        log_activity(db, organization_id, f"Leave request submitted by employee {record.employee_id} ({record.leave_type}, {record.days}d).", ActivityStatus.INFO)
    except Exception:
        pass

    # Notify the org's payroll administrator so the request actually gets
    # reviewed (best-effort — see _notify_leave_request_submitted). Status
    # emails (approved / rejected) are reserved for review_payroll_leave_request.

    return _enrich_leave_request(db, record, organization_id)


def get_payroll_leave_requests(db: Session, organization_id: int, *, employee_id=None, status=None, leave_type=None) -> list:
    _backfill_orphaned_leave_syncs(db, organization_id)
    _dedupe_auto_created_leave_requests(db, organization_id)

    query = db.query(PayrollLeaveRequest).filter(
        PayrollLeaveRequest.organization_id == organization_id,
    )
    if employee_id:
        query = query.filter(PayrollLeaveRequest.employee_id == employee_id)
    if status:
        query = query.filter(PayrollLeaveRequest.status == status)
    if leave_type:
        query = query.filter(PayrollLeaveRequest.leave_type == leave_type)

    rows = query.order_by(PayrollLeaveRequest.created_at.desc()).all()
    return [_enrich_leave_request(db, r, organization_id) for r in rows]


# ── UK Statutory Family Pay wired into real leave requests (§11) ────────
# (ZP-TAX-UK-2026-27-001 gap-closure Part 7A, 2026-09-09). Maps the
# business-language leave_type values a leave request already uses onto
# the HMRC payment-type codes calculate_uk_statutory_pay() (Phase 5)
# expects. Deliberately new string keys — none collide with any other
# country's existing leave_type values ("paid"/"unpaid"/"sick"/"compOff").
_UK_LEAVE_TYPE_TO_STATUTORY_PAY_TYPE = {
    "maternity": "SMP",
    "paternity": "SPP",
    "adoption": "SAP",
    "sharedParental": "SHPP",
    "bereavement": "SPBP",
    "neonatal": "SNCP",
}


def _uk_statutory_pay_for_period(db: Session, employee_id: int, organization_id: int, period_start, period_end) -> Decimal:
    """Reads the frozen statutory_pay_total_amount from any APPROVED
    statutory leave request for this employee whose own [start_date,
    end_date] overlaps [period_start, period_end], pro-rated by how many
    of the leave's own days fall inside this specific pay period. This is
    what actually makes an approved statutory leave request show up on
    the employee's NEXT normal payslip without a payroll processor
    manually applying anything — called from _compute_payslip_values/
    preview_payroll_run, gated behind the same switch as the freeze step.

    Deliberate simplification, disclosed: pro-rating by calendar days
    (not by which HMRC claim-week each day falls in) is an approximation
    when a pay period boundary falls mid-week — the frozen total is
    always correct in aggregate across the whole claim, this only affects
    how it's SPLIT between consecutive pay periods."""
    if period_start is None or period_end is None:
        return Decimal("0")
    rows = db.query(PayrollLeaveRequest).filter(
        PayrollLeaveRequest.employee_id == employee_id,
        PayrollLeaveRequest.organization_id == organization_id,
        PayrollLeaveRequest.status == "approved",
        PayrollLeaveRequest.statutory_pay_total_amount.isnot(None),
        PayrollLeaveRequest.start_date <= period_end,
        PayrollLeaveRequest.end_date >= period_start,
    ).all()
    total = Decimal("0")
    for row in rows:
        overlap_start = max(row.start_date, period_start)
        overlap_end = min(row.end_date, period_end)
        overlap_days = (overlap_end - overlap_start).days + 1
        claim_days = (row.end_date - row.start_date).days + 1
        if overlap_days <= 0 or claim_days <= 0:
            continue
        total += Decimal(row.statutory_pay_total_amount) * overlap_days / claim_days
    return _round2(total)


def _maybe_compute_uk_statutory_leave_pay(db: Session, record: PayrollLeaveRequest, organization_id: int) -> None:
    """Called once, right after a leave request transitions to "approved".
    Computes AWE (Phase 4) as of the leave's own start_date, then sums
    calculate_uk_statutory_pay()'s per-week amount (Phase 5 — this reuses
    that exact calculator rather than re-deriving the SMP/SAP first-6-
    weeks rule a second time) across ceil(days/7) claim weeks, and
    freezes both the AWE and the total onto the record.

    No-ops silently (leaves every statutory_pay_* column NULL) when: the
    switch is off, this leave_type isn't one of the 6 statutory types, or
    the employee isn't UK — none of these are errors, they're just "this
    request has nothing to do with UK statutory pay."

    Stops accumulating at the FIRST week that fails closed (e.g. a rate
    that isn't configured) rather than silently under-crediting a partial
    total — statutory_pay_note carries that reason, statutory_pay_total_
    amount stays NULL (not a partial number that looks complete)."""
    if "UK" not in _UK_STATUTORY_LEAVE_PAY_ENABLED_COUNTRIES:
        return
    payment_type = _UK_LEAVE_TYPE_TO_STATUTORY_PAY_TYPE.get(record.leave_type)
    if not payment_type:
        return

    employee = db.query(PayrollEmployee).filter(
        PayrollEmployee.id == record.employee_id, PayrollEmployee.organization_id == organization_id,
    ).first()
    if not employee:
        return
    country = _resolve_employee_country(db, organization_id, getattr(employee, "country_code", None))
    if country != "UK":
        return

    weeks = max(1, (record.days + 6) // 7)
    awe = None
    total = Decimal("0")
    for week_number in range(1, weeks + 1):
        result = calculate_uk_statutory_pay(
            db, organization_id, record.employee_id, payment_type, record.start_date,
            week_number=week_number, average_weekly_earnings=awe,
        )
        if not result["eligible"]:
            record.statutory_pay_type = payment_type
            record.statutory_awe_snapshot = awe
            record.statutory_pay_total_amount = None
            record.statutory_pay_note = f"week {week_number}: {result['reason']}"
            return
        awe = result["average_weekly_earnings"]
        total += result["amount"]

    record.statutory_pay_type = payment_type
    record.statutory_awe_snapshot = awe
    record.statutory_pay_total_amount = _round2(total)
    record.statutory_pay_note = f"computed over {weeks} week(s)"


def _ie_rate_map_for_statutory_leave(db: Session, organization_id: int, as_of: date) -> dict:
    """Ireland's component-key -> rate row map for a LEAVE assessment on `as_of`.

    Deliberately NOT `_resolve_effective_rate_inputs()`. That function is the
    payroll calculation path and it ends in `_assert_jurisdiction_ready()`,
    which refuses to resolve unless the jurisdiction's tax SLABS are also
    configured. Statutory sick pay is an entitlement, not a tax computation: it
    depends only on the four ie_sick_leave_* rows, and demanding a signed
    income-tax slab table before an employer can have a sick day assessed would
    be a category error that also blocks the assessment for any employer who has
    not finished tax configuration.

    It still honours the same content resolution discipline as a real payroll
    run, so a claim is never decided against different content than the engine
    would have used: the canonical, date-effective pack wins when the org has
    opted into canonical tax packs, otherwise the org's own country-level rows
    are used (seeding the IE catalog on first access, as a payroll run would).
    """
    if _org_uses_canonical_tax_pack(db, organization_id):
        from app.modules.payroll.engine.tax_resolver import resolve_tax_configuration
        canonical_rates, _canonical_slabs, pack = resolve_tax_configuration(
            db, "IE", state=None, tax_regime=None, payroll_date=as_of,
        )
        if pack is not None and canonical_rates:
            return {
                _normalize_engine_component_key(r.component_key): r
                for r in canonical_rates
            }
    return {
        _normalize_engine_component_key(r.component_key): r
        for r in get_contribution_rates(db, organization_id, country="IE", payroll_date=as_of)
    }


def _ie_sick_days_taken_in_calendar_year(db: Session, employee_id: int, calendar_year: int,
                                         exclude_leave_request_id: Optional[int] = None) -> Decimal:
    """Days of Irish statutory sick entitlement already CREDITED for this
    employee in this calendar year (IE-037's calendar-year counter).

    Derived from the ledger rather than kept as a mutable running total, so the
    figure is reconstructable and cannot drift away from the records behind it.
    Reversed claims are excluded, because a withdrawn entitlement must return to
    the employee rather than stay consumed.

    REVERSED rows for the same request are excluded alongside the request's own
    prior assessment, so re-approving a request re-assesses it against the
    counter it would have seen the first time rather than against its own
    previous claim.
    """
    query = db.query(
        sa_func.coalesce(
            sa_func.sum(IrelandStatutorySickLeaveRecord.days_credited), 0
        )
    ).filter(
        IrelandStatutorySickLeaveRecord.employee_id == employee_id,
        IrelandStatutorySickLeaveRecord.calendar_year == int(calendar_year),
        IrelandStatutorySickLeaveRecord.status != "REVERSED",
    )
    if exclude_leave_request_id is not None:
        query = query.filter(IrelandStatutorySickLeaveRecord.leave_request_id != exclude_leave_request_id)
    total = query.scalar()
    return Decimal(str(total if total is not None else 0))


def _ie_usual_daily_earnings(db: Session, employee_id: int, as_of: date) -> Optional[Decimal]:
    """Usual daily earnings for a sick claim: gross actually PAID on this
    employee's most recent paid payslip, divided by the calendar days from that
    pay date to the absence.

    Uses real paid payslips rather than the current contract salary, because
    statutory sick pay is defined on what the employee ordinarily earns over the
    pay period, not on salary annualised through the platform's fixed 30-day
    payroll model. Only PAID items count — a pending or failed payslip is not
    evidence of ordinary earnings.

    Returns None when there is no usable paid history, which the caller must
    treat as "not evidenced" — never as zero, which would silently assess 70%
    of nothing as a genuine entitlement.
    """
    row = (
        db.query(PayslipItem.gross_pay, PayrollRun.pay_date)
        .join(PayrollRun, PayrollRun.id == PayslipItem.payroll_run_id)
        .filter(
            PayslipItem.employee_id == employee_id,
            PayslipItem.status == PayslipStatus.PAID.value,
            PayrollRun.pay_date != None,  # noqa: E711 — SQLAlchemy needs the operator form
        )
        .order_by(PayrollRun.pay_date.desc(), PayslipItem.id.desc())
        .first()
    )
    if row is None:
        return None
    gross_pay, pay_date = row
    if not pay_date or as_of <= pay_date:
        return None
    covered_days = (as_of - pay_date).days
    if covered_days <= 0:
        return None
    gross = Decimal(str(gross_pay if gross_pay is not None else 0))
    if gross <= 0:
        return None
    return _round2(gross / Decimal(covered_days))


def _maybe_assess_ie_statutory_sick_leave(db: Session, record: PayrollLeaveRequest,
                                          organization_id: int) -> Optional[IrelandStatutorySickLeaveRecord]:
    """Called once, right after an Irish `sick` leave request is approved.

    Writes ONE IrelandStatutorySickLeaveRecord capturing the full IE-037
    evidence — absence dates, entitlement used, usual daily earnings, the rate
    before and after the cap, the service qualification, the certification
    state, and the reason for the outcome. Mirrors
    _maybe_compute_uk_statutory_leave_pay above: additive at approval time,
    frozen there and never recomputed, so a later rate update cannot rewrite a
    historic claim.

    Returns None (silently, leaving no record) when the switch is off, the
    leave type is not `sick`, or the employee is not Irish — none of these are
    errors, they just mean there is no Irish statutory sick pay to assess.

    The computed amount is recorded as EVIDENCE ONLY. It is deliberately not
    added to gross: see
    engine/countries/shared.py::_IE_STATUTORY_LEAVE_PAY_ENABLED_COUNTRIES for
    why the payroll mechanism waits behind G5.
    """
    if "IE" not in _IE_STATUTORY_LEAVE_PAY_ENABLED_COUNTRIES:
        return None
    if record.leave_type != "sick":
        return None

    from app.modules.payroll.engine.countries.ireland import (
        build_rate_pack,
        calculate_statutory_sick_pay,
    )

    employee = db.query(PayrollEmployee).filter(
        PayrollEmployee.id == record.employee_id, PayrollEmployee.organization_id == organization_id,
    ).first()
    if not employee:
        return None
    country = _resolve_employee_country(db, organization_id, getattr(employee, "country_code", None))
    if country != "IE":
        return None

    absence_start = record.start_date
    calendar_year = int(absence_start.year) if absence_start else None
    if calendar_year is None:
        return None

    try:
        ie_pack = build_rate_pack(
            _ie_rate_map_for_statutory_leave(db, organization_id, absence_start), organization_id,
        )
        taken_before = _ie_sick_days_taken_in_calendar_year(
            db, employee.id, calendar_year, exclude_leave_request_id=record.id,
        )
        assessment = calculate_statutory_sick_pay(
            pack=ie_pack,
            usual_daily_earnings=_ie_usual_daily_earnings(db, employee.id, absence_start),
            days_claimed=record.days,
            days_taken_in_calendar_year=taken_before,
            service_start_date=getattr(employee, "date_of_joining", None),
            absence_start_date=absence_start,
            absence_end_date=record.end_date,
            # Certification is a statutory CONDITION and there is no field on
            # the generic leave request to carry it. Until one exists the claim
            # is assessed as uncertified, which disallows the entitlement and
            # says so in the record — it is never assumed certified because the
            # absence was reported.
            certified=False,
        )
    except Exception:
        # A payroll run must not fail because signed sick-pay content is not
        # yet configured for this employer. The absence is still an approved
        # leave request and the attendance sync has already happened; the claim
        # simply is not assessed, and that silence is visible because no record
        # exists. Raising here would block an unrelated employee's payroll.
        import logging
        logging.getLogger("zoiko").warning(
            f"[payroll-leave] Ireland statutory sick pay assessment skipped for leave "
            f"request {record.id}: statutory content or evidence unavailable",
            exc_info=True,
        )
        return None

    row = IrelandStatutorySickLeaveRecord(
        organization_id=organization_id,
        employee_id=employee.id,
        leave_request_id=record.id,
        calendar_year=calendar_year,
        absence_start_date=absence_start,
        absence_end_date=record.end_date,
        days_claimed=Decimal(str(record.days or 0)),
        days_credited=assessment["days_credited"],
        days_disallowed=assessment["days_disallowed"],
        days_taken_before=taken_before,
        entitlement_remaining_after=max(
            Decimal("0"),
            assessment["entitlement_remaining_before"] - assessment["days_credited"],
        ),
        entitlement_days=assessment["entitlement_days"],
        pct_applied=assessment["pct_applied"],
        daily_cap=assessment["daily_cap"],
        usual_daily_earnings=assessment["usual_daily_earnings"] or None,
        daily_rate_before_cap=assessment["daily_rate_before_cap"] or None,
        daily_rate=assessment["daily_rate"] or None,
        cap_applied=bool(assessment["cap_applied"]),
        amount=assessment["amount"],
        service_start_date=getattr(employee, "date_of_joining", None),
        service_weeks_actual=assessment.get("service_weeks_actual"),
        service_weeks_required=assessment["service_weeks_required"],
        service_qualified=bool(assessment["service_weeks_satisfied"]),
        certified=bool(assessment["certified"]),
        eligible=bool(assessment["eligible"]),
        reason=assessment["reason"] or "allowed in full",
        status="ASSESSED",
    )
    db.add(row)
    db.flush()
    return row


def review_payroll_leave_request(db: Session, request_id: int, data, organization_id: int, reviewer_id: int) -> dict:
    record = db.query(PayrollLeaveRequest).filter(
        PayrollLeaveRequest.id == request_id,
        PayrollLeaveRequest.organization_id == organization_id,
    ).first()
    if not record:
        raise NotFoundException("PayrollLeaveRequest", request_id)

    prev_status = record.status
    new_status = data.status if hasattr(data, "status") else None

    if new_status and new_status in ("approved", "rejected"):
        record.status = new_status
        record.reviewed_by = reviewer_id
        record.reviewed_at = datetime.utcnow()

    # Update leave allocation balances when approved
    if record.status == "approved" and prev_status != "approved":
        _sync_leave_to_attendance(db, record, organization_id)
        _maybe_compute_uk_statutory_leave_pay(db, record, organization_id)
        _maybe_assess_ie_statutory_sick_leave(db, record, organization_id)
        alloc = db.query(PayrollLeaveAllocation).filter(
            PayrollLeaveAllocation.organization_id == organization_id,
            PayrollLeaveAllocation.employee_id == record.employee_id,
        ).first()
        if not alloc:
            alloc = PayrollLeaveAllocation(
                organization_id=organization_id,
                employee_id=record.employee_id,
                leave_balances={},
            )
            db.add(alloc)
            db.flush()
        balances = copy.deepcopy(alloc.leave_balances or {})
        lt = record.leave_type
        if lt not in balances:
            balances[lt] = {"used": 0, "total": 0}
        balances[lt]["used"] = balances[lt].get("used", 0) + record.days
        alloc.leave_balances = balances
        try:
            log_activity(db, organization_id,
                f"Leave request #{record.id} approved — attendance auto-created ({record.days}d).",
                ActivityStatus.INFO)
        except Exception:
            pass

    elif record.status == "rejected" and prev_status != "rejected":
        _remove_linked_attendance(db, record, organization_id)
        alloc = db.query(PayrollLeaveAllocation).filter(
            PayrollLeaveAllocation.organization_id == organization_id,
            PayrollLeaveAllocation.employee_id == record.employee_id,
        ).first()
        if alloc and prev_status == "approved":
            balances = copy.deepcopy(alloc.leave_balances or {})
            lt = record.leave_type
            if lt in balances:
                used = balances[lt].get("used", 0)
                balances[lt]["used"] = max(0, used - record.days)
                alloc.leave_balances = balances

    db.commit()
    db.refresh(record)

    try:
        log_activity(db, organization_id, f"Leave request #{record.id} {record.status} by admin ({record.days}d).", ActivityStatus.INFO)
    except Exception:
        pass

    # Best-effort status email — never blocks the review. Sent to the employee
    # only when their request actually transitions (approved / rejected).
    if prev_status != record.status and record.status in ("approved", "rejected"):
        try:
            employee = db.query(PayrollEmployee).filter(PayrollEmployee.id == record.employee_id).first()
            if employee and employee.email:
                from app.services.email_service import (
                    send_leave_request_approved_email,
                    send_leave_request_rejected_email,
                )
                from app.modules.communications.service import queue_email, repeatable_idempotency_key

                sender = (
                    send_leave_request_approved_email
                    if record.status == "approved"
                    else send_leave_request_rejected_email
                )
                event_type = f"payroll.leave_{record.status}"
                # Repeatable: a request can go approved → rejected → approved.
                queue_email(
                    "payroll", event_type, None, employee.email,
                    repeatable_idempotency_key(
                        organization_id, event_type, employee.email, None, f"leave:{record.id}",
                        {"status": record.status},
                    ),
                    sender, employee.email, employee.name,
                    record.leave_type, str(record.start_date), str(record.end_date),
                    record.days, record.request_code,
                    send_kwargs={"organization_id": organization_id},
                    organization_id=organization_id, actor_user_id=reviewer_id, db=db,
                )
        except Exception as exc:
            import logging
            logging.getLogger("zoiko").warning(f"[payroll-mail] leave-request status email failed: {exc}")

    return _enrich_leave_request(db, record, organization_id)


# ── France (ZP-FR-ENG-001) ───────────────────────────────────────────────

_FR_FILING_DUE_DATE_CLASSES = {"M5", "M15", "DEFERRED_M15"}
_FR_PAS_RATE_TYPES = {"PERSONALIZED", "NEUTRAL"}
_FR_PAS_SOURCES = {"CRM", "NEUTRAL_GRID"}
_FR_DSN_STATUSES = (
    "DRAFT", "VALIDATED", "QUEUED", "TRANSMITTED", "ACKNOWLEDGED",
    "BUSINESS_REJECTED", "CRM_RESOLVED", "UNKNOWN", "SETTLED",
)
_FR_DSN_TRANSITIONS = {
    "DRAFT": {"VALIDATED"},              # re-runs the FR-031 validator
    "VALIDATED": {"QUEUED"},
    "QUEUED": {"TRANSMITTED", "UNKNOWN"},
    "TRANSMITTED": {"ACKNOWLEDGED", "BUSINESS_REJECTED", "UNKNOWN"},
    "ACKNOWLEDGED": {"CRM_RESOLVED", "SETTLED"},
    "BUSINESS_REJECTED": {"CRM_RESOLVED"},  # a correction is a NEW submission (correction_of_id)
    "CRM_RESOLVED": {"SETTLED"},
    # UNKNOWN (timeout / uncertain transport) is resolved by reconciliation
    # only — never re-queued or re-transmitted blind (FR-033/FR-058).
    "UNKNOWN": {"ACKNOWLEDGED", "BUSINESS_REJECTED"},
    "SETTLED": set(),
}
_FR_DSN_OUTBOX_ACTIONS = {"TRANSMIT", "PAS_RATE_EXCHANGE", "CRM_CLOSE", "CORRECTION"}
_FR_DSN_OUTBOX_STATUSES = ("PENDING", "SENT", "UNKNOWN", "ACKNOWLEDGED", "FAILED")


def seed_france_pack_rows(db: Session, pack: JurisdictionPack) -> List[ContributionRate]:
    """Insert every France statutory content row (engine/countries/
    france_content.py — the catalog france.py reads) that `pack` is missing.
    INSERT-ONLY: a (component_key, effective_from) row already in the pack
    is never overwritten, so a Super Admin's edits survive. Row-dated
    content (the 1 June SMIC) is included only where its window overlaps
    the pack's own window. Shared by the Super Admin "load statutory
    defaults" action and scripts/seed_france_canonical_packs.py."""
    from app.modules.payroll.engine.countries.france_content import FR_2026_CONTENT

    existing = {
        (r.component_key, r.effective_from)
        for r in db.query(ContributionRate).filter(
            ContributionRate.jurisdiction_pack_id == pack.id, ContributionRate.organization_id.is_(None))
    }
    added: List[ContributionRate] = []
    for sort_order, (key, label, _category, kind, value, eff_from, eff_to, note) in enumerate(FR_2026_CONTENT):
        if pack.effective_from is not None and eff_to is not None and eff_to < pack.effective_from:
            continue
        if pack.effective_to is not None and eff_from is not None and eff_from > pack.effective_to:
            continue
        if (key, eff_from) in existing:
            continue
        amount = Decimal(value)
        display = f"{amount}%" if kind in ("ee", "er") else str(amount)
        row = ContributionRate(
            jurisdiction_pack_id=pack.id,
            jurisdiction_country="FR",
            organization_id=None,
            component_key=key,
            label=label if note != "PENDING_G1" else f"{label} [PENDING G1]",
            employee_share=display if kind in ("ee", "amount") else "—",
            employer_share=display if kind == "er" else "—",
            total=display,
            employee_rate_pct=amount if kind == "ee" else None,
            employer_rate_pct=amount if kind == "er" else None,
            flat_amount=amount if kind == "amount" else None,
            effective_from=eff_from,
            effective_to=eff_to,
            sort_order=sort_order,
        )
        db.add(row)
        added.append(row)
    db.flush()
    return added


def load_france_statutory_defaults(db: Session, pack_id: int, actor_id: Optional[int] = None) -> dict:
    """Super Admin action: fill a France tax pack's missing statutory rows
    from the content catalog. Only a France pack_type='tax' pack that is
    still editable (never an Active/published one); insert-only and audited
    row by row; an existing approval is invalidated like any other edit."""
    pack = db.query(JurisdictionPack).filter(JurisdictionPack.id == pack_id).first()
    if not pack:
        raise NotFoundException("JurisdictionPack", pack_id)
    if _normalize_country(pack.jurisdiction_country) != "FR" or pack.pack_type != "tax":
        raise BadRequestException("France statutory defaults can only be loaded into a France tax pack.")
    _require_editable_pack(pack)
    added = seed_france_pack_rows(db, pack)
    if added:
        _invalidate_pack_approval_on_edit(pack)
    db.commit()
    for row in added:
        db.refresh(row)
        record_tax_audit(
            db, actor_id=actor_id, action="create", entity_type="contribution_rate", entity_id=row.id,
            jurisdiction_pack_id=pack.id, tax_version=pack.version,
            new_value={"component_key": row.component_key, "employee_rate_pct": str(row.employee_rate_pct),
                       "employer_rate_pct": str(row.employer_rate_pct), "flat_amount": str(row.flat_amount),
                       "effective_from": str(row.effective_from), "effective_to": str(row.effective_to)},
            reason="Loaded France 2026 statutory defaults (ZP-FR-ENG-001 content catalog)",
        )
    pending = sorted({r.component_key for r in added if r.label.endswith("[PENDING G1]")})
    return {
        "packId": pack.id,
        "added": len(added),
        "addedKeys": sorted({r.component_key for r in added}),
        "pendingG1Keys": pending,
        "message": (f"Added {len(added)} France statutory row(s)." if added
                    else "Nothing to add — the pack already has every France statutory row."),
    }


_FR_FNAL_CLASSES = {"UNDER_50", "OVER_50"}
_FR_CFP_CLASSES = {"UNDER_11", "OVER_11"}


def require_france_organization(db: Session, organization_id: int):
    """Every France authority endpoint is organization-scoped; reject an id
    that is not an existing organization whose country resolves to FR, so a
    typo or a non-French org can never silently accumulate France records
    (or report a misleading "not ready")."""
    from app.core.jurisdiction import get_jurisdiction_code
    from app.modules.organizations.models import Organization

    org = db.query(Organization).filter(Organization.id == organization_id).first()
    if not org:
        raise NotFoundException("Organization", organization_id)
    if get_jurisdiction_code(getattr(org, "country", None)) != "FR":
        raise BadRequestException(
            f"Organization {organization_id} is not a France organization "
            f"(country={getattr(org, 'country', None)!r}); France compliance data is FR-only."
        )
    return org


def require_ireland_organization(db: Session, organization_id: int):
    """Every Ireland authority endpoint is organization-scoped; reject an id
    that is not an existing organization whose country resolves to IE, so a
    typo or a non-Irish org can never silently accumulate Ireland records."""
    from app.core.jurisdiction import get_jurisdiction_code
    from app.modules.organizations.models import Organization

    org = db.query(Organization).filter(Organization.id == organization_id).first()
    if not org:
        raise NotFoundException("Organization", organization_id)
    if get_jurisdiction_code(getattr(org, "country", None)) != "IE":
        raise BadRequestException(
            f"Organization {organization_id} is not an Ireland organization "
            f"(country={getattr(org, 'country', None)!r}); Ireland compliance data is IE-only."
        )
    return org


def _validate_france_employer_classes(fnal_class: Optional[str], cfp_class: Optional[str]) -> None:
    """The stored FNAL/CFP vocabulary — the engine maps these to its rate
    keys (france.normalize_fnal_class / normalize_cfp_class)."""
    if fnal_class is not None and fnal_class not in _FR_FNAL_CLASSES:
        raise BadRequestException(f"fnalClass must be one of {sorted(_FR_FNAL_CLASSES)}, got {fnal_class!r}.")
    if cfp_class is not None and cfp_class not in _FR_CFP_CLASSES:
        raise BadRequestException(f"cfpClass must be one of {sorted(_FR_CFP_CLASSES)}, got {cfp_class!r}.")


def _fr_dsn_payload_hash(organization_id: int, period_start, period_end, release_ref: str, due_date) -> str:
    canonical = json.dumps(
        {
            "organization_id": organization_id,
            "period_start": str(period_start),
            "period_end": str(period_end),
            "release_ref": release_ref,
            "dsn_version": "P26V01",
            "due_date": str(due_date),
        },
        sort_keys=True,
        default=str,
    )
    return hashlib.sha256(canonical.encode("utf-8")).hexdigest()


def get_employer_france_profile(db: Session, organization_id: int) -> EmployerFranceProfile:
    row = (db.query(EmployerFranceProfile)
           .filter(EmployerFranceProfile.organization_id == organization_id).first())
    if not row:
        raise NotFoundException(f"France employer profile for organization {organization_id} not found.")
    return row


_FR_IDCC_STATUSES = {"APPLICABLE", "NOT_APPLICABLE", "UNDER_REVIEW"}
_FR_INSEE_RE = re.compile(r"^(\d{5}|2[AB]\d{3})$")


def upsert_employer_france_profile(
    db: Session, organization_id: int, data: "EmployerFranceProfileUpsert", actor_id: Optional[int] = None,
) -> EmployerFranceProfile:
    """Create or update the org 1:1 France employer profile (FR §11 panels
    A/C/D). Not payload-writable (never overwritten by a profile save):
    pas_crm_status (authority-held), effectif_state (governed history —
    record_france_effectif / correct_france_effectif) and readiness_status
    (computed by get_france_readiness; LIVE only via set_france_live)."""
    siren = (data.siren or "").strip()
    if not re.match(r"^\d{9}$", siren):
        raise BadRequestException("French SIREN must be exactly 9 digits.")
    if data.filingDueDateClass not in _FR_FILING_DUE_DATE_CLASSES:
        raise BadRequestException(
            f"filingDueDateClass must be one of {sorted(_FR_FILING_DUE_DATE_CLASSES)}, "
            f"got {data.filingDueDateClass!r}."
        )
    if data.idccStatus is not None and data.idccStatus not in _FR_IDCC_STATUSES:
        raise BadRequestException(f"idccStatus must be one of {sorted(_FR_IDCC_STATUSES)}, got {data.idccStatus!r}.")
    if data.idccStatus == "APPLICABLE" and not (data.idcc or "").strip():
        raise BadRequestException("idccStatus APPLICABLE requires the IDCC code (FR-035).")

    row = db.query(EmployerFranceProfile).filter(
        EmployerFranceProfile.organization_id == organization_id).first()
    action = "update" if row else "create"
    old_value = None
    if row:
        old_value = {"siren": row.siren, "idcc": row.idcc, "filing_due_date_class": row.filing_due_date_class}
        if row.siren != siren:
            siret_mismatch = (db.query(FranceEstablishment)
                              .filter(FranceEstablishment.organization_id == organization_id,
                                      ~FranceEstablishment.siret.startswith(siren)).first())
            if siret_mismatch:
                raise BadRequestException(
                    f"SIREN {siren} does not match existing establishment SIRET {siret_mismatch.siret} "
                    "(a SIRET is the SIREN + a 5-digit NIC)."
                )
    else:
        row = EmployerFranceProfile(organization_id=organization_id, siren=siren, created_by_id=actor_id)
        db.add(row)
    row.siren = siren
    row.legal_name = data.legalName
    row.legal_form = data.legalForm
    row.address = data.address
    row.payroll_contact = data.payrollContact
    row.idcc = (data.idcc or "").strip() or None
    if data.idccStatus is not None:
        row.idcc_status = data.idccStatus
    elif row.idcc:
        row.idcc_status = row.idcc_status or "APPLICABLE"
    row.urssaf_account = data.urssafAccount
    row.dsn_declarant = data.dsnDeclarant
    row.filing_due_date_class = data.filingDueDateClass
    row.payment_mandate_ref = data.paymentMandateRef
    row.pas_collector_identity = data.pasCollectorIdentity

    db.commit()
    db.refresh(row)
    record_tax_audit(
        db, actor_id=actor_id, action=action, entity_type="france_employer_profile",
        entity_id=row.id, old_value=old_value, new_value={
            "organization_id": organization_id, "siren": siren,
            "idcc": row.idcc, "idcc_status": row.idcc_status,
            "filing_due_date_class": row.filing_due_date_class,
        },
    )
    log_activity(db, organization_id, f"France employer profile {action}d (SIREN {siren}).",
                 actor_id=actor_id)
    return row


def record_france_effectif(
    db: Session, organization_id: int, data: "FranceEffectifRecord", actor_id: Optional[int] = None,
) -> EmployerFranceProfile:
    """Record a NEW year of governed annual effectif (FR-015/FR-036). An
    already-recorded year is changed only through correct_france_effectif,
    which keeps the previous value in that year's history."""
    profile = get_employer_france_profile(db, organization_id)
    if data.value < 0:
        raise BadRequestException("Annual effectif cannot be negative.")
    if not (1980 <= data.year <= 2100):
        raise BadRequestException(f"Effectif year {data.year} is outside a plausible range.")
    if not (data.source or "").strip():
        raise BadRequestException("An effectif value needs its governed source (e.g. DSN, Urssaf notice).")
    state = dict(profile.effectif_state or {})
    if str(data.year) in state:
        raise BadRequestException(
            f"Effectif {data.year} is already recorded ({state[str(data.year)].get('value')}); "
            "use the correction action to change it — history is never overwritten."
        )
    state[str(data.year)] = {
        "value": data.value,
        "source": data.source,
        "validatedAt": datetime.utcnow().isoformat(),
        "history": [],
    }
    profile.effectif_state = state
    db.commit()
    db.refresh(profile)
    record_tax_audit(
        db, actor_id=actor_id, action="create", entity_type="france_employer_profile",
        entity_id=profile.id, new_value={f"effectif.{data.year}": state[str(data.year)]},
    )
    log_activity(db, organization_id, f"France annual effectif {data.year} recorded = {data.value}.", actor_id=actor_id)
    return profile


def correct_france_effectif(
    db: Session, organization_id: int, data: "FranceEffectifCorrection", actor_id: Optional[int] = None,
) -> EmployerFranceProfile:
    """Correct an already-recorded effectif year: the prior value/source
    move into that year's `history` with the reason and actor — auditable,
    never silently replaced."""
    profile = get_employer_france_profile(db, organization_id)
    if data.value < 0:
        raise BadRequestException("Annual effectif cannot be negative.")
    if not (data.reason or "").strip():
        raise BadRequestException("A correction needs a reason.")
    state = dict(profile.effectif_state or {})
    current = state.get(str(data.year))
    if not current:
        raise NotFoundException(f"No effectif recorded for {data.year} — record it first.")
    history = list(current.get("history") or [])
    history.append({
        "value": current.get("value"), "source": current.get("source"),
        "validatedAt": current.get("validatedAt"),
        "replacedAt": datetime.utcnow().isoformat(), "replacedBy": actor_id, "reason": data.reason,
    })
    state[str(data.year)] = {
        "value": data.value, "source": data.source,
        "validatedAt": datetime.utcnow().isoformat(), "history": history,
    }
    profile.effectif_state = state
    db.commit()
    db.refresh(profile)
    record_tax_audit(
        db, actor_id=actor_id, action="update", entity_type="france_employer_profile",
        entity_id=profile.id, legal_reference="FR-015/FR-036",
        old_value={f"effectif.{data.year}": current.get("value")},
        new_value={f"effectif.{data.year}": data.value, "reason": data.reason},
    )
    log_activity(db, organization_id,
                 f"France annual effectif {data.year} corrected {current.get('value')} → {data.value}.",
                 actor_id=actor_id)
    return profile


# ── Establishments (SIRET registry, FR §11 panel B) ────────────────────

def _validate_siret_for_org(db: Session, organization_id: int, siret: str) -> str:
    siret = (siret or "").strip().replace(" ", "")
    if not re.match(r"^\d{14}$", siret):
        raise BadRequestException("French SIRET must be exactly 14 digits.")
    profile = db.query(EmployerFranceProfile).filter(
        EmployerFranceProfile.organization_id == organization_id).first()
    if profile and not siret.startswith(profile.siren):
        raise BadRequestException(
            f"SIRET {siret} does not belong to SIREN {profile.siren} (SIRET = SIREN + 5-digit NIC)."
        )
    return siret


def upsert_france_establishment(
    db: Session, organization_id: int, data: "FranceEstablishmentUpsert",
    establishment_id: Optional[int] = None, actor_id: Optional[int] = None,
) -> FranceEstablishment:
    """Create (establishment_id None) or update an establishment. The SIRET
    of an existing establishment is immutable — rate packs and filings are
    keyed on it; open a new establishment instead."""
    siret = _validate_siret_for_org(db, organization_id, data.siret)
    commune = (data.communeInsee or "").strip().upper() or None
    if commune and not _FR_INSEE_RE.match(commune):
        raise BadRequestException("Commune INSEE code must be 5 characters (e.g. 75056, or 2A004 / 2B033 for Corsica).")

    if establishment_id is not None:
        row = (db.query(FranceEstablishment)
               .filter(FranceEstablishment.id == establishment_id,
                       FranceEstablishment.organization_id == organization_id).first())
        if not row:
            raise NotFoundException("FranceEstablishment", establishment_id)
        if row.siret != siret:
            raise BadRequestException("An establishment's SIRET cannot change — create a new establishment.")
        action = "update"
    else:
        if db.query(FranceEstablishment).filter(
                FranceEstablishment.organization_id == organization_id,
                FranceEstablishment.siret == siret).first():
            raise BadRequestException(f"SIRET {siret} is already registered for this organization.")
        profile = db.query(EmployerFranceProfile).filter(
            EmployerFranceProfile.organization_id == organization_id).first()
        row = FranceEstablishment(
            organization_id=organization_id, siret=siret,
            employer_profile_id=profile.id if profile else None, created_by_id=actor_id,
        )
        db.add(row)
        action = "create"
    row.name = data.name
    row.address = data.address
    row.commune_insee = commune
    row.workforce_location = data.workforceLocation
    row.payroll_identifier = data.payrollIdentifier
    row.is_active = bool(data.isActive)
    db.commit()
    db.refresh(row)
    record_tax_audit(db, actor_id=actor_id, action=action, entity_type="france_establishment",
                     entity_id=row.id, legal_reference="FR-002",
                     new_value={"siret": siret, "commune_insee": commune, "is_active": row.is_active})
    log_activity(db, organization_id, f"France establishment {siret} {action}d.", actor_id=actor_id)
    return row


def list_france_establishments(db: Session, organization_id: int, include_inactive: bool = True) -> List[FranceEstablishment]:
    query = db.query(FranceEstablishment).filter(FranceEstablishment.organization_id == organization_id)
    if not include_inactive:
        query = query.filter(FranceEstablishment.is_active.is_(True))
    return query.order_by(FranceEstablishment.siret).all()


# ── Establishment rate packs (FR-002/FR-013) ───────────────────────────

def _validate_rate_pack_values(at_mp, at_mp_evidence, at_mp_source, vm_rate, vm_evidence, vm_source, fnal, cfp):
    for label, value in (("AT/MP", at_mp), ("Versement mobilité", vm_rate)):
        if value is not None and not (Decimal("0") <= Decimal(str(value)) <= Decimal("100")):
            raise BadRequestException(f"{label} rate must be between 0 and 100%.")
    if at_mp is not None and not at_mp_evidence and not at_mp_source:
        raise BadRequestException(
            "An AT/MP rate is authority decision data (FR-013) — provide atMpEvidence and/or atMpSource."
        )
    if vm_rate is not None and not vm_evidence and not vm_source:
        raise BadRequestException(
            "A versement mobilité rate is authority data (FR-013) — provide vmEvidence and/or vmSource."
        )
    _validate_france_employer_classes(fnal, cfp)


def upsert_france_establishment_rate_pack(
    db: Session, organization_id: int, data: "FranceEstablishmentRatePackUpsert", actor_id: Optional[int] = None,
) -> FranceEstablishmentRatePack:
    """Append a new effective-dated SIRET rate-pack period row, auto-closing
    the previous period's row (effective_to = day before new effective_from)
    so Jan/Jul history is never rewritten (FR-002/FR-013). Backdated periods
    are accepted — Urssaf AT/MP notices are frequently retroactive."""
    establishment = None
    if data.establishmentId is not None:
        establishment = (db.query(FranceEstablishment)
                         .filter(FranceEstablishment.id == data.establishmentId,
                                 FranceEstablishment.organization_id == organization_id).first())
        if not establishment:
            raise NotFoundException("FranceEstablishment", data.establishmentId)
        siret = establishment.siret
    else:
        siret = _validate_siret_for_org(db, organization_id, data.siret or "")
        establishment = (db.query(FranceEstablishment)
                         .filter(FranceEstablishment.organization_id == organization_id,
                                 FranceEstablishment.siret == siret).first())
    _validate_rate_pack_values(data.atMpRatePct, data.atMpEvidence, data.atMpSource,
                               data.vmRatePct, data.vmEvidence, data.vmSource, data.fnalClass, data.cfpClass)
    if data.effectiveTo is not None and data.effectiveTo < data.effectiveFrom:
        raise BadRequestException("effectiveTo cannot be before effectiveFrom.")

    open_period = (db.query(FranceEstablishmentRatePack)
                   .filter(
                       FranceEstablishmentRatePack.organization_id == organization_id,
                       FranceEstablishmentRatePack.siret == siret,
                       FranceEstablishmentRatePack.effective_to.is_(None),
                   )
                   .first())
    if open_period:
        if open_period.effective_from >= data.effectiveFrom:
            raise BadRequestException(
                f"A rate pack for SIRET {siret} is already effective from {open_period.effective_from}; "
                "a new period must start after it (edit the future period instead)."
            )
        open_period.effective_to = data.effectiveFrom - timedelta(days=1)
    new_pack = FranceEstablishmentRatePack(
        organization_id=organization_id,
        establishment_id=establishment.id if establishment else None,
        siret=siret,
        commune_insee=(establishment.commune_insee if establishment and establishment.commune_insee else data.communeInsee),
        workplace_label=data.workplaceLabel or (establishment.name if establishment else None),
        at_mp_rate_pct=data.atMpRatePct,
        at_mp_risk_code=data.atMpRiskCode,
        at_mp_evidence=data.atMpEvidence,
        at_mp_source=data.atMpSource,
        vm_rate_pct=data.vmRatePct,
        vm_threshold_applies=data.vmThresholdApplies,
        vm_source=data.vmSource,
        vm_evidence=data.vmEvidence,
        ags_special_status=data.agsSpecialStatus,
        fnal_class=data.fnalClass,
        cfp_class=data.cfpClass,
        effectif=data.effectif,
        effective_from=data.effectiveFrom,
        effective_to=data.effectiveTo,
        created_by_id=actor_id,
    )
    db.add(new_pack)
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        raise BadRequestException(
            f"A France rate pack for SIRET {siret} effective {data.effectiveFrom} already exists for this "
            "organization — a new period must start on a different date."
        )
    db.refresh(new_pack)
    record_tax_audit(db, actor_id=actor_id, action="create", entity_type="france_establishment_rate_pack",
                     entity_id=new_pack.id, legal_reference="FR-002/FR-013",
                     new_value={"siret": siret, "effective_from": str(data.effectiveFrom),
                                "at_mp_rate_pct": str(new_pack.at_mp_rate_pct),
                                "vm_rate_pct": str(new_pack.vm_rate_pct)})
    log_activity(db, organization_id, f"France SIRET {siret} rate pack effective {data.effectiveFrom} recorded.",
                 actor_id=actor_id)
    return new_pack


def _get_france_rate_pack(db: Session, organization_id: int, pack_id: int) -> FranceEstablishmentRatePack:
    pack = (db.query(FranceEstablishmentRatePack)
            .filter(FranceEstablishmentRatePack.id == pack_id,
                    FranceEstablishmentRatePack.organization_id == organization_id).first())
    if not pack:
        raise NotFoundException("FranceEstablishmentRatePack", pack_id)
    return pack


def update_france_establishment_rate_pack(
    db: Session, organization_id: int, pack_id: int, data: "FranceEstablishmentRatePackUpdate",
    actor_id: Optional[int] = None,
) -> FranceEstablishmentRatePack:
    """Edit a period that has not started yet. A period already in force (a
    payroll may have run on it) is never edited in place — append a new
    period instead."""
    pack = _get_france_rate_pack(db, organization_id, pack_id)
    if pack.effective_from <= date.today():
        raise BadRequestException(
            f"This period has been in force since {pack.effective_from}; it cannot be edited in place — "
            "add a new rate-pack period (history the payroll ran on stays intact)."
        )
    fields = data.model_dump(exclude_unset=True)
    merged = {
        "at_mp": fields.get("atMpRatePct", pack.at_mp_rate_pct),
        "at_mp_evidence": fields.get("atMpEvidence", pack.at_mp_evidence),
        "at_mp_source": fields.get("atMpSource", pack.at_mp_source),
        "vm_rate": fields.get("vmRatePct", pack.vm_rate_pct),
        "vm_evidence": fields.get("vmEvidence", pack.vm_evidence),
        "vm_source": fields.get("vmSource", pack.vm_source),
        "fnal": fields.get("fnalClass", pack.fnal_class),
        "cfp": fields.get("cfpClass", pack.cfp_class),
    }
    _validate_rate_pack_values(**merged)
    old_value = {"at_mp_rate_pct": str(pack.at_mp_rate_pct), "vm_rate_pct": str(pack.vm_rate_pct),
                 "fnal_class": pack.fnal_class, "cfp_class": pack.cfp_class}
    column_for = {
        "communeInsee": "commune_insee", "workplaceLabel": "workplace_label",
        "atMpRatePct": "at_mp_rate_pct", "atMpRiskCode": "at_mp_risk_code",
        "atMpEvidence": "at_mp_evidence", "atMpSource": "at_mp_source",
        "vmRatePct": "vm_rate_pct", "vmThresholdApplies": "vm_threshold_applies",
        "vmSource": "vm_source", "vmEvidence": "vm_evidence", "agsSpecialStatus": "ags_special_status",
        "fnalClass": "fnal_class", "cfpClass": "cfp_class", "effectif": "effectif",
    }
    for key, value in fields.items():
        setattr(pack, column_for[key], value)
    db.commit()
    db.refresh(pack)
    record_tax_audit(db, actor_id=actor_id, action="update", entity_type="france_establishment_rate_pack",
                     entity_id=pack.id, legal_reference="FR-002/FR-013", old_value=old_value,
                     new_value={k: str(v) for k, v in fields.items()})
    log_activity(db, organization_id, f"France SIRET {pack.siret} future rate pack ({pack.effective_from}) edited.",
                 actor_id=actor_id)
    return pack


def close_france_establishment_rate_pack(
    db: Session, organization_id: int, pack_id: int, data: "FranceRatePackClose", actor_id: Optional[int] = None,
) -> FranceEstablishmentRatePack:
    pack = _get_france_rate_pack(db, organization_id, pack_id)
    if pack.effective_to is not None:
        raise BadRequestException(f"This period is already closed ({pack.effective_to}).")
    if data.effectiveTo < pack.effective_from:
        raise BadRequestException("A period cannot close before it starts.")
    pack.effective_to = data.effectiveTo
    db.commit()
    db.refresh(pack)
    record_tax_audit(db, actor_id=actor_id, action="update", entity_type="france_establishment_rate_pack",
                     entity_id=pack.id, legal_reference="FR-013", new_value={"effective_to": str(data.effectiveTo)})
    log_activity(db, organization_id, f"France SIRET {pack.siret} rate pack closed on {data.effectiveTo}.",
                 actor_id=actor_id)
    return pack


def list_france_establishment_rate_packs(
    db: Session, organization_id: int, siret: Optional[str] = None,
) -> List[FranceEstablishmentRatePack]:
    query = db.query(FranceEstablishmentRatePack).filter(
        FranceEstablishmentRatePack.organization_id == organization_id)
    if siret:
        query = query.filter(FranceEstablishmentRatePack.siret == siret)
    return query.order_by(FranceEstablishmentRatePack.siret, FranceEstablishmentRatePack.effective_from.desc()).all()


# ── PAS (FR-008/FR-010) ────────────────────────────────────────────────

_FR_PAS_APPLICATION_WINDOW_DAYS = 60


def ingest_france_pas_rate(
    db: Session, organization_id: int, data: "FrancePASRateUpsert", actor_id: Optional[int] = None,
) -> FrancePASRate:
    """Record a PAS rate (FR-008/FR-010).

    PERSONALIZED = a DGFiP CRM rate transcribed WITH its provenance: the
    DGFiP rate identifier, the CRM reference and the receipt date are all
    mandatory, and the rate must be applied within the legal window —
    no earlier than its receipt and no later than 60 days after it. NEUTRAL
    rows carry no percentage (the engine resolves the statutory grid).
    `source` is derived from the type, never chosen. A correction marks the
    corrected row CORRECTED (excluded from lookups); a plain supersede
    closes the previous row (STALE — still valid for its own window, so
    re-running an old period uses the rate that governed it)."""
    if data.rateType not in _FR_PAS_RATE_TYPES:
        raise BadRequestException(f"rateType must be one of {sorted(_FR_PAS_RATE_TYPES)}, got {data.rateType!r}.")
    source = "CRM" if data.rateType == "PERSONALIZED" else "NEUTRAL_GRID"
    if data.source is not None and data.source != source:
        raise BadRequestException(f"A {data.rateType} rate's source is {source}, not {data.source!r}.")
    if data.rateType == "PERSONALIZED":
        if data.ratePct is None:
            raise BadRequestException("A PERSONALIZED PAS rate requires ratePct (DGFiP authority value).")
        if not (Decimal("0") <= Decimal(str(data.ratePct)) <= Decimal("100")):
            raise BadRequestException("A PAS rate must be between 0 and 100%.")
        missing = [label for label, value in (("dgfipRateId", data.dgfipRateId),
                                              ("crmReference", data.crmReference),
                                              ("receivedDate", data.receivedDate)) if not value]
        if missing:
            raise BadRequestException(
                "A PERSONALIZED rate is DGFiP authority data — its provenance is mandatory (FR-008/FR-010): "
                + ", ".join(missing)
            )
        if data.effectiveFrom < data.receivedDate:
            raise BadRequestException("A PAS rate cannot be applied before the DGFiP CRM delivering it was received.")
        if data.effectiveFrom > data.receivedDate + timedelta(days=_FR_PAS_APPLICATION_WINDOW_DAYS):
            raise BadRequestException(
                f"A DGFiP rate must be applied within {_FR_PAS_APPLICATION_WINDOW_DAYS} days of receipt "
                f"(received {data.receivedDate}, latest start "
                f"{data.receivedDate + timedelta(days=_FR_PAS_APPLICATION_WINDOW_DAYS)})."
            )
    elif data.ratePct is not None or data.dgfipRateId:
        raise BadRequestException(
            "NEUTRAL PAS rows carry no percentage or DGFiP rate id — the statutory neutral grid is resolved "
            "by the engine from the payroll date."
        )
    if data.effectiveTo is not None and data.effectiveTo < data.effectiveFrom:
        raise BadRequestException("effectiveTo cannot be before effectiveFrom.")

    employee = (db.query(PayrollEmployee)
                .filter(PayrollEmployee.id == data.employeeId,
                        PayrollEmployee.organization_id == organization_id).first())
    if not employee:
        raise NotFoundException("PayrollEmployee", data.employeeId)

    if data.correctionOfId is not None:
        prior = (db.query(FrancePASRate)
                 .filter(FrancePASRate.id == data.correctionOfId,
                         FrancePASRate.organization_id == organization_id).first())
        if not prior:
            raise NotFoundException("FrancePASRate", data.correctionOfId)
        if prior.employee_id != data.employeeId:
            raise BadRequestException(
                f"correctionOfId {data.correctionOfId} belongs to employee {prior.employee_id}, "
                f"not {data.employeeId} — a correction must replace the same employee's rate."
            )
        prior.status = "CORRECTED"
    else:
        open_rows = (db.query(FrancePASRate)
                     .filter(FrancePASRate.organization_id == organization_id,
                             FrancePASRate.employee_id == data.employeeId,
                             FrancePASRate.status.in_(["ACTIVE", "PENDING"]),
                             FrancePASRate.effective_to.is_(None)).all())
        for previous in open_rows:
            if previous.effective_from >= data.effectiveFrom:
                raise BadRequestException(
                    f"Employee {data.employeeId} already has a PAS rate from {previous.effective_from}; "
                    "a replacement must start after it (or record it as a correction)."
                )
            previous.status = "STALE"
            previous.effective_to = data.effectiveFrom - timedelta(days=1)

    new_rate = FrancePASRate(
        organization_id=organization_id,
        employee_id=data.employeeId,
        rate_type=data.rateType,
        rate_pct=data.ratePct,
        dgfip_rate_id=data.dgfipRateId,
        crm_reference=data.crmReference,
        source=source,
        received_date=data.receivedDate,
        effective_from=data.effectiveFrom,
        effective_to=data.effectiveTo,
        status="ACTIVE" if data.effectiveFrom <= date.today() else "PENDING",
        correction_of_id=data.correctionOfId,
        created_by_id=actor_id,
    )
    db.add(new_rate)
    db.commit()
    db.refresh(new_rate)
    record_tax_audit(db, actor_id=actor_id, action="create", entity_type="france_pas_rate",
                     entity_id=new_rate.id, legal_reference="FR-008/FR-010",
                     new_value={"employee_id": data.employeeId, "rate_type": data.rateType,
                                "rate_pct": str(data.ratePct), "source": source,
                                "crm_reference": data.crmReference,
                                "received_date": str(data.receivedDate),
                                "effective_from": str(data.effectiveFrom),
                                "correction_of_id": data.correctionOfId})
    log_activity(db, organization_id, f"France PAS {data.rateType} rate recorded for employee {data.employeeId}.",
                 actor_id=actor_id)
    return new_rate


def get_active_france_pas_rate(
    db: Session, organization_id: int, employee_id: int, as_of: Optional[date] = None,
) -> Optional[FrancePASRate]:
    """The PAS rate governing a France employee at as_of (default today),
    selected by its effective window: a superseded (STALE) row still
    governs its own past window, so re-running an old period uses the rate
    that applied then (FR §4 correction rule). CORRECTED / EXPIRED rows
    never resolve."""
    as_of = as_of or date.today()
    return (db.query(FrancePASRate)
            .filter(FrancePASRate.organization_id == organization_id,
                    FrancePASRate.employee_id == employee_id,
                    FrancePASRate.effective_from <= as_of)
            .filter((FrancePASRate.effective_to.is_(None)) | (FrancePASRate.effective_to >= as_of))
            .filter(FrancePASRate.status.in_(["ACTIVE", "PENDING", "STALE"]))
            .order_by(FrancePASRate.effective_from.desc(), FrancePASRate.id.desc())
            .first())


def list_france_pas_rates(
    db: Session, organization_id: int, employee_id: Optional[int] = None,
) -> List[FrancePASRate]:
    query = db.query(FrancePASRate).filter(FrancePASRate.organization_id == organization_id)
    if employee_id:
        query = query.filter(FrancePASRate.employee_id == employee_id)
    return query.order_by(FrancePASRate.employee_id, FrancePASRate.effective_from.desc()).all()


# ── Readiness (FR §11 gate H + FR-031 dry-run) ──────────────────────────

def _france_employees(db: Session, organization_id: int) -> List[PayrollEmployee]:
    """France employees of the org — explicit FR, or no country of their own
    in a France organization (country_code is nullable and then inherits
    the org's), so a NULL-country employee is never skipped by the checks."""
    from app.core.jurisdiction import get_jurisdiction_code
    from app.modules.organizations.models import Organization

    org = db.query(Organization).filter(Organization.id == organization_id).first()
    org_is_fr = bool(org) and get_jurisdiction_code(getattr(org, "country", None)) == "FR"
    query = db.query(PayrollEmployee).filter(PayrollEmployee.organization_id == organization_id)
    if org_is_fr:
        query = query.filter((PayrollEmployee.country_code == "FR") | (PayrollEmployee.country_code.is_(None)))
    else:
        query = query.filter(PayrollEmployee.country_code == "FR")
    return query.all()


def compute_france_readiness_checks(db: Session, organization_id: int, period: date) -> List[dict]:
    """Every §11 A–H launch check, computed from the real records — the ONE
    readiness definition shared by the readiness endpoint, the go-live
    action and the FR-031 DSN pre-submit validator."""
    checks: List[dict] = []

    def check(key, section, label, ok, detail):
        checks.append({"key": key, "section": section, "label": label, "ok": bool(ok),
                       "detail": None if ok else detail})

    profile = db.query(EmployerFranceProfile).filter(
        EmployerFranceProfile.organization_id == organization_id).first()
    check("legal_entity", "A", "Legal entity (SIREN, legal name)",
          profile is not None and profile.siren and profile.legal_name,
          "France employer profile is not configured (SIREN, legal name).")
    idcc_ok = bool(profile) and (
        (profile.idcc_status in (None, "APPLICABLE") and profile.idcc)
        or profile.idcc_status == "NOT_APPLICABLE"
    )
    check("idcc", "A", "Collective agreement (IDCC) resolved", idcc_ok,
          "IDCC must be set, or explicitly NOT_APPLICABLE — UNDER_REVIEW/empty blocks launch (FR-035, gate G3).")

    establishments = list_france_establishments(db, organization_id, include_inactive=False)
    check("establishments", "B", "At least one active establishment (SIRET)", establishments,
          "No active France establishment (SIRET) is registered.")

    check("urssaf_dsn", "C", "Urssaf / DSN identity",
          profile is not None and profile.urssaf_account and profile.dsn_declarant
          and profile.filing_due_date_class in _FR_FILING_DUE_DATE_CLASSES,
          "Urssaf account, DSN declarant and filing due-date class are all required.")
    check("payment_mandate", "C", "Payment mandate", profile is not None and profile.payment_mandate_ref,
          "No Urssaf payment mandate reference recorded.")
    check("pas_collector", "D", "DGFiP PAS collector identity", profile is not None and profile.pas_collector_identity,
          "No DGFiP PAS collector identity recorded.")

    packs = list_france_establishment_rate_packs(db, organization_id)
    uncovered = []
    for est in establishments:
        effective = [p for p in packs
                     if (p.establishment_id == est.id or p.siret == est.siret)
                     and p.effective_from <= period and (p.effective_to is None or p.effective_to >= period)]
        pack = effective[0] if effective else None
        if (pack is None or pack.at_mp_rate_pct is None
                or (pack.vm_rate_pct is None and pack.vm_threshold_applies is not False)
                or pack.fnal_class not in _FR_FNAL_CLASSES or pack.cfp_class not in _FR_CFP_CLASSES):
            uncovered.append(est.siret)
    check("employer_rates", "E", "Employer rates effective for every establishment (AT/MP, VM, FNAL, CFP)",
          establishments and not uncovered,
          f"No complete rate pack (AT/MP, versement mobilité, FNAL/CFP class) effective at {period} for SIRET "
          + (", ".join(uncovered) if uncovered else "(no establishments)") + ".")

    effectif_state = (profile.effectif_state if profile else None) or {}
    latest_year = max((int(k) for k in effectif_state if str(k).isdigit()), default=None)
    check("effectif", "E", "Governed annual effectif (FR-015)",
          latest_year is not None and latest_year >= period.year - 1,
          "No governed annual effectif recorded (FR-015)." if latest_year is None
          else f"Latest governed effectif is for {latest_year}; expected {period.year - 1} or later.")

    employees = _france_employees(db, organization_id)
    missing_pas = [e for e in employees if get_active_france_pas_rate(db, organization_id, e.id, as_of=period) is None]
    check("pas_rates", "D", "PAS rate for every France employee", not missing_pas,
          f"{len(missing_pas)} France employee(s) have no active PAS rate at period start.")

    from app.modules.payroll.engine.tax_resolver import resolve_tax_configuration
    _rates, fr_slabs, pack = resolve_tax_configuration(db, "FR", payroll_date=period)
    check("statutory_pack", "H", "Active France statutory pack (gate G1)", pack is not None,
          f"No Active France statutory pack covers {period} — approve and activate the FR pack (gate G1).")
    neutral_employees = [e for e in employees
                         if (lambda r: r is not None and r.rate_type == "NEUTRAL" and r.rate_pct is None)(
                             get_active_france_pas_rate(db, organization_id, e.id, as_of=period))]
    if neutral_employees:
        has_grid = any(getattr(sl, "rule_type", None) == "FR_PAS_NEUTRAL" for sl in (fr_slabs or []))
        check("pas_neutral_grid", "D", "PAS neutral grid loaded (FR-009)", has_grid,
              f"{len(neutral_employees)} employee(s) are on the neutral PAS rate but the active France pack has no "
              f"FR_PAS_NEUTRAL grid covering {period}.")
    return checks


def _validate_france_dsn_completeness(
    db: Session, organization_id: int, period_start: date,
) -> Tuple[List[str], Optional[str]]:
    """FR-031 pre-submit validator. Returns (errors, blocked_reason) from
    the shared readiness checks. A clean run passes into VALIDATED; any
    error keeps the submission DRAFT with the detail recorded — approval is
    blocked, never bypassed (FR-027)."""
    errors = [c["detail"] for c in compute_france_readiness_checks(db, organization_id, period_start) if not c["ok"]]
    blocked = "; ".join(errors) if errors else None
    return errors, blocked


def get_france_readiness(db: Session, organization_id: int, for_period: Optional[date] = None) -> dict:
    """Per-org France launch readiness (FR §11 gate H + FR-031 dry-run).
    Computed from the real records on every call — the status is never a
    hand-set flag. LIVE is shown only after set_france_live accepted it."""
    period = for_period or (date.today().replace(day=28) + timedelta(days=4)).replace(day=1)
    checks = compute_france_readiness_checks(db, organization_id, period)
    errors = [c["detail"] for c in checks if not c["ok"]]
    profile = db.query(EmployerFranceProfile).filter(
        EmployerFranceProfile.organization_id == organization_id).first()
    packs = list_france_establishment_rate_packs(db, organization_id)
    ready = not errors
    if profile is not None and profile.readiness_status == "LIVE":
        status = "LIVE" if ready else "LIVE_CHECKS_FAILING"
    else:
        status = "READY" if ready else "NOT_READY"
    return {
        "asOf": str(date.today()),
        "forPeriod": str(period),
        "ready": ready,
        "organizationId": organization_id,
        "profileConfigured": profile is not None,
        "readinessStatus": status,
        "pasCrmStatus": profile.pas_crm_status if profile else "NOT_CONNECTED",
        "effectiveRatePacks": sum(1 for p in packs if p.effective_from <= period
                                  and (p.effective_to is None or p.effective_to >= period)),
        "effectifGoverned": bool(profile and profile.effectif_state),
        "dsnBlockedReason": "; ".join(errors) if errors else None,
        "missing": errors,
        "checks": checks,
    }


def set_france_live(
    db: Session, organization_id: int, data: "FranceGoLiveRequest", actor_id: Optional[int] = None,
) -> dict:
    """Mark France payroll LIVE for an org — accepted only when every
    computed check passes; evidence is recorded on the profile and audited."""
    readiness = get_france_readiness(db, organization_id)
    if not readiness["ready"]:
        raise BadRequestException("France cannot go LIVE until every readiness check passes: "
                                  + "; ".join(readiness["missing"]))
    profile = get_employer_france_profile(db, organization_id)
    old_status = profile.readiness_status
    profile.readiness_status = "LIVE"
    profile.readiness_evidence = {
        **(data.evidence or {}),
        "checks": readiness["checks"], "wentLiveAt": datetime.utcnow().isoformat(), "wentLiveBy": actor_id,
    }
    db.commit()
    record_tax_audit(db, actor_id=actor_id, action="update", entity_type="france_employer_profile",
                     entity_id=profile.id, legal_reference="FR §11 gate H",
                     old_value={"readiness_status": old_status}, new_value={"readiness_status": "LIVE"})
    log_activity(db, organization_id, "France payroll marked LIVE (all readiness checks passed).", actor_id=actor_id)
    return get_france_readiness(db, organization_id)


# ── DSN (FR-030..033) ───────────────────────────────────────────────────

def create_france_dsn_submission(
    db: Session, organization_id: int, data: "FranceDsnSubmissionCreate", actor_id: Optional[int] = None,
) -> FranceDsnSubmission:
    """Open a FranceDsnSubmission (FR-030..033). payload_hash is computed
    over the immutable original identity; due_date follows the profile's
    filing_due_date_class (5th or 15th of M+1). Runs the FR-031 validator:
    clean → VALIDATED, blocked → DRAFT with validation_errors recorded.
    `correctionOfId` opens a correction of an earlier same-period
    submission; the original is never modified (FR-033/FR-053)."""
    period_start = data.periodStart
    if data.correctionOfId is not None:
        original = (db.query(FranceDsnSubmission)
                    .filter(FranceDsnSubmission.id == data.correctionOfId,
                            FranceDsnSubmission.organization_id == organization_id).first())
        if not original:
            raise NotFoundException("FranceDsnSubmission", data.correctionOfId)
        if original.period_start != period_start:
            raise BadRequestException("A correction must cover the same period as the submission it corrects.")
        if original.status not in {"BUSINESS_REJECTED", "ACKNOWLEDGED", "CRM_RESOLVED", "SETTLED"}:
            raise BadRequestException(
                f"Only a filed submission can be corrected (status {original.status}); "
                "an unfiled one is simply revalidated."
            )
    profile = db.query(EmployerFranceProfile).filter(
        EmployerFranceProfile.organization_id == organization_id).first()
    due_day = 5 if profile is not None and profile.filing_due_date_class == "M5" else 15
    period_end = data.periodEnd or (period_start.replace(day=28) + timedelta(days=4)).replace(day=1) - timedelta(days=1)
    due_date = (period_end.replace(day=28) + timedelta(days=4)).replace(day=1) + timedelta(days=due_day - 1)

    errors, blocked = _validate_france_dsn_completeness(db, organization_id, period_start)
    submission = FranceDsnSubmission(
        organization_id=organization_id,
        dsn_version="P26V01",
        release_ref=data.releaseRef,
        payload_hash=_fr_dsn_payload_hash(organization_id, period_start, period_end, data.releaseRef, due_date),
        period_start=period_start,
        period_end=period_end,
        due_date=due_date,
        status="DRAFT" if errors else "VALIDATED",
        validation_errors=errors or [],
        blocked_reason=blocked,
        correction_of_id=data.correctionOfId,
        created_by_id=actor_id,
    )
    db.add(submission)
    db.commit()
    db.refresh(submission)
    record_tax_audit(db, actor_id=actor_id, action="create", entity_type="france_dsn_submission",
                     entity_id=submission.id, legal_reference="FR-030/FR-031",
                     new_value={"period_start": str(period_start), "period_end": str(period_end),
                                "due_date": str(due_date), "status": submission.status,
                                "correction_of_id": data.correctionOfId})
    log_activity(db, organization_id,
                 f"France DSN {submission.dsn_version} for {period_start} opened ({submission.status}).",
                 actor_id=actor_id)
    return submission


def list_france_dsn_submissions(
    db: Session, organization_id: int, status: Optional[str] = None,
) -> List[FranceDsnSubmission]:
    query = db.query(FranceDsnSubmission).filter(FranceDsnSubmission.organization_id == organization_id)
    if status:
        if status not in _FR_DSN_STATUSES:
            raise BadRequestException(f"Unknown DSN status {status!r}.")
        query = query.filter(FranceDsnSubmission.status == status)
    return query.order_by(FranceDsnSubmission.period_start.desc()).all()


# Which lifecycle column must carry evidence for a target status (FR-032):
# an authority state is never asserted without the signal that proves it.
_FR_DSN_EVIDENCE_FOR_STATUS = {
    "ACKNOWLEDGED": ("technical_ack", "technicalAck (transport acknowledgement)"),
    "BUSINESS_REJECTED": ("business_crm", "businessCrm (the rejecting business CRM)"),
    "CRM_RESOLVED": ("business_crm", "businessCrm (the CRM showing anomalies resolved)"),
    "SETTLED": ("payment_state", "paymentState (the settlement reference)"),
}


def transition_france_dsn_submission(
    db: Session, organization_id: int, submission_id: int, data: "FranceDsnStatusUpdate",
    actor_id: Optional[int] = None,
) -> FranceDsnSubmission:
    """State-machine DSN lifecycle (FR-032/FR-033). Transport
    acknowledgement, business CRM and payment settlement are separate
    columns, and each authority state requires its evidence. DRAFT →
    VALIDATED re-runs the FR-031 validator (never a bypass). UNKNOWN is
    resolved only by reconciliation to ACKNOWLEDGED or BUSINESS_REJECTED —
    never re-queued or re-transmitted blind (FR-058)."""
    if data.status not in _FR_DSN_STATUSES:
        raise BadRequestException(f"Unknown DSN status {data.status!r}.")
    submission = (db.query(FranceDsnSubmission)
                  .filter(FranceDsnSubmission.id == submission_id,
                          FranceDsnSubmission.organization_id == organization_id).first())
    if not submission:
        raise NotFoundException("FranceDsnSubmission", submission_id)
    allowed = _FR_DSN_TRANSITIONS.get(submission.status, set())
    if data.status not in allowed:
        raise BadRequestException(
            f"Cannot transition a France DSN from {submission.status} to {data.status}."
        )
    if data.status == "VALIDATED":
        errors, blocked = _validate_france_dsn_completeness(db, organization_id, submission.period_start)
        if errors:
            submission.validation_errors = errors
            submission.blocked_reason = blocked
            db.commit()
            raise BadRequestException("The FR-031 pre-submit validator still fails: " + blocked)
        submission.validation_errors = []
        submission.blocked_reason = None
    if data.technicalAck is not None:
        submission.technical_ack = data.technicalAck
    if data.businessCrm is not None:
        submission.business_crm = data.businessCrm
    if data.paymentState is not None:
        submission.payment_state = data.paymentState
    evidence = _FR_DSN_EVIDENCE_FOR_STATUS.get(data.status)
    if evidence and not getattr(submission, evidence[0]):
        db.rollback()
        raise BadRequestException(f"Moving a DSN to {data.status} requires {evidence[1]}.")
    old_status = submission.status
    submission.status = data.status
    if data.blockedReason is not None:
        submission.blocked_reason = data.blockedReason
    if data.status == "TRANSMITTED":
        submission.submitted_at = datetime.utcnow()
    if data.status in {"ACKNOWLEDGED", "CRM_RESOLVED"}:
        submission.acknowledged_at = submission.acknowledged_at or datetime.utcnow()
    db.commit()
    db.refresh(submission)
    record_tax_audit(db, actor_id=actor_id, action="update", entity_type="france_dsn_submission",
                     entity_id=submission.id, legal_reference="FR-032",
                     old_value={"status": old_status}, new_value={"status": data.status})
    return submission


def create_france_dsn_outbox_item(
    db: Session, organization_id: int, data: "FranceDsnOutboxCreate", actor_id: Optional[int] = None,
) -> FranceDsnOutboxItem:
    """Durable idempotent outbox (FR-033). The idempotency key is the
    (organization, submission, action) identity — NOT the payload — so a
    retry with a changed payload still resolves to the one existing row
    instead of queuing a second transmission of the same action."""
    if data.action not in _FR_DSN_OUTBOX_ACTIONS:
        raise BadRequestException(f"action must be one of {sorted(_FR_DSN_OUTBOX_ACTIONS)}, got {data.action!r}.")
    submission = (db.query(FranceDsnSubmission)
                  .filter(FranceDsnSubmission.id == data.submissionId,
                          FranceDsnSubmission.organization_id == organization_id).first())
    if not submission:
        raise NotFoundException("FranceDsnSubmission", data.submissionId)

    idempotency_key = hashlib.sha256(
        json.dumps({"org": organization_id, "submission": data.submissionId, "action": data.action},
                   sort_keys=True).encode("utf-8")
    ).hexdigest()[:64]

    existing = (db.query(FranceDsnOutboxItem)
                .filter(FranceDsnOutboxItem.idempotency_key == idempotency_key).first())
    if existing:
        return existing

    item = FranceDsnOutboxItem(
        submission_id=data.submissionId,
        action=data.action,
        payload=data.payload or {},
        idempotency_key=idempotency_key,
        status="PENDING",
    )
    db.add(item)
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        existing = (db.query(FranceDsnOutboxItem)
                    .filter(FranceDsnOutboxItem.idempotency_key == idempotency_key).first())
        if existing:
            return existing
        raise
    db.refresh(item)
    return item


def list_france_dsn_outbox_items(
    db: Session, organization_id: int, submission_id: Optional[int] = None,
) -> List[FranceDsnOutboxItem]:
    query = (db.query(FranceDsnOutboxItem)
             .join(FranceDsnSubmission, FranceDsnSubmission.id == FranceDsnOutboxItem.submission_id)
             .filter(FranceDsnSubmission.organization_id == organization_id))
    if submission_id:
        query = query.filter(FranceDsnOutboxItem.submission_id == submission_id)
    return query.order_by(FranceDsnOutboxItem.created_at.desc()).all()


# Outbox transport states (FR-033/FR-058). UNKNOWN is resolved only by
# reconciliation (ACKNOWLEDGED, or FAILED once non-receipt is proven) —
# never straight back to SENT; only a DEFINITE failure may be re-sent.
_FR_DSN_OUTBOX_TRANSITIONS = {
    "PENDING": {"SENT", "UNKNOWN", "FAILED"},
    "SENT": {"ACKNOWLEDGED", "UNKNOWN", "FAILED"},
    "UNKNOWN": {"ACKNOWLEDGED", "FAILED"},
    "FAILED": {"SENT"},
    "ACKNOWLEDGED": set(),
}


def transition_france_dsn_outbox_item(
    db: Session, organization_id: int, item_id: int, status: str,
    last_error: Optional[str] = None, actor_id: Optional[int] = None,
) -> FranceDsnOutboxItem:
    """Transport-side outbox transition (FR-033/FR-058) — see
    _FR_DSN_OUTBOX_TRANSITIONS. Declaring an UNKNOWN item FAILED requires a
    reconciliation note (last_error)."""
    if status not in _FR_DSN_OUTBOX_STATUSES:
        raise BadRequestException(f"Outbox status must be one of {_FR_DSN_OUTBOX_STATUSES}, got {status!r}.")
    item = (db.query(FranceDsnOutboxItem)
            .join(FranceDsnSubmission, FranceDsnSubmission.id == FranceDsnOutboxItem.submission_id)
            .filter(FranceDsnOutboxItem.id == item_id,
                    FranceDsnSubmission.organization_id == organization_id).first())
    if not item:
        raise NotFoundException("FranceDsnOutboxItem", item_id)
    if status not in _FR_DSN_OUTBOX_TRANSITIONS.get(item.status, set()):
        raise BadRequestException(f"Cannot move a France DSN outbox item from {item.status} to {status}.")
    if item.status == "UNKNOWN" and status == "FAILED" and not (last_error or "").strip():
        raise BadRequestException("Declaring an UNKNOWN transmission FAILED requires the reconciliation result (last_error).")
    old_status = item.status
    item.status = status
    if status == "SENT":
        item.attempts += 1
    item.last_error = last_error
    if status in {"SENT", "ACKNOWLEDGED"}:
        item.sent_at = item.sent_at or datetime.utcnow()
    if status == "ACKNOWLEDGED":
        item.acknowledged_at = datetime.utcnow()
    db.commit()
    db.refresh(item)
    record_tax_audit(db, actor_id=actor_id, action="update", entity_type="france_dsn_outbox_item",
                     entity_id=item.id, legal_reference="FR-033",
                     old_value={"status": old_status}, new_value={"status": status})
    return item


# ═══════════════════════════════════════════════════════════════════════════
# Italy filing outbox (ZP-IT-ENG-001 §15/§16, IT-044/IT-048)
#
# Delivery state ONLY. Filing status, receipt_id, correction lineage and schema
# version live on the linked StatutoryFiling, exactly as France's outbox defers
# to FranceDsnSubmission. Nothing here generates a UniEmens/F24/LUL/CU/770
# document or talks to INPS/INAIL/Agenzia delle Entrate: this is the durable,
# idempotent queue a future transport worker drains, so a calculation can never
# fail because a government endpoint is down (IT-044).
# ═══════════════════════════════════════════════════════════════════════════

_IT_FILING_OUTBOX_ACTIONS = {
    "UNIEMENS_TRANSMIT", "F24_SUBMIT", "LUL_REGISTER",
    "CU_TRANSMIT", "770_TRANSMIT", "CORRECTION",
}
_IT_FILING_OUTBOX_STATUSES = ("PENDING", "SENT", "UNKNOWN", "ACKNOWLEDGED", "FAILED")

# Transport states (IT-048). UNKNOWN is a first-class status: a timeout yields
# UNKNOWN plus reconciliation, never a blind replay, so it can only leave via
# ACKNOWLEDGED or a FAILED proven not to have landed. Same graph as France's.
_IT_FILING_OUTBOX_TRANSITIONS = {
    "PENDING": {"SENT", "UNKNOWN", "FAILED"},
    "SENT": {"ACKNOWLEDGED", "UNKNOWN", "FAILED"},
    "UNKNOWN": {"ACKNOWLEDGED", "FAILED"},
    "FAILED": {"SENT"},
    "ACKNOWLEDGED": set(),
}


def create_italy_filing_outbox_item(
    db: Session, organization_id: int, data, actor_id: Optional[int] = None,
) -> ItalyFilingOutboxItem:
    """Enqueue one outbound Italian filing action (IT-044).

    The idempotency key is the (organization, action, statutory filing, period)
    IDENTITY — not the payload — so retrying with a corrected payload still
    resolves to the one existing row instead of queueing a second transmission
    of the same action. A CORRECTION is a distinct action precisely because it
    must queue separately from the original filing it corrects.
    """
    if data.action not in _IT_FILING_OUTBOX_ACTIONS:
        raise BadRequestException(
            f"action must be one of {sorted(_IT_FILING_OUTBOX_ACTIONS)}, got {data.action!r}.")

    # A linked filing must belong to THIS tenant; ownership is never taken from
    # the request body.
    if data.statutoryFilingId is not None:
        filing = (db.query(StatutoryFiling)
                  .filter(StatutoryFiling.id == data.statutoryFilingId,
                          StatutoryFiling.organization_id == organization_id).first())
        if not filing:
            raise NotFoundException("StatutoryFiling", data.statutoryFilingId)
        if (filing.jurisdiction or "").upper() not in {"IT", "ITALY"}:
            raise BadRequestException(
                f"StatutoryFiling {filing.id} is jurisdiction {filing.jurisdiction!r}, not Italy.")

    idempotency_key = hashlib.sha256(
        json.dumps({
            "org": organization_id,
            "action": data.action,
            "filing": data.statutoryFilingId,
            "period": data.periodKey,
        }, sort_keys=True).encode("utf-8")
    ).hexdigest()[:64]

    existing = (db.query(ItalyFilingOutboxItem)
                .filter(ItalyFilingOutboxItem.idempotency_key == idempotency_key).first())
    if existing:
        return existing

    item = ItalyFilingOutboxItem(
        organization_id=organization_id,
        action=data.action,
        statutory_filing_id=data.statutoryFilingId,
        period_key=data.periodKey,
        payload=data.payload or {},
        idempotency_key=idempotency_key,
        status="PENDING",
    )
    db.add(item)
    try:
        db.commit()
    except IntegrityError:
        # Two concurrent enqueues of the same action: the UNIQUE key is what
        # makes that safe, so resolve to the winner instead of failing.
        db.rollback()
        existing = (db.query(ItalyFilingOutboxItem)
                    .filter(ItalyFilingOutboxItem.idempotency_key == idempotency_key).first())
        if existing:
            return existing
        raise
    db.refresh(item)
    record_tax_audit(db, actor_id=actor_id, action="create",
                     entity_type="italy_filing_outbox_item", entity_id=item.id,
                     legal_reference="IT-044",
                     new_value={"action": item.action, "period": item.period_key,
                                "statutory_filing_id": item.statutory_filing_id})
    return item


def list_italy_filing_outbox_items(
    db: Session, organization_id: int,
    statutory_filing_id: Optional[int] = None,
    action: Optional[str] = None,
) -> List[ItalyFilingOutboxItem]:
    query = db.query(ItalyFilingOutboxItem).filter(
        ItalyFilingOutboxItem.organization_id == organization_id)
    if statutory_filing_id is not None:
        query = query.filter(ItalyFilingOutboxItem.statutory_filing_id == statutory_filing_id)
    if action:
        query = query.filter(ItalyFilingOutboxItem.action == action)
    return query.order_by(ItalyFilingOutboxItem.created_at.desc(),
                          ItalyFilingOutboxItem.id.desc()).all()


def transition_italy_filing_outbox_item(
    db: Session, organization_id: int, item_id: int, status: str,
    last_error: Optional[str] = None, actor_id: Optional[int] = None,
) -> ItalyFilingOutboxItem:
    """Transport-side transition (IT-048) — see _IT_FILING_OUTBOX_TRANSITIONS.

    Recording an UNKNOWN item as FAILED requires the reconciliation result
    (last_error), so "we never got a receipt" can never be written as a silent
    failure that invites a duplicate transmission.
    """
    if status not in _IT_FILING_OUTBOX_STATUSES:
        raise BadRequestException(
            f"Outbox status must be one of {_IT_FILING_OUTBOX_STATUSES}, got {status!r}.")
    item = (db.query(ItalyFilingOutboxItem)
            .filter(ItalyFilingOutboxItem.id == item_id,
                    ItalyFilingOutboxItem.organization_id == organization_id).first())
    if not item:
        raise NotFoundException("ItalyFilingOutboxItem", item_id)
    if status not in _IT_FILING_OUTBOX_TRANSITIONS.get(item.status, set()):
        raise BadRequestException(
            f"Cannot move an Italy filing outbox item from {item.status} to {status}.")
    if item.status == "UNKNOWN" and status == "FAILED" and not (last_error or "").strip():
        raise BadRequestException(
            "Declaring an UNKNOWN transmission FAILED requires the reconciliation result (last_error).")
    old_status = item.status
    item.status = status
    if status == "SENT":
        item.attempts += 1
    item.last_error = last_error
    if status in {"SENT", "ACKNOWLEDGED"}:
        item.sent_at = item.sent_at or datetime.utcnow()
    if status == "ACKNOWLEDGED":
        item.acknowledged_at = datetime.utcnow()
    db.commit()
    db.refresh(item)
    record_tax_audit(db, actor_id=actor_id, action="update",
                     entity_type="italy_filing_outbox_item", entity_id=item.id,
                     legal_reference="IT-048",
                     old_value={"status": old_status}, new_value={"status": status})
    return item


# ═══════════════════════════════════════════════════════════════════════════
# Italy F24 (§16, IT-043/IT-046/IT-047) — the governed causale catalog and the
# derivation of payable F24 lines from COMMITTED payroll.
#
# The rule this whole section is built around: IT-043 forbids inventing an F24
# causale. A causale is a real code in the Agenzia delle Entrate catalog, and a
# guessed one is not a broken feature, it is a wrong payment instruction. So
# there is no fallback code anywhere below, the catalog ships empty, and the
# builder REFUSES any component that has no governed causale rather than
# emitting a plausible-looking line.
#
# Second rule: IT-046/IT-047 — a F24 is built from COMMITTED payroll only. The
# builder rejects a draft run outright instead of estimating, because paying a
# liability computed from a run that may still be recalculated is worse than not
# paying it yet. Payment STATE (authorised/settled/…) deliberately lives on
# StatutoryFiling, never on the line, so a code correction can never rewrite the
# fact that money already moved (IT-045).
# ═══════════════════════════════════════════════════════════════════════════

_IT_F24_SECTIONS = {"ERARIO", "INPS", "REGIONI", "ENTI_LOCALI", "INAIL"}
_IT_F24_DIRECTIONS = {"DEBIT", "CREDIT"}

# The snapshot components that represent an actual remittance, and where each
# one is read from PayslipItem.it_calculation_snapshot. Only components listed
# here are ever asked of the catalog; the snapshot's other keys (contributory
# bases, annual net, wedge tax-free sums, TFR accruals, fringe/meal taxable
# values) are inputs to a computation or report-only, and none of them is a
# liability owed to a tax authority.
#
# Membership here is a statement about this engine's own output, not about
# statute: it says "the Italy engine computed a withholding on a payslip", and
# the catalog supplies which code it settles. That split is what lets IT-046 be
# satisfied without hardcoding a single causale.
_IT_F24_COMPONENT_PATHS = {
    "inps.employee":              ("inps", "employee"),
    "inps.employer":              ("inps", "employer"),
    "inps.additional1pct":        ("inps", "additional1pct"),
    "irpef.withheld":             ("irpef", "withheld"),
    "irpef.additionalDeduction":  ("irpef", "additionalDeduction"),
    "wedge.recoveredNow":         ("wedge", "recoveredNow"),
    "localTax.regionalSaldo":     ("localTax", "regionalSaldo"),
    "localTax.municipalSaldo":    ("localTax", "municipalSaldo"),
    "localTax.municipalAcconto":  ("localTax", "municipalAcconto"),
    "localTax.terminationWithheld": ("localTax", "terminationWithheld"),
}

# Components whose value is a recovery FROM the employee are still settled by a
# governed causale, and it is that catalog row's `direction` which decides
# DEBIT vs CREDIT - NOT a rule inferred here.
#
# An earlier draft of this module defaulted wedge.recoveredNow to CREDIT, on the
# reasoning that a recovery is money flowing back. That was wrong on two counts:
# it hardcoded a statutory judgement the platform has no authority to make
# (IT-043 is not limited to codes), and it silently overrode whatever the
# administrator had recorded in the catalog, because the column's default made
# `direction` always truthy. Whether a component offsets a liability on the F24
# is a fact about that causale, so it is now required on the catalog row and
# there is no inference left to get wrong.



def _it_f24_sections_from_catalog(catalog_rows, on_date: date) -> dict:
    """component_key -> catalog row, for the rows in force on `on_date`.

    Later effective_from wins, and a Draft row is honoured: a Draft causale is
    still a REAL code an administrator has recorded, and refusing to pay
    because the entry has not yet been through second review would be safer for
    nobody. Status matters for reporting, not for payability.
    """
    best: Dict[str, ItalyF24Causale] = {}
    for row in catalog_rows:
        if row.effective_from > on_date:
            continue
        if row.effective_to is not None and row.effective_to < on_date:
            continue
        current = best.get(row.component_key)
        if current is None or row.effective_from > current.effective_from:
            best[row.component_key] = row
    return best


def upsert_italy_f24_causale(
    db: Session, organization_id: int, data, actor_id: Optional[int] = None,
) -> ItalyF24Causale:
    """Record one governed F24 causale (IT-043/IT-046).

    This is an UPSERT BY IDENTITY, not a patch of the first row found: the
    identity is (organization, section, component, effectiveFrom). Re-submitting
    that same identity updates the existing row in place, so a typo in a causale
    can be corrected. Changing the code for a period that has ALREADY been built
    or filed is a different act, and is deliberately not offered here — that is a
    supersession (close the old row with an effectiveTo and open a new one), so
    the audit trail shows what code was in force when each F24 was produced.
    """
    section = (data.section or "").strip().upper()
    if section not in _IT_F24_SECTIONS:
        raise BadRequestException(
            f"section must be one of {sorted(_IT_F24_SECTIONS)}, got {data.section!r}.")
    direction = (data.direction or "").strip().upper()
    if direction not in _IT_F24_DIRECTIONS:
        raise BadRequestException(
            f"direction must be one of {sorted(_IT_F24_DIRECTIONS)}, got {data.direction!r}.")
    component_key = (data.componentKey or "").strip()
    if component_key not in _IT_F24_COMPONENT_PATHS:
        # Refusing an unknown component is the guard that stops this table
        # becoming a place to park arbitrary codes that no derivation will ever
        # read — a catalog entry nothing consumes looks like coverage but pays
        # nothing.
        raise BadRequestException(
            f"componentKey {component_key!r} is not an F24-remittable snapshot component. "
            f"Known components: {sorted(_IT_F24_COMPONENT_PATHS)}.")
    if data.effectiveTo is not None and data.effectiveTo < data.effectiveFrom:
        raise BadRequestException(
            "effectiveTo cannot be earlier than effectiveFrom.")

    existing = (db.query(ItalyF24Causale)
                .filter(ItalyF24Causale.organization_id == organization_id,
                        ItalyF24Causale.section == section,
                        ItalyF24Causale.component_key == component_key,
                        ItalyF24Causale.effective_from == data.effectiveFrom).first())
    if existing:
        old_tax_code = existing.tax_code
        existing.tax_code = data.taxCode
        existing.requires_region = bool(data.requiresRegion)
        existing.requires_comune = bool(data.requiresComune)
        existing.direction = direction
        existing.effective_to = data.effectiveTo
        existing.source_document_id = data.sourceDocumentId
        existing.notes = data.notes
        db.commit()
        db.refresh(existing)
        record_tax_audit(db, actor_id=actor_id, action="update",
                         entity_type="italy_f24_causale", entity_id=existing.id,
                         legal_reference="IT-043",
                         old_value={"tax_code": old_tax_code}, new_value={"tax_code": data.taxCode})
        return existing

    row = ItalyF24Causale(
        organization_id=organization_id,
        section=section,
        component_key=component_key,
        tax_code=data.taxCode,
        requires_region=bool(data.requiresRegion),
        requires_comune=bool(data.requiresComune),
        direction=direction,
        effective_from=data.effectiveFrom,
        effective_to=data.effectiveTo,
        source_document_id=data.sourceDocumentId,
        notes=data.notes,
        status="Draft",
        created_by_id=actor_id,
    )
    db.add(row)
    try:
        db.commit()
    except IntegrityError:
        # Concurrent inserts of the same identity: the UNIQUE constraint makes
        # the winner authoritative, so adopt it rather than failing.
        db.rollback()
        existing = (db.query(ItalyF24Causale)
                    .filter(ItalyF24Causale.organization_id == organization_id,
                            ItalyF24Causale.section == section,
                            ItalyF24Causale.component_key == component_key,
                            ItalyF24Causale.effective_from == data.effectiveFrom).first())
        if existing:
            return existing
        raise
    db.refresh(row)
    record_tax_audit(db, actor_id=actor_id, action="create",
                     entity_type="italy_f24_causale", entity_id=row.id,
                     legal_reference="IT-043",
                     new_value={"section": row.section, "component_key": row.component_key,
                                "tax_code": row.tax_code, "effective_from": row.effective_from.isoformat()})
    return row


def list_italy_f24_causales(
    db: Session, organization_id: int, section: Optional[str] = None,
    component_key: Optional[str] = None, as_of: Optional[date] = None,
) -> List[ItalyF24Causale]:
    query = db.query(ItalyF24Causale).filter(ItalyF24Causale.organization_id == organization_id)
    if section:
        query = query.filter(ItalyF24Causale.section == section.strip().upper())
    if component_key:
        query = query.filter(ItalyF24Causale.component_key == component_key.strip())
    if as_of is not None:
        query = query.filter(ItalyF24Causale.effective_from <= as_of,
                             or_(ItalyF24Causale.effective_to.is_(None),
                                 ItalyF24Causale.effective_to >= as_of))
    return query.order_by(ItalyF24Causale.section, ItalyF24Causale.component_key,
                          ItalyF24Causale.effective_from).all()


def _it_f24_snapshot_value(snapshot: Optional[dict], component_key: str) -> Decimal:
    """The Decimal this component contributes, or 0 when the payslip did not
    compute it. Snapshot values are stored as exact strings, never floats."""
    path = _IT_F24_COMPONENT_PATHS.get(component_key)
    if not path or not isinstance(snapshot, dict):
        return Decimal("0")
    node = snapshot
    for key in path:
        if not isinstance(node, dict) or key not in node:
            return Decimal("0")
        node = node[key]
    if node is None or node == "":
        return Decimal("0")
    try:
        return Decimal(str(node))
    except Exception:
        # A non-numeric snapshot value is a data-integrity problem upstream, not
        # something to silently treat as zero: zero would quietly underpay.
        raise BadRequestException(
            f"Snapshot component {component_key!r} is not numeric: {node!r}.")


def _it_f24_reference_date(reference_period: str) -> date:
    """'MM/YYYY' -> the last day of that month.

    Resolving to the period's END is deliberate. A causale that comes into force
    on the 15th of the month is in force for a payment referenced to the whole
    of that month, so testing the 15th would pick the wrong code for a liability
    that spans it.
    """
    parts = (reference_period or "").split("/")
    if len(parts) != 2 or len(parts[0]) != 2 or len(parts[1]) != 4:
        raise BadRequestException(
            f"referencePeriod must be MM/YYYY, got {reference_period!r}.")
    try:
        year, month = int(parts[1]), int(parts[0])
    except ValueError:
        raise BadRequestException(
            f"referencePeriod must be MM/YYYY, got {reference_period!r}.")
    if not 1 <= month <= 12:
        raise BadRequestException(f"referencePeriod month must be 01-12, got {month!r}.")
    if month == 12:
        return date(year + 1, 1, 1) - timedelta(days=1)
    return date(year, month + 1, 1) - timedelta(days=1)


def _it_f24_region_comune(db: Session, employee_id: int) -> Tuple[Optional[str], Optional[str]]:
    """The employee's tax-domicile (region, comune) codes.

    Read from the IT-031 statutory profile rather than from the employee's
    address, because it is the tax domicile that decides which regional and
    municipal authority the withholding is owed to.
    """
    from app.modules.payroll.models import EmployeeStatutoryProfile

    profile = (db.query(EmployeeStatutoryProfile)
               .filter(EmployeeStatutoryProfile.employee_id == employee_id).first())
    if profile is None:
        return None, None
    return profile.it_tax_domicile_region, profile.it_tax_domicile_comune


def build_italy_f24_lines(
    db: Session, organization_id: int, data, actor_id: Optional[int] = None,
) -> List[ItalyF24Line]:
    """Derive the payable F24 lines for one committed run and period (IT-046).

    Re-running this for the same (run, period) is safe and returns the same
    lines: identity is the full tuple the new UNIQUE constraint enforces, so a
    rebuild updates in place instead of appending a duplicate. That is what keeps
    a retried build from becoming a second payment instruction (IT-044).

    Raises rather than guessing. A component with no governed causale, a local
    authority line whose region/comune is unknown, or a draft run all stop the
    build, because each of those would otherwise produce a payable line that is
    wrong in a way nobody would notice until the money was gone.
    """
    if data.statutoryFilingId is not None:
        filing = (db.query(StatutoryFiling)
                  .filter(StatutoryFiling.id == data.statutoryFilingId,
                          StatutoryFiling.organization_id == organization_id).first())
        if not filing:
            raise NotFoundException("StatutoryFiling", data.statutoryFilingId)
        if (filing.jurisdiction or "").upper() not in {"IT", "ITALY"}:
            raise BadRequestException(
                f"StatutoryFiling {filing.id} is jurisdiction {filing.jurisdiction!r}, not Italy.")

    reference_period = data.referencePeriod.strip()
    period_end = _it_f24_reference_date(reference_period)

    run = (db.query(PayrollRun)
           .filter(PayrollRun.id == data.payrollRunId,
                   PayrollRun.organization_id == organization_id).first())
    if not run:
        raise NotFoundException("PayrollRun", data.payrollRunId)
    if PAYROLL_STATUS_ORDER.index(run.status) < PAYROLL_STATUS_ORDER.index(PayrollStatus.APPROVED):
        raise BadRequestException(
            f"Payroll run {run.id} is {run.status}; an F24 can only be built from a run "
            f"that is {PayrollStatus.APPROVED} or later (IT-044).")

    # Governed catalog in force for the period.
    catalog = _it_f24_sections_from_catalog(
        list_italy_f24_causales(db, organization_id, as_of=period_end), period_end)
    if not catalog:
        raise BadRequestException(
            f"No governed F24 causale is in force for {reference_period}. IT-043 forbids "
            f"inventing a causale, so this build refuses rather than emitting a guessed code. "
            f"Record the catalog entries first (POST /payroll/italy/f24/causales).")

    payslips = (db.query(PayslipItem)
                .filter(PayslipItem.payroll_run_id == run.id,
                        PayslipItem.organization_id == organization_id)
                .order_by(PayslipItem.id).all())

    # Aggregate by the line identity the UNIQUE constraint enforces.
    totals: Dict[tuple, Dict] = {}
    unmapped = set()
    for payslip in payslips:
        snapshot = payslip.it_calculation_snapshot or {}
        if not snapshot:
            continue
        region_code, comune_code = _it_f24_region_comune(db, payslip.employee_id)
        for component_key in _IT_F24_COMPONENT_PATHS:
            amount = _it_f24_snapshot_value(snapshot, component_key)
            if amount == 0:
                continue
            causale = catalog.get(component_key)
            if causale is None:
                # A non-zero withholding with no governed causale. Silently
                # dropping it would underpay while looking like a clean build.
                unmapped.add(component_key)
                continue
            if (causale.requires_region or causale.requires_comune) and not (region_code and comune_code):
                raise BadRequestException(
                    f"{component_key!r} is settled by causale {causale.tax_code} which requires the "
                    f"employee's tax-domicile region AND comune codes, but employee "
                    f"{payslip.employee_id} has none recorded (IT-031). Record the tax domicile; "
                    f"the authority to pay cannot be determined without it.")
            direction = causale.direction
            key = (causale.section, causale.tax_code, region_code, comune_code, direction)
            bucket = totals.setdefault(key, {"amount": Decimal("0"), "sources": []})
            bucket["amount"] += amount
            bucket["sources"].append({
                "payslipItemId": payslip.id,
                "employeeId": payslip.employee_id,
                "componentKey": component_key,
                "amount": str(amount),
            })

    if unmapped:
        raise BadRequestException(
            f"Committed payroll contains F24 liabilities with no governed causale: "
            f"{sorted(unmapped)}. IT-043 forbids inventing a causale, so nothing was built. "
            f"Record these components in the catalog first.")

    # Lines already derived for this identity (a rebuild updates, never appends).
    existing = {(row.section, row.tax_code, row.region_code, row.comune_code):
                row for row in (db.query(ItalyF24Line)
                                .filter(ItalyF24Line.payroll_run_id == run.id,
                                        ItalyF24Line.organization_id == organization_id).all())}

    created, updated = [], []
    for (section, tax_code, region_code, comune_code, direction), bucket in totals.items():
        debit = bucket["amount"] if direction == "DEBIT" else Decimal("0")
        credit = bucket["amount"] if direction == "CREDIT" else Decimal("0")
        match = existing.get((section, tax_code, region_code, comune_code))
        if match is not None:
            match.debit_amount = debit
            match.credit_amount = credit
            match.reference_period = reference_period
            match.source_lines = bucket["sources"]
            if data.statutoryFilingId is not None:
                match.statutory_filing_id = data.statutoryFilingId
            updated.append(match)
            continue
        line = ItalyF24Line(
            organization_id=organization_id,
            statutory_filing_id=data.statutoryFilingId,
            payroll_run_id=run.id,
            section=section,
            tax_code=tax_code,
            region_code=region_code,
            comune_code=comune_code,
            reference_period=reference_period,
            debit_amount=debit,
            credit_amount=credit,
            source_lines=bucket["sources"],
        )
        db.add(line)
        created.append(line)
    db.commit()
    for line in created:
        db.refresh(line)
    for line in updated:
        db.refresh(line)
    record_tax_audit(db, actor_id=actor_id, action="create" if created else "update",
                     entity_type="italy_f24_line",
                     entity_id=(created[0].id if created else updated[0].id) if (created or updated) else 0,
                     legal_reference="IT-046",
                     new_value={"payroll_run_id": run.id, "reference_period": reference_period,
                                "lines": len(created) + len(updated)})
    return created + updated


# ═══════════════════════════════════════════════════════════════════════════
# Italy Libro Unico del Lavoro (§20, IT-058/IT-059/IT-060) — the sequential,
# inalterable, retained registration ledger.
#
# IT-058 is emphatic that the LUL is "an auditable statutory record, not a PDF
# theme", and names four things that are therefore engineering requirements
# rather than formatting: SEQUENCE, INALTERABILITY, RETENTION, and the
# AUTHORIZED METHOD. Each is implemented as a mechanism below rather than
# asserted in a docstring:
#
#   SEQUENCE      - allocated per employer, contiguous, and never reused.
#   INALTERABILITY- content_hash over the exact registered payload, plus a
#                  verification pass that recomputes it. A correction is a NEW
#                  entry pointing at the one it corrects; the original is never
#                  rewritten, because "do not rewrite prior LUL evidence
#                  invisibly" (spec §20, Correction) is the whole point.
#   RETENTION     - five years from the LAST registration, so the horizon
#                  ADVANCES on every new registration. A per-entry fixed date
#                  would start expiring the earliest evidence exactly when the
#                  employer's retention obligation is still live.
#   METHOD        - snapshot of the employer's authorized method at
#                  registration time, so a later change never rewrites history.
#
# Reconciliation (IT-059) is achieved by construction rather than by a
# comparison: the registered payload is DERIVED from the committed payslip, so a
# LUL line cannot disagree with the payslip it describes.
#
# No transmission here. The authorized method belongs to the employer or their
# consultant; this ledger records what they registered. Delivery stays on the
# /italy/filing-outbox queue.
# ═══════════════════════════════════════════════════════════════════════════

# Spec §20: retention is "five years from the last registration".
_IT_LUL_RETENTION_YEARS = 5

_IT_LUL_ENTRY_TYPES = {"ORIGINAL", "CORRECTION"}


def _it_month_end(year: int, month: int) -> date:
    """The last calendar day of a month, leap-year aware."""
    return date(year + 1, 1, 1) - timedelta(days=1) if month == 12 \
        else date(year, month + 1, 1) - timedelta(days=1)


def _it_lul_reference_month(reference_month: str) -> date:
    """'YYYY-MM' -> the last day of that month.

    The deadline is "end of month following the reference month" (spec §20,
    Timing), so the reference month is resolved to its end before that is
    computed.
    """
    parts = (reference_month or "").split("-")
    if len(parts) != 2 or len(parts[0]) != 4 or len(parts[1]) != 2:
        raise BadRequestException(
            f"referenceMonth must be YYYY-MM, got {reference_month!r}.")
    try:
        year, month = int(parts[0]), int(parts[1])
    except ValueError:
        raise BadRequestException(
            f"referenceMonth must be YYYY-MM, got {reference_month!r}.")
    if not 1 <= month <= 12:
        raise BadRequestException(f"referenceMonth month must be 01-12, got {month!r}.")
    return _it_month_end(year, month)


def _it_lul_deadline(reference_month: str) -> date:
    """End of the month FOLLOWING the reference month (spec §20, Timing).

    Resolved as a calendar step, never by adding a fixed number of days:
    "end of month following" is a calendar instruction, and "+31 days" would
    push a 31-day reference month into the month AFTER next (2026-03 would
    deadline on 2026-05-02, a full month late and silently unlawful).
    """
    period_end = _it_lul_reference_month(reference_month)
    if period_end.month == 12:
        return _it_month_end(period_end.year + 1, 1)
    return _it_month_end(period_end.year, period_end.month + 1)


def _it_lul_payload(employee, payslip, event_kind: Optional[str]) -> dict:
    """Exactly what gets registered for one employee-month.

    Built from the COMMITTED payslip, which is what makes IT-059 reconciliation
    true by construction: these figures are not re-derived from the employee
    record or re-entered by hand, they are the payslip's own snapshot and totals.
    """
    snapshot = (payslip.it_calculation_snapshot or {}) if payslip else {}
    return {
        "employeeCode": getattr(employee, "employee_code", None),
        "employeeName": getattr(employee, "name", None),
        "referenceMonth": None,
        "eventKind": event_kind,
        # Gross pay, the statutory deductions the employee actually bore, and net
        # pay - the same values the payslip shows, so a discrepancy between the
        # two artifacts is impossible by construction.
        "grossPay": str(payslip.gross_pay) if payslip and payslip.gross_pay is not None else None,
        "totalDeductions": str(payslip.total_deductions) if payslip and payslip.total_deductions is not None else None,
        "netPay": str(payslip.net_pay) if payslip and payslip.net_pay is not None else None,
        # The Italy statutory breakdown, verbatim from the engine snapshot.
        "it": snapshot,
    }


def _it_lul_content_hash(payload: dict) -> str:
    """SHA-256 over the canonical JSON of what was registered.

    sort_keys matters: the same content must hash identically regardless of dict
    insertion order, or a verification pass would report drift on a record that
    never changed.
    """
    return hashlib.sha256(
        json.dumps(payload, sort_keys=True, default=str).encode("utf-8")
    ).hexdigest()


def _it_lul_next_sequence(db: Session, organization_id: int) -> int:
    """The next per-employer sequence number.

    MAX+1 rather than COUNT+1: a gap left by a deleted or rolled-back entry must
    not cause a later registration to reuse its number, because that number is
    the identifier an auditor cites.
    """
    highest = (db.query(sa_func.max(ItalyLulEntry.sequence_number))
               .filter(ItalyLulEntry.organization_id == organization_id).scalar())
    return (highest or 0) + 1


def _it_lul_apply_retention(db: Session, organization_id: int, registered_on: date) -> None:
    """Advance the employer's whole retention horizon to five years out.

    Spec §20 sets retention from the LAST registration, so every entry the
    employer holds must survive that long - not just the newest one. Entries
    registered years ago and never touched again are exactly the evidence the
    obligation exists to preserve.
    """
    horizon = date(registered_on.year + _IT_LUL_RETENTION_YEARS, registered_on.month,
                   registered_on.day)
    for entry in (db.query(ItalyLulEntry)
                  .filter(ItalyLulEntry.organization_id == organization_id)
                  .all()):
        if entry.retention_until is None or entry.retention_until < horizon:
            entry.retention_until = horizon


def _it_lul_authoritative_method(db: Session, organization_id: int) -> Optional[str]:
    from app.modules.payroll.models import EmployerItalyProfile

    profile = (db.query(EmployerItalyProfile)
               .filter(EmployerItalyProfile.organization_id == organization_id).first())
    return getattr(profile, "lul_method", None) if profile else None


def build_italy_lul_entries(
    db: Session, organization_id: int, data, actor_id: Optional[int] = None,
) -> List[ItalyLulEntry]:
    """Register the committed payroll for one reference month in the LUL ledger.

    One entry per employee payslip, sequentially numbered for the employer, each
    carrying the exact content registered and its hash. Re-running for the same
    run and month is a NO-OP that returns the existing entries, so a retried
    registration cannot consume sequence numbers and leave holes in a record the
    auditor will read as contiguous.
    """
    reference_month = data.referenceMonth.strip()
    _it_lul_reference_month(reference_month)   # validate shape before any write

    if data.eventKind is not None and not data.eventKind.strip():
        raise BadRequestException("eventKind cannot be blank when supplied.")

    run = (db.query(PayrollRun)
           .filter(PayrollRun.id == data.payrollRunId,
                   PayrollRun.organization_id == organization_id).first())
    if not run:
        raise NotFoundException("PayrollRun", data.payrollRunId)
    if PAYROLL_STATUS_ORDER.index(run.status) < PAYROLL_STATUS_ORDER.index(PayrollStatus.APPROVED):
        raise BadRequestException(
            f"Payroll run {run.id} is {run.status}; the LUL records COMMITTED payroll, so the "
            f"run must be {PayrollStatus.APPROVED} or later (IT-058).")

    payslips = (db.query(PayslipItem)
                .filter(PayslipItem.payroll_run_id == run.id,
                        PayslipItem.organization_id == organization_id)
                .order_by(PayslipItem.id).all())
    if not payslips:
        raise BadRequestException(
            f"Payroll run {run.id} has no payslips, so there is nothing to register in the LUL.")

    # Already registered for this run and month: idempotent, and deliberately
    # checked BEFORE allocating sequence numbers.
    existing = (db.query(ItalyLulEntry)
                .filter(ItalyLulEntry.payroll_run_id == run.id,
                        ItalyLulEntry.organization_id == organization_id,
                        ItalyLulEntry.reference_month == reference_month,
                        ItalyLulEntry.entry_type == "ORIGINAL")
                .order_by(ItalyLulEntry.sequence_number).all())
    if existing:
        return existing

    method = _it_lul_authoritative_method(db, organization_id)
    if not method:
        # IT-058 names the AUTHORIZED METHOD as part of the specification, not an
        # optional attribute. Registering without one produces a record nobody
        # can attest was made under a valid arrangement.
        raise BadRequestException(
            "This organization has no authorized LUL method recorded (§17G). Record it on the "
            "Italy employer profile before registering.")

    registered_on = date.today()
    sequence = _it_lul_next_sequence(db, organization_id)
    created = []
    for payslip in payslips:
        employee = (db.query(PayrollEmployee)
                    .filter(PayrollEmployee.id == payslip.employee_id,
                            PayrollEmployee.organization_id == organization_id).first())
        if employee is None:
            # The payslip names an employee outside this tenant. Registering it
            # would publish another org's worker to a statutory registry.
            raise BadRequestException(
                f"Payslip {payslip.id} names employee {payslip.employee_id}, which does not "
                f"resolve inside this organization.")
        payload = _it_lul_payload(employee, payslip, data.eventKind)
        payload["referenceMonth"] = reference_month
        entry = ItalyLulEntry(
            organization_id=organization_id,
            employee_id=employee.id,
            reference_month=reference_month,
            sequence_number=sequence,
            entry_type="ORIGINAL",
            payslip_item_id=payslip.id,
            payroll_run_id=run.id,
            content_hash=_it_lul_content_hash(payload),
            payload=payload,
            event_kind=data.eventKind,
            method=method,
            registered_reference=reference_month,
            registered_at=datetime.combine(registered_on, datetime.min.time()),
            retention_until=registered_on,
        )
        db.add(entry)
        created.append(entry)
        sequence += 1

    db.flush()
    _it_lul_apply_retention(db, organization_id, registered_on)
    db.commit()
    for entry in created:
        db.refresh(entry)
    record_tax_audit(db, actor_id=actor_id, action="create",
                     entity_type="italy_lul_entry", entity_id=created[0].id,
                     legal_reference="IT-058",
                     new_value={"payroll_run_id": run.id, "reference_month": reference_month,
                                "entries": len(created), "method": method})
    return created


def correct_italy_lul_entry(
    db: Session, organization_id: int, entry_id: int, data, actor_id: Optional[int] = None,
) -> ItalyLulEntry:
    """Register a CORRECTION to an existing LUL entry (spec §20, Correction).

    The original row is never touched. A correction is a NEW, higher-sequence
    entry carrying `corrects_entry_id`, because "do not rewrite prior LUL
    evidence invisibly" means the original and the correction must both remain
    readable - an auditor has to see what was first registered AND what changed.
    Overwriting the row would destroy the very evidence that rule protects.
    """
    original = (db.query(ItalyLulEntry)
                .filter(ItalyLulEntry.id == entry_id,
                        ItalyLulEntry.organization_id == organization_id).first())
    if not original:
        raise NotFoundException("ItalyLulEntry", entry_id)
    if original.entry_type == "CORRECTION":
        # Corrections correct ORIGINALS. Allowing a chain makes "the current
        # truth" ambiguous without a defined resolution rule.
        raise BadRequestException(
            f"LUL entry {entry_id} is itself a CORRECTION; a correction corrects an ORIGINAL entry.")

    reason = (data.reason or "").strip()
    if not reason:
        raise BadRequestException(
            "A LUL correction requires a reason — the correction record is the only "
            "explanation an auditor will ever have of why an original was superseded.")

    registered_on = date.today()
    payload = dict(original.payload or {})
    payload["correctsSequence"] = original.sequence_number
    payload["correctionReason"] = reason
    for field, value in (("eventKind", data.eventKind),):
        if value is not None:
            payload[field] = value

    entry = ItalyLulEntry(
        organization_id=organization_id,
        employee_id=original.employee_id,
        reference_month=original.reference_month,
        sequence_number=_it_lul_next_sequence(db, organization_id),
        entry_type="CORRECTION",
        corrects_entry_id=original.id,
        payslip_item_id=original.payslip_item_id,
        payroll_run_id=original.payroll_run_id,
        content_hash=_it_lul_content_hash(payload),
        payload=payload,
        event_kind=data.eventKind or original.event_kind,
        method=original.method,          # the correction corrects THAT registration
        registered_reference=original.registered_reference or original.reference_month,
        registered_at=datetime.combine(registered_on, datetime.min.time()),
        retention_until=registered_on,
    )
    db.add(entry)
    db.flush()
    _it_lul_apply_retention(db, organization_id, registered_on)
    try:
        db.commit()
    except IntegrityError:
        db.rollback()
        raise BadRequestException(
            "A concurrent registration took this sequence number; the LUL ledger must be "
            "numbered serially. Retry the correction.")
    db.refresh(entry)
    record_tax_audit(db, actor_id=actor_id, action="create",
                     entity_type="italy_lul_entry", entity_id=entry.id,
                     legal_reference="IT-058",
                     new_value={"corrects_entry_id": original.id, "reason": reason})
    return entry


def verify_italy_lul_integrity(
    db: Session, organization_id: int, reference_month: Optional[str] = None,
) -> dict:
    """Recompute every content hash and report drift, gaps and retention (IT-058).

    Inalterability is only a real guarantee if something checks it. This is that
    check: it re-derives each hash from the stored payload, so a payload edited
    in the database outside the service shows up here rather than at an audit
    three years later. It also reports sequence contiguity and the retention
    horizon, because those are the other two mechanisms IT-058 names.
    """
    query = db.query(ItalyLulEntry).filter(ItalyLulEntry.organization_id == organization_id)
    if reference_month:
        query = query.filter(ItalyLulEntry.reference_month == reference_month.strip())
    entries = query.order_by(ItalyLulEntry.sequence_number).all()

    drifted = [e.sequence_number for e in entries
               if e.payload is not None and _it_lul_content_hash(e.payload) != e.content_hash]
    unhashed = [e.sequence_number for e in entries if e.payload is None]

    numbers = [e.sequence_number for e in entries]
    num_set = set(numbers)
    gaps = [n for n in range(numbers[0], numbers[-1] + 1) if n not in num_set] \
        if numbers and numbers[-1] > numbers[0] else []
    retention = min((e.retention_until for e in entries), default=None)
    return {
        "entries": len(entries),
        "firstSequence": numbers[0] if numbers else None,
        "lastSequence": numbers[-1] if numbers else None,
        "sequenceGaps": gaps,
        "driftedSequenceNumbers": drifted,
        "unverifiableSequenceNumbers": unhashed,
        "earliestRetentionUntil": retention,
        "verifiedAt": date.today().isoformat(),
    }


def list_italy_lul_entries(
    db: Session, organization_id: int, reference_month: Optional[str] = None,
    employee_id: Optional[int] = None, payroll_run_id: Optional[int] = None,
    entry_type: Optional[str] = None, include_superseded: bool = True,
) -> List[ItalyLulEntry]:
    """List this employer's LUL ledger, newest registration last.

    By default superseded entries are INCLUDED: an ORIGINAL that has been
    corrected is still statutory evidence and hiding it would defeat IT-058.
    Pass include_superseded=False for the current-truth view.
    """
    query = db.query(ItalyLulEntry).filter(ItalyLulEntry.organization_id == organization_id)
    if reference_month:
        query = query.filter(ItalyLulEntry.reference_month == reference_month.strip())
    if employee_id is not None:
        query = query.filter(ItalyLulEntry.employee_id == employee_id)
    if payroll_run_id is not None:
        query = query.filter(ItalyLulEntry.payroll_run_id == payroll_run_id)
    if entry_type:
        query = query.filter(ItalyLulEntry.entry_type == entry_type.strip().upper())
    entries = query.order_by(ItalyLulEntry.sequence_number).all()
    if not include_superseded:
        superseded = {e.corrects_entry_id for e in entries if e.corrects_entry_id}
        entries = [e for e in entries if e.id not in superseded]
    return entries


def get_italy_lul_deadline(db: Session, organization_id: int, reference_month: str) -> dict:
    """The §20 registration deadline for a reference month, and whether it passed.

    Reported rather than enforced. Refusing to record a registration that
    legally happened would be worse than recording it late — the employer's
    obligation is to register, and a late registration is still the truth. What
    the platform owes is an accurate, visible answer to "was this in time".
    """
    reference_month = (reference_month or "").strip()
    period_end = _it_lul_reference_month(reference_month)
    deadline = _it_lul_deadline(reference_month)
    registered = (db.query(ItalyLulEntry)
                  .filter(ItalyLulEntry.organization_id == organization_id,
                          ItalyLulEntry.reference_month == reference_month).all())
    first = min((e.registered_at.date() for e in registered), default=None)
    return {
        "referenceMonth": reference_month,
        "referencePeriodEnd": period_end.isoformat(),
        "deadline": deadline.isoformat(),
        "registered": bool(registered),
        "firstRegisteredAt": first.isoformat() if first else None,
        "metDeadline": (first <= deadline) if first else None,
        "daysLate": max(0, (first - deadline).days) if first else None,
        "entries": len(registered),
    }


# ═══════════════════════════════════════════════════════════════════════════
# Italy TFR (§13, IT-037/IT-038/IT-039/IT-040/IT-041) — the dedicated liability
# ledger for Trattamento di Fine Rapporto.
#
# IT-037: TFR is a LIABILITY, not a monthly bonus earning. Payroll journals
# distinguish the employer expense, the employee TFR liability, and the amounts
# transferred to pension fund / Fondo Tesoreria.
# IT-038: Changing TFR destination redirects FUTURE funding flows; it never
# erases accrued employee entitlement history. The ledger records the destination
# in force for EACH entry.
# IT-039: TFR taxation is the statutory separate-tax method (TUIR art. 17/19),
# never the employee's current IRPEF marginal rate.
# IT-040: Fondo Tesoreria obligation threshold is prior-calendar-year average
# headcount >= 60 (2026-2027), falling to 50 (2028-2031), 40 (2032+).
# IT-041: Transferred-worker exceptions to the Tesoreria threshold require
# explicit evidence, never inferred.
#
# The engine (italy.py resolve_tfr) computes the monthly accrual:
#   gross = qualifying_remuneration / 13.5
#   offset = contributory_base * 0.5% (INPS)
#   net = gross - offset
# The service posts these to the ledger with the destination in force, and
# provides annual revaluation and settlement operations.
# ═══════════════════════════════════════════════════════════════════════════

_IT_TFR_ENTRY_TYPES = {
    "ACCRUAL", "INPS_OFFSET", "REVALUATION", "REVALUATION_TAX",
    "TRANSFER_PENSION_FUND", "TRANSFER_TESORERIA", "ADVANCE",
    "SETTLEMENT", "SETTLEMENT_TAX",
}

_IT_TFR_DESTINATIONS = {"AZIENDA", "FONDO_PENSIONE", "FONDO_TESORERIA"}

# Fondo Tesoreria headcount threshold (Budget Law 2026: 60 for 2026-2027).
_IT_TESORERIA_THRESHOLD_2026_2027 = 60


def _it_tfr_idempotency_key(organization_id: int, employee_id: int,
                            entry_type: str, tax_year: int,
                            source_ref: str) -> str:
    """One payslip posts one accrual, forever.

    The identity is the SOURCE (the payslip), not the date it was posted. An
    earlier version keyed on the posting date, which meant re-running the
    posting the next morning inserted a second ACCRUAL for the same payslip and
    silently doubled the employee's provision — the exact failure an idempotent
    ledger exists to prevent. source_ref is the payslip_item_id for an accrual.
    """
    return hashlib.sha256(
        json.dumps({
            "org": organization_id,
            "emp": employee_id,
            "type": entry_type,
            "year": tax_year,
            "source": str(source_ref),
        }, sort_keys=True).encode("utf-8")
    ).hexdigest()[:64]


def _it_tfr_employer_profile(db: Session, organization_id: int):
    from app.modules.payroll.models import EmployerItalyProfile
    return (db.query(EmployerItalyProfile)
            .filter(EmployerItalyProfile.organization_id == organization_id).first())


def post_italy_tfr_accrual(
    db: Session, organization_id: int, payroll_run_id: int,
    actor_id: Optional[int] = None,
) -> List[ItalyTfrLedgerEntry]:
    """Post TFR accruals for a COMMITTED payroll run (IT-037).

    One entry per employee payslip, idempotent by (org, emp, ACCRUAL, year, date).
    The destination (AZIENDA / FONDO_PENSIONE / FONDO_TESORERIA) is read from the
    employee's statutory profile and validated against the Tesoreria headcount
    rule (IT-040/IT-041). An absent destination leaves the routing unresolved —
    the accrual is still posted, but a subsequent filing stage must settle it.
    """
    run = (db.query(PayrollRun)
           .filter(PayrollRun.id == payroll_run_id,
                   PayrollRun.organization_id == organization_id).first())
    if not run:
        raise NotFoundException("PayrollRun", payroll_run_id)
    if PAYROLL_STATUS_ORDER.index(run.status) < PAYROLL_STATUS_ORDER.index(PayrollStatus.APPROVED):
        raise BadRequestException(
            f"Payroll run {run.id} is {run.status}; TFR accruals are posted from "
            f"{PayrollStatus.APPROVED} or later (IT-037).")

    payslips = (db.query(PayslipItem)
                .filter(PayslipItem.payroll_run_id == run.id,
                        PayslipItem.organization_id == organization_id)
                .order_by(PayslipItem.id).all())
    if not payslips:
        raise BadRequestException(
            f"Payroll run {run.id} has no payslips; nothing to accrue.")

    employer = _it_tfr_employer_profile(db, organization_id)
    headcount = getattr(employer, "prior_year_avg_headcount", None)
    threshold = _IT_TESORERIA_THRESHOLD_2026_2027

    created = []
    tax_year = run.period_start.year if run.period_start else date.today().year
    entry_date = date.today()

    for payslip in payslips:
        snapshot = payslip.it_calculation_snapshot or {}
        tfr_snap = snapshot.get("tfr", {})
        gross = tfr_snap.get("accrual") or tfr_snap.get("gross")
        offset = tfr_snap.get("inpsOffset") or tfr_snap.get("inps_offset")
        net = tfr_snap.get("net")

        if gross is None or net is None:
            # The engine did not compute TFR for this payslip (e.g. non-Italian).
            continue

        # The destination is an ELECTION held on the employee's statutory
        # profile, not a computed fact: the engine cannot know which of the
        # three depositories an employee (or their employer) chose, so the
        # snapshot may only echo what was already decided. Reading the snapshot
        # first would let a stale or absent snapshot silently override the
        # election on file, which is the opposite of what IT-038/IT-040 govern.
        profile = (db.query(EmployeeStatutoryProfile)
                   .filter(EmployeeStatutoryProfile.employee_id == payslip.employee_id,
                           EmployeeStatutoryProfile.organization_id == organization_id)
                   .order_by(EmployeeStatutoryProfile.effective_from.desc()).first())
        elected = getattr(profile, "it_tfr_destination", None)
        destination = (elected or tfr_snap.get("destination") or "").upper()

        if destination not in _IT_TFR_DESTINATIONS:
            destination = "UNRESOLVED"
        elif destination == "FONDO_PENSIONE":
            if not getattr(profile, "it_pension_fund", None):
                raise BadRequestException(
                    f"Employee {payslip.employee_id}: TFR destination is FONDO_PENSIONE "
                    f"but no pension fund is recorded. An election to a complementary "
                    f"pension fund is void without naming the fund (IT-038); record "
                    f"it_pension_fund on the employee profile or change the destination.")
        elif destination == "FONDO_TESORERIA":
            if headcount is None or headcount < threshold:
                raise BadRequestException(
                    f"Employee {payslip.employee_id}: TFR destination is FONDO_TESORERIA "
                    f"but prior-year avg headcount ({headcount}) is below the {threshold} "
                    f"threshold (IT-040). Record the headcount or change the destination.")
        elif destination == "AZIENDA":
            if headcount is not None and headcount >= threshold:
                raise BadRequestException(
                    f"Employee {payslip.employee_id}: prior-year avg headcount {headcount} >= "
                    f"{threshold} requires FONDO_TESORERIA, not AZIENDA (IT-040). "
                    f"Record transferred-worker evidence (IT-041) or change the destination.")

        idem = _it_tfr_idempotency_key(organization_id, payslip.employee_id,
                                       "ACCRUAL", tax_year, payslip.id)
        existing = (db.query(ItalyTfrLedgerEntry)
                    .filter(ItalyTfrLedgerEntry.idempotency_key == idem).first())
        if existing:
            created.append(existing)
            continue

        entry = ItalyTfrLedgerEntry(
            organization_id=organization_id,
            employee_id=payslip.employee_id,
            entry_type="ACCRUAL",
            tax_year=tax_year,
            entry_date=entry_date,
            amount=Decimal(str(net)),
            destination=destination if destination != "UNRESOLVED" else None,
            pension_fund=getattr(profile, "it_pension_fund", None)
            if destination == "FONDO_PENSIONE" else None,
            payslip_item_id=payslip.id,
            payroll_run_id=run.id,
            evidence={
                "grossAccrual": str(gross),
                "inpsOffset": str(offset) if offset else "0",
                "netAccrual": str(net),
            },
            idempotency_key=idem,
        )
        db.add(entry)
        created.append(entry)

    if created:
        db.commit()
        for e in created:
            db.refresh(e)
        record_tax_audit(db, actor_id=actor_id, action="create",
                         entity_type="italy_tfr_ledger_entry",
                         entity_id=created[0].id, legal_reference="IT-037",
                         new_value={"payroll_run_id": run.id, "tax_year": tax_year,
                                    "entries": len(created)})
    return created


def post_italy_tfr_revaluation(
    db: Session, organization_id: int, tax_year: int,
    istat_foi_increase_pct: Decimal, months: int = 12,
    actor_id: Optional[int] = None,
) -> List[ItalyTfrLedgerEntry]:
    """Post the annual TFR revaluation on prior-year balances (IT-037/IT-038).

    Called at 31 December (or termination). Revalues the TFR each employee accrued
    up to the PREVIOUS 31 December — never the current year's quota. The
    coefficient is:

      coefficient = fixed_pct * months/12 + max(0, istat_increase) * istat_share / 100

    revaluation = prior_balance * coefficient / 100
    revaluation_tax = revaluation * tax_pct / 100  (substitute tax, employee side)

    Both entries carry the same tax_year (the year the revaluation belongs to)
    and the SAME employee_id, because a revaluation belongs to a person, not to
    the employer's aggregate.
    """
    if not isinstance(months, int) or not 0 <= months <= 12:
        raise BadRequestException("months must be an integer 0-12.")
    if Decimal(str(istat_foi_increase_pct)) < 0:
        raise BadRequestException("istat_foi_increase_pct must be non-negative (a fall in the index "
                                  "does not reduce the fixed part below zero growth).")

    rates = _load_italy_reval_rates(db, organization_id)
    fixed_pct = rates["fixed_pct"]
    istat_share = rates["istat_share"]
    tax_pct = rates["tax_pct"]

    istat = max(Decimal("0"), Decimal(str(istat_foi_increase_pct)))
    coefficient = (fixed_pct * Decimal(months) / Decimal(12)
                   + istat * istat_share / Decimal(100))

    # Revaluation is PER EMPLOYEE, not an employer-level lump. Each employee's
    # fund is their own accrued provision (art. 2120 c.c.), it is revalued on
    # the quota THEY accrued, and it is theirs to receive. One aggregate row
    # with employee_id=NULL would lose exactly that: which employee's fund was
    # revalued, by how much, and what substitute tax was withheld from whom.
    # A termination mid-year also revalues one person, not the whole employer.
    carriers = ["ACCRUAL", "REVALUATION", "TRANSFER_PENSION_FUND", "TRANSFER_TESORERIA"]
    balances = (db.query(
        ItalyTfrLedgerEntry.employee_id,
        sa_func.sum(ItalyTfrLedgerEntry.amount).label("prior"))
        .filter(ItalyTfrLedgerEntry.organization_id == organization_id,
                ItalyTfrLedgerEntry.tax_year < tax_year,
                ItalyTfrLedgerEntry.entry_type.in_(carriers))
        .group_by(ItalyTfrLedgerEntry.employee_id)
        .all())
    balances = [(row.employee_id, Decimal(str(row.prior or 0)))
                for row in balances if Decimal(str(row.prior or 0)) > 0]

    if not balances:
        return []

    entry_date = date(tax_year, 12, 31)
    created = []

    for employee_id, prior in balances:
        revaluation = _round2(prior * coefficient / Decimal(100))
        tax = _round2(revaluation * tax_pct / Decimal(100))

        idem_base = hashlib.sha256(
            json.dumps({"org": organization_id, "emp": employee_id,
                        "year": tax_year, "type": "REVALUATION"},
                       sort_keys=True).encode("utf-8")
        ).hexdigest()[:48]

        if revaluation > 0:
            idem = idem_base + "R"
            if not (db.query(ItalyTfrLedgerEntry)
                    .filter(ItalyTfrLedgerEntry.idempotency_key == idem).first()):
                e = ItalyTfrLedgerEntry(
                    organization_id=organization_id,
                    employee_id=employee_id,
                    entry_type="REVALUATION",
                    tax_year=tax_year,
                    entry_date=entry_date,
                    amount=revaluation,
                    evidence={
                        "priorBalance": str(prior),
                        "fixedPct": str(fixed_pct),
                        "istatIncrease": str(istat_foi_increase_pct),
                        "istatShare": str(istat_share),
                        "months": str(months),
                        "coefficient": str(coefficient),
                        "revaluation": str(revaluation),
                    },
                    idempotency_key=idem,
                )
                db.add(e)
                created.append(e)

        if tax > 0:
            idem = idem_base + "T"
            if not (db.query(ItalyTfrLedgerEntry)
                    .filter(ItalyTfrLedgerEntry.idempotency_key == idem).first()):
                e = ItalyTfrLedgerEntry(
                    organization_id=organization_id,
                    employee_id=employee_id,
                    entry_type="REVALUATION_TAX",
                    tax_year=tax_year,
                    entry_date=entry_date,
                    amount=tax,
                    evidence={
                        "revaluation": str(revaluation),
                        "taxPct": str(tax_pct),
                        "substituteTax": str(tax),
                    },
                    idempotency_key=idem,
                )
                db.add(e)
                created.append(e)

    if created:
        db.commit()
        for e in created:
            db.refresh(e)
        record_tax_audit(db, actor_id=actor_id, action="create",
                         entity_type="italy_tfr_ledger_entry",
                         entity_id=created[0].id, legal_reference="IT-037",
                         new_value={"tax_year": tax_year, "employees": len(balances),
                                    "coefficient": str(coefficient),
                                    "entries": len(created)})
    return created


def _load_italy_reval_rates(db: Session, organization_id: int):
    """Load TFR revaluation rates from ContributionRate for the org.

    Returns a dict with keys: fixed_pct, istat_share, tax_pct (all Decimal).
    All three are stored in ContributionRate: the first two as employer_rate_pct,
    the tax_pct as employee_rate_pct (substitute tax on revaluation is employee-side).
    """
    from app.modules.payroll.models import ContributionRate

    def _get_employer(key):
        row = (db.query(ContributionRate)
               .filter(ContributionRate.component_key == key,
                       ContributionRate.organization_id.in_([organization_id, None]))
               .order_by(ContributionRate.organization_id.desc().nullslast())
               .first())
        if row is None or row.employer_rate_pct is None:
            raise BadRequestException(f"Missing revaluation rate: {key}")
        return Decimal(str(row.employer_rate_pct))

    def _get_employee(key):
        row = (db.query(ContributionRate)
               .filter(ContributionRate.component_key == key,
                       ContributionRate.organization_id.in_([organization_id, None]))
               .order_by(ContributionRate.organization_id.desc().nullslast())
               .first())
        if row is None or row.employee_rate_pct is None:
            raise BadRequestException(f"Missing revaluation tax rate: {key}")
        return Decimal(str(row.employee_rate_pct))

    return {
        "fixed_pct": _get_employer("it_tfr_revaluation_fixed_pct"),
        "istat_share": _get_employer("it_tfr_revaluation_istat_share"),
        "tax_pct": _get_employee("it_tfr_revaluation_tax_pct"),
    }


def _round2(d: Decimal) -> Decimal:
    return d.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def list_italy_tfr_ledger(
    db: Session, organization_id: int, employee_id: Optional[int] = None,
    tax_year: Optional[int] = None, entry_type: Optional[str] = None,
) -> List[ItalyTfrLedgerEntry]:
    query = db.query(ItalyTfrLedgerEntry).filter(
        ItalyTfrLedgerEntry.organization_id == organization_id)
    if employee_id is not None:
        query = query.filter(ItalyTfrLedgerEntry.employee_id == employee_id)
    if tax_year is not None:
        query = query.filter(ItalyTfrLedgerEntry.tax_year == tax_year)
    if entry_type:
        query = query.filter(ItalyTfrLedgerEntry.entry_type == entry_type.strip().upper())
    return query.order_by(ItalyTfrLedgerEntry.tax_year, ItalyTfrLedgerEntry.entry_date,
                          ItalyTfrLedgerEntry.id).all()


def get_italy_tfr_balance(
    db: Session, organization_id: int, employee_id: Optional[int] = None,
    as_of_year: Optional[int] = None,
) -> dict:
    """Current TFR liability balance, broken down by destination.

    Sums ACCRUAL + REVALUATION - ADVANCE - SETTLEMENT - TRANSFER_*,
    grouped by destination (AZIENDA / FONDO_PENSIONE / FONDO_TESORERIA / UNRESOLVED / None).
    """
    query = db.query(ItalyTfrLedgerEntry).filter(
        ItalyTfrLedgerEntry.organization_id == organization_id)
    if employee_id is not None:
        query = query.filter(ItalyTfrLedgerEntry.employee_id == employee_id)
    if as_of_year is not None:
        query = query.filter(ItalyTfrLedgerEntry.tax_year <= as_of_year)

    entries = query.all()
    by_dest: Dict[str, Decimal] = {}
    for e in entries:
        dest = e.destination or "UNRESOLVED"
        sign = Decimal("1") if e.entry_type in (
            "ACCRUAL", "REVALUATION", "INPS_OFFSET"
        ) else Decimal("-1")
        by_dest[dest] = by_dest.get(dest, Decimal("0")) + sign * e.amount

    total = sum(by_dest.values())
    return {
        "total": str(total),
        "byDestination": {k: str(v) for k, v in by_dest.items()},
        "asOfYear": as_of_year,
    }


def verify_italy_tfr_idempotency(
    db: Session, organization_id: int,
) -> dict:
    """Check for duplicate idempotency keys (should be impossible with the UNIQUE
    constraint, but useful for auditing)."""
    dupes = (db.query(ItalyTfrLedgerEntry.idempotency_key, sa_func.count(ItalyTfrLedgerEntry.id))
             .filter(ItalyTfrLedgerEntry.organization_id == organization_id)
             .group_by(ItalyTfrLedgerEntry.idempotency_key)
             .having(sa_func.count(ItalyTfrLedgerEntry.id) > 1)
             .all())
    return {
        "duplicateCount": len(dupes),
        "duplicateKeys": [k for k, _ in dupes],
        "checkedAt": date.today().isoformat(),
    }


def list_italy_f24_lines(
    db: Session, organization_id: int, payroll_run_id: Optional[int] = None,
    statutory_filing_id: Optional[int] = None, reference_period: Optional[str] = None,
    section: Optional[str] = None,
) -> List[ItalyF24Line]:
    query = db.query(ItalyF24Line).filter(ItalyF24Line.organization_id == organization_id)
    if payroll_run_id is not None:
        query = query.filter(ItalyF24Line.payroll_run_id == payroll_run_id)
    if statutory_filing_id is not None:
        query = query.filter(ItalyF24Line.statutory_filing_id == statutory_filing_id)
    if reference_period:
        query = query.filter(ItalyF24Line.reference_period == reference_period.strip())
    if section:
        query = query.filter(ItalyF24Line.section == section.strip().upper())
    return query.order_by(ItalyF24Line.section, ItalyF24Line.tax_code,
                          ItalyF24Line.id).all()


# ═══════════════════════════════════════════════════════════════════════════
# Sweden (ZP-SE-ENG-001) — readiness, preview, collective-agreement registry,
# sick-pay episodes and annual-leave ledgers.
#
# Statutory figures are computed ONLY by engine/countries/sweden.py; this
# layer assembles facts, enforces governance (four-eyes, explicit CBA status,
# no national default agreement) and stores the separate ledgers SE-006 and
# spec §8 require. Nothing here activates live Swedish payroll.
# ═══════════════════════════════════════════════════════════════════════════

def _latest_se_tax_pack(db: Session, pack_id: Optional[int] = None):
    query = db.query(JurisdictionPack).filter(JurisdictionPack.jurisdiction_country == "SE",
                                             JurisdictionPack.pack_type == "tax")
    if pack_id is not None:
        pack = query.filter(JurisdictionPack.id == pack_id).first()
        if pack is None:
            raise NotFoundException("JurisdictionPack", pack_id)
        return pack
    # Default: the pack in force today; else the most recent one.
    today = date.today()
    in_force = (query.filter(or_(JurisdictionPack.effective_from.is_(None), JurisdictionPack.effective_from <= today),
                             or_(JurisdictionPack.effective_to.is_(None), JurisdictionPack.effective_to >= today))
                .order_by(JurisdictionPack.effective_from.desc(), JurisdictionPack.id.desc()).first())
    return in_force or query.order_by(JurisdictionPack.effective_from.desc(), JurisdictionPack.id.desc()).first()


def get_se_readiness(db: Session, pack_id: Optional[int] = None) -> dict:
    """spec §16 release gates / §37 checklist for one Sweden tax pack —
    read-only. `ready` is True only when every REQUIRED item is complete;
    the items that depend on work outside this platform (specialist
    sign-off, AGI XML certification, parallel payroll) are listed as
    required and stay incomplete until evidenced — Sweden never becomes
    production-ready merely because the country record exists."""
    pack = _latest_se_tax_pack(db, pack_id)
    items = []

    def add(key, label, complete, detail=None, required=True):
        items.append({"key": key, "label": label, "required": required, "complete": bool(complete), "detail": detail})

    if pack is None:
        add("statutory_pack", "Sweden statutory tax pack exists", False, "No SE tax pack — run the Sweden seed.")
        return {"packId": None, "packVersion": None, "ready": False, "items": items,
                "blockers": ["No Sweden tax pack exists."]}

    source = (db.query(SourceArtifact).filter(SourceArtifact.id == pack.source_document_id).first()
              if pack.source_document_id else None)
    add("source_evidence", "Primary-source evidence linked to the pack", source is not None,
        source.title if source else "Link a Source Evidence artifact.")
    add("specialist_review", "Swedish payroll/tax specialist has reviewed the evidence (§16)",
        bool(source and source.reviewer_approved_at),
        "Reviewed" if source and source.reviewer_approved_at else "Awaiting independent review of the source artifact.")
    content_blockers = se_activation_blockers(db, pack)
    param_blockers = [b for b in content_blockers if b.startswith("missing ")]
    table_blockers = [b for b in content_blockers if not b.startswith("missing ")]
    add("parameters", "Employer-contribution, SINK, SLP and cohort parameters configured", not param_blockers,
        "; ".join(param_blockers) or "All required parameters configured.")
    add("tax_tables", "Tax tables 29–42 and one-time-payment tables entered from Skatteverket", not table_blockers,
        "; ".join(table_blockers) or "All tax-table rows declare an AMOUNT/PERCENT basis.")
    latest_run = (db.query(TestCertificationRun).filter(TestCertificationRun.jurisdiction_country == "SE")
                  .order_by(TestCertificationRun.run_at.desc(), TestCertificationRun.id.desc()).first())
    add("certification", "Golden-vector certification PASS", latest_run is not None and latest_run.status == "PASS",
        f"Latest run #{latest_run.id}: {latest_run.status}" if latest_run else "No SE certification run yet.")
    add("approval", "Distinct approver recorded (four-eyes)", pack.approved_by_id is not None,
        "Approved" if pack.approved_by_id else "Not yet approved by a distinct Super Admin.")
    calendar_rows = (db.query(StatutoryFilingCalendar)
                     .filter(StatutoryFilingCalendar.jurisdiction_country == "SE",
                             StatutoryFilingCalendar.report_type == "AGI",
                             StatutoryFilingCalendar.reporting_year == (pack.tax_year or "")).count())
    add("agi_calendar", "AGI declaration/payment calendar for the income year", calendar_rows >= 12,
        f"{calendar_rows} of 12 monthly periods configured.")
    agi_template = (db.query(ReportTemplate).filter(ReportTemplate.jurisdiction_country == "SE",
                                                    ReportTemplate.report_type == "AGI").first())
    add("agi_template", "AGI individual-statement template", agi_template is not None,
        f"{agi_template.template_key} ({agi_template.status})" if agi_template else "Not seeded.")
    add("agi_xml", "AGI XML generated and validated against Technical Description 1.1.18.2 (§10/§16)", False,
        "Not built — XML generation and Skatteverket test-service validation are a separate, gated phase (SE-008).")
    add("parallel_payroll", "Two reconciled parallel payroll cycles (§16)", False,
        "Evidence required from the implementation team.")
    cba_count = (db.query(CollectiveAgreement)
                 .filter(CollectiveAgreement.jurisdiction_country == "SE", CollectiveAgreement.status == "Active").count())
    add("cba_registry", "Collective-agreement registry (optional: no national default exists)", True,
        f"{cba_count} Active agreement(s); employers without one resolve to an explicit NONE.", required=False)

    blockers = [f"{i['label']}: {i['detail']}" for i in items if i["required"] and not i["complete"]]
    return {"packId": pack.id, "packVersion": pack.version, "ready": not blockers, "items": items,
            "blockers": blockers}


def preview_sweden_calculation(db: Session, data) -> dict:
    """Read-only Super Admin simulation (spec §13 "simulation before
    activation"): the SAME production engine a payroll run uses, against ONE
    Sweden pack's canonical rows in force on data.payDate, with the worker's
    facts supplied inline. Writes nothing; a blocked calculation returns the
    engine's own reason, never a figure."""
    from types import SimpleNamespace

    from app.modules.payroll.engine.base import PayrollContext
    from app.modules.payroll.engine.countries.shared import MissingComplianceConfigurationError
    from app.modules.payroll.engine.resolver import calculate_payroll

    pack = _latest_se_tax_pack(db, data.jurisdictionPackId)
    rates = _sg_rows_in_force(list_canonical_contribution_rates(db, jurisdiction_pack_id=pack.id), data.payDate)
    slabs = _sg_rows_in_force(list_canonical_tax_slabs(db, jurisdiction_pack_id=pack.id), data.payDate)
    profile = SimpleNamespace(
        se_tax_status=data.taxStatus, se_income_role=data.incomeRole,
        se_tax_table=data.taxTable, se_tax_column=data.taxColumn, se_sink_status=data.sinkStatus,
        se_decision_override=data.decisionOverride, se_skatteverket_decision_id=data.decisionId,
        se_decision_effective_from=data.decisionEffectiveFrom, se_decision_effective_to=data.decisionEffectiveTo,
        se_decision_monthly_withholding=data.decisionMonthlyWithholding, se_decision_rate_pct=data.decisionRatePct,
        se_annual_income=data.annualIncome, se_employee_pension_share=data.employeePensionShare,
        se_employer_pension_share=data.employerPensionShare, se_pension_plan=None,
        se_cba_status="NONE", se_cba_id=None,
    )
    ctx = PayrollContext(
        gross=data.gross, basic=data.gross, country="SE", pay_frequency=data.payFrequency, pay_date=data.payDate,
        rate_map={_normalize_engine_component_key(r.component_key): r for r in rates}, slabs=slabs,
        date_of_birth=data.dateOfBirth, sweden_statutory_profile=profile, se_organization_id=None,
        se_month_to_date_prior=data.monthToDatePrior, se_cash_pay=data.cashPay,
        se_pension_cost_base=data.pensionCostBase,
    )
    base = {"pack": {"id": pack.id, "packId": pack.pack_id, "version": pack.version, "status": pack.status},
            "payDate": data.payDate.isoformat(), "readOnly": True}
    try:
        result = calculate_payroll(ctx, "standard")
    except MissingComplianceConfigurationError as exc:
        return {**base, "blocked": True, "blockedKey": exc.key,
                "blockedReason": getattr(exc, "reason", None) or str(exc)}
    return {**base, "blocked": False,
            "result": {"gross": str(result.gross), "totalDeductions": str(result.total_deductions),
                       "netPay": str(result.net_pay)},
            "sweden": _se_payslip_snapshot(result)}


# ── Collective-agreement registry (spec §9/§13 "Agreement registry") ─────

_CBA_TYPES = ("EMPLOYER_SPECIFIC", "SECTOR", "LOCAL_SUPPLEMENT")  # deliberately no NATIONAL
_CBA_MODULES = ("wage_scales", "overtime", "unsocial_hours", "sickness_supplements", "parental_pay",
                "vacation_enhancement", "occupational_pension", "insurance", "termination")
_CBA_TRANSITIONS = {
    "Draft": ("In Review",),
    "In Review": ("Draft", "Approved"),
    "Approved": ("Draft", "Active"),
    "Active": ("Superseded",),
    "Superseded": (),
}


def list_collective_agreements(db: Session, country: str = "SE",
                               organization_id: Optional[int] = None) -> List[CollectiveAgreement]:
    """Agreement definitions (organization_id NULL) plus, when an org is
    given, that employer's own assignments."""
    query = db.query(CollectiveAgreement).filter(CollectiveAgreement.jurisdiction_country == _normalize_country(country))
    if organization_id is not None:
        query = query.filter(or_(CollectiveAgreement.organization_id == organization_id,
                                 CollectiveAgreement.organization_id.is_(None)))
    return query.order_by(CollectiveAgreement.agreement_code, CollectiveAgreement.version).all()


def upsert_collective_agreement(db: Session, data, actor_id: Optional[int] = None) -> CollectiveAgreement:
    """Create or edit a Draft agreement version. Refuses a NATIONAL/unknown
    type (spec §44: no Swedish national default CBA) and editing any version
    that has left Draft — a change to released content is a NEW version."""
    if _normalize_country(data.jurisdictionCountry) == "CH":
        raise BadRequestException("Swiss wage floors are governed — use /compliance/switzerland/wage-floors.")
    if data.agreementType not in _CBA_TYPES:
        raise BadRequestException(f"agreementType must be one of {list(_CBA_TYPES)} — there is no national "
                                  "default collective agreement (ZP-SE-ENG-001 §9).")
    unknown = [m for m in (data.modules or []) if m not in _CBA_MODULES]
    if unknown:
        raise BadRequestException(f"Unknown agreement module(s): {unknown}. Allowed: {list(_CBA_MODULES)}.")
    if data.effectiveFrom and data.effectiveTo and data.effectiveTo < data.effectiveFrom:
        raise BadRequestException("effectiveTo must not be before effectiveFrom.")
    if data.id:
        row = db.query(CollectiveAgreement).filter(CollectiveAgreement.id == data.id).first()
        if row is None:
            raise NotFoundException("CollectiveAgreement", data.id)
        if row.status != "Draft":
            raise BadRequestException(f"Agreement {row.agreement_code} v{row.version} is {row.status} — create a new "
                                      "version instead of editing released content.")
        old = {"status": row.status, "version": row.version}
    else:
        clash = (db.query(CollectiveAgreement)
                 .filter(CollectiveAgreement.agreement_code == data.agreementCode,
                         CollectiveAgreement.version == data.version).first())
        if clash is not None:
            raise BadRequestException(f"Agreement {data.agreementCode} v{data.version} already exists.")
        row = CollectiveAgreement(created_by_id=actor_id, status="Draft")
        db.add(row)
        old = None
    row.jurisdiction_country = _normalize_country(data.jurisdictionCountry)
    row.organization_id = data.organizationId
    row.agreement_code = data.agreementCode
    row.name = data.name
    row.agreement_type = data.agreementType
    row.employer_scope = data.employerScope
    row.employee_group = data.employeeGroup
    row.occupation = data.occupation
    row.grade = data.grade
    row.version = data.version
    row.effective_from = data.effectiveFrom
    row.effective_to = data.effectiveTo
    row.modules = data.modules or []
    row.source_document_id = data.sourceDocumentId
    row.previous_version_id = data.previousVersionId
    row.notes = data.notes
    row.updated_by_id = actor_id
    row.approved_by_id = None          # any edit invalidates a prior approval
    db.flush()
    record_tax_audit(db, actor_id=actor_id, action="create" if old is None else "update",
                     entity_type="collective_agreement", entity_id=row.id, legal_reference="ZP-SE-ENG-001 §9",
                     old_value=old, new_value={"code": row.agreement_code, "version": row.version,
                                               "type": row.agreement_type, "modules": row.modules},
                     reason=data.reason, auto_commit=False)
    db.commit()
    db.refresh(row)
    return row


def set_collective_agreement_status(db: Session, agreement_id: int, status: str, actor_id: Optional[int] = None,
                                    reason: Optional[str] = None) -> CollectiveAgreement:
    """Governed lifecycle (spec §13: "No rule activation without source /
    effective dates / test pack"; §14 four-eyes): the approver is never the
    author/last editor, the activator is never the approver, and an Active
    version needs a source artifact, an effective-from date and at least one
    module. Activating a version supersedes the previous Active one."""
    row = db.query(CollectiveAgreement).filter(CollectiveAgreement.id == agreement_id).first()
    if row is None:
        raise NotFoundException("CollectiveAgreement", agreement_id)
    if row.jurisdiction_country == "CH":
        raise BadRequestException("Swiss wage floors are governed — use /compliance/switzerland/wage-floors.")
    if status not in _CBA_TRANSITIONS.get(row.status, ()):
        raise BadRequestException(f"Cannot move agreement from {row.status} to {status}.")
    if status == "Approved":
        if actor_id is not None and actor_id in (row.updated_by_id, row.created_by_id):
            raise BadRequestException("The approver must be a different Super Admin than the agreement's author/editor.")
        row.approved_by_id = actor_id
    if status == "Active":
        if not row.source_document_id:
            raise BadRequestException("An agreement needs a linked source artifact before it can go Active.")
        if not row.effective_from:
            raise BadRequestException("An agreement needs an effective-from date before it can go Active.")
        if not row.modules:
            raise BadRequestException("An agreement with no configured modules has no payroll effect — configure one first.")
        if row.approved_by_id is None or (actor_id is not None and row.approved_by_id == actor_id):
            raise BadRequestException("The Super Admin who approved this agreement cannot also activate it.")
        for prior in (db.query(CollectiveAgreement)
                      .filter(CollectiveAgreement.agreement_code == row.agreement_code,
                              CollectiveAgreement.id != row.id, CollectiveAgreement.status == "Active")):
            prior.status = "Superseded"
    if status == "Draft":
        row.approved_by_id = None
    before = row.status
    row.status = status
    record_tax_audit(db, actor_id=actor_id, action="status_change", entity_type="collective_agreement",
                     entity_id=row.id, legal_reference="ZP-SE-ENG-001 §9/§14",
                     old_value={"status": before}, new_value={"status": status}, reason=reason, auto_commit=False)
    db.commit()
    db.refresh(row)
    return row


# ── Sick-pay episodes (spec §8) ───────────────────────────────────────────

_SE_SICK_RECURRENCE_DAYS = 5         # spec §8 "Recurrence within 5 days" — rule shape
_SE_EMPLOYER_SICK_PERIOD_DAYS = 14   # spec §8 "days 1-14" — rule shape


def _se_in_force_param(db: Session, key: str, as_of) -> Optional[Decimal]:
    """A Sweden amount parameter from the ACTIVE canonical pack in force on
    `as_of` — None when no Active pack configures it (never a default)."""
    from app.modules.payroll.engine.tax_resolver import resolve_tax_configuration

    rates, _slabs, pack = resolve_tax_configuration(db, "SE", payroll_date=as_of)
    if pack is None or pack.status != "Active":
        return None
    for row in rates:
        if _normalize_engine_component_key(row.component_key) == key and row.flat_amount is not None:
            return Decimal(str(row.flat_amount))
    return None


def list_se_sick_episodes(db: Session, organization_id: int, employee_id: Optional[int] = None) -> List[SwedenSickEpisode]:
    query = db.query(SwedenSickEpisode).filter(SwedenSickEpisode.organization_id == organization_id)
    if employee_id is not None:
        query = query.filter(SwedenSickEpisode.employee_id == employee_id)
    return query.order_by(SwedenSickEpisode.episode_start.desc(), SwedenSickEpisode.id.desc()).all()


def upsert_se_sick_episode(db: Session, organization_id: int, data, actor_id: Optional[int] = None) -> SwedenSickEpisode:
    """Record one sickness episode and resolve its statutory state (spec §8):
      * RECURRENCE — an episode starting within 5 days of the previous one's
        end joins its recurrence group: one combined 14-day employer period,
        and no second full qualifying deduction if one was already made;
      * EMPLOYER PERIOD — which of days 1–14 this episode covers; any day
        beyond 14 flags the Försäkringskassan transfer;
      * QUALIFYING DEDUCTION — pct × expected average-week sick pay, never
        exceeding the payable sick pay. The pct comes from the request or the
        Active pack's se_sick_qualifying_deduction_pct — neither → refused.
    Only a certificate REFERENCE is stored; never clinical content (§14)."""
    employee = get_employee_by_id(db, data.employeeId, organization_id)
    if _normalize_country(getattr(employee, "country_code", None)) != "SE":
        raise BadRequestException("Swedish sick-pay episodes can only be recorded for a Sweden employee.")
    if data.episodeEnd is not None and data.episodeEnd < data.episodeStart:
        raise BadRequestException("episodeEnd must not be before episodeStart.")
    if data.workCapacityPct is not None and not (Decimal("0") < data.workCapacityPct <= Decimal("100")):
        raise BadRequestException("workCapacityPct must be greater than 0 and at most 100.")

    row = None
    if data.id:
        row = (db.query(SwedenSickEpisode)
               .filter(SwedenSickEpisode.id == data.id, SwedenSickEpisode.organization_id == organization_id).first())
        if row is None:
            raise NotFoundException("SwedenSickEpisode", data.id)
        if row.status == "CLOSED":
            raise BadRequestException("A closed sick-pay episode cannot be edited — record a correction episode.")
    others = [SwedenSickEpisode.id != row.id] if row is not None else []

    previous = (db.query(SwedenSickEpisode)
                .filter(SwedenSickEpisode.employee_id == employee.id,
                        SwedenSickEpisode.organization_id == organization_id,
                        SwedenSickEpisode.episode_start < data.episodeStart,
                        SwedenSickEpisode.episode_end.isnot(None), *others)
                .order_by(SwedenSickEpisode.episode_start.desc()).first())
    group_root = None
    if previous is not None and (data.episodeStart - previous.episode_end).days <= _SE_SICK_RECURRENCE_DAYS:
        group_root = previous.recurrence_group_id or previous.id
    group = []
    if group_root is not None:
        group = (db.query(SwedenSickEpisode)
                 .filter(or_(SwedenSickEpisode.id == group_root, SwedenSickEpisode.recurrence_group_id == group_root),
                         *others)
                 .all())
    days_before = sum(((g.episode_end - g.episode_start).days + 1) for g in group if g.episode_end)
    own_days = ((data.episodeEnd - data.episodeStart).days + 1) if data.episodeEnd else None
    day_from = days_before + 1
    day_to = (days_before + own_days) if own_days is not None else None
    transfer = bool(day_to is not None and day_to > _SE_EMPLOYER_SICK_PERIOD_DAYS)
    deduction_already = any(g.deduction_already_applied or (g.qualifying_deduction_amount or 0) > 0 for g in group)

    deduction_pct = data.qualifyingDeductionPct
    if deduction_pct is None:
        deduction_pct = _se_in_force_param(db, "se_sick_qualifying_deduction_pct", data.episodeStart)
    deduction_amount = Decimal("0")
    if not deduction_already and day_from <= _SE_EMPLOYER_SICK_PERIOD_DAYS:
        if data.expectedWeeklySickPay is None:
            raise BadRequestException("expectedWeeklySickPay is required to apply the qualifying deduction (spec §8).")
        if deduction_pct is None:
            raise BadRequestException("No qualifying-deduction percentage: supply qualifyingDeductionPct or activate a "
                                      "Sweden pack configuring se_sick_qualifying_deduction_pct.")
        deduction_amount = (Decimal(str(deduction_pct)) / Decimal("100") * data.expectedWeeklySickPay).quantize(Decimal("0.01"))
        if data.employerSickPayAmount is not None and deduction_amount > data.employerSickPayAmount:
            deduction_amount = Decimal(str(data.employerSickPayAmount))   # never exceeds payable sick pay

    if row is None:
        row = SwedenSickEpisode(organization_id=organization_id, employee_id=employee.id)
        db.add(row)
    row.episode_start = data.episodeStart
    row.episode_end = data.episodeEnd
    row.recurrence_group_id = group_root
    row.work_capacity_pct = data.workCapacityPct
    row.expected_weekly_sick_pay = data.expectedWeeklySickPay
    row.qualifying_deduction_pct = deduction_pct
    row.qualifying_deduction_amount = deduction_amount
    row.deduction_already_applied = bool(deduction_already or deduction_amount > 0)
    row.employer_period_day_from = day_from
    row.employer_period_day_to = min(day_to, _SE_EMPLOYER_SICK_PERIOD_DAYS) if day_to is not None else None
    row.transfer_to_forsakringskassan = transfer
    row.medical_certificate_ref = data.medicalCertificateRef
    row.absence_reported = data.absenceReported
    row.employer_sick_pay_amount = data.employerSickPayAmount
    row.cba_supplement_amount = data.cbaSupplementAmount
    row.cba_agreement_id = data.cbaAgreementId
    row.status = data.status or "OPEN"
    row.source = data.source
    db.flush()
    record_tax_audit(db, actor_id=actor_id, action="update" if data.id else "create", entity_type="se_sick_episode",
                     entity_id=row.id, legal_reference="ZP-SE-ENG-001 §8",
                     new_value={"dayFrom": str(day_from), "dayTo": str(row.employer_period_day_to),
                                "recurrenceGroup": str(group_root), "deduction": str(deduction_amount),
                                "transfer": str(transfer)},
                     auto_commit=False)
    db.commit()
    db.refresh(row)
    return row


# ── Annual-leave ledgers (spec §7, SE-006) ────────────────────────────────

_SE_VACATION_METHODS = ("PERCENTAGE_12", "SAME_PAY", "CBA_OVERRIDE")
_SE_STATUTORY_LEAVE_DAYS = Decimal("25")          # spec §7 [S10] — statutory baseline
_SE_SAVEABLE_ABOVE_PAID_DAYS = Decimal("20")      # spec §7 "Paid days exceeding 20 may generally be saved"
_SE_SAVED_DAYS_YEARS = 5                          # spec §7 "normally taken within five years"


def list_se_leave_ledgers(db: Session, organization_id: int, employee_id: Optional[int] = None) -> List[SwedenLeaveLedger]:
    query = db.query(SwedenLeaveLedger).filter(SwedenLeaveLedger.organization_id == organization_id)
    if employee_id is not None:
        query = query.filter(SwedenLeaveLedger.employee_id == employee_id)
    return query.order_by(SwedenLeaveLedger.entitlement_year.desc(), SwedenLeaveLedger.id.desc()).all()


def upsert_se_leave_ledger(db: Session, organization_id: int, data, actor_id: Optional[int] = None) -> SwedenLeaveLedger:
    """One (employee, entitlement year) leave ledger. Days and money stay
    separate (SE-006): this row holds days + the qualifying-year earnings;
    vacation MONEY is never derived from the day balance here. Statutory
    bounds apply unless a CBA override method is recorded with its agreement."""
    employee = get_employee_by_id(db, data.employeeId, organization_id)
    if _normalize_country(getattr(employee, "country_code", None)) != "SE":
        raise BadRequestException("Swedish leave ledgers can only be recorded for a Sweden employee.")
    if data.vacationPayMethod not in _SE_VACATION_METHODS:
        raise BadRequestException(f"vacationPayMethod must be one of {list(_SE_VACATION_METHODS)}.")
    for label, value in (("paidDays", data.paidDays), ("unpaidDays", data.unpaidDays),
                         ("savedDays", data.savedDays), ("carryoverDays", data.carryoverDays)):
        if value is not None and value < 0:
            raise BadRequestException(f"{label} must not be negative.")
    if data.vacationPayMethod == "CBA_OVERRIDE":
        if data.cbaAgreementId is None:
            raise BadRequestException("CBA_OVERRIDE requires the governing cbaAgreementId (spec §7 CBA override).")
    else:
        if data.paidDays + data.unpaidDays > _SE_STATUTORY_LEAVE_DAYS:
            raise BadRequestException("Paid + unpaid days exceed the 25-day statutory entitlement; record the governing "
                                      "agreement with vacationPayMethod CBA_OVERRIDE if an agreement grants more.")
        if data.savedDays > max(Decimal("0"), data.paidDays - _SE_SAVEABLE_ABOVE_PAID_DAYS):
            raise BadRequestException("Only paid days exceeding 20 may be saved (spec §7 Saving days).")
    if data.carryoverExpiry is not None and data.entitlementYear.isdigit():
        if data.carryoverExpiry.year > int(data.entitlementYear) + _SE_SAVED_DAYS_YEARS:
            raise BadRequestException("Saved days are normally taken within five years — carryoverExpiry is too late.")

    if data.id:
        row = (db.query(SwedenLeaveLedger)
               .filter(SwedenLeaveLedger.id == data.id, SwedenLeaveLedger.organization_id == organization_id).first())
        if row is None:
            raise NotFoundException("SwedenLeaveLedger", data.id)
    else:
        row = (db.query(SwedenLeaveLedger)
               .filter(SwedenLeaveLedger.employee_id == employee.id,
                       SwedenLeaveLedger.entitlement_year == data.entitlementYear).first())
    if row is not None and row.status == "Closed":
        raise BadRequestException("This ledger is closed (final vacation allowance settled) — it can no longer be edited.")
    old = None if row is None else {"paidDays": str(row.paid_days), "savedDays": str(row.saved_days)}
    if row is None:
        row = SwedenLeaveLedger(organization_id=organization_id, employee_id=employee.id,
                                entitlement_year=data.entitlementYear)
        db.add(row)
    row.qualifying_year = data.qualifyingYear
    row.paid_days = data.paidDays
    row.unpaid_days = data.unpaidDays
    row.saved_days = data.savedDays
    row.carryover_days = data.carryoverDays
    row.carryover_expiry = data.carryoverExpiry
    row.qualifying_earnings = data.qualifyingEarnings
    row.vacation_pay_method = data.vacationPayMethod
    row.credited_absence = data.creditedAbsence
    row.final_vacation_allowance = data.finalVacationAllowance
    row.cba_agreement_id = data.cbaAgreementId
    row.effective_from = data.effectiveFrom
    row.effective_to = data.effectiveTo
    row.version = data.version
    row.status = data.status
    db.flush()
    record_tax_audit(db, actor_id=actor_id, action="update" if old else "create", entity_type="se_leave_ledger",
                     entity_id=row.id, legal_reference="ZP-SE-ENG-001 §7/SE-006", old_value=old,
                     new_value={"paidDays": str(row.paid_days), "savedDays": str(row.saved_days),
                                "method": row.vacation_pay_method}, auto_commit=False)
    db.commit()
    db.refresh(row)
    return row
